// Raw VT/ANSI escape sequences. Everything prism-term writes to a terminal is
// built from these, so this file is also the reference for what we depend on:
// only widely-supported CSI/DEC private modes, nothing terminal-specific.

export const ESC = '\x1b';
export const CSI = '\x1b[';

export const reset = '\x1b[0m';

export const cursor = {
  hide: '\x1b[?25l',
  show: '\x1b[?25h',
  home: '\x1b[H',
  save: '\x1b7',
  restore: '\x1b8',
  /** Absolute move, 0-based. */
  to: (x, y) => `\x1b[${y + 1};${x + 1}H`,
  /** Absolute column on the current row, 0-based. */
  column: (x) => `\x1b[${x + 1}G`,
  up: (n = 1) => (n > 0 ? `\x1b[${n}A` : ''),
  down: (n = 1) => (n > 0 ? `\x1b[${n}B` : ''),
  right: (n = 1) => (n > 0 ? `\x1b[${n}C` : ''),
  left: (n = 1) => (n > 0 ? `\x1b[${n}D` : ''),
};

export const screen = {
  altOn: '\x1b[?1049h',
  altOff: '\x1b[?1049l',
  clear: '\x1b[2J',
  clearDown: '\x1b[J',
  clearLine: '\x1b[2K',
  clearLineRight: '\x1b[K',
  // DEC mode 2026 "synchronized output": the terminal buffers everything between
  // these and paints it atomically — no tearing. Terminals that don't know the
  // mode ignore it, so it is always safe to send.
  syncStart: '\x1b[?2026h',
  syncEnd: '\x1b[?2026l',
  // Autowrap off means writing the bottom-right cell can never scroll the screen.
  wrapOff: '\x1b[?7l',
  wrapOn: '\x1b[?7h',
};

export const mouse = {
  on: '\x1b[?1000h\x1b[?1006h',
  off: '\x1b[?1000l\x1b[?1006l',
};

/** OSC 0 — set the terminal window/tab title. */
export const title = (s) => `\x1b]0;${String(s).replace(/[\x00-\x1f]/g, '')}\x07`;

// CSI … final-byte, OSC … BEL/ST, and lone two-byte escapes.
const ANSI_RE = /\x1b\[[0-?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[@-Z\\-_]/g;

export function stripAnsi(s) {
  return String(s).replace(ANSI_RE, '');
}

sources.prism-term/src/ascii.js:
// ASCII folding — how every facet degrades on a terminal without Unicode
// (TERM=linux consoles, LANG=C, serial lines, old Windows consoles).
//
// foldChar() maps any single glyph to ONE printable 7-bit character, so a fold
// never shifts a column: box drawing becomes + - |, blocks and braille become a
// density ramp, arrows/marks become their closest ASCII shape, accented letters
// lose their accent, and anything unknown becomes '?'. Wide (2-cell) glyphs fold
// to two characters for the same reason.
//
// asciiSurface(surface) wraps any Surface so everything drawn through it is
// folded. createContext() applies it automatically when caps.unicode is false,
// so facets don't need their own ASCII paths (though bespoke ones look better).

import { Surface } from './buffer.js';
import { charWidth } from './width.js';

const MAP = new Map();
const put = (chars, a) => { for (const c of chars) MAP.set(c, a); };

// Box drawing (U+2500–257F): straight runs keep their direction, everything else is a joint.
for (let cp = 0x2500; cp <= 0x257f; cp++) MAP.set(String.fromCodePoint(cp), '+');
put('─━┄┅┈┉╌╍╴╶╸╺╼╾', '-');
put('═', '=');
put('│┃┆┇┊┋╎╏║╵╷╹╻╽╿', '|');
put('╱', '/'); put('╲', '\\'); put('╳', 'X');

// Block elements (U+2580–259F) by how much of the cell they fill.
put('█▓▉▊▋■▪▮◼▇', '#');
put('▒▚▞', ':');
put('░▖▗▘▝▁▂', '.');
put('▃▄', '_');
put('▅▆▬', '=');
put('▀▔', '"');
put('▏▎▍▌▐▕', '|');
put('▙▛▜▟', '#');

// Shapes, arrows, marks and punctuation.
put('●◉⬤◍', 'o'); put('○◌◯', 'o'); put('◆◈❖', '*'); put('◇', 'o'); put('□▯▢', '[');
put('★☆✦✧✶✸✺✹✷⁂☼', '*'); put('•∙⋅·', '.'); put('◐◑◒◓◔◕', 'o');
put('→⇒⟶➜➔➝➞⇢⇨', '>'); put('←⇐⟵⇠⇦', '<'); put('↑⇑⇡⇧', '^'); put('↓⇓⇣⇩', 'v');
put('↗↙', '/'); put('↖↘', '\\'); put('↔⇔', '-'); put('↕⇕', '|'); put('↻↺⟳⟲', '@');
put('▶▸►▹⏵❯›»', '>'); put('◀◂◄◃⏴❮‹«', '<'); put('▲▴△▵⏶', '^'); put('▼▾▽▿⏷', 'v');
put('✔✓☑', '+'); put('✖✗✘☒', 'x'); put('⚠', '!'); put('ℹ', 'i'); put('⚡', '!');
put('—–‒―−', '-'); put('…', '.'); put('×', 'x'); put('÷', '/'); put('±', '+');
put('≥≧', '>'); put('≤≦', '<'); put('≠', '#'); put('≈∼', '~'); put('°', 'o'); put('µμ', 'u');
put('‘’‚′', "'"); put('“”„″', '"'); put('¦‖', '|'); put('§', 'S'); put('¶', 'P');
put('©', 'c'); put('®', 'r'); put('™', 't'); put('€', 'E'); put('£', 'L'); put('¥', 'Y');
put('∞', '8'); put('√', 'v'); put('∑', 'E'); put('∆Δ', 'A'); put('λ', 'l'); put('π', 'p'); put('σ', 's');
put('⎇', 'Y'); put('⎈', '*'); put('⊘⌀', '0'); put('␣', '_'); put('⏎↵', '<');

const BRAILLE_RAMP = ' ..::++##';
const SEXTANT_RAMP = ' ..::+##';
const popcount = (n) => { let k = 0; while (n) { k += n & 1; n >>= 1; } return k; };

/** One printable ASCII character for any single glyph. */
export function foldChar(c) {
  if (!c) return c;
  const cp = c.codePointAt(0);
  if (cp >= 0x20 && cp < 0x7f) return c;
  if (cp < 0x20 || cp === 0x7f) return ' ';
  const m = MAP.get(c);
  if (m) return m;
  if (cp >= 0x2800 && cp <= 0x28ff) return BRAILLE_RAMP[popcount(cp - 0x2800)];
  if (cp >= 0x1fb00 && cp <= 0x1fb3b) {
    // Invert canvas.js's sextant numbering (masks 21 and 42 are ▌▐, 63 is █).
    let mask = cp - 0x1fb00 + 1;
    if (mask >= 21) mask++;
    if (mask >= 42) mask++;
    return SEXTANT_RAMP[popcount(mask)];
  }
  const base = c.normalize('NFD')[0];
  if (base && base.codePointAt(0) < 0x7f && base.codePointAt(0) >= 0x20) return base;
  return '?';
}

/** Fold a string so it occupies exactly the same number of columns in 7-bit ASCII. */
export function foldText(s) {
  let out = '';
  for (const c of String(s)) {
    const cp = c.codePointAt(0);
    if (cp >= 0x20 && cp < 0x7f) { out += c; continue; }
    const w = charWidth(cp);
    if (w === 0) continue;
    out += w === 2 ? '??' : foldChar(c);
  }
  return out;
}

class AsciiSurface extends Surface {
  constructor(inner) {
    super();
    this.inner = inner;
    this.ascii = true;
  }
  get width() { return this.inner.width; }
  get height() { return this.inner.height; }
  set(x, y, ch, fg, bg, attr) {
    // '' marks the right half of a wide glyph; once the glyph folds to one cell, it needs a filler.
    if (ch !== undefined) ch = ch === '' ? '?' : foldChar(String.fromCodePoint(ch.codePointAt(0)));
    return this.inner.set(x, y, ch, fg, bg, attr);
  }
  get(x, y) { return this.inner.get(x, y); }
  clear(bg, fg) { this.inner.clear(bg, fg); return this; }
  text(x, y, str, fg, bg, attr) { return super.text(x, y, foldText(str), fg, bg, attr); }
}

/** Wrap a surface so everything drawn through it is 7-bit ASCII (idempotent). */
export function asciiSurface(surface) {
  return surface && surface.ascii ? surface : new AsciiSurface(surface);
}

sources.prism-term/src/buffer.js:
// Cell buffers — the in-memory screen.
//
// A CellBuffer is a grid of cells (char, fg, bg, attr) stored as parallel typed
// arrays so the renderer can diff whole frames cheaply. A View is a clipped,
// offset window onto a CellBuffer (or another View) with the same drawing API —
// widgets draw into views and never need to know where they sit on screen.
//
// Write semantics shared by every surface: an `undefined` fg/bg/attr keeps the
// cell's current value (so text can be laid over an effect without erasing its
// background); NONE (-1) means the terminal's default color.
//
// Wide characters (CJK, emoji) occupy two cells: the glyph in the first and an
// empty-string continuation marker in the second, which the renderer skips.

import { NONE, fgParam, bgParam, normalizeDepth } from './color.js';
import { charWidth } from './width.js';

export const ATTR = Object.freeze({
  BOLD: 1, DIM: 2, ITALIC: 4, UNDERLINE: 8, BLINK: 16, INVERSE: 32, STRIKE: 64,
});

const ATTR_SGR = [[1, '1'], [2, '2'], [4, '3'], [8, '4'], [16, '5'], [32, '7'], [64, '9']];

/**
 * True when `surface` (or the buffer it draws into) renders for a light terminal:
 * createContext() sets `light16` on the root buffer from the theme's mode. At 16
 * colors that keeps white / bright-white text off the default background (color.js
 * ansi16Text); other depths ignore it.
 */
export function lightTerminal(surface) {
  for (let s = surface, i = 0; s && i < 16; s = s.parent || s.inner, i++) if (s.light16 !== undefined) return !!s.light16;
  return false;
}

/**
 * The color the serializers send as the terminal's own foreground (SGR 39), or -2:
 * with --transparent createContext() sets `inkAsDefault` on the root buffer to the
 * theme's ink, so body text follows the terminal (readable on a light or a dark
 * background even when the theme guess is wrong).
 */
export function defaultInk(surface) {
  for (let s = surface, i = 0; s && i < 16; s = s.parent || s.inner, i++) if (s.inkAsDefault !== undefined) return s.inkAsDefault ?? -2;
  return -2;
}

/**
 * Is `ch` text (as opposed to a pixel glyph whose fg is a fill: block elements,
 * shades, braille, sextants)? Only text gets the light-terminal rule.
 */
export function lightText(ch) {
  const cp = ch ? ch.codePointAt(0) : 32;
  return !((cp >= 0x2580 && cp <= 0x259f) || (cp >= 0x2800 && cp <= 0x28ff) || (cp >= 0x1fb00 && cp <= 0x1fb3b));
}

/** SGR parameter fragment for an attribute bitmask (empty string for none). */
export function attrParams(a) {
  if (!a) return '';
  let s = '';
  for (const [bit, code] of ATTR_SGR) if (a & bit) s += (s ? ';' : '') + code;
  return s;
}

/** Parse 'bold,italic' / ['bold'] / number into an attribute mask. */
export function parseAttr(v) {
  if (v == null) return undefined;
  if (typeof v === 'number') return v;
  const names = Array.isArray(v) ? v : String(v).split(/[\s,|]+/);
  let a = 0;
  for (const n of names) {
    const k = String(n).toUpperCase();
    if (k === 'UNDERLINED') a |= ATTR.UNDERLINE;
    else if (k === 'REVERSE') a |= ATTR.INVERSE;
    else if (ATTR[k]) a |= ATTR[k];
  }
  return a;
}

/** Shared drawing API. Subclasses implement width/height/set/get. */
export class Surface {
  /** Write `str` starting at (x,y). Returns the column after the last glyph. */
  text(x, y, str, fg, bg, attr) {
    x = Math.round(x); y = Math.round(y);
    if (y < 0 || y >= this.height) return x + [...String(str)].length;
    for (const ch of String(str)) {
      const cp = ch.codePointAt(0);
      if (ch === '\n') continue;
      const w = charWidth(cp);
      if (w === 0) continue; // zero-width marks are dropped rather than mis-attached
      if (x >= 0 && x < this.width) {
        if (w === 2 && x + 1 >= this.width) { this.set(x, y, ' ', fg, bg, attr); x++; break; }
        this.set(x, y, ch, fg, bg, attr);
        if (w === 2) this.set(x + 1, y, '', fg, bg, attr);
      }
      x += w;
    }
    return x;
  }

  /** Fill a rectangle. `ch` undefined keeps characters (recolor only). */
  fill(x, y, w, h, ch, fg, bg, attr) {
    const x0 = Math.max(0, Math.round(x)), y0 = Math.max(0, Math.round(y));
    const x1 = Math.min(this.width, Math.round(x + w)), y1 = Math.min(this.height, Math.round(y + h));
    for (let yy = y0; yy < y1; yy++) for (let xx = x0; xx < x1; xx++) this.set(xx, yy, ch, fg, bg, attr);
  }

  /** A clipped window onto this surface. */
  view(x, y, w, h) {
    return new View(this, x, y, w, h);
  }

  /** Copy another surface onto this one. With `transparent`, NONE-bg spaces are skipped. */
  blit(src, dx = 0, dy = 0, { transparent = false } = {}) {
    for (let y = 0; y < src.height; y++) {
      for (let x = 0; x < src.width; x++) {
        const c = src.get(x, y);
        if (!c) continue;
        if (transparent && c.ch === ' ' && c.bg === NONE) continue;
        this.set(x + dx, y + dy, c.ch, c.fg, c.bg, c.attr);
      }
    }
  }

  /** Plain text of the surface, one line per row, trailing spaces trimmed. */
  toString() {
    const lines = [];
    for (let y = 0; y < this.height; y++) {
      let line = '';
      for (let x = 0; x < this.width; x++) line += this.get(x, y).ch;
      lines.push(line.replace(/\s+$/, ''));
    }
    return lines.join('\n');
  }

  /**
   * Serialize as an ANSI string (rows separated by '\n', styles reset at line
   * ends) — for printing static art into normal scrollback.
   */
  toAnsi(depth = 'truecolor') {
    depth = normalizeDepth(depth);
    const light = depth === '16' && lightTerminal(this), ink = defaultInk(this);
    const lines = [];
    for (let y = 0; y < this.height; y++) {
      let line = '', fg = NONE, bg = NONE, at = 0, styled = false, fgP = '39';
      let end = this.width;
      // Trim trailing default-styled blanks so lines don't wrap in narrow terminals.
      while (end > 0) { const c = this.get(end - 1, y); if (c.ch === ' ' && c.bg === NONE && !c.attr) end--; else break; }
      for (let x = 0; x < end; x++) {
        const c = this.get(x, y);
        if (c.ch === '') continue;
        if (c.fg === ink) c.fg = NONE;
        // Light 16: the fg slot depends on the fill and on whether the glyph is text (color.js ansi16Text).
        const fp = light ? fgParam(c.fg, depth, c.bg, lightText(c.ch)) : null;
        if (depth === 'mono') {
          if (c.attr !== at) { line += `\x1b[0${c.attr ? ';' + attrParams(c.attr) : ''}m`; at = c.attr; styled = true; }
        } else if (c.attr !== at) {
          const ap = attrParams(c.attr);
          line += `\x1b[0${ap ? ';' + ap : ''};${fp ?? fgParam(c.fg, depth)};${bgParam(c.bg, depth)}m`;
          fg = c.fg; bg = c.bg; at = c.attr; styled = true; fgP = fp;
        } else if (light ? fp !== fgP || c.bg !== bg : c.fg !== fg || c.bg !== bg) {
          const parts = [];
          if (light ? fp !== fgP : c.fg !== fg) parts.push(fp ?? fgParam(c.fg, depth));
          if (c.bg !== bg) parts.push(bgParam(c.bg, depth));
          line += `\x1b[${parts.join(';')}m`;
          fg = c.fg; bg = c.bg; styled = true; fgP = fp;
        }
        line += c.ch;
      }
      if (styled) line += '\x1b[0m';
      lines.push(line);
    }
    return lines.join('\n');
  }
}

export class CellBuffer extends Surface {
  constructor(width, height) {
    super();
    this.resize(width, height);
  }

  resize(width, height) {
    this.width = Math.max(0, width | 0);
    this.height = Math.max(0, height | 0);
    const n = this.width * this.height;
    this.ch = new Array(n).fill(' ');
    this.fg = new Int32Array(n).fill(NONE);
    this.bg = new Int32Array(n).fill(NONE);
    this.at = new Uint8Array(n);
    return this;
  }

  clear(bg = NONE, fg = NONE) {
    this.ch.fill(' ');
    this.fg.fill(fg);
    this.bg.fill(bg);
    this.at.fill(0);
    return this;
  }

  set(x, y, ch, fg, bg, attr) {
    x |= 0; y |= 0;
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return;
    const i = y * this.width + x;
    if (ch !== undefined) this.ch[i] = ch;
    if (fg !== undefined) this.fg[i] = fg;
    if (bg !== undefined) this.bg[i] = bg;
    if (attr !== undefined) this.at[i] = attr;
  }

  get(x, y) {
    x |= 0; y |= 0;
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return null;
    const i = y * this.width + x;
    return { ch: this.ch[i], fg: this.fg[i], bg: this.bg[i], attr: this.at[i] };
  }

  /** Deep copy (used for transitions / snapshots). */
  clone() {
    const b = new CellBuffer(this.width, this.height);
    b.ch = this.ch.slice();
    b.fg.set(this.fg);
    b.bg.set(this.bg);
    b.at.set(this.at);
    return b;
  }

  /** Copy every cell of a same-sized buffer into this one (fast path). */
  copyFrom(src) {
    if (src.width !== this.width || src.height !== this.height) return this.resize(src.width, src.height).copyFrom(src);
    for (let i = 0; i < src.ch.length; i++) this.ch[i] = src.ch[i];
    this.fg.set(src.fg);
    this.bg.set(src.bg);
    this.at.set(src.at);
    return this;
  }
}

export class View extends Surface {
  constructor(parent, x, y, w, h) {
    super();
    this.parent = parent;
    this.ox = Math.round(x);
    this.oy = Math.round(y);
    this.width = Math.max(0, Math.round(w));
    this.height = Math.max(0, Math.round(h));
  }

  set(x, y, ch, fg, bg, attr) {
    x |= 0; y |= 0;
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return;
    this.parent.set(x + this.ox, y + this.oy, ch, fg, bg, attr);
  }

  get(x, y) {
    x |= 0; y |= 0;
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return null;
    return this.parent.get(x + this.ox, y + this.oy);
  }

  clear(bg = NONE, fg = NONE) {
    this.fill(0, 0, this.width, this.height, ' ', fg, bg, 0);
    return this;
  }
}

sources.prism-term/src/canvas.js:
// Canvas — a sub-cell pixel framebuffer that paints into a cell buffer.
//
// You draw in pixels; `paint()` encodes those pixels into terminal glyphs using
// one of five resolution modes (pixels per cell, W×H):
//
//   braille  2×4  ⣿  8 dots/cell, one color per cell — best for lines, plots, wireframes
//   sextant  2×3  🬗  Unicode 13 legacy-computing blocks, two colors per cell
//   quad     2×2  ▚  quadrant blocks, two colors per cell
//   half     1×2  ▀  half blocks, both pixels keep exact color — best for color fields
//   ascii    1×1  @  luminance ramp, works on anything
//
// So scenes are written once at pixel resolution and degrade gracefully on any
// terminal. Pixel aspect differs per mode (a cell is ~1:2), exposed as `aspect`
// (pixel height ÷ width) so geometry can stay round.
//
// Mono depth (NO_COLOR, pipes, TERM=dumb) has no color to carry a picture, so a
// canvas built with `mono` paints every mode except braille as a luminance ramp
// instead: each cell's ink (contrast against the theme background, coverage-
// weighted) normalized to the canvas's brightest cell, as ' ░▒▓█' (Unicode) or the
// 10-level ASCII_RAMP (7-bit). Braille keeps its dots: they already carry shape.
//
// The NONE color is the transparent pixel: transparent areas leave the target
// buffer untouched, so canvases compose over text, panels and other canvases.

import { NONE, luminance, distance2 } from './color.js';

export const MODES = Object.freeze({
  braille: { sx: 2, sy: 4 },
  sextant: { sx: 2, sy: 3 },
  quad: { sx: 2, sy: 2 },
  half: { sx: 1, sy: 2 },
  ascii: { sx: 1, sy: 1 },
});

export const MODE_NAMES = Object.keys(MODES);

const BRAILLE_BITS = [[0x01, 0x08], [0x02, 0x10], [0x04, 0x20], [0x40, 0x80]];
const QUAD_CHARS = [' ', '▘', '▝', '▀', '▖', '▌', '▞', '▛', '▗', '▚', '▐', '▜', '▄', '▙', '▟', '█'];
const SEXTANT_CHARS = (() => {
  const out = new Array(64);
  for (let m = 0; m < 64; m++) {
    if (m === 0) out[m] = ' ';
    else if (m === 63) out[m] = '█';
    else if (m === 21) out[m] = '▌';
    else if (m === 42) out[m] = '▐';
    else out[m] = String.fromCodePoint(0x1fb00 + m - 1 - (m > 21 ? 1 : 0) - (m > 42 ? 1 : 0));
  }
  return out;
})();
export const ASCII_RAMP = ' .:-=+*#%@';
/** Mono-depth shading ramp for Unicode terminals (blank → full block). */
export const MONO_RAMP = ' ░▒▓█';
const HALF_SHAPES = [' ', '▀', '▄', '█']; // bit 0 = top pixel, bit 1 = bottom
const popcount = (m) => { let c = 0; for (; m; m &= m - 1) c++; return c; };

/**
 * The mono paint hint of a surface: createContext() sets `surface.monoPaint` =
 * { ramp, ref } at mono depth (null otherwise); views / wrappers inherit it from
 * the surface they draw into. So every canvas painted into a mono scene, also
 * ones a facet builds itself (banners, meters), gets the ramp.
 */
export function monoHint(surface) {
  for (let s = surface, i = 0; s && i < 16; s = s.parent || s.inner, i++) if (s.monoPaint !== undefined) return s.monoPaint;
  return null;
}
// Normalization floor: a canvas whose brightest cell has less ink than this is not
// stretched to full blocks (keeps faint fields faint instead of amplifying noise).
const MONO_FLOOR = 0.3;
// 4×4 Bayer matrix, normalized to (0,1), for ordered-dither braille shading.
const BAYER4 = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5].map((v) => (v + 0.5) / 16);

/** Pick the best mode for a kind of content given terminal caps. */
export function pickMode(kind = 'field', caps = {}) {
  if (MODES[kind]) return kind;
  if (caps.unicode === false) return 'ascii';
  if (kind === 'line' || kind === 'dots') return 'braille';
  if (kind === 'hires') return caps.sextant ? 'sextant' : 'quad';
  return 'half';
}

export class Canvas {
  /**
   * @param {number} cols  width in terminal cells
   * @param {number} rows  height in terminal cells
   * @param {object} opts  { mode, dither (braille), threshold (braille), ramp (ascii),
   *                         mono: { ramp, ref }: paint as a luminance ramp (mono depth; see top) }
   */
  constructor(cols, rows, { mode = 'half', dither = false, threshold = 0.08, ramp = ASCII_RAMP, merge = 24, mono = null } = {}) {
    if (!MODES[mode]) throw new Error(`unknown canvas mode "${mode}" (expected ${MODE_NAMES.join('|')})`);
    this.mode = mode;
    // half mode: pixel pairs closer than this (weighted RGB distance²) paint as one
    // background-only cell — invisible on screen, roughly halves bytes on smooth fields.
    this.merge = merge;
    this.dither = dither;
    this.threshold = threshold;
    this.ramp = ramp;
    this.mono = mono && mode !== 'braille' ? { ramp: mono.ramp || MONO_RAMP, ref: mono.ref ?? NONE } : null;
    this.resize(cols, rows);
  }

  resize(cols, rows) {
    const { sx, sy } = MODES[this.mode];
    this.cols = Math.max(0, cols | 0);
    this.rows = Math.max(0, rows | 0);
    this.sx = sx;
    this.sy = sy;
    this.width = this.cols * sx;
    this.height = this.rows * sy;
    this.aspect = (2 * sx) / sy;
    this.px = new Int32Array(this.width * this.height).fill(NONE);
    return this;
  }

  clear(color = NONE) {
    this.px.fill(color);
    return this;
  }

  set(x, y, c) {
    x = Math.floor(x); y = Math.floor(y);
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return;
    this.px[y * this.width + x] = c;
  }

  get(x, y) {
    x = Math.floor(x); y = Math.floor(y);
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return NONE;
    return this.px[y * this.width + x];
  }

  /** Saturating additive plot — overlapping glows brighten instead of overwrite. */
  add(x, y, c) {
    x = Math.floor(x); y = Math.floor(y);
    if (x < 0 || y < 0 || x >= this.width || y >= this.height || c === NONE) return;
    const i = y * this.width + x, o = this.px[i];
    if (o === NONE) { this.px[i] = c; return; }
    const r = Math.min(255, ((o >> 16) & 255) + ((c >> 16) & 255));
    const g = Math.min(255, ((o >> 8) & 255) + ((c >> 8) & 255));
    const b = Math.min(255, (o & 255) + (c & 255));
    this.px[i] = (r << 16) | (g << 8) | b;
  }

  /** Alpha-blend `c` over the existing pixel (a in 0..1). Over transparent, writes c scaled by a. */
  blend(x, y, c, a) {
    x = Math.floor(x); y = Math.floor(y);
    if (x < 0 || y < 0 || x >= this.width || y >= this.height || c === NONE || a <= 0) return;
    const i = y * this.width + x, o = this.px[i] === NONE ? 0 : this.px[i];
    if (a >= 1) { this.px[i] = c; return; }
    const r = ((o >> 16) & 255) + ((((c >> 16) & 255) - ((o >> 16) & 255)) * a);
    const g = ((o >> 8) & 255) + ((((c >> 8) & 255) - ((o >> 8) & 255)) * a);
    const b = (o & 255) + (((c & 255) - (o & 255)) * a);
    this.px[i] = (r << 16) | (g << 8) | (b | 0);
  }

  /** Fill every pixel from fn(x, y) → color. */
  shade(fn) {
    const { width: W, height: H, px } = this;
    for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i++) px[i] = fn(x, y);
    return this;
  }

  /** Multiply every pixel's brightness by k (trails / motion blur). Pixels below `floor` become transparent. */
  fade(k, floor = 6) {
    const px = this.px;
    for (let i = 0; i < px.length; i++) {
      const c = px[i];
      if (c === NONE) continue;
      const r = ((c >> 16) & 255) * k, g = ((c >> 8) & 255) * k, b = (c & 255) * k;
      px[i] = r < floor && g < floor && b < floor ? NONE : (r << 16) | (g << 8) | (b | 0);
    }
    return this;
  }

  // ── primitives ───────────────────────────────────────────────────────────

  line(x0, y0, x1, y1, c) {
    x0 = Math.round(x0); y0 = Math.round(y0); x1 = Math.round(x1); y1 = Math.round(y1);
    const dx = Math.abs(x1 - x0), dy = -Math.abs(y1 - y0);
    const stx = x0 < x1 ? 1 : -1, sty = y0 < y1 ? 1 : -1;
    let err = dx + dy;
    // Guard against absurd coordinates (e.g. a projected vertex behind the camera).
    for (let n = 0; n < 1e5; n++) {
      this.set(x0, y0, c);
      if (x0 === x1 && y0 === y1) break;
      const e2 = 2 * err;
      if (e2 >= dy) { err += dy; x0 += stx; }
      if (e2 <= dx) { err += dx; y0 += sty; }
    }
    return this;
  }

  /** Polyline through [[x,y], …]. */
  path(points, c, closed = false) {
    for (let i = 1; i < points.length; i++) this.line(points[i - 1][0], points[i - 1][1], points[i][0], points[i][1], c);
    if (closed && points.length > 2) this.line(points.at(-1)[0], points.at(-1)[1], points[0][0], points[0][1], c);
    return this;
  }

  rect(x, y, w, h, c, fill = false) {
    if (fill) {
      for (let yy = Math.max(0, Math.floor(y)); yy < Math.min(this.height, Math.floor(y + h)); yy++)
        for (let xx = Math.max(0, Math.floor(x)); xx < Math.min(this.width, Math.floor(x + w)); xx++) this.px[yy * this.width + xx] = c;
      return this;
    }
    return this.path([[x, y], [x + w - 1, y], [x + w - 1, y + h - 1], [x, y + h - 1]], c, true);
  }

  /** Ellipse with radii rx, ry (pass ry = rx / aspect for a visually round circle). */
  ellipse(cx, cy, rx, ry, c, fill = false) {
    if (fill) {
      for (let y = Math.ceil(cy - ry); y <= Math.floor(cy + ry); y++) {
        const t = (y - cy) / ry, half = rx * Math.sqrt(Math.max(0, 1 - t * t));
        for (let x = Math.ceil(cx - half); x <= Math.floor(cx + half); x++) this.set(x, y, c);
      }
      return this;
    }
    const steps = Math.max(16, Math.ceil(2 * Math.PI * Math.max(rx, ry)));
    let px = cx + rx, py = cy;
    for (let i = 1; i <= steps; i++) {
      const a = (i / steps) * Math.PI * 2;
      const nx = cx + Math.cos(a) * rx, ny = cy + Math.sin(a) * ry;
      this.line(px, py, nx, ny, c);
      px = nx; py = ny;
    }
    return this;
  }

  /** Aspect-corrected circle: radius r in horizontal pixels. */
  circle(cx, cy, r, c, fill = false) {
    return this.ellipse(cx, cy, r, r / this.aspect, c, fill);
  }

  /** Scanline-filled polygon ([[x,y], …], even-odd rule). */
  polygon(points, c) {
    if (points.length < 3) return this;
    let minY = Infinity, maxY = -Infinity;
    for (const p of points) { if (p[1] < minY) minY = p[1]; if (p[1] > maxY) maxY = p[1]; }
    const y0 = Math.max(0, Math.ceil(minY)), y1 = Math.min(this.height - 1, Math.floor(maxY));
    const xs = [];
    for (let y = y0; y <= y1; y++) {
      xs.length = 0;
      const sy = y + 0.5;
      for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
        const [xi, yi] = points[i], [xj, yj] = points[j];
        if ((yi > sy) !== (yj > sy)) xs.push(xi + ((sy - yi) / (yj - yi)) * (xj - xi));
      }
      xs.sort((a, b) => a - b);
      for (let k = 0; k + 1 < xs.length; k += 2) {
        const xa = Math.max(0, Math.ceil(xs[k] - 0.5)), xb = Math.min(this.width - 1, Math.floor(xs[k + 1] - 0.5));
        for (let x = xa; x <= xb; x++) this.px[y * this.width + x] = c;
      }
    }
    return this;
  }

  triangle(a, b, c, color) {
    return this.polygon([a, b, c], color);
  }

  /** Quadratic/cubic Bézier through control points [[x,y]×3|4]. */
  bezier(pts, c, steps = 0) {
    const n = steps || Math.max(8, Math.ceil(Math.hypot(pts.at(-1)[0] - pts[0][0], pts.at(-1)[1] - pts[0][1])));
    const out = [];
    for (let i = 0; i <= n; i++) {
      const t = i / n, u = 1 - t;
      if (pts.length === 3) out.push([u * u * pts[0][0] + 2 * u * t * pts[1][0] + t * t * pts[2][0], u * u * pts[0][1] + 2 * u * t * pts[1][1] + t * t * pts[2][1]]);
      else out.push([
        u * u * u * pts[0][0] + 3 * u * u * t * pts[1][0] + 3 * u * t * t * pts[2][0] + t * t * t * pts[3][0],
        u * u * u * pts[0][1] + 3 * u * u * t * pts[1][1] + 3 * u * t * t * pts[2][1] + t * t * t * pts[3][1],
      ]);
    }
    return this.path(out, c);
  }

  /** Composite another canvas (same mode or not) at pixel offset; NONE pixels are skipped. */
  draw(src, dx = 0, dy = 0) {
    for (let y = 0; y < src.height; y++)
      for (let x = 0; x < src.width; x++) {
        const c = src.px[y * src.width + x];
        if (c !== NONE) this.set(x + dx, y + dy, c);
      }
    return this;
  }

  // ── encoding ─────────────────────────────────────────────────────────────

  /**
   * Encode pixels into glyphs on `target` (any Surface) with the top-left cell
   * at (ox, oy). Transparent cells are left untouched.
   */
  paint(target, ox = 0, oy = 0) {
    const mono = this.mono || (this.mode !== 'braille' ? monoHint(target) : null);
    if (mono) return this._paintMono(target, ox, oy, mono);
    switch (this.mode) {
      case 'half': return this._paintHalf(target, ox, oy);
      case 'braille': return this._paintBraille(target, ox, oy);
      case 'ascii': return this._paintAscii(target, ox, oy);
      default: return this._paintBlocks(target, ox, oy, this.mode === 'quad' ? QUAD_CHARS : SEXTANT_CHARS);
    }
  }

  _paintHalf(target, ox, oy) {
    const { cols, rows, width: W, px, merge } = this;
    for (let cy = 0; cy < rows; cy++) {
      const r0 = 2 * cy * W, r1 = r0 + W;
      for (let cx = 0; cx < cols; cx++) {
        const top = px[r0 + cx], bot = px[r1 + cx];
        if (top === NONE && bot === NONE) continue;
        if (top === bot || (top !== NONE && bot !== NONE && merge > 0 && distance2(top, bot) <= merge)) target.set(cx + ox, cy + oy, ' ', undefined, top);
        else if (top === NONE) target.set(cx + ox, cy + oy, '▄', bot);
        else if (bot === NONE) target.set(cx + ox, cy + oy, '▀', top);
        else target.set(cx + ox, cy + oy, '▀', top, bot);
      }
    }
    return target;
  }

  _paintBraille(target, ox, oy) {
    const { cols, rows, width: W, px, dither, threshold } = this;
    for (let cy = 0; cy < rows; cy++) {
      for (let cx = 0; cx < cols; cx++) {
        let mask = 0, r = 0, g = 0, b = 0, n = 0;
        for (let dy = 0; dy < 4; dy++) {
          const row = (cy * 4 + dy) * W + cx * 2;
          for (let dx = 0; dx < 2; dx++) {
            const c = px[row + dx];
            if (c === NONE) continue;
            if (dither) {
              const x = cx * 2 + dx, y = cy * 4 + dy;
              if (luminance(c) <= BAYER4[(y & 3) * 4 + (x & 3)]) continue;
            } else if (threshold > 0 && luminance(c) < threshold) continue;
            mask |= BRAILLE_BITS[dy][dx];
            r += (c >> 16) & 255; g += (c >> 8) & 255; b += c & 255; n++;
          }
        }
        if (!mask) continue;
        let fr = r / n, fg = g / n, fb = b / n;
        if (dither) {
          // Dithering already encodes brightness as dot density — push the hue to full value.
          const m = Math.max(fr, fg, fb, 1), k = 255 / m;
          fr *= k; fg *= k; fb *= k;
        }
        target.set(cx + ox, cy + oy, String.fromCharCode(0x2800 + mask), (fr << 16) | (fg << 8) | (fb | 0));
      }
    }
    return target;
  }

  _paintAscii(target, ox, oy) {
    const { cols, rows, width: W, px, ramp } = this;
    const last = ramp.length - 1;
    for (let cy = 0; cy < rows; cy++) {
      for (let cx = 0; cx < cols; cx++) {
        const c = px[cy * W + cx];
        if (c === NONE) continue;
        const ch = ramp[Math.min(last, Math.max(1, Math.round(luminance(c) * last)))];
        target.set(cx + ox, cy + oy, ch, c);
      }
    }
    return target;
  }

  // Mono: each pixel's ink (|luminance − background luminance|) is normalized to
  // the canvas's brightest pixel (at least MONO_FLOOR, so faint art stays faint);
  // a fully opaque canvas (a color field) is also stretched up from its darkest
  // pixel so mid-luminance pictures use the whole ramp. Then per cell:
  //   • all pixels "no ink" or "full ink" → the shape glyph (▀ ▄ █ / quadrant /
  //     sextant mask), so banners, bars and outlines stay crisp;
  //   • an edge cell (some pixels transparent) whose visible pixels are bright →
  //     the shape of the visible pixels (letters keep their half-block edges);
  //   • anything else → the ramp glyph of the cell's average (shading).
  // fg is the terminal default; bg is left as is.
  _paintMono(target, ox, oy, mono) {
    const { cols, rows, width: W, px, sx, sy, mode } = this;
    const { ramp, ref } = mono;
    const refL = ref === NONE || ref === undefined ? 0 : luminance(ref);
    const n = sx * sy, last = ramp.length - 1;
    const shapes = mode === 'half' ? HALF_SHAPES : mode === 'quad' ? QUAD_CHARS : mode === 'sextant' ? SEXTANT_CHARS : null;
    const N = px.length;
    const ink = this._monoInk?.length === N ? this._monoInk : (this._monoInk = new Float32Array(N));
    let lo = Infinity, hi = 0;
    for (let i = 0; i < N; i++) {
      const c = px[i];
      if (c === NONE) { ink[i] = -1; continue; }
      const v = Math.abs(luminance(c) - refL);
      ink[i] = v;
      if (v < lo) lo = v;
      if (v > hi) hi = v;
    }
    if (hi === 0 && lo === Infinity) return target; // fully transparent
    let transparent = false;
    for (let i = 0; i < N; i++) if (ink[i] < 0) { transparent = true; break; }
    const top = Math.max(hi, MONO_FLOOR);
    const bot = transparent ? 0 : Math.min(Math.max(0, lo), top - MONO_FLOOR);
    const k = 1 / (top - bot);
    for (let cy = 0; cy < rows; cy++) {
      for (let cx = 0; cx < cols; cx++) {
        let sum = 0, opaque = 0, full = 0, seen = 0, seenSum = 0, binary = true;
        for (let dy = 0, j = 0; dy < sy; dy++) {
          const row = (cy * sy + dy) * W + cx * sx;
          for (let dx = 0; dx < sx; dx++, j++) {
            const v = ink[row + dx];
            if (v < 0) continue;
            opaque++;
            const q = Math.min(1, Math.max(0, (v - bot) * k));
            sum += q;
            const lv = Math.round(q * last);
            if (lv === last) full |= 1 << j;
            else if (lv !== 0) binary = false;
            if (lv > 0) { seen |= 1 << j; seenSum += q; }
          }
        }
        if (!opaque) continue;
        let ch;
        if (shapes && binary) ch = shapes[full];
        else if (shapes && opaque < n && seen && seenSum / popcount(seen) >= 0.5) ch = shapes[seen];
        else ch = ramp[Math.min(last, Math.round((sum / n) * last))];
        target.set(cx + ox, cy + oy, ch, NONE);
      }
    }
    return target;
  }

  // Two-color block encoding (quad 2×2 / sextant 2×3): split the cell's pixels
  // into two clusters seeded by its most distant pair, then pick the glyph whose
  // fg mask matches cluster A. Transparent pixels are always "background".
  _paintBlocks(target, ox, oy, chars) {
    const { cols, rows, width: W, px, sx, sy } = this;
    const n = sx * sy;
    const cell = new Int32Array(n);
    for (let cy = 0; cy < rows; cy++) {
      for (let cx = 0; cx < cols; cx++) {
        let opaque = 0;
        for (let dy = 0, k = 0; dy < sy; dy++)
          for (let dx = 0; dx < sx; dx++, k++) {
            const c = px[(cy * sy + dy) * W + cx * sx + dx];
            cell[k] = c;
            if (c !== NONE) opaque++;
          }
        if (!opaque) continue;

        if (opaque < n) {
          let mask = 0, r = 0, g = 0, b = 0;
          for (let k = 0; k < n; k++) {
            const c = cell[k];
            if (c === NONE) continue;
            mask |= 1 << k;
            r += (c >> 16) & 255; g += (c >> 8) & 255; b += c & 255;
          }
          target.set(cx + ox, cy + oy, chars[mask], ((r / opaque) << 16) | ((g / opaque) << 8) | ((b / opaque) | 0));
          continue;
        }

        let ia = 0, ib = 0, best = -1;
        for (let i = 0; i < n; i++)
          for (let j = i + 1; j < n; j++) {
            const d = distance2(cell[i], cell[j]);
            if (d > best) { best = d; ia = i; ib = j; }
          }
        if (best < 64) {
          // Visually uniform cell: a plain background is cheapest and gap-free.
          let r = 0, g = 0, b = 0;
          for (let k = 0; k < n; k++) { r += (cell[k] >> 16) & 255; g += (cell[k] >> 8) & 255; b += cell[k] & 255; }
          target.set(cx + ox, cy + oy, ' ', undefined, ((r / n) << 16) | ((g / n) << 8) | ((b / n) | 0));
          continue;
        }
        const ca = cell[ia], cb = cell[ib];
        let mask = 0, ar = 0, ag = 0, ab = 0, an = 0, br = 0, bg = 0, bb = 0, bn = 0;
        for (let k = 0; k < n; k++) {
          const c = cell[k];
          if (distance2(c, ca) <= distance2(c, cb)) {
            mask |= 1 << k; ar += (c >> 16) & 255; ag += (c >> 8) & 255; ab += c & 255; an++;
          } else {
            br += (c >> 16) & 255; bg += (c >> 8) & 255; bb += c & 255; bn++;
          }
        }
        const fgc = ((ar / an) << 16) | ((ag / an) << 8) | ((ab / an) | 0);
        const bgc = ((br / bn) << 16) | ((bg / bn) << 8) | ((bb / bn) | 0);
        target.set(cx + ox, cy + oy, chars[mask], fgc, bgc);
      }
    }
    return target;
  }
}

