// A voice-assistant style status orb on a hi-res canvas: it breathes when
// idle, ripples while listening, swirls while thinking, rings while speaking.
import { ATTR, glyphs, phase, mix, span } from './_ai.js';

// [start, state, tone, caption]
const STATES = [
  [0, 'idle', 'muted', 'Ready'], [1.6, 'listening', 'info', 'Listening'], [3.4, 'thinking', 'accent', 'Thinking'],
  [5.6, 'speaking', 'pos', 'Speaking'], [7.6, 'idle', 'muted', 'Ready'],
];

export default {
  id: 'ai-status-orb',
  title: 'Status Orb',
  category: 'Thinking States',
  description: 'An assistant status orb on a hi-res canvas that breathes when idle, ripples while listening, swirls while thinking and pulses rings while speaking.',
  tags: ['orb', 'voice', 'status', 'assistant', 'canvas'],
  kind: 'scene',
  canvas: 'hires',
  size: { w: 36, h: 14 },
  minSize: { w: 20, h: 8 },
  loop: 9,
  color: 'truecolor',
  order: 40,
  setup(ctx) {
    const th = ctx.theme;
    let cv = null;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx);
      const p = phase(t, 9);
      let k = 0;
      STATES.forEach(([at], i) => { if (p >= at) k = i; });
      const [at, state, tone, caption] = STATES[k];
      const prevTone = STATES[Math.max(0, k - 1)][2];
      const blendIn = span(p, at, at + 0.4);
      const col = mix(th[prevTone], th[tone], blendIn);
      if (!cv || cv.cols !== W || cv.rows !== H - 1) cv = ctx.canvas('hires', { cols: W, rows: H - 1 });
      cv.clear();
      const cx = cv.width / 2, cy = cv.height / 2;
      // Pixels aren't square: measure y in x-pixel units so the orb reads as a circle.
      const ay = cv.aspect;
      const R = Math.min(cv.width / 2, (cv.height / 2) * ay) * 0.62;
      const w = (n) => (2 * Math.PI * n) / 9;
      for (let y = 0; y < cv.height; y++) {
        for (let x = 0; x < cv.width; x++) {
          const dx = x - cx, dy = (y - cy) * ay;
          const d = Math.hypot(dx, dy), a = Math.atan2(dy, dx);
          let r = R, glow = 0;
          if (state === 'idle') r = R * (0.86 + 0.06 * Math.sin(w(3) * p));
          if (state === 'listening') { r = R * (0.9 + 0.05 * Math.sin(a * 6 + w(9) * p)); glow = Math.max(0, 1 - Math.abs(((d - R * 1.05 - ((p * 9) % 6)) / 2))) * 0.6; }
          if (state === 'thinking') r = R * (0.88 + 0.07 * Math.sin(a * 3 - w(6) * p) * Math.cos(a * 2 + w(3) * p));
          if (state === 'speaking') { r = R * (0.88 + 0.08 * Math.abs(Math.sin(w(13) * p))); glow = Math.max(0, 1 - Math.abs(d - R * (1.15 + 0.25 * ((p * 1.5) % 1))) / 1.4) * (1 - ((p * 1.5) % 1)); }
          if (d <= r) {
            // Lit from the upper left, with a swirl while thinking.
            const shade = 0.55 + 0.45 * Math.max(0, 1 - Math.hypot(dx + r * 0.35, dy + r * 0.35) / (r * 1.4));
            const swirl = state === 'thinking' ? 0.18 * Math.sin(a * 2 + d * 0.35 - w(9) * p) : 0;
            cv.set(x, y, mix(th.bg, col, Math.min(1, shade + swirl)));
          } else if (glow > 0.05) cv.set(x, y, mix(th.bg, col, glow * 0.7));
        }
      }
      cv.paint(b);
      const label = state === 'thinking' || state === 'listening' ? `${caption}${g.ellipsis}` : caption;
      b.text(Math.max(0, Math.floor((W - label.length) / 2)), H - 1, label, th[tone], undefined, ATTR.BOLD);
    };
  },
};

sources.prism-term/src/facets/ai/structured-outp:
// Structured output streaming: JSON arrives token by token, pretty-printed
// with syntax color, while a schema checklist ticks off completed fields.
import { ATTR, glyphs, uni, phase, fit, reveal, stringWidth } from './_ai.js';

const OBJ = {
  incident: 'INC-3127', severity: 'sev2', service: 'checkout-api', cause: 'db pool starvation', confidence: 0.87,
  actions: [{ type: 'config', set: 'DB_POOL_SIZE=40' }, { type: 'alert', on: 'pool_wait_ms > 200' }],
  needs_approval: true,
};
// Pretty-printed, with each action object kept on one line.
const JSON_TEXT = JSON.stringify(OBJ, null, 2).replace(/\{\n\s+"type"/g, '{ "type"').replace(/,\n\s+"(set|on)"/g, ', "$1"').replace(/"\n\s+\}/g, '" }');
const FIELDS = Object.keys(OBJ);
// Where each top-level field's value ends in the text (it's complete once revealed past this).
const ENDS = FIELDS.map((k, i) => {
  const at = JSON_TEXT.indexOf(`"${k}"`);
  const next = i + 1 < FIELDS.length ? JSON_TEXT.indexOf(`"${FIELDS[i + 1]}"`) : JSON_TEXT.lastIndexOf('}');
  return [at, next];
});

export default {
  id: 'ai-structured-output',
  title: 'Structured Output',
  category: 'Token Streams',
  description: 'Structured output streaming in: JSON arrives token by token, pretty-printed with syntax color, while a schema checklist ticks off each completed field.',
  tags: ['json', 'structured output', 'schema', 'streaming', 'tool use'],
  kind: 'text',
  size: { w: 72, h: 14 },
  minSize: { w: 44, h: 10 },
  loop: 9,
  color: '16',
  order: 40,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9);
      const r = reveal(JSON_TEXT, p, 0.3, 30);
      const shown = r.text;
      const side = W >= 64;
      const jw = side ? W - 20 : W;
      const lines = shown.split('\n');
      const first = Math.max(0, lines.length - (H - 1));
      lines.slice(first).forEach((line, y) => {
        let x = 0;
        // Tokenize one line of JSON for color.
        for (const m of line.matchAll(/("(?:[^"\\]|\\.)*"?)(\s*:)?|(-?\d+(?:\.\d+)?)|(true|false|null)|([{}[\],])|(\s+)|(.)/g)) {
          const [tok, str, colon, num, lit, punct] = m;
          let c = th.ink;
          if (str) c = colon ? th.accent : th.pos;
          else if (num) c = th.warn;
          else if (lit) c = th.crit;
          else if (punct) c = th.dim;
          const room = Math.max(0, jw - x);
          if (!room) break;
          const piece = stringWidth(tok) <= room ? tok : tok.slice(0, room);
          if (str && colon) { x = b.text(x, y, piece.slice(0, piece.length - colon.length), c); x = b.text(x, y, piece.slice(piece.length - colon.length), th.dim); }
          else x = b.text(x, y, piece, c);
        }
      });
      if (!r.done && lines.length) {
        const ly = lines.length - 1 - first;
        b.set(Math.min(jw - 1, lines[lines.length - 1].length), ly, u ? '▍' : '_', th.accent);
      }
      // Schema checklist.
      const done = FIELDS.map((_, i) => shown.length >= ENDS[i][1]);
      const started = FIELDS.map((_, i) => shown.length > ENDS[i][0]);
      if (side) {
        const sx = W - 18;
        for (let y = 0; y < H - 1; y++) b.set(sx - 2, y, u ? '│' : '|', th.line);
        b.text(sx, 0, fit('IncidentSummary', W - sx, undefined, ctx), th.ink, undefined, ATTR.BOLD);
        FIELDS.forEach((k, i) => {
          const y = 2 + i;
          if (y >= H - 1) return;
          const mark = done[i] ? g.check : started[i] ? g.tri : g.ring;
          b.text(sx, y, mark, done[i] ? th.pos : started[i] ? th.accent : th.dim, undefined, ATTR.BOLD);
          b.text(sx + 2, y, fit(k, W - sx - 2, undefined, ctx).trimEnd(), done[i] ? th.ink : th.muted);
        });
      }
      const n = done.filter(Boolean).length;
      const msg = r.done ? `${g.check} valid against IncidentSummary ${g.mid} ${FIELDS.length}/${FIELDS.length} fields ${g.mid} needs_approval: true`
        : `streaming ${g.mid} ${n}/${FIELDS.length} fields ${g.mid} ${r.n}/${r.total} tokens`;
      b.text(0, H - 1, fit(msg, W, undefined, ctx), r.done ? th.pos : th.muted);
    };
  },
};

sources.prism-term/src/facets/ai/subagent-tree.j:
// An orchestrator fans work out to subagents shown as a live tree, each with its status, current action and
// token use; as each finishes, its result folds back into the parent.
import { ATTR, uni, phase, spin, span } from './_ai.js';
import { sub, mark, runs, putR, kilo, fitRows, beat, BEATS } from './_kit7.js';

const LOOP = 14, DONE = 9.8, FOLD = 0.8, R0 = 12.8, R1 = 13.5;
// [name, spawned, starts, ends, tokens, actions [[at, text]], result, summary]
const AGENTS = [
  ['researcher', 0.4, 0.4, 3.6, 12400, [[0.4, 'reading 4 files'], [1.8, 'grepping for CreateOrder']], '3 call sites found', '3 call sites in api/ and jobs/'],
  ['implementer', 0.7, 3.8, 7.0, 21700, [[3.8, 'editing handlers.go'], [5.2, 'editing jobs/settle.go']], '3 files changed', 'patched 3 files, +41 -12'],
  ['tester', 1.0, 7.2, 9.2, 6200, [[7.2, 'running go test ./...']], '18 passed', '18 passed, 0 failed'],
];
const TOTAL = AGENTS.reduce((n, a) => n + a[4], 0);

export default {
  id: 'ai-subagent-tree',
  since: '0.3.0',
  title: 'Subagent Tree',
  category: 'Agents & Pipelines',
  description: 'An orchestrator fans work out to subagents in a live tree with status, current action and token use; each result folds back into the parent as it finishes.',
  tags: ['subagents', 'orchestrator', 'multi-agent', 'delegation', 'tree', 'agent'],
  kind: 'tui',
  size: { w: 64, h: 10 },
  minSize: { w: 44, h: 7 },
  loop: LOOP,
  color: '16',
  order: 200,
  setup(ctx) {
    const th = ctx.theme;
    const draw = (b, p) => {
      const W = b.width, H = b.height, u = uni(ctx), MID = u ? '·' : '-';
      const running = AGENTS.filter(([, sp, a, e]) => p >= sp && p >= a && p < e).length;
      const rows = fitRows([{ k: 'head' }, ...AGENTS.map((a, i) => ({ k: 'agent', i })), { k: 'gap', drop: 2 }, ...AGENTS.map((a, i) => ({ k: 'sum', i, drop: 1 }))], H);
      const showTok = W >= 52, showAct = W >= 50;
      rows.forEach((r, y) => {
        if (r.k === 'head') {
          const done = p >= DONE, x = done ? mark(ctx, b, 0, y, '✔', '+', th.pos) : mark(ctx, b, 0, y, '◆', '*', th.accent);
          runs(ctx, b, x + 1, y, W - x - 1, [['orchestrator', th.ink, ATTR.BOLD], [done ? ` ${MID} done ${MID} ${kilo(TOTAL)} tok` : ` ${MID} 3 subagents ${MID} ${running} running`, th.ink]]);
        } else if (r.k === 'agent') {
          const [name, spawned, a, e, tok, acts, result] = AGENTS[r.i];
          if (p < spawned) return;
          b.text(0, y, r.i < AGENTS.length - 1 ? (u ? '├─' : '|-') : (u ? '└─' : '`-'), th.muted);
          b.text(3, y, name, th.ink, undefined, ATTR.BOLD);
          let x = 16;
          if (p < a) { x = mark(ctx, b, x, y, '◌', '.', th.muted); runs(ctx, b, x + 1, y, W - x - 1, [[`waiting for ${AGENTS[r.i - 1][0]}`, sub(th), 0, true]]); return; }
          const live = p < e;
          x = live ? (b.set(x, y, spin(ctx, p + r.i * 0.3), th.accent, undefined, ATTR.BOLD), x + 1) : mark(ctx, b, x, y, '✔', '+', th.pos);
          const tw = showTok ? 10 : 0, act = !live ? result : showAct ? acts.filter(([t]) => p >= t).pop()[1] : 'working';
          runs(ctx, b, x + 1, y, W - x - 1 - tw, [[act, live && !showAct ? sub(th) : th.ink]]);
          if (showTok) putR(b, W, y, `${kilo(tok * span(p, a, e))} tok`, sub(th));
        } else if (r.k === 'sum' && p >= AGENTS[r.i][3] + FOLD) {
          const x = mark(ctx, b, 0, y, '↳', '>', th.muted);
          runs(ctx, b, x + 1, y, W - x - 1, [[`${AGENTS[r.i][0]}: `, th.ink, ATTR.BOLD], [AGENTS[r.i][7], th.ink]]);
        }
      });
    };
    const plan = BEATS.collapse(0);
    return (t) => { const p = phase(t, LOOP); if (!beat(ctx, ctx.buffer, draw, p, R0, R1, plan)) draw(ctx.buffer, p >= R1 ? 0 : p); };
  },
};

sources.prism-term/src/facets/ai/task-plan.js:
// An agent's task plan as a live checklist: items move from pending to
// in progress (spinner, bold) to done (ticked, dimmed), with timings.
import { ATTR, glyphs, uni, phase, fit, spin } from './_ai.js';

// [task, start, end] in seconds; the approval step waits on a human.
const TASKS = [
  ['Reproduce the p99 spike from traces', 0.3, 1.4],
  ['Correlate p99 with deploys and pool metrics', 1.4, 2.9],
  ['Draft a fix: DB_POOL_SIZE 20 -> 40', 2.9, 4.0],
  ['Get approval from on-call', 4.0, 5.6],
  ['Apply and verify p99 < 300ms', 5.6, 7.4],
];

export default {
  id: 'ai-task-plan',
  title: 'Task Plan',
  category: 'Agents & Pipelines',
  description: 'An agent\'s plan as a live checklist: each task moves from pending to in progress with a spinner to done and dimmed, with timings and a waiting-on-human step.',
  tags: ['plan', 'todo', 'checklist', 'agent', 'progress'],
  kind: 'tui',
  size: { w: 60, h: 8 },
  minSize: { w: 40, h: 7 },
  loop: 9,
  color: '16',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9);
      const n = TASKS.filter(([, , z]) => p >= z).length;
      b.text(0, 0, u ? '●' : '*', n === TASKS.length ? th.pos : th.accent, undefined, ATTR.BOLD);
      const x = b.text(2, 0, 'Plan', th.ink, undefined, ATTR.BOLD);
      b.text(x + 1, 0, `${n}/${TASKS.length} done`, th.muted);
      TASKS.forEach(([task, a, z], i) => {
        const y = 1 + i;
        if (y >= H - (H > TASKS.length + 2 ? 1 : 0)) return;
        const state = p >= z ? 'done' : p >= a ? 'run' : 'todo';
        const waiting = state === 'run' && i === 3;
        b.text(2, y, i === 0 ? (u ? '⎿' : '\\_') : '  ', th.dim);
        const mark = state === 'done' ? g.check : state === 'run' ? (waiting ? (u ? '‖' : '=') : spin(ctx, t)) : (u ? '☐' : '[ ]');
        const mx = b.text(5, y, mark, state === 'done' ? th.pos : waiting ? th.warn : state === 'run' ? th.accent : th.dim, undefined, ATTR.BOLD);
        const label = u ? task.replace('->', '→') : task;
        const tail = state === 'done' ? `${(z - a).toFixed(1)}s` : waiting ? 'waiting on you' : state === 'run' ? `${(p - a).toFixed(1)}s` : '';
        const room = W - mx - 2 - (tail ? tail.length + 1 : 0);
        b.text(mx + 1, y, fit(label, Math.max(0, room), undefined, ctx).trimEnd(),
          state === 'done' ? th.dim : state === 'run' ? th.ink : th.muted, undefined,
          state === 'done' ? ATTR.STRIKE : state === 'run' ? ATTR.BOLD : 0);
        if (tail) b.text(W - tail.length, y, tail, waiting ? th.warn : th.dim);
      });
      if (H > TASKS.length + 2) {
        const msg = n === TASKS.length ? `${g.check} incident mitigated in 7.1s of agent time` : `${g.mid} ctrl+t to hide plan`;
        b.text(0, H - 1, fit(msg, W, undefined, ctx), n === TASKS.length ? th.pos : th.dim);
      }
    };
  },
};

