// A tool call fails validation, the assistant notes why, lists the directory to find the right path, and the
// corrected call succeeds.
import { ATTR, uni, phase, spin } from './_ai.js';
import { sub, mark, runs, fitRows, beat, BEATS } from './_kit7.js';

const LOOP = 12, REASON = 2.0, R0 = 10.8, R1 = 11.5;
// [starts, ends, ok, tool, arg key, path, result]
const CALLS = [
  [0.4, 1.4, false, 'read_file', 'path', 'src/handler.go', 'path not found: src/handler.go'],
  [2.6, 3.4, true, 'list_dir', 'path', 'src/', '6 entries: api/ db/ http/ jobs/ retry/ main.go'],
  [4.0, 5.0, true, 'read_file', 'path', 'src/api/handlers.go', '142 lines; CreateOrder at L37'],
];

export default {
  id: 'ai-tool-retry',
  since: '0.3.0',
  title: 'Tool Error & Fix',
  category: 'Tool Calls',
  description: 'A tool call fails validation on a wrong path; the assistant notes the error, lists the directory, and the corrected call succeeds.',
  tags: ['tool calls', 'error', 'retry', 'self-correction', 'agent', 'function calling'],
  kind: 'tui',
  size: { w: 64, h: 10 },
  minSize: { w: 44, h: 7 },
  loop: LOOP,
  color: '16',
  order: 200,
  setup(ctx) {
    const th = ctx.theme;
    const draw = (b, p) => {
      const W = b.width, H = b.height, u = uni(ctx), ELBOW = u ? '⎿' : '\\_';
      // rows keep the places the finished trace gives them, so nothing reflows as calls land
      const list = [{ k: 'ask', at: 0, drop: 2 }];
      CALLS.forEach((c, i) => {
        if (i) list.push({ k: 'gap', drop: 4 });
        list.push({ k: 'call', c, at: c[0] }, { k: 'result', c, at: c[1] });
        if (i === 0) list.push({ k: 'gap', drop: 4 }, { k: 'reason', at: REASON, drop: 3 });
      });
      fitRows(list, H).forEach((r, y) => {
        if (r.at === undefined || p < r.at) return;
        if (r.k === 'ask') { const x = mark(ctx, b, 0, y, '›', '>', th.accent); runs(ctx, b, x + 1, y, W - x - 1, [['where is CreateOrder handled?', th.ink, ATTR.BOLD]]); }
        else if (r.k === 'call') {
          const [a, e, ok, tool, key, path] = r.c;
          const x = p < e ? (b.set(0, y, spin(ctx, p + a), th.accent, undefined, ATTR.BOLD), 1) : ok ? mark(ctx, b, 0, y, '✔', '+', th.pos) : mark(ctx, b, 0, y, '✖', 'x', th.neg);
          runs(ctx, b, x + 1, y, W - x - 1, [[tool, th.ink, ATTR.BOLD], [`  ${key}=`, th.ink], [path, th.ink, ATTR.BOLD]]);
        } else if (r.k === 'result') {
          b.text(2, y, ELBOW, th.muted);
          runs(ctx, b, 2 + ELBOW.length + 1, y, W - ELBOW.length - 3, [[r.c[6], th.ink]]);
        } else if (r.k === 'reason') {
          const x = mark(ctx, b, 0, y, '↳', '=>', th.muted);
          runs(ctx, b, x + 1, y, W - x - 1, [['wrong path; listing src/ to find the handler', sub(th), ATTR.ITALIC]]);
        }
      });
    };
    // the cards fold up under the question into a one-line summary, which holds, then everything clears
    const plan = (k, info) => {
      if (k >= 0.9) return BEATS.clear()(1, info);
      const fold = BEATS.collapse(0)(Math.min(1, k / 0.4) * 0.65, info), u = uni(ctx);
      if (k >= 0.4) fold.over = [{ x: 0, y: 1, text: u ? '✔' : '+', fg: th.pos, attr: ATTR.BOLD }, { x: 2, y: 1, text: `3 tool calls ${u ? '·' : '-'} 1 retried`, fg: th.ink, attr: ATTR.BOLD }];
      if (k >= 0.8) fold.rows[0] = null;
      return fold;
    };
    return (t) => { const p = phase(t, LOOP); if (!beat(ctx, ctx.buffer, draw, p, R0, R1, plan)) draw(ctx.buffer, p >= R1 ? 0 : p); };
  },
};

sources.prism-term/src/facets/ai/tool-server.js:
// Connecting to tool servers: handshakes resolve, each lists its tools, one fails auth with a 401 and reconnects
// after a token refresh.
import { ATTR, uni, phase, spin } from './_ai.js';
import { sub, inv, mark, runs, flow, fitRows } from './_kit7.js';

const LOOP = 14, R0 = 12.8, R1 = 13.5, PICK = 6.2;
// [name, address, connects at, tools, fails auth at]
const SERVERS = [
  ['files', './bin/fs-tools', 1.2, ['read_file', 'write_file', 'list_dir', 'move', 'delete', 'search', 'apply_patch', 'stat', 'glob', 'diff', 'tail', 'watch']],
  ['tickets', 'tickets.internal', 2.4, ['create_ticket', 'get_ticket', 'update_ticket', 'search_tickets', 'add_comment']],
  ['metrics', 'metrics.internal', 5.4, ['query_metrics', 'list_series', 'get_alerts', 'silence_alert', 'describe_slo', 'top_errors', 'compare_windows', 'annotate'], 3.0],
];

export default {
  id: 'ai-tool-server',
  since: '0.3.0',
  title: 'Tool Server Connect',
  category: 'Tool Calls',
  description: 'Connecting to tool servers: handshakes resolve and list their tools, one fails auth with a 401 and reconnects after a token refresh.',
  tags: ['tool server', 'connection', 'auth', 'tools', 'handshake', 'agent'],
  kind: 'tui',
  size: { w: 64, h: 10 },
  minSize: { w: 44, h: 7 },
  loop: LOOP,
  color: '16',
  order: 240,
  setup(ctx) {
    const th = ctx.theme;
    const draw = (b, at) => {
      const kb = at >= R0 && at < R1 ? (at - R0) / (R1 - R0) : -1;
      if (kb >= 0.9) return draw(b, 0);
      const p = kb >= 0 ? R0 : at;
      const W = b.width, H = b.height, u = uni(ctx), MID = u ? '·' : '-';
      const up = SERVERS.filter((s) => p >= s[2]), tools = up.reduce((n, s) => n + s[3].length, 0), sel = p >= PICK ? 2 : 0, cur = SERVERS[sel];
      const names = p >= cur[2] ? flow(cur[3].map((t, i) => ({ t: (i ? '  ' : '') + t, fg: th.ink })), W - 2) : [];
      const want = flow(cur[3].map((t, i) => ({ t: (i ? '  ' : '') + t })), W - 2).length;
      const rows = fitRows([{ k: 'head' }, { k: 'gap', drop: 4 }, ...SERVERS.map((s, i) => ({ k: 'srv', i })), { k: 'gap', drop: 3 }, { k: 'list' },
        ...Array.from({ length: want }, (_, i) => ({ k: 'tools', i, drop: 2 + i / 100 }))], H);
      // names that don't fit fold into a count on the last row that does
      const avail = rows.filter((r) => r.k === 'tools').length;
      if (avail && names.length > avail) {
        const lastRow = names[avail - 1];
        let hidden = names.slice(avail).reduce((n, row) => n + row.length, 0);
        const end = () => (lastRow.length ? lastRow[lastRow.length - 1].x + lastRow[lastRow.length - 1].t.length : 0);
        while (lastRow.length && end() + `  +${hidden + 1} more`.length > W - 2) { lastRow.pop(); hidden++; }
        lastRow.push({ x: end() + (lastRow.length ? 2 : 0), t: `+${hidden} more`, fg: sub(th) });
      }
      rows.forEach((r, y) => {
        if (r.k === 'head') runs(ctx, b, 0, y, W, [['tool servers', th.ink, ATTR.BOLD], [kb >= 0 ? ` ${MID} disconnect all` : ` ${MID} 3 configured ${MID} ${tools} tools`, th.ink]]);
        else if (r.k === 'srv') {
          // rows arrive one by one after t=0; in the beat each goes to a ring, then the list clears
          if (kb >= 0.6 || (kb < 0 && p < 0.2 + r.i * 0.15)) return;
          const [name, where, at, list, fails] = SERVERS[r.i], on = r.i === sel && kb < 0, off = kb >= 0 && kb > 0.1 + r.i * 0.15;
          if (on) mark(ctx, b, 0, y, '›', '>', th.accent);
          let gx;
          if (off) gx = mark(ctx, b, 2, y, '○', 'o', th.muted);
          else if (p >= at) gx = mark(ctx, b, 2, y, '●', '*', th.pos);
          else if (fails !== undefined && p >= fails && p < fails + 1.2) gx = mark(ctx, b, 2, y, '✖', 'x', th.neg);
          else { b.set(2, y, spin(ctx, p + r.i * 0.3), th.warn, undefined, ATTR.BOLD); gx = 3; }
          const nx = on ? inv(ctx, b, gx + 1, y, ` ${name} `) : b.text(gx + 2, y, name, th.ink, undefined, ATTR.BOLD) + 1;
          const state = off ? 'disconnected' : p >= at ? `connected ${MID} ${list.length} tools` : fails !== undefined && p >= fails ? (p < fails + 1.2 ? '401 auth failed' : 'refreshing token') : 'connecting';
          // addresses show on every row or on none
          const sw = state.length, wx = Math.max(nx + 1, 15);
          if (15 + 16 + 2 + 20 <= W) runs(ctx, b, wx, y, where.length, [[where, sub(th)]]);
          runs(ctx, b, W - sw, y, sw, [[state, th.ink]]);
        } else if (r.k === 'list') {
          if (kb >= 0.45 || (kb < 0 && p < 0.2)) return;
          const n = p >= cur[2] ? `${cur[3].length} tools` : 'waiting for the handshake';
          runs(ctx, b, 0, y, W, [[cur[0], th.ink, ATTR.BOLD], [` ${MID} ${n}`, th.ink]]);
        } else if (r.k === 'tools' && names[r.i] && kb < 0.45) names[r.i].forEach((it) => runs(ctx, b, 2 + it.x, y, W - 2 - it.x, [[it.t, it.fg]]));
      });
    };
    return (t) => { const p = phase(t, LOOP); draw(ctx.buffer, p >= R1 ? 0 : p); };
  },
};

sources.prism-term/src/facets/ai/typing-indicato:
// A sampler of "the model is working" indicators, each labeled:
// bouncing dots, a braille wave, a pulse, an orbit, a scanner and a meter.
import { ATTR, uni, phase, mix, fit } from './_ai.js';

const BRAILLE_LV = ['⡀', '⡄', '⡆', '⡇', '⡏', '⡟', '⡿', '⣿'];

export default {
  id: 'ai-typing-indicators',
  title: 'Typing Indicators',
  category: 'Thinking States',
  description: 'Six labeled "model is working" indicators side by side: a chat bubble of bouncing dots, a braille wave, a pulse, an orbit, a scanner and an equalizer.',
  tags: ['typing indicator', 'dots', 'wave', 'loading', 'chat'],
  kind: 'spinner',
  size: { w: 66, h: 4 },
  minSize: { w: 33, h: 4 },
  loop: 2.4,
  color: '256',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx);
      const p = phase(t, 2.4);
      // Whole cycles per loop, so every indicator repeats seamlessly.
      const w = (k) => (2 * Math.PI * k) / 2.4;
      const cells = [
        ['bounce', (s, x, y) => {
          // Chat bubble with three dots rising in turn.
          s.text(x, y, u ? '╭───────╮' : '+-------+', th.line);
          s.text(x, y + 1, u ? '│       │' : '|       |', th.line);
          s.text(x, y + 2, u ? '╰─┬─────╯' : '+-+-----+', th.line);
          for (let i = 0; i < 3; i++) {
            const k = Math.max(0, Math.sin((p / 2.4) * Math.PI * 4 - i * 0.9));
            s.set(x + 2 + i * 2, y + 1, u ? (k > 0.6 ? '●' : k > 0.2 ? '•' : '∙') : (k > 0.6 ? 'O' : k > 0.2 ? 'o' : '.'), mix(th.muted, th.accent, k), undefined, ATTR.BOLD);
          }
        }],
        ['wave', (s, x, y) => {
          for (let i = 0; i < 9; i++) {
            const v = (Math.sin(w(2) * p - i * 0.7) + 1) / 2;
            s.set(x + i, y + 1, u ? BRAILLE_LV[Math.round(v * 7)] : ' .:-=+*#'[Math.round(v * 7)], mix(th.info, th.accent, v));
          }
        }],
        ['pulse', (s, x, y) => {
          const k = (Math.sin(w(2) * p) + 1) / 2;
          const ring = u ? ['∙', '•', '●', '◉', '◎'][Math.round(k * 4)] : ['.', 'o', 'O', '@', '0'][Math.round(k * 4)];
          s.set(x + 4, y + 1, ring, mix(th.dim, th.accent, k), undefined, ATTR.BOLD);
          s.text(x, y + 1, u ? '·  ' : '.  ', mix(th.bg, th.accent, k * 0.6));
          s.text(x + 6, y + 1, u ? '  ·' : '  .', mix(th.bg, th.accent, k * 0.6));
        }],
        ['orbit', (s, x, y) => {
          const pts = [[4, 0], [6, 1], [4, 2], [2, 1]];
          pts.forEach(([dx, dy], i) => {
            const lead = Math.floor(p * 5) % 4;
            const age = (lead - i + 4) % 4;
            s.set(x + dx, y + dy, u ? (age === 0 ? '●' : '∙') : (age === 0 ? 'O' : '.'), age === 0 ? th.accent : mix(th.bg, th.accent, 0.6 - age * 0.15), undefined, ATTR.BOLD);
          });
          s.set(x + 4, y + 1, u ? '✳' : '*', th.muted);
        }],
        ['scan', (s, x, y) => {
          const n = 9, pos = Math.round((Math.sin(w(1) * p) + 1) / 2 * (n - 1));
          for (let i = 0; i < n; i++) {
            const d = Math.abs(i - pos);
            s.set(x + i, y + 1, u ? (d === 0 ? '█' : d === 1 ? '▓' : d === 2 ? '▒' : '░') : (d === 0 ? '#' : d === 1 ? '=' : '-'), d < 3 ? mix(th.accent, th.bg, d * 0.3) : th.line);
          }
        }],
        ['meter', (s, x, y) => {
          const LV = u ? ' ▁▂▃▄▅▆▇█' : ' ..::==##';
          for (let i = 0; i < 7; i++) {
            const v = (Math.sin(w(2 + (i % 3)) * p + i) + 1) / 2;
            s.set(x + 1 + i, y + 1, LV[1 + Math.round(v * 7)], mix(th.pos, th.warn, v));
          }
        }],
      ];
      // Lay the cells out in as many columns as fit (11 columns each).
      const cw = 11, cols = Math.max(1, Math.floor(W / cw)), rowH = 4;
      const rows = Math.max(1, Math.floor(H / rowH));
      const n = Math.min(cells.length, cols * rows);
      const x0 = Math.max(0, Math.floor((W - Math.min(cols, n) * cw) / 2));
      for (let i = 0; i < n; i++) {
        const [name, draw] = cells[i];
        const cx = x0 + (i % cols) * cw, cy = Math.floor(i / cols) * rowH;
        draw(b, cx, cy);
        b.text(cx, cy + 3, fit(name, cw - 1, undefined, ctx).trimEnd(), th.dim);
      }
    };
  },
};

