// Pure ASCII — three classics that played themselves into history: a falling-
// block game in its Elektronika 60 text-mode well, a roguelike descent that ends
// at the tombstone, and a 1971 BASIC starship session at the short-range scan.
// 7-bit glyphs only; original code and art, after the games credited below.
import { hash } from './_ascii.js';
import { mix } from '../../color.js';

const shared = { gallery: 'ascii', category: 'Classics', glyphs: 'ascii', color: '16', kind: 'art' };
/** Time within the loop, quantized so t and t + loop draw identical frames (flicker keys included). */
const phase = (t, loop) => Math.round((((t % loop) + loop) % loop) * 1e6) / 1e6;
const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);

// ── block stacker ───────────────────────────────────────────────────────────────────
const SHAPES = { I: [[0, 1], [1, 1], [2, 1], [3, 1]], O: [[1, 0], [2, 0], [1, 1], [2, 1]], T: [[1, 0], [0, 1], [1, 1], [2, 1]], S: [[1, 0], [2, 0], [0, 1], [1, 1]], Z: [[0, 0], [1, 0], [1, 1], [2, 1]], J: [[0, 0], [0, 1], [1, 1], [2, 1]], L: [[2, 0], [0, 1], [1, 1], [2, 1]] };
const NAMES = Object.keys(SHAPES);
const ROT = NAMES.map((n) => {                              // four rotation states per piece
  const size = n === 'I' ? 4 : 3, out = [SHAPES[n]];
  for (let r = 1; r < 4; r++) out.push(n === 'O' ? SHAPES.O : out[r - 1].map(([x, y]) => [size - 1 - y, x]));
  return out;
});
const COLS = 10;

/** Precompute one game: a list of placed pieces with their timing, until the stack tops out. */
function playStacker(rows) {
  const board = Array.from({ length: rows }, () => new Int8Array(COLS).fill(-1));
  const fits = (cells, px, py) => cells.every(([x, y]) => x + px >= 0 && x + px < COLS && y + py < rows && (y + py < 0 || board[y + py][x + px] < 0));
  const land = (cells, px) => { let py = -1; while (fits(cells, px, py + 1)) py++; return py; };
  const seq = [];
  for (let bag = 0; seq.length < 200; bag++) {
    const ids = [0, 1, 2, 3, 4, 5, 6].map((i) => [hash(bag, i, 77), i]).sort((a, b) => a[0] - b[0]).map(([, i]) => i);
    seq.push(...ids);
  }
  const events = [];
  let tm = 0.4, lines = 0, score = 0;
  for (let n = 0; n < seq.length; n++) {
    const id = seq[n], level = 1 + Math.floor(lines / 4), grav = Math.max(0.035, 0.12 - 0.018 * (level - 1));
    const panic = tm > 28;                                  // late game: speed and nerves fail
    let best = null;
    for (let r = 0; r < 4; r++) for (let px = -2; px < COLS; px++) {
      const cells = ROT[id][r];
      if (!fits(cells, px, 0)) continue;
      const py = land(cells, px);
      if (py < 0) continue;
      // score the board after this placement (aggregate height, holes, bumpiness, lines)
      const tmp = board.map((row) => row.slice());
      cells.forEach(([x, y]) => { tmp[y + py][x + px] = id; });
      const full = tmp.filter((row) => row.every((c) => c >= 0)).length;
      const hts = Array.from({ length: COLS }, (_, x) => { const y = tmp.findIndex((row) => row[x] >= 0); return y < 0 ? 0 : rows - y; });
      let holes = 0;
      for (let x = 0; x < COLS; x++) { let seen = false; for (let y = 0; y < rows; y++) { if (tmp[y][x] >= 0) seen = true; else if (seen) holes++; } }
      const bump = hts.slice(1).reduce((s, h, i) => s + Math.abs(h - hts[i]), 0);
      let v = -0.51 * hts.reduce((a, b) => a + b, 0) + 0.76 * full - 0.36 * holes - 0.18 * bump + (hash(n, r, px + 9) - 0.5) * 0.4;
      if (panic) v = -Math.abs(px - 3) - holes * 0.01 + hash(n, r, px) * 2;   // panicking: piles up near the middle
      if (!best || v > best.v) best = { v, r, px, py };
    }
    if (!best) { events.push({ over: tm }); break; }
    const actions = best.r + Math.abs(best.px - 3), drop = !panic && hash(n, 5) < 0.7;   // SPACE: DROP once lined up
    const fall = drop ? actions * 0.06 + 0.08 : Math.max(actions * 0.06, (best.py + 1) * grav);
    ROT[id][best.r].forEach(([x, y]) => { board[y + best.py][x + best.px] = id; });
    const cleared = [];
    board.forEach((row, y) => { if (row.every((c) => c >= 0)) cleared.push(y); });
    events.push({ id, r: best.r, px: best.px, py: best.py, t0: tm, t1: tm + fall, grav, drop, actions, cleared, next: seq[n + 1], level, lines, score });
    tm += fall;
    if (cleared.length) {
      lines += cleared.length; score += [0, 40, 100, 300, 1200][cleared.length] * level;
      for (const y of cleared) { board.splice(y, 1); board.unshift(new Int8Array(COLS).fill(-1)); }
      tm += 0.35;
    }
    tm += 0.05;
    if (tm > 37) { events.push({ over: tm }); break; }
  }
  return events;
}

const blockStacker = {
  ...shared,
  id: 'ascii-block-stacker',
  since: '0.3.0',
  title: 'Block Stacker',
  tags: ['block stacker', 'falling blocks', 'puzzle', 'elektronika 60', 'autoplay', 'retro game', 'text mode'],
  order: 300,
  loop: 40,
  size: { w: 64, h: 22 },
  minSize: { w: 40, h: 14 },
  description: 'A falling-block game in its original text-mode well: [] blocks drop between <! and !>, a so-so autoplayer clears lines as speed rises, then tops out.',
  credits: "after Alexey Pajitnov's 1984 falling-block game on the Elektronika 60",
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const rows = Math.max(12, Math.min(20, H - 4)), y0 = Math.max(0, Math.floor((H - rows - 2) / 2));
    const panels = W >= 60, wx = panels ? 20 : 0, rx = wx + 26;
    const events = playStacker(rows), overAt = (events.at(-1).over ?? 37);
    const tint = [th.info, th.warn, th.accent, th.pos, th.neg, th.accent2, th.crit];
    return (t) => {
      const b = ctx.buffer;
      const tau = phase(t, 40);
      const board = Array.from({ length: rows }, () => new Int8Array(COLS).fill(-1));
      let cur = null, flash = null, stats = { lines: 0, score: 0, level: 1, next: events[0].id };
      for (const e of events) {
        if (e.over !== undefined || e.t0 > tau) break;
        if (tau < e.t1) { cur = e; stats = { lines: e.lines, score: e.score, level: e.level, next: e.next }; break; }
        ROT[e.id][e.r].forEach(([x, y]) => { if (y + e.py >= 0) board[y + e.py][x + e.px] = e.id; });
        stats = { lines: e.lines + e.cleared.length, score: e.score + [0, 40, 100, 300, 1200][e.cleared.length] * e.level, level: e.level, next: e.next };
        if (e.cleared.length) {
          if (tau < e.t1 + 0.35) { flash = e.cleared; break; }  // the full rows flash, then collapse
          for (const y of e.cleared) { board.splice(y, 1); board.unshift(new Int8Array(COLS).fill(-1)); }
        }
      }
      // game over: the well fills with [] bottom-up, then clears before the wrap
      const fill = tau >= overAt ? Math.min(rows, Math.floor((tau - overAt) / 0.08)) : 0, gone = tau >= 39.3;
      for (let y = 0; y < rows; y++) {
        b.text(wx, y0 + y, '<!', th.muted); b.text(wx + 22, y0 + y, '!>', th.muted);
        for (let x = 0; x < COLS; x++) {
          const c = board[y][x], filled = !gone && rows - 1 - y < fill;
          if (flash && flash.includes(y)) b.text(wx + 2 + x * 2, y0 + y, '==', th.ink, undefined, 1);
          else if (filled) b.text(wx + 2 + x * 2, y0 + y, '[]', th.dim);
          else if (c >= 0 && !gone) b.text(wx + 2 + x * 2, y0 + y, '[]', tint[c]);
          else b.text(wx + 2 + x * 2, y0 + y, ' .', th.dim);
        }
      }
      if (cur && !gone && fill === 0) {                       // the falling piece
        const u = (tau - cur.t0) / Math.max(1e-6, cur.t1 - cur.t0);
        const moved = clamp01((tau - cur.t0) / Math.max(1e-6, cur.actions * 0.06));
        const px = Math.round(3 + (cur.px - 3) * moved), r = Math.round(cur.r * moved);
        const py = cur.drop ? (moved < 1 ? 0 : cur.py) : Math.min(cur.py, Math.floor(u * (cur.py + 1)));
        ROT[cur.id][r].forEach(([x, y]) => { const Y = y + py, X = x + px; if (Y >= 0 && Y < rows && X >= 0 && X < COLS) b.text(wx + 2 + X * 2, y0 + Y, '[]', tint[cur.id], undefined, 1); });
      }
      if (fill >= rows && !gone && Math.floor(tau * 2) % 2 === 0) {          // GAME OVER over the filled well until it clears
        b.text(wx + 6, y0 + Math.floor(rows / 2), ' GAME OVER ', th.bg, th.neg, 1);
      }
      b.text(wx, y0 + rows, '<!' + '='.repeat(20) + '!>', th.muted);
      if (y0 + rows + 1 < H) b.text(wx + 2, y0 + rows + 1, '\\/'.repeat(10), th.muted);
      const sx = panels ? 1 : rx, sy = panels ? y0 + 2 : y0;
      b.text(sx, sy, `LINES: ${stats.lines}`, th.ink); b.text(sx, sy + 1, `LEVEL: ${stats.level}`, th.ink); b.text(sx, sy + 2, `SCORE: ${stats.score}`, th.ink);
      if (panels) ['7: LEFT   9: RIGHT', '   8: ROTATE', '4: SPEED UP', '5: SHOW NEXT', 'SPACE: DROP'].forEach((s, i) => b.text(rx, y0 + 1 + i, s, th.muted));
      if (W - rx >= 10 && !gone) {                            // SHOW NEXT
        const ny = panels ? y0 + 8 : y0 + 4;
        b.text(rx, ny, 'NEXT:', th.ink);
        ROT[stats.next][0].forEach(([x, y]) => b.text(rx + 1 + x * 2, ny + 1 + y, '[]', tint[stats.next]));
      }
    };
  },
};

// ── dungeon crawl ────────────────────────────────────────────────────────────────────
const TOMB = ['     ___________', '    /           \\', '   /   REST IN   \\', '  /     PEACE     \\', ' |                 |', ' |      Arlo       |', ' |     214 Au      |', ' |   killed by a   |', ' |    hobgoblin    |', ' |      2026       |', ' |                 |', '_|_________________|_'];

/** A roguelike level: a 3×3 grid of rooms, L-shaped corridors, items, monsters and @'s scripted route. */
function rogueLevel(W, H) {
  const MH = H - 2, grid = Array.from({ length: MH }, () => new Array(W).fill(' '));
  const cw = Math.floor(W / 3), ch = Math.floor(MH / 3), rooms = [];
  for (let gy = 0; gy < 3; gy++) for (let gx = 0; gx < 3; gx++) {
    const k = gy * 3 + gx, rw = Math.max(6, Math.floor(cw * (0.55 + hash(k, 1) * 0.3))), rh = Math.max(4, Math.floor(ch * (0.6 + hash(k, 2) * 0.35)));
    const x = gx * cw + 1 + Math.floor(hash(k, 3) * Math.max(1, cw - rw - 2)), y = gy * ch + Math.floor(hash(k, 4) * Math.max(1, ch - rh));
    rooms.push({ x, y, w: Math.min(rw, cw - 2), h: Math.min(rh, ch) });
  }
  for (const r of rooms) for (let y = r.y; y < r.y + r.h; y++) for (let x = r.x; x < r.x + r.w; x++) {
    grid[y][x] = y === r.y || y === r.y + r.h - 1 ? '-' : x === r.x || x === r.x + r.w - 1 ? '|' : '.';
  }
  const dig = (x, y) => { if (grid[y][x] === ' ') grid[y][x] = '#'; else if (grid[y][x] === '-' || grid[y][x] === '|') grid[y][x] = '+'; };
  const link = (a, b, horiz) => {                         // door to door with one bend
    const A = rooms[a], B = rooms[b];
    const ax = horiz ? A.x + A.w - 1 : A.x + Math.floor(A.w / 2), ay = horiz ? A.y + Math.floor(A.h / 2) : A.y + A.h - 1;
    const bx = horiz ? B.x : B.x + Math.floor(B.w / 2), by = horiz ? B.y + Math.floor(B.h / 2) : B.y;
    if (horiz) { const mx = Math.floor((ax + bx) / 2); for (let x = ax; x <= mx; x++) dig(x, ay); for (let y = Math.min(ay, by); y <= Math.max(ay, by); y++) dig(mx, y); for (let x = mx; x <= bx; x++) dig(x, by); }
    else { const my = Math.floor((ay + by) / 2); for (let y = ay; y <= my; y++) dig(ax, y); for (let x = Math.min(ax, bx); x <= Math.max(ax, bx); x++) dig(x, my); for (let y = my; y <= by; y++) dig(bx, y); }
  };
  [[0, 1, 1], [1, 2, 1], [0, 3, 0], [3, 4, 1], [2, 5, 0], [4, 7, 0], [5, 8, 0], [7, 8, 1], [6, 7, 1]].forEach(([a, b, h]) => link(a, b, h));
  const center = (k) => [rooms[k].x + Math.floor(rooms[k].w / 2), rooms[k].y + Math.floor(rooms[k].h / 2)];
  const spot = (k, fx, fy) => [rooms[k].x + 1 + Math.floor((rooms[k].w - 2) * fx), rooms[k].y + 1 + Math.floor((rooms[k].h - 2) * fy)];
  const items = [{ at: spot(0, 0.8, 0.3), ch: '*', name: 'gold' }, { at: spot(1, 0.3, 0.6), ch: '!', name: 'potion' }, { at: spot(4, 0.7, 0.7), ch: '?', name: 'scroll' }, { at: spot(8, 0.8, 0.8), ch: '%', name: 'stairs' }];
  // BFS walk between waypoints over floor, doors and corridors
  const walk = (from, to) => {
    const key = ([x, y]) => y * W + x, prev = new Map([[key(from), null]]), q = [from];
    while (q.length) {
      const [x, y] = q.shift();
      if (x === to[0] && y === to[1]) break;
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = x + dx, ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= W || ny >= MH || prev.has(ny * W + nx) || !'.+#'.includes(grid[ny][nx])) continue;
        prev.set(ny * W + nx, [x, y]); q.push([nx, ny]);
      }
    }
    const path = [];
    for (let p = to; p && prev.has(key(p)); p = prev.get(key(p))) path.unshift(p);
    return path.length ? path : [from];
  };
  const way = [center(0), items[0].at, center(1), items[1].at, center(4), center(5), spot(8, 0.3, 0.5)];
  let route = [way[0]];
  for (let i = 1; i < way.length; i++) route = route.concat(walk(route.at(-1), way[i]).slice(1));
  return { grid, rooms, items, route, MH, bat: spot(4, 0.2, 0.3), kobold: spot(5, 0.5, 0.5), hob: spot(8, 0.55, 0.5) };
}

const dungeonCrawl = {
  ...shared,
  id: 'ascii-dungeon-crawl',
  since: '0.3.0',
  title: 'Dungeon Crawl',
  tags: ['roguelike', 'dungeon', 'crawl', 'tombstone', 'kobold', 'hobgoblin', 'retro game'],
  order: 310,
  loop: 40,
  size: { w: 80, h: 24 },
  minSize: { w: 48, h: 16 },
  description: 'A roguelike descent: rooms light up as @ enters, corridors appear as walked, a bat flits, a kobold falls, then a hobgoblin wins and the tombstone rises.',
  credits: 'after Rogue (1980) by Michael Toy, Glenn Wichman and Ken Arnold',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const L = rogueLevel(W, H), R = L.route, deathAt = 35, steps = R.length - 1;
    // the status line: Rogue's own spacing when it fits, else single spaces, then whole fields drop from the right
    const status = (gold, hp) => ['Level: 3', `Gold: ${gold}`, `Hp: ${hp}(12)`, 'Str: 16(16)', 'Arm: 4', 'Exp: 3/27'];
    const widest = status(214, 12), stSep = widest.join('  ').length <= W ? '  ' : ' ';
    let stN = widest.length;
    while (stN > 1 && widest.slice(0, stN).join(stSep).length > W) stN--;
    const pace = (deathAt - 6) / Math.max(1, steps);         // seconds per step, leaving time to fight
    const near = (a, b, d = 1) => Math.abs(a[0] - b[0]) <= d && Math.abs(a[1] - b[1]) <= d;
    const koboldStep = R.findIndex((p) => near(p, L.kobold)), fightAt = 1 + Math.max(0, koboldStep) * pace;
    const posAt = (tau) => {                                  // the kobold fight holds @ in place for 3 s
      const s = tau < fightAt ? (tau - 1) / pace : tau < fightAt + 3 ? koboldStep : koboldStep + (tau - fightAt - 3) / pace;
      return R[Math.max(0, Math.min(steps, Math.floor(s)))];
    };
    const roomOf = ([x, y]) => L.rooms.findIndex((r) => x > r.x && x < r.x + r.w - 1 && y > r.y && y < r.y + r.h - 1);
    const seen = new Uint8Array(W * L.MH), lit = new Set();
    return (t) => {
      const b = ctx.buffer;
      let tau = phase(t, 40);
      if (tau >= 36 && tau < 39.4) {                          // REST IN PEACE ...
        TOMB.forEach((s, i) => b.text(Math.floor((W - 21) / 2), Math.floor((H - TOMB.length) / 2) + i, s, i > 4 && i < 10 ? th.ink : th.muted));
        return;
      }
      if (tau >= 39.4) tau = 0;                               // ... then a fresh game on the same seed, already at its first frame
      seen.fill(0); lit.clear();
      const me = posAt(tau);
      // memory: every lit room entered so far, and corridor squares next to the path walked
      const walked = Math.max(0, Math.min(steps, Math.floor(tau < fightAt ? (tau - 1) / pace : tau < fightAt + 3 ? koboldStep : koboldStep + (tau - fightAt - 3) / pace)));
      for (let i = 0; i <= walked; i++) {
        const p = R[i], k = roomOf(p);
        if (k >= 0) lit.add(k);
        for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) { const x = p[0] + dx, y = p[1] + dy; if (x >= 0 && y >= 0 && x < W && y < L.MH) seen[y * W + x] = 1; }
      }
      for (let y = 0; y < L.MH; y++) for (let x = 0; x < W; x++) {
        const c = L.grid[y][x];
        if (c === ' ') continue;
        const inLit = [...lit].some((k) => { const r = L.rooms[k]; return x >= r.x && x < r.x + r.w && y >= r.y && y < r.y + r.h; });
        if (!inLit && !(c === '#' && seen[y * W + x]) && !(c === '+' && seen[y * W + x])) continue;
        b.set(x, y + 1, c, c === '#' ? th.dim : c === '.' ? mix(th.muted, th.bg, 0.4) : th.muted);
      }
      let gold = 160, msg = 'Hello Arlo, welcome to the dungeon!', hp = 12;
      for (const it of L.items) {
        const k = roomOf(it.at), taken = it.ch !== '%' && R.slice(0, walked + 1).some((p) => p[0] === it.at[0] && p[1] === it.at[1]);
        if (taken && it.ch === '*') { gold = 214; if (msg.startsWith('Hello')) msg = 'You found 54 gold pieces.'; }
        if (taken && it.ch === '!') msg = 'You now have a potion of healing (p).';
        if (!taken && k >= 0 && lit.has(k)) b.set(it.at[0], it.at[1] + 1, it.ch, it.ch === '*' ? th.warn : th.accent);
      }
      // the bat: erratic, in the room it haunts, while @ crosses it
      if (lit.has(roomOf(L.bat))) {
        const r = L.rooms[roomOf(L.bat)], k = Math.floor(tau * 5);
        const bx = r.x + 1 + Math.floor(hash(k, 3) * (r.w - 2)), by = r.y + 1 + Math.floor(hash(k, 4) * (r.h - 2));
        b.set(bx, by + 1, 'B', th.neg);
        if (near([bx, by], me)) { msg = 'The bat bites you.'; hp = 11; }
      }
      if (tau >= fightAt + 3) hp = Math.min(hp, 9);
      if (tau < fightAt + 3 && lit.has(roomOf(L.kobold))) b.set(L.kobold[0], L.kobold[1] + 1, 'K', th.neg);
      if (tau >= fightAt && tau < fightAt + 3) msg = ['You hit the kobold.', 'The kobold hits you.', 'You hit the kobold.', 'You have defeated the kobold.'][Math.min(3, Math.floor((tau - fightAt) / 0.75))];
      if (tau >= fightAt + 1) hp = Math.min(hp, 10);
      const hobRoom = roomOf(L.hob);
      if (lit.has(hobRoom)) {
        b.set(L.hob[0], L.hob[1] + 1, 'H', th.neg);
        if (near(me, L.hob, 3) || tau >= deathAt - 2) { msg = tau >= deathAt - 0.8 ? 'You die...  --More--' : tau >= deathAt - 1.6 ? 'The hobgoblin hits you.' : 'The hobgoblin hits you.'; hp = tau >= deathAt - 0.8 ? 0 : tau >= deathAt - 1.6 ? 2 : 5; }
      }
      b.set(me[0], me[1] + 1, '@', th.warn, undefined, 1);
      b.text(0, 0, msg.slice(0, W), th.ink);
      b.text(0, H - 1, status(gold, hp).slice(0, stN).join(stSep).slice(0, W), th.ink);
    };
  },
};

// ── starship command (1971 BASIC style) ─────────────────────────────────────────────────────────
const SCAN0 = { E: [2, 6], K: [[4, 2], [6, 2]], stars: [[1, 1], [7, 3], [5, 5], [3, 8], [8, 7]], base: [7, 6] };
const TRACK = [[3, 5], [3, 4], [3, 3], [4, 2]];

const starship = {
  ...shared,
  id: 'ascii-starship-command',
  since: '0.3.0',
  title: 'Starship Command',
  tags: ['starship', 'basic', 'strategy', 'teletype', 'retro game', 'space', 'short range scan'],
  order: 320,
  loop: 36,
  size: { w: 72, h: 22 },
  minSize: { w: 48, h: 14 },
  description: 'A 1971-style BASIC starship game at its short-range scan: a torpedo steps cell by cell into a raider, lasers finish another, then the drive returns home.',
  credits: "after Mike Mayfield's 1971 STTR1",
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const wide = W >= 66;
    // the session: [time, text]; typed commands reveal one character per 0.12 s
    const K = 1.45;                                          // session pace: the warp lands near 32.5 s
    const type = (at, prompt, ans) => ({ at: at * K, f: (tau) => prompt + ans.slice(0, Math.max(0, Math.floor((tau - at * K - 0.5) / 0.17))) });
    const say = (at, s) => ({ at: at * K, f: () => s });
    const S = [type(1, 'COMMAND? ', 'TOR'), type(2.2, 'TORPEDO COURSE (1-9)? ', '2.7'), say(3.4, 'TORPEDO TRACK:'),
      ...TRACK.map((p, i) => say(3.8 + i * 0.5, `               ${p[0]},${p[1]}`)), say(6, '*** RAIDER DESTROYED ***'),
      say(7.2, '214 UNIT HIT ON YOUR SHIP FROM SECTOR 6,2'), say(7.6, '      <SHIELDS DOWN TO 186 UNITS>'),
      type(9.4, 'COMMAND? ', 'LAS'), say(10.6, W >= 49 ? 'LASERS LOCKED ON TARGET;  ENERGY AVAILABLE = 2860' : 'LASERS LOCKED; ENERGY = 2860'), type(11.2, 'NUMBER OF UNITS TO FIRE? ', '500'),
      say(12.8, '312 UNIT HIT ON RAIDER AT SECTOR 6,2'), say(13.2, '   (SENSORS SHOW 0 UNITS REMAINING)'), say(13.8, '*** RAIDER DESTROYED ***'),
      type(16.5, 'COMMAND? ', 'NAV'), type(17.6, 'COURSE (0-9)? ', '7'), type(18.6, 'DRIVE FACTOR (0-8)? ', '1'), say(20, 'NOW ENTERING QUADRANT 4,7 ...')];
    const warpAt = 20.4 * K, arriveAt = 22.4 * K;
    const scanX = 0, scanY = 0, statX = wide ? 36 : 34;      // a column clear of the 33-column scan
    return (t) => {
      const b = ctx.buffer;
      const tau = phase(t, 36);
      const reset = tau >= arriveAt;                          // back at the start scan, as at t = 0
      const k1 = !reset && tau >= 6 * K, k2 = !reset && tau >= 13.8 * K, hitE = !reset && tau >= 7.2 * K;
      const line = '-'.repeat(33);
      b.text(scanX, scanY, line, th.muted);
      b.text(scanX, scanY + 9, line, th.muted);
      const warping = tau >= warpAt && tau < arriveAt;
      for (let r = 1; r <= 8; r++) {
        if (warping) {                                        // the drive streak
          for (let x = 0; x < 33; x++) if (hash(x, r, Math.floor(tau * 20)) < 0.2) b.set(scanX + (x + Math.floor(tau * 40)) % 33, scanY + r, '-', th.info);
          continue;
        }
        for (let c = 1; c <= 8; c++) {
          const sx = scanX + 1 + (c - 1) * 4, sy = scanY + r;
          let g = null, col = th.dim;
          if (SCAN0.E[0] === c && SCAN0.E[1] === r) { g = '<*>'; col = th.info; }
          else if ((SCAN0.K[0][0] === c && SCAN0.K[0][1] === r && !k1) || (SCAN0.K[1][0] === c && SCAN0.K[1][1] === r && !k2)) { g = '+R+'; col = th.neg; }
          else if (SCAN0.base[0] === c && SCAN0.base[1] === r) { g = '>!<'; col = th.pos; }
          else if (SCAN0.stars.some(([x, y]) => x === c && y === r)) { g = ' * '; col = th.dim; }
          if (g) b.text(sx, sy, g, col, undefined, g === '<*>' ? 1 : 0);
        }
      }
      if (tau >= 3.8 * K && tau < 6 * K) {                    // the torpedo, one sector per step
        const [c, r] = TRACK[Math.min(TRACK.length - 1, Math.floor((tau - 3.8 * K) / (0.5 * K)))];
        b.text(scanX + 1 + (c - 1) * 4, scanY + r, ' + ', th.warn, undefined, 1);
      }
      if (tau >= 12.8 * K && tau < 13.4 * K) for (let x = 1; x < 22; x++) if ((x + Math.floor(tau * 30)) % 3 === 0) b.set(scanX + 4 + x, scanY + 6 - Math.round(x * 4 / 21), '.', th.warn);
      const red = !reset && !k2, energy = !reset && tau >= 12.8 * K ? 2360 : 2860, shields = hitE ? 186 : 400;
      const stat = wide
        ? [['CYCLE', '2306.4'], ['CONDITION', red || reset ? '*RED*' : 'GREEN'], ['QUADRANT', '4,7'], ['SECTOR', '2,6'], ['TORPEDOES', k1 ? '8' : '9'], ['TOTAL ENERGY', String(energy)], ['SHIELDS', String(shields)], ['RAIDERS REMAINING', String(14 - (k1 ? 1 : 0) - (k2 ? 1 : 0))]]
        : [['CYCL', '2306.4'], ['COND', red || reset ? '*RED*' : 'GREEN'], ['QUAD', '4,7'], ['SECT', '2,6'], ['TORP', k1 ? '8' : '9'], ['ENGY', String(energy)], ['SHLD', String(shields)], ['RAID', String(14 - (k1 ? 1 : 0) - (k2 ? 1 : 0))]];
      stat.forEach(([k, v], i) => { b.text(statX, scanY + 1 + i, k, th.muted); b.text(statX + (wide ? 20 : 6), scanY + 1 + i, v, k.startsWith('COND') ? (v === 'GREEN' ? th.pos : th.neg) : th.ink); });
      // the transcript under the scan, newest last
      const ty = scanY + 10, rows = H - ty;
      const shown = reset ? [] : S.filter((l) => l.at <= tau);
      const lines = shown.map((l) => l.f(tau)).slice(-Math.max(1, rows));
      if (!lines.length || tau >= arriveAt) lines.push(`COMMAND? ${Math.floor(tau * 2) % 2 ? '_' : ''}`);   // the prompt, cursor blinking
      lines.slice(-rows).forEach((s, i) => b.text(0, ty + i, s.slice(0, W), s.startsWith('***') ? th.neg : s.includes('?') ? th.warn : th.ink));
    };
  },
};

export default [blockStacker, dungeonCrawl, starship];

sources.prism-term/src/facets/ascii/landscapes.j:
// Pure ASCII — landscapes by day and night: a campfire that settles mid-cycle,
// a hot-air balloon over patchwork hills, a torch-lit castle, a desert caravan
// under heat shimmer, and a firefly forest. 7-bit glyphs only; reads in mono.
import { sprite, hash } from './_ascii.js';
import { mix } from '../../color.js';
import { clamp } from '../../easing.js';

const shared = { gallery: 'ascii', glyphs: 'ascii', color: '16', kind: 'art', size: { w: 80, h: 24 }, minSize: { w: 36, h: 12 } };
const TAU = Math.PI * 2;
/** Time within the loop, quantized so t and t + loop draw identical frames (flicker keys included). */
const phase = (t, loop) => Math.round((((t % loop) + loop) % loop) * 1e6) / 1e6;
const ease = (k) => k * k * (3 - 2 * k);

function stars(b, W, rows, th, t, seed = 0) {
  for (let k = 0; k < W * 0.42; k++) {
    const x = Math.floor(hash(k, 11 + seed) * W), y = Math.floor(hash(k, 23 + seed) * rows);
    if (hash(k, 5 + seed, Math.floor(t * 2)) < 0.8) b.set(x, y, hash(k, 7) < 0.18 ? '*' : '.', th.dim);
  }
}

function moon(b, x, y, th) {
  b.text(x, y, ' _.._', th.ink); b.text(x, y + 1, '( (  `', th.ink); b.text(x, y + 2, " `-.'", th.ink);
}

// ── campfire ─────────────────────────────────────────────────────────────────
const CPINE = ['  ^  ', ' /^\\ ', '/_|_\\', '  |  '];

const campfire = {
  ...shared,
  id: 'ascii-campfire',
  since: '0.3.0',
  title: 'Campfire',
  category: 'ASCII Animations',
  tags: ['campfire', 'fire', 'sparks', 'night', 'camping', 'smoke', 'logs'],
  order: 210,
  loop: 10,
  minSize: { w: 32, h: 10 },
  description: 'A ringed campfire under the stars: flames sway, sparks spiral up, the top log settles in a burst, burns down to coals, and a fresh log is laid on before the next round.',
  setup(ctx) {
    const { width: W, height: H, theme: th, noise } = ctx;
    const cx = Math.floor(W / 2), ground = H - 2, logY = H - 4;
    const fw = clamp(Math.round(W * 0.1), 3, 8), half = Math.max(5, fw); // flame half-width, log half-length
    const maxH = Math.max(3, Math.min(logY - 2, Math.round(H * 0.5)));
    const tc = 6.8, burnt = 9, laid = 9.8;              // the top log settles, is burnt through, a new one lands
    const R = 4.14;                                     // flame noise sampled on a circle: one lap per 10 s loop
    const logC = mix(th.warn, th.bg, 0.45), stone = (dx) => (Math.abs(dx) <= half + 2 ? mix(th.muted, th.warn, 0.35) : th.muted);
    return (t) => {
      const b = ctx.buffer;
      const p = phase(t, 10);
      const ang = TAU * p / 10, nx = R * Math.cos(ang), ny = R * Math.sin(ang);
      stars(b, W, Math.max(2, H - 8), th, p);
      moon(b, Math.floor(W * 0.8), 1, th);
      if (W >= 44) { sprite(b, 2, ground - 4, CPINE, th.dim); sprite(b, W - 8, ground - 4, CPINE, th.dim); }
      for (let x = 0; x < W; x++) b.set(x, ground + 1, hash(x, 3) < 0.2 ? ',' : '_', mix(th.muted, th.bg, 0.5));
      for (const dx of [-half - 4, -half - 2, half + 2, half + 4]) b.set(cx + dx, ground, Math.abs(dx) > half + 3 ? 'o' : 'O', stone(dx));
      for (const dx of [-half - 3, half + 3]) b.set(cx + dx, ground - 1, 'o', stone(dx));
      // flames
      const settle = clamp((p - tc) / 0.35, 0, 1);
      const flare = settle > 0 && settle < 1 ? Math.sin(settle * Math.PI) * 0.5 : 0;
      for (let dx = -fw; dx <= fw; dx++) {
        const prof = (1 - Math.abs(dx) / (fw + 1)) * (1 + flare);
        const hCol = maxH * prof * (0.55 + 0.45 * noise.noise3(dx * 0.7, nx, ny));
        for (let i = 0; i < hCol; i++) {
          const y = logY - 1 - i, rel = i / Math.max(1, hCol);
          const ch = rel > 0.78 ? (hash(dx, i, Math.floor(p * 8)) < 0.5 ? "'" : '.') : Math.sin(TAU * 8 * p / 10 + dx * 1.3 + i * 0.9) > 0 ? '(' : ')';
          b.set(cx + dx, y, ch, rel > 0.78 ? th.muted : Math.abs(dx) < fw * 0.45 ? th.warn : th.neg);
        }
      }
      // logs: the bottom one stays; the top one is raised, settles at tc, burns down to coals, and a
      // fresh one is lowered on at 9–9.8 s so the loop starts with a raised log again
      b.text(cx - half, logY, '<' + '='.repeat(2 * half - 1) + '>', logC);
      let lift = 2, drop = 0, burn = 0;
      if (p >= tc && p < burnt) { lift = Math.round(2 * (1 - ease(settle))); burn = clamp((p - tc - 0.35) / (burnt - tc - 0.6), 0, 1); }
      else if (p >= burnt) drop = Math.round(3 * (1 - clamp((p - burnt) / (laid - burnt), 0, 1)) ** 2);
      if (p < burnt) {
        for (let i = 0; i < 2 * half - 1; i++) {
          const y = logY - 1 - Math.round(lift * (1 - i / (2 * half - 2))) - drop, k = hash(i, 17);
          if (burn > 0 && k < burn) { if (k > burn - 0.25) b.set(cx - half + 1 + i, y, '*', th.neg); continue; } // charred through
          b.set(cx - half + 1 + i, y, burn > 0.4 && k < burn + 0.2 ? '-' : '=', burn > 0 ? mix(logC, th.neg, burn * 0.6) : logC);
        }
        if (burn < 0.5) { b.set(cx - half, logY - 1 - lift - drop, '<', logC); b.set(cx + half - 1, logY - 1 - drop, '>', logC); }
      } else {
        for (let i = 0; i < 2 * half - 1; i++) b.set(cx - half + 1 + i, logY - 1 - Math.round(2 * (1 - i / (2 * half - 2))) - drop, '=', logC);
        b.set(cx - half, logY - 3 - drop, '<', logC); b.set(cx + half - 1, logY - 1 - drop, '>', logC);
      }
      // embers on the logs
      for (let k = 0; k < 4; k++) if (hash(k, Math.floor(p * 6)) < 0.6) b.set(cx - 3 + k * 2, logY, '*', th.neg);
      // sparks (5, 6 or 7 lifts per loop), with bursts when the log drops and when the new one lands
      const burst = (p > tc && p < tc + 0.9) || p > laid - 0.05;
      for (let k = 0; k < (burst ? 14 : 8); k++) {
        const ph = (p * (0.5 + (k % 3) * 0.1) + hash(k, 9) * 3) % 1;
        const y = logY - 2 - ph * (maxH + 2);
        const x = cx + (hash(k, 4) - 0.5) * 5 + Math.sin(ph * 7 + k) * 2 * ph;
        if (y > 0 && hash(k, Math.floor(p * 9)) < 0.85 - ph * 0.5) {
          b.set(Math.round(x), Math.round(y), ph < 0.3 ? '*' : ph < 0.6 ? "'" : '.', ph < 0.3 ? th.warn : ph < 0.6 ? th.neg : th.dim);
        }
      }
      if (p > tc && p < tc + 0.9) for (let k = 0; k < 10; k++) {
        const a = hash(k, 31) * Math.PI, r = (p - tc) * 9;
        b.set(Math.round(cx + Math.cos(a) * r), Math.round(logY - 1 - Math.sin(a) * r * 0.5), r < 4 ? '*' : '.', th.warn);
      }
      // smoke wisps above the flames, two rises a loop each
      for (let k = 0; k < 3; k++) {
        const ph = (p * 0.2 + k / 3) % 1;
        const y = logY - 2 - maxH - ph * 4;
        const x = cx + Math.sin(ph * 5 + k * 2) * (2 + ph * 3) + 1;
        if (y > 1 && hash(k, Math.floor(p * 3)) < 0.75) b.set(Math.round(x), Math.round(y), '~', mix(th.muted, th.bg, 0.35 + ph * 0.5));
      }
      // firelight flicker on the ground
      for (let dx = -half - 5; dx <= half + 5; dx++) {
        if (hash(dx + 30, Math.floor(p * 6)) < 0.3 * (1 - Math.abs(dx) / (half + 6))) b.set(cx + dx, ground, '.', th.warn);
      }
    };
  },
};

// ── hot-air balloon ──────────────────────────────────────────────────────────
const ENV = [
  '   .--"--.   ',
  '  / ( | ) \\  ',
  ' |  ( | )  | ',
  ' |  ( | )  | ',
  '  \\ ( | ) /  ',
  "   `-.|.-'   ",
  '    \\ | /    ',
  '    [___]    ',
];
const ENV_S = [
  ' .-"-. ',
  '( ( ) )',
  ' \\( )/ ',
  "  `.'  ",
  '  \\|/  ',
  '  [_]  ',
];

const balloon = {
  ...shared,
  id: 'ascii-balloon',
  since: '0.3.0',
  title: 'Hot-Air Balloon',
  category: 'ASCII Art',
  tags: ['balloon', 'hot air', 'hills', 'drift', 'burner', 'pastoral'],
  order: 230,
  loop: 16,
  description: 'A gored balloon drifts over patchwork hills, sinking gently until the burner roars it back up; clouds slide past and a far balloon crosses behind.',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const art = H < 16 ? ENV_S : ENV;
    const aw = art[0].length;
    const yFar = (x) => H - 6 - Math.sin(x * 0.045 + 1.2) * 1.6 - Math.sin(x * 0.11) * 0.9;
    const yNear = (x) => H - 3.2 - Math.sin(x * 0.06 + 4) * 1.5 - Math.sin(x * 0.15 + 1) * 0.8;
    const depth = clamp(Math.round(H * 0.2), 2, 5);     // how far it sinks before the burner fires
    // the envelope is opaque: each row of the art blanks its span before drawing
    const spans = art.map((row) => [row.search(/\S/), row.length - row.trimEnd().length]);
    return (t) => {
      const b = ctx.buffer;
      t = phase(t, 16);
      const sx = 3;
      b.text(sx, 1, '\\ /', th.warn); b.text(sx - 2, 2, '--(_)--', th.warn); b.text(sx, 3, '/ \\', th.warn);
      for (let c = 0; c < 3; c++) {                      // clouds, one crossing per loop
        const cx = Math.floor((c * 29 + t * ((W + 16) / 16)) % (W + 16)) - 8, cy = 1 + c * 2;
        b.text(cx + 1, cy, '.--.', th.dim); b.text(cx, cy + 1, '(___)', th.dim);
      }
      for (let k = 0; k < 3; k++) {                      // birds filling the mid sky, one crossing per loop each
        const span = W + 6 + 10 * k, x = Math.floor((k * 31 + t * span / 16) % span) - 3;
        b.set(x, 4 + k * Math.max(2, Math.floor(H / 6)), Math.floor(t * 4 + k) % 2 ? 'v' : 'V', th.muted);
      }
      for (let x = 0; x < W; x++) {                      // far hills
        const yf = Math.round(yFar(x));
        b.set(x, yf, '_', mix(th.pos, th.bg, 0.55));
        for (let y = yf + 1; y < H; y++) if (hash(x, y, 3) < 0.2) b.set(x, y, '.', mix(th.pos, th.bg, 0.68));
      }
      const dx2 = ((t * ((W + 10) / 16)) % (W + 10)) - 5; // distant balloon between the hill lines
      b.text(Math.floor(dx2), Math.max(4, Math.floor(H * 0.3)), ' _ ', th.muted);
      b.text(Math.floor(dx2), Math.max(5, Math.floor(H * 0.3) + 1), '( )', th.muted);
      b.text(Math.floor(dx2), Math.max(6, Math.floor(H * 0.3) + 2), ' u ', th.muted);
      for (let x = 0; x < W; x++) {                      // near hills: hedged crop bands
        const yn = Math.round(yNear(x));
        b.set(x, yn, '_', th.pos);
        for (let y = yn + 1; y < H; y++) {
          const bv = (x + (y - yn) * 2) / 9;
          const band = ((Math.floor(bv) % 3) + 3) % 3;
          const hedge = bv - Math.floor(bv) < 0.14;
          const ch = hedge ? ':' : band === 0 ? ',' : band === 1 ? (x % 2 ? '"' : ' ') : (x + y) % 2 ? '.' : ' ';
          if (ch !== ' ') b.set(x, y, ch, mix(th.pos, th.bg, hedge ? 0.2 : 0.3 + band * 0.14));
        }
      }
      const hx = Math.floor(W * 0.74);                   // farmhouse on the near hill
      const hy = Math.round(yNear(hx));
      b.text(hx, hy - 2, '/\\', th.muted); b.text(hx, hy - 1, '||', th.muted);
      const p8 = t % 8;                                  // sinks gently, the burner roars at the bottom, it climbs
      const sink = p8 < 5.4 ? ease(p8 / 5.4) : p8 < 6.4 ? 1 : 1 - ease((p8 - 6.4) / 1.6);
      const bx = Math.round(W * 0.5 + Math.sin(TAU * t / 16) * W * 0.12 - aw / 2);
      const by = 2 + Math.round(depth * sink);
      const shx = bx + Math.floor(aw / 2);               // its shadow on the field
      b.text(shx - 2, Math.min(H - 1, Math.round(yNear(shx)) + 1), '===', mix(th.pos, th.bg, 0.7));
      for (let r = 0; r < art.length; r++) for (let c = spans[r][0]; c >= 0 && c < aw - spans[r][1]; c++) b.set(bx + c, by + r, ' ');
      sprite(b, bx, by, art, (ch, c, r) => (r >= art.length - 2 ? th.muted : ch === '(' || ch === ')' ? th.accent : ch === '|' ? th.accent2 : th.ink));
      if (p8 > 5.4 && p8 < 6.4) {                        // the burner roars
        const fy = by + art.length - 2, fx = bx + Math.floor(aw / 2);
        b.set(fx, fy, hash(1, Math.floor(t * 10)) < 0.5 ? '*' : '^', th.warn);
        b.set(fx, fy - 1, "'", th.neg);
      }
    };
  },
};

// ── castle at night ──────────────────────────────────────────────────────────
const castle = {
  ...shared,
  id: 'ascii-castle',
  since: '0.3.0',
  title: 'Castle at Night',
  category: 'ASCII Art',
  tags: ['castle', 'torches', 'flag', 'moat', 'battlements', 'medieval'],
  order: 240,
  loop: 12,
  description: 'A keep and two towers over a moat: the pennant streams in the wind, gate torches gutter, arrow slits glow, bats flit across a crescent moon.',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const cx = Math.floor(W / 2);
    const baseY = H - 4;
    const keepW = W < 44 ? 9 : 11, tw = W < 44 ? 5 : 7;
    const wg = clamp(Math.round(W * 0.07), 3, 8);
    // Short screens: the keep stops 4 rows below the top so flagpole and flag stay on screen,
    // and towers and walls step down under it (at 80x24 these caps don't bind).
    const keepH = Math.min(Math.max(6, Math.round(H * 0.5)), baseY - 4);
    const towH = Math.min(Math.max(4, Math.round(H * 0.36)), keepH - 1);
    const wallH = Math.min(Math.max(3, Math.round(H * 0.2)), towH - 1);
    const keepL = cx - (keepW >> 1), keepR = keepL + keepW - 1;
    const towLx = keepL - wg - tw + 1, towRx = keepR + wg;
    const wall = (x0, w, hgt) => {                       // crenellated block
      const b = ctx.buffer;
      const top = baseY - hgt;
      for (let i = 0; i < w; i++) if (i % 2 === 0) b.set(x0 + i, top - 1, '_', th.ink);
      for (let i = 0; i < w; i++) b.set(x0 + i, top, i === 0 || i === w - 1 ? '|' : i % 2 ? '_' : '|', th.ink);
      for (let y = top + 1; y <= baseY; y++) {
        b.set(x0, y, '|', th.ink); b.set(x0 + w - 1, y, '|', th.ink);
        for (let i = 1; i < w - 1; i++) b.set(x0 + i, y, hash(x0 + i, y, 3) < 0.08 ? '.' : ' ', mix(th.muted, th.bg, 0.5));
      }
      return top;
    };
    return (t) => {
      const b = ctx.buffer;
      t = phase(t, 12); // flicker keys on loop time too, so the castle closes exactly
      stars(b, W, Math.max(3, H - 8), th, t);
      moon(b, Math.floor(W * 0.08), 1, th);
      for (let k = 0; k < 2; k++) {                      // bats
        const a = TAU * t / 6 + k * 2.6;
        const x = Math.round(cx + Math.cos(a) * (10 + k * 6)), y = Math.round(3 + Math.sin(a * 2) * 1.5 + k);
        b.set(x, y, Math.floor(t * 6 + k) % 2 ? 'v' : 'w', th.muted);
      }
      wall(keepL - wg, wg + 1, wallH); wall(keepR, wg + 1, wallH);       // curtain walls
      const lt = wall(towLx, tw, towH), rt = wall(towRx, tw, towH);      // towers
      const kt = wall(keepL, keepW, keepH);                              // the keep, in front
      for (const [x, y] of [[towLx + (tw >> 1), lt + 2], [towRx + (tw >> 1), rt + 2], [cx - 2, kt + 2], [cx + 2, kt + 2], [cx, kt + 4]]) {
        b.set(x, y, '!', hash(x, Math.floor(t / 1.5)) < 0.7 ? th.warn : th.dim);  // arrow slits
      }
      b.set(cx, kt - 2, '|', th.ink); b.set(cx, kt - 3, '|', th.ink);             // flagpole
      for (let i = 0; i < 5; i++) {
        const y = kt - 3 + Math.round(Math.sin(TAU * t / 2 - i * 0.9) * 0.8 * ((i + 1) / 5));
        b.set(cx + 1 + i, y, i === 4 ? '>' : '~', th.accent);
      }
      const gw = 4, gx = cx - (gw >> 1);                 // gate + portcullis
      b.text(gx, baseY - 3, ' __ ', th.muted);
      for (let y = baseY - 2; y <= baseY; y++) for (let i = 0; i < gw; i++) {
        b.set(gx + i, y, (i + y) % 2 ? '#' : '+', mix(th.muted, th.bg, 0.35));
      }
      for (const s of [-1, 1]) {                         // gate torches
        const x = cx + s * ((gw >> 1) + 2);
        b.set(x, baseY, '|', th.muted); b.set(x, baseY - 1, '|', th.muted);
        const f = hash(s + 2, Math.floor(t * 7));
        b.set(x, baseY - 2, f < 0.35 ? '(' : f < 0.7 ? ')' : '*', f < 0.5 ? th.warn : th.neg);
        if (hash(s + 5, Math.floor(t * 5)) < 0.4) b.set(x + s, baseY - 3, "'", th.warn);
      }
      for (let x = 0; x < W; x++) b.set(x, baseY + 1, '_', mix(th.pos, th.bg, 0.5));
      for (let y = baseY + 2; y < H; y++) for (let x = 0; x < W; x++) {           // the moat
        const v = Math.sin(x * 0.3 + hash(y, 61) * TAU + t * (TAU / 6) * (y % 2 ? 1 : -1));
        if (v > 0.35) b.set(x, y, v > 0.85 ? '~' : '-', mix(th.info, th.bg, 0.45 + (y - baseY) * 0.1));
      }
      for (const s of [-1, 1]) {                         // torchlight on the water
        const x = cx + s * ((gw >> 1) + 2);
        if (hash(s + 9, Math.floor(t * 4)) < 0.6) b.set(x, baseY + 2, '.', th.warn);
      }
      b.text(gx - 1, baseY + 2, '='.repeat(gw + 2), th.muted);                    // the bridge
    };
  },
};

// ── desert caravan ───────────────────────────────────────────────────────────
const CAMEL = [
  ' ,,    __    __  ',
  ' (.`,-"  `--"  `.',
  '  \\ ;          \\ \\',
];
const LEG_X = [5, 8, 12, 15];

/** A dune crest as one smooth curve: its height inside each cell picks the glyph (" - . _, top to bottom); sparse sand below. */
const CURVE = ['"', '-', '.', '_'];
function crest(b, W, yOf, yMax, line, sand, dens, seed) {
  for (let x = 0; x < W; x++) {
    const y = yOf(x), r = Math.floor(y);
    b.set(x, r, CURVE[Math.min(3, Math.floor((y - r) * 4))], line);
    for (let yy = r + 1; yy < yMax; yy++) if (hash(x, yy, seed) < dens) b.set(x, yy, hash(x, yy, seed + 1) < 0.5 ? '.' : ',', sand);
  }
}

const caravan = {
  ...shared,
  id: 'ascii-caravan',
  since: '0.3.0',
  title: 'Desert Caravan',
  category: 'ASCII Art',
  tags: ['desert', 'caravan', 'camels', 'dunes', 'heat', 'shimmer'],
  order: 260,
  loop: 18,
  minSize: { w: 44, h: 13 },
  description: 'Three roped camels sway across the dunes under a hard sun: heat shimmer bends the far ridge, footprints trail off and drift over, a vulture rides the thermal.',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const gy = H - 7;                                    // camel top row
    const horizon = Math.max(2, Math.min(Math.floor(H * 0.45), gy - 2));
    const span = W + 76;
    const sand = mix(th.warn, th.bg, 0.45), sandDim = mix(th.warn, th.bg, th.mode === 'light' ? 0.5 : 0.62);
    return (t) => {
      const b = ctx.buffer;
      const p = phase(t, 18);
      const sx = Math.floor(W * 0.78);
      b.text(sx + 1, 1, ' __ ', th.warn); b.text(sx, 2, '(__)', th.warn);
      for (const [dx, dy, ch] of [[-2, 0, '-'], [6, 0, '-'], [2, -2, '|'], [-1, 2, '/'], [5, 2, '\\']]) b.set(sx + dx + 1, 2 + dy, ch, th.warn);
      // far ridge, bent by a travelling heat-shimmer wave
      crest(b, W, (x) => horizon - 1.2 * Math.sin(x * 0.05 + 2) - 0.7 * Math.sin(x * 0.12 + 0.7) + 0.35 * Math.sin(x * 0.35 - TAU * 9 * p / 18), horizon + 2, sandDim, sandDim, 0.05, 11);
      // a mid dune behind the caravan
      crest(b, W, (x) => gy - 2.2 + Math.sin(x * 0.08 + 1) * 1.2, gy, sandDim, sandDim, 0.08, 13);
      const vx = Math.round(W * 0.3 + Math.cos(TAU * p / 9) * 12);                // vulture
      b.set(vx, Math.round(2 + Math.sin(TAU * p / 9) * 1.2), Math.floor(p * 2) % 2 ? 'v' : '-', th.muted);
      const head = W + 10 - p * (span / 18);             // the caravan walks right to left
      for (let i = 0; i < 3; i++) {
        const x = Math.round(head + i * 20);
        sprite(b, x, gy, CAMEL, th.ink);
        const stride = Math.floor(p * 2.5 + i * 0.7) % 2;
        for (let l = 0; l < 4; l++) {
          const lx = x + LEG_X[l];
          b.set(lx, gy + 3, '|', th.ink);
          b.set(lx + (stride && l % 2 ? -1 : stride ? 1 : 0), gy + 4, stride ? (l % 2 ? '/' : '\\') : '|', th.ink);
        }
        if (i === 0) { b.set(x + 9, gy - 1, 'o', th.accent); b.set(x + 10, gy, '(', th.accent); }
        if (i < 2) { b.set(x + 17, gy + 1, '-', th.muted); b.set(x + 18, gy + 2, '.', th.muted); b.set(x + 19, gy + 1, '-', th.muted); }
      }
      for (let x = 0; x < W; x++) b.set(x, gy + 5, hash(x, 2) < 0.7 ? '_' : '.', sand);   // the track
      for (let j = 1; j < 14; j++) {                     // footprints, the oldest drifting over first in the last 2 s
        const fx = Math.round(head + 3 * 20 + j * 3), gone = 18 - 2 * (j / 13);
        if (fx <= 0 || fx >= W || p >= gone) continue;
        b.set(fx + (j % 2), gy + 5, gone - p < 0.4 ? '.' : j % 2 ? 'v' : 'w', mix(th.warn, th.bg, 0.5 + j * 0.03));
      }
      for (let y = gy + 6; y < H; y++) for (let x = 0; x < W; x++) {              // open sand
        if (hash(x, y, 9) < 0.12) b.set(x, y, hash(x, y, 5) < 0.5 ? '.' : ',', sandDim);
      }
    };
  },
};

// ── firefly forest ───────────────────────────────────────────────────────────
const fireflies = {
  ...shared,
  id: 'ascii-fireflies',
  since: '0.3.0',
  title: 'Firefly Forest',
  category: 'ASCII Art',
  tags: ['fireflies', 'forest', 'night', 'glow', 'trees', 'summer'],
  order: 270,
  loop: 14,
  description: 'A dark stand of trees full of fireflies: each one wanders on its own looping path and pulses . o * o . while moonlight falls through a gap in the canopy.',
  setup(ctx) {
    const { width: W, height: H, theme: th, noise } = ctx;
    const canopyY = Math.max(2, Math.floor(H * 0.2));
    const ground = H - 2;
    const trunks = [];
    for (let i = 0, n = Math.max(3, Math.floor(W / 14)); i < n; i++) {
      trunks.push({ x: Math.floor((0.06 + 0.9 * ((i + hash(i, 2) * 0.6) / n)) * W), w: hash(i, 3) < 0.45 ? 2 : 1 });
    }
    const owl = trunks.find((tr) => tr.w === 2);
    const flies = Math.max(14, Math.round(W * H / 50));
    const gapX = Math.floor(W * 0.6);
    return (t) => {
      const b = ctx.buffer;
      t = phase(t, 14);
      const ang = TAU * t / 14, ca = Math.cos(ang), sa = Math.sin(ang);  // noise sampled on a circle: paths close in 14 s
      for (let y = 0; y <= canopyY + 1; y++) for (let x = 0; x < W; x++) {   // canopy
        if (Math.abs(x - gapX) < 5 - y) continue;                            // moon gap
        const r = hash(x, y, 7);
        const tw = hash(x, y, Math.floor(t * 1.5));
        if (r < 0.78 - y * 0.15 && tw < 0.92) b.set(x, y, r < 0.14 ? '%' : r < 0.34 ? ';' : ':', mix(th.pos, th.bg, 0.5 + r * 0.3));
      }
      b.text(gapX - 1, 0, '(_)', th.ink);                                    // the moon in the gap
      for (let k = 0; k < 14; k++) {                                         // moonbeam motes
        const y = 1 + Math.floor(hash(k, 13) * (ground - 2));
        const x = gapX - 1 + Math.floor(hash(k, 17) * 4) - Math.floor(y / 5);
        if (hash(k, Math.floor(t * 2)) < 0.55) b.set(x, y, '.', mix(th.ink, th.bg, 0.6));
      }
      for (const tr of trunks) {                                             // trunks + roots
        for (let y = canopyY + 1; y <= ground; y++) {
          for (let i = 0; i < tr.w; i++) {
            const r = hash(tr.x + i, y, 5);
            b.set(tr.x + i, y, r < 0.12 ? ')' : r < 0.2 ? '(' : '|', mix(th.muted, th.bg, 0.35));
          }
        }
        b.set(tr.x - 1, ground, '/', mix(th.muted, th.bg, 0.35));
        b.set(tr.x + tr.w, ground, '\\', mix(th.muted, th.bg, 0.35));
      }
      if (owl) {                                                             // an owl in one hollow
        const blink = Math.floor(t + hash(owl.x, 4) * 7) % 7 === 0;
        b.text(owl.x, canopyY + 3, blink ? '--' : 'oo', th.warn);
      }
      for (let x = 0; x < W; x++) {                                          // undergrowth
        const r = hash(x, 21);
        b.set(x, ground + 1, r < 0.3 ? ',' : r < 0.4 ? 'v' : '.', mix(th.pos, th.bg, th.mode === 'light' ? 0.45 : 0.6));
        if (r > 0.92) b.set(x, ground, 'w', mix(th.pos, th.bg, 0.45));
      }
      b.text(Math.floor(W * 0.15), ground, '(______)', mix(th.muted, th.bg, 0.4));  // a fallen log
      for (let k = 0; k < flies; k++) {                                      // the fireflies
        const fx = hash(k, 51) * W, fy = canopyY + 2 + hash(k, 52) * (ground - canopyY - 3);
        const x = Math.round(fx + noise.noise3(k * 3.1, 0.49 * ca, 0.49 * sa) * 9);
        const y = Math.round(fy + noise.noise3(k * 3.1 + 40, 0.4 * ca, 0.4 * sa) * 3);
        const P = 14 / (5 + Math.floor(hash(k, 53) * 4));  // 5–8 blinks per loop
        const bp = ((t + hash(k, 54) * P * 3) % P) / P;
        if (bp > 0.45 || y <= canopyY || y >= ground + 1) continue;
        const s = bp / 0.45;
        const ch = s < 0.25 || s > 0.75 ? '.' : s < 0.45 || s > 0.55 ? 'o' : '*';
        b.set(x, y, ch, ch === '*' ? th.warn : mix(th.warn, th.bg, 0.3));
        if (ch === '*') { b.set(x - 1, y, '.', mix(th.warn, th.bg, 0.55)); b.set(x + 1, y, '.', mix(th.warn, th.bg, 0.55)); }
      }
    };
  },
};

export default [campfire, balloon, castle, caravan, fireflies];

sources.prism-term/src/facets/ascii/loading.js:
// Pure ASCII — waiting for the machine: an Award BIOS POST into LILO, a ZX
// Spectrum loading from tape, Arch's pacman with ILoveCandy, and the spinning
// wait cursor at poster size. 7-bit glyphs only (0x20–0x7e).
import { hash } from './_ascii.js';
import { mix } from '../../color.js';

const shared = { gallery: 'ascii', category: 'ASCII Spinners & Bars', glyphs: 'ascii', color: '16' };
const TAU = Math.PI * 2;
/** Time within the loop, quantized so t and t + loop draw identical frames (flicker keys included). */
const phase = (t, loop) => Math.round((((t % loop) + loop) % loop) * 1e6) / 1e6;
const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
const fit = (s, w) => (w <= 0 ? '' : s.length > w ? s.slice(0, w) : s);

/** Scripted terminal: lines = [{ at, parts(tau) → [[text, color], …] }]; shows the newest lines that fit. */
function terminal(b, lines, tau, x, y, w, h) {
  const shown = lines.filter((l) => l.at <= tau);
  const tail = shown.slice(Math.max(0, shown.length - h));
  tail.forEach((l, r) => { let cx = x; for (const [s, c] of l.parts(tau)) { cx = b.text(cx, y + r, fit(s, x + w - cx), c); if (cx >= x + w) break; } });
  return tail.length;
}

// ── Award BIOS POST ──────────────────────────────────────────────────────────
const bios = {
  ...shared,
  id: 'ascii-bios-post',
  since: '0.3.0',
  title: 'BIOS POST',
  tags: ['bios', 'post', 'boot', 'award', 'lilo', 'linux', 'retro', 'memory test'],
  order: 300,
  kind: 'progress',
  loop: 22,
  size: { w: 80, h: 24 },
  minSize: { w: 44, h: 12 },
  description: 'An Award-style BIOS POST: the memory test races up in 1024K steps, drives are detected dot by dot, then LILO loads and Linux boots before a warm reboot.',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const S = (at, ...parts) => ({ at, parts: typeof parts[0] === 'function' ? parts[0] : () => parts });
    const dots = (t0, n, gaps) => (tau) => {             // dots that tick at irregular waits
      let k = 0, at = t0;
      while (k < n && at + gaps[k % gaps.length] <= tau) { at += gaps[k % gaps.length]; k++; }
      return k;
    };
    const detect = (at, what, result) => S(at, (tau) => {
      const k = dots(at, 3, [0.35, 0.55, 0.25])(tau);
      return [[(W >= 48 ? '  Detecting ' : '  ') + what.padEnd(19) + ' ' + '.'.repeat(k), th.ink], ...(k === 3 && tau >= at + 1.25 ? [[' ' + result, result === 'None' ? th.dim : th.pos]] : [])];
    });
    const fits = (full, short) => (full.length <= W ? full : short);   // narrow screens get whole-word short forms
    const lines = [
      S(0.2, ['Award Modular BIOS v4.51PG', th.info]),
      S(0.3, ['Copyright (C) 1984-98, Award Software, Inc.', th.info]),
      S(0.7, ['PENTIUM-MMX CPU at 233MHz', th.ink]),
      S(1.0, (tau) => {
        const k = Math.min(64, Math.floor((tau - 1) / 0.04));
        return [['Memory Test : ', th.info], [`${String(k * 1024).padStart(6)}K`, th.ink], ...(k >= 64 ? [[' OK', th.pos]] : [])];
      }),
      S(4.0, ['Award Plug and Play BIOS Extension v1.0A', th.info]),
      S(4.1, ['Copyright (C) 1998, Award Software, Inc.', th.info]),
      detect(4.5, 'HDD Primary Master', 'WDC AC22100H'),
      detect(6.0, 'HDD Primary Slave', 'None'),
      detect(7.5, 'HDD Secondary Master', 'ATAPI CDROM'),
      detect(9.0, 'HDD Secondary Slave', 'None'),
      S(10.6, (tau) => [['Verifying DMI Pool Data ', th.ink], ['.'.repeat(Math.min(8, Math.floor((tau - 10.6) / 0.18))), th.ink]]),
      S(12.3, ['LILO boot:', th.ink]),
      S(13.6, (tau) => [['Loading linux', th.ink], ['.'.repeat(Math.min(8, Math.floor((tau - 13.6) / 0.16))), th.ink]]),
      S(15.2, ['Uncompressing Linux... ', th.ink], ['Ok', th.pos], [W >= 46 ? ', booting the kernel.' : '', th.ink]),
      S(15.9, [fits('Linux version 2.2.14 (root@prism) (gcc version egcs-2.91.66) #1', 'Linux version 2.2.14 (root@prism)'), th.muted]),
      S(16.2, ['Detected 233866 kHz processor.', th.muted]),
      S(16.4, ['Console: colour VGA+ 80x25', th.muted]),
      S(16.7, ['Calibrating delay loop... 466.94 BogoMIPS', th.muted]),
      S(17.1, [fits('Memory: 62712k/65536k available (1084k kernel code)', 'Memory: 62712k/65536k available'), th.muted]),
      S(17.5, ['INIT: version 2.78 booting', th.ink]),
      S(18.6, ['INIT: Sending processes the TERM signal', th.ink]),
      S(19.4, ['Restarting system.', th.warn]),
    ];
    return (t) => {
      const b = ctx.buffer;
      const tau = phase(t, 22);
      if (tau >= 20.2) {                                    // warm reboot: a blank screen, the cursor blinking
        if (Math.floor(tau * 3) % 2 === 0) b.set(0, 0, '_', th.ink);
        return;
      }
      const used = terminal(b, lines, tau, 0, 0, W, H - 2);  // the cursor keeps a row of its own below the newest line
      if (Math.floor(tau * 3) % 2 === 0) b.set(0, Math.min(H - 2, used), '_', th.ink);
      if (tau >= 0.15 && tau < 12) b.text(0, H - 1, fits('Press DEL to enter SETUP, ESC to skip memory test', 'Press DEL to enter SETUP'), th.dim);
    };
  },
};

// ── ZX Spectrum tape loader ──────────────────────────────────────────────────
// Phases of one load: [start, kind]; kinds: 'pilot' | 'data' | 'quiet'.
const TAPE = [[0, 'pilot'], [2, 'data'], [2.3, 'pilot'], [3.5, 'data'], [4, 'pilot'], [4.6, 'data'], [12.4, 'quiet']];
const RAMP = ' .:-=+*#%@';

const tape = {
  ...shared,
  id: 'ascii-tape-loader',
  since: '0.3.0',
  title: '8-bit Tape Loader',
  tags: ['zx spectrum', 'tape', 'loading', 'border', '8-bit', 'retro', 'cassette'],
  order: 310,
  kind: 'progress',
  loop: 16,
  size: { w: 80, h: 24 },
  minSize: { w: 40, h: 12 },
  description: 'A ZX Spectrum loads from tape: the border rolls with thick pilot stripes and noisy data bands while the picture fills like a venetian blind.',
  credits: 'after the Sinclair ZX Spectrum (1982) ROM loader',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const bx = Math.max(3, Math.round(W * 0.1)), by = Math.max(2, Math.round(H * 0.12));
    const iw = W - 2 * bx, ih = H - 2 * by;
    // the picture (luminance 0..1 per cell): a ringed planet with the title over it
    const pic = new Float32Array(iw * ih), attr = new Int32Array(iw * ih);
    const pcx = iw * 0.62, pcy = ih * 0.58, pr = Math.min(iw * 0.22, ih * 0.42 * 2);
    const tones = [th.info, th.accent2, th.warn, th.pos, th.ink];
    for (let y = 0; y < ih; y++) for (let x = 0; x < iw; x++) {
      const dx = (x - pcx) / pr, dy = ((y - pcy) * 2) / pr, d = Math.hypot(dx, dy);
      let v = d < 1 ? 0.25 + 0.75 * Math.max(0, 1 - Math.hypot(dx + 0.4, dy + 0.4) * 0.8) : 0;
      const ring = Math.abs(dy * 1 - dx * 0.25) < 0.08 && d > 1.05 && d < 1.7;
      if (ring) v = 0.6;
      if (!v && hash(x, y, 7) < 0.035) v = 0.9;            // stars
      pic[y * iw + x] = v;
      attr[y * iw + x] = ring ? tones[2] : d < 1 ? tones[0] : v ? tones[4] : th.ink;
    }
    const title = 'P L A N E T S', ty = Math.max(0, Math.floor(ih * 0.15)), tx = Math.max(0, Math.floor(iw * 0.08));
    // Spectrum line order: thirds, then line n of every character row, then line n + 1 …
    const order = [], third = Math.max(1, Math.ceil(ih / 3)), L = ih >= 12 ? 3 : 2;
    for (let tr = 0; tr < 3; tr++) for (let line = 0; line < L; line++) for (let cr = 0; cr * L < third; cr++) {
      const y = tr * third + cr * L + line;
      if (y < ih && y < (tr + 1) * third) order.push(y);
    }
    for (let y = 0; y < ih; y++) if (!order.includes(y)) order.push(y);
    const rank = new Int32Array(ih); order.forEach((y, i) => { rank[y] = i; });
    return (t) => {
      const b = ctx.buffer;
      const tau = phase(t, 16);
      let kind = 'pilot';
      for (const [at, k] of TAPE) if (tau >= at) kind = k;
      const blank = tau >= 14.8;
      // the border
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        if (x >= bx && x < W - bx && y >= by && y < H - by) continue;
        let ch = ' ', c = th.dim;
        if (kind === 'pilot') { const band = Math.floor((y + tau * 9) / 2) % 2; ch = band ? '#' : '='; c = band ? th.neg : th.info; }
        else if (kind === 'data') { const r = hash(y, Math.floor(tau * 25)); ch = r < 0.5 ? '#' : '-'; c = r < 0.5 ? th.accent2 : th.warn; }
        else ch = '.';
        b.set(x, y, ch, c);
      }
      // the screen
      const filled = kind === 'quiet' || tau >= 12.4 ? ih : tau >= 4.6 ? Math.floor(((tau - 4.6) / 6.4) * ih) : 0;
      const attrs = tau >= 11 ? clamp01((tau - 11) / 1.4) : 0;
      if (!blank) for (let y = 0; y < ih; y++) {
        if (rank[y] >= filled) continue;
        for (let x = 0; x < iw; x++) {
          const v = pic[y * iw + x];
          if (!v) continue;
          const lit = (y * iw + x) / (iw * ih) < attrs;          // attributes load in linear order
          b.set(bx + x, by + y, RAMP[Math.min(9, Math.round(v * 9))], lit ? attr[y * iw + x] : th.ink);
        }
        if (y === ty) b.text(bx + tx, by + y, title, attrs > 0.1 ? th.warn : th.ink);
      }
      const msgY = H - by - 1;
      if (!blank && tau >= 2.3) b.text(bx + 1, msgY, 'Program: PLANETS', th.ink);
      if (!blank && tau >= 4 && tau < 11) b.text(bx + 1, msgY - 1, 'Bytes: SCREEN$', th.ink);
    };
  },
};

// ── a package sync with ILoveCandy ──────────────────────────────────────────────
const PKGS = [['curl-8.11.0-1', 1.2], ['linux-6.12.1.arch1-1', 136.2], ['linux-headers-6.12.1.arch1-1', 35.4], ['mesa-1:24.2.7-1', 9.1], ['openssl-3.4.0-1', 5.3], ['python-3.12.7-1', 11.8], ['systemd-256.8-1', 8.4]];

const pacman = {
  ...shared,
  id: 'ascii-chomp-sync',
  since: '0.3.0',
  title: 'Chomping Package Sync',
  tags: ['arch linux', 'ilovecandy', 'package manager', 'chomp', 'update', 'terminal'],
  order: 320,
  kind: 'progress',
  loop: 20,
  size: { w: 80, h: 16 },
  minSize: { w: 44, h: 6 },
  description: 'Arch\'s package manager with ILoveCandy on: each progress bar is a chomping mouth eating a row of pellets as databases sync, packages download and hooks run.',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const bw = Math.max(10, Math.min(24, Math.floor(W * 0.28)));
    // [------C o  o  o ] — the trail behind, the mouth alternating C/c, pellets every third cell ahead
    const candy = (p, tau) => {
      const n = bw - 2, pos = Math.round(clamp01(p) * n);
      const out = [['[', th.ink]];
      for (let i = 0; i < n; i++) {
        if (i < pos || (p >= 1 && i < n)) out.push(['-', th.dim]);
        else if (i === pos) out.push([Math.floor(tau * 10) % 2 ? 'C' : 'c', th.warn]);
        else out.push([(i - pos) % 3 === 0 ? 'o' : ' ', th.ink]);
      }
      out.push([']', th.ink]);
      return out;
    };
    // info(p) → [size, 'rate time']; when narrow only the size stays, as pacman drops columns, so the bar and % always fit
    const row = (at, dur, name, info) => ({ at, parts: (tau) => {
      const p = clamp01((tau - at) / dur), cols = info ? info(p) : null;
      const full = cols && W - bw - 37 >= 8, infoW = !cols ? 0 : full ? 30 : W - bw - 17 >= 8 ? 10 : 0, nameW = Math.max(8, W - bw - 7 - infoW);
      const nm = name.length > nameW ? name.slice(0, nameW - 3) + '...' : name.padEnd(nameW);
      const inf = !infoW ? [] : [[full ? `${cols[0]}  ${cols[1]}`.padStart(29) + ' ' : cols[0].padStart(9) + ' ', th.muted]];
      return [[` ${nm} `, th.ink], ...inf, ...candy(p, tau), [` ${String(Math.round(p * 100)).padStart(3)}%`, th.ink]];
    } });
    const L = (at, ...parts) => ({ at, parts: () => parts });
    const ln = [];
    ln.push({ at: 0, parts: (tau) => [['$ ', th.pos], ['sudo pacman -Syu'.slice(0, Math.floor(clamp01(tau / 0.8) * 16)), th.ink]] });
    ln.push(L(0.9, [':: ', th.info], ['Synchronizing package databases...', th.ink]));
    [['core', 130.3, 912], ['extra', 8499, 6210], ['multilib', 142.7, 1102]].forEach(([n, kb, rate], i) => ln.push(row(1 + i * 0.5, 0.45, n, (p) => [kb >= 1000 ? (kb / 1024).toFixed(1) + ' MiB' : kb + ' KiB', `${rate >= 1000 ? (rate / 1024).toFixed(2) + ' MiB/s' : rate + ' KiB/s'} 00:0${p < 1 ? 1 : 0}`])));
    ln.push(L(2.7, [':: ', th.info], ['Starting full system upgrade...', th.ink]));
    ln.push(L(2.9, ['resolving dependencies...', th.ink]));
    ln.push(L(3.1, ['looking for conflicting packages...', th.ink]));
    ln.push(L(3.4, [`Packages (7) ${PKGS.map(([n]) => n).join('  ')}`, th.ink]));
    ln.push(L(3.6, ['Total Download Size:   207.40 MiB', th.ink]));
    ln.push(L(3.7, ['Total Installed Size:  612.18 MiB', th.ink]));
    ln.push({ at: 4.2, parts: (tau) => [[':: ', th.info], ['Proceed with installation? [Y/n] ', th.ink], [tau >= 5.1 ? 'y' : Math.floor(tau * 3) % 2 ? '_' : ' ', th.ink]] });
    ln.push(L(5.3, [':: ', th.info], ['Retrieving packages...', th.ink]));
    let at = 5.4;
    for (const [n, mib] of PKGS) { const dur = 0.35 + mib / 60; ln.push(row(at, dur, `${n}-x86_64`, (p) => [`${(mib * p).toFixed(1)} MiB`, `9.81 MiB/s 00:${String(Math.max(0, Math.round((1 - p) * mib / 9.8))).padStart(2, '0')}`])); at += dur + 0.05; }
    for (const s of ['checking keys in keyring', 'checking package integrity', 'loading package files', 'checking for file conflicts']) { ln.push(row(at, 0.3, `(7/7) ${s}`)); at += 0.33; }
    ln.push(L(at + 0.1, [':: ', th.info], ['Processing package changes...', th.ink])); at += 0.2;
    PKGS.forEach(([n], i) => { ln.push(row(at, 0.4, `(${i + 1}/7) upgrading ${n.split(/-\d/)[0]}`)); at += 0.43; });
    ln.push(L(at + 0.1, [':: ', th.info], ['Running post-transaction hooks...', th.ink])); at += 0.2;
    ['Arming ConditionNeedsUpdate...', 'Updating module dependencies...', 'Updating linux initcpios...', 'Reloading system manager configuration...'].forEach((s, i) => { ln.push(L(at, [`(${i + 1}/4) ${s}`, th.ink])); at += 0.35; });
    const promptAt = at + 0.2;
    ln.push({ at: promptAt, parts: (tau) => [['$ ', th.pos], ['clear'.slice(0, Math.floor(clamp01((tau - promptAt - 0.4) / 0.5) * 5)), th.ink]] });
    const clearAt = Math.min(19.6, promptAt + 1.2);
    return (t) => {
      const b = ctx.buffer;
      const tau = phase(t, 20);
      if (tau >= clearAt) { b.text(0, 0, '$ ', th.pos); if (Math.floor(tau * 3) % 2) b.set(2, 0, '_', th.ink); return; }
      terminal(b, ln, tau, 0, 0, W, H);
    };
  },
};

// ── the spinning wait cursor ─────────────────────────────────────────────────
// angular speed profile over the loop: spin-up, steady with a hitch, spin-down, recovered, hang again
// the hang's spin-up straddles the seam (0 → 0.5 over 10.5–12 s, 0.5 → 1 over 0–1 s), so speed is continuous too
const omegaRaw = (t) => (t < 1 ? 0.5 + 0.5 * t : t < 7.5 ? (Math.abs(t - 4.3) < 0.25 ? 0.25 : 1) : t < 8.5 ? 8.5 - t : t < 10.5 ? 0 : ((t - 10.5) / 1.5) * 0.5);
const BALL = (() => {                                     // integrate, scaled to exactly 6 turns per loop
  const N = 1200, ang = new Float64Array(N + 1);
  for (let i = 0; i < N; i++) ang[i + 1] = ang[i] + omegaRaw(((i + 0.5) / N) * 12) * (12 / N);
  const k = (6 * TAU) / ang[N];
  return (t) => { const x = (t / 12) * N, i = Math.min(N - 1, Math.floor(x)); return (ang[i] + (ang[i + 1] - ang[i]) * (x - i)) * k; };
})();
const ARROW = ['|\\', '|.\\', '|..\\', '|...\\', '|..--', '|/'];

const beachball = {
  ...shared,
  id: 'ascii-beachball',
  since: '0.3.0',
  title: 'Spinning Wait Cursor',
  tags: ['beachball', 'wait cursor', 'not responding', 'spinner', 'macos', 'hang'],
  order: 330,
  kind: 'spinner',
  loop: 12,
  size: { w: 48, h: 22 },
  minSize: { w: 24, h: 11 },
  description: 'The spinning wait cursor at poster size: eight shaded wedges spin up, hitch, wind down as the app recovers and the arrow returns, then it hangs again.',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const cols = [th.accent, th.accent2, th.info, th.pos, th.warn, th.neg, th.crit, th.ink];
    const capY = H - 2, R = Math.max(4, Math.min((W - 4) / 2, (capY - 1) * 1.0));
    const cx = W / 2, cy = (capY - 1) / 2 + 0.5;
    const SHADE = '@%#*+=-:.';
    return (t) => {
      const b = ctx.buffer;
      const tau = phase(t, 12), rot = BALL(tau);
      const recovered = tau >= 8.5 && tau < 10.5;
      if (!recovered) for (let y = 0; y < capY; y++) for (let x = 0; x < W; x++) {
        const dx = x + 0.5 - cx, dy = (y + 0.5 - cy) * 2, r = Math.hypot(dx, dy) / R;
        if (r > 1) continue;
        const wedge = ((Math.floor(((Math.atan2(dy, dx) + rot) / TAU) * 8) % 8) + 8) % 8;
        const gloss = r > 0.45 && r < 0.75 && Math.abs(Math.atan2(dy, dx) + 2.3) < 0.35;  // a highlight band, fixed in place
        b.set(x, y, gloss ? ':' : SHADE[Math.min(8, Math.floor(r * 9))], gloss ? mix(cols[wedge], th.ink, 0.6) : cols[wedge]);
      }
      else ARROW.forEach((s, i) => b.text(Math.floor(cx) - 1, Math.floor(cy) - 3 + i, s, th.ink));
      const cap = W >= 30 ? (recovered ? 'Finder' : 'Finder -- Not Responding') : recovered ? 'Finder' : 'Not Responding';
      b.text(Math.max(0, Math.floor((W - cap.length) / 2)), capY, cap, th.muted);
    };
  },
};

export default [bios, tape, pacman, beachball];

sources.prism-term/src/facets/ascii/operations.j:
// Pure ASCII — long operations, watched: MS-DOS DEFRAG condensing a disk, a
// Windows 95 copy dialog with its flying page, a quay crane loading a ship as a
// Kubernetes rollout, and a theater marquee of chasing bulbs. 7-bit only.
import { sprite, hash, box } from './_ascii.js';
import { mix } from '../../color.js';

const shared = { gallery: 'ascii', category: 'ASCII Spinners & Bars', glyphs: 'ascii', color: '16' };
/** Time within the loop, quantized so t and t + loop draw identical frames (flicker keys included). */
const phase = (t, loop) => Math.round((((t % loop) + loop) % loop) * 1e6) / 1e6;
const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
const ease = (k) => { k = clamp01(k); return k * k * (3 - 2 * k); };
const mmss = (s) => `${String(Math.floor(s / 3600)).padStart(2, '0')}:${String(Math.floor(s / 60) % 60).padStart(2, '0')}:${String(Math.floor(s) % 60).padStart(2, '0')}`;
const pbar = (w, p) => '[' + '#'.repeat(Math.round(clamp01(p) * w)) + '.'.repeat(w - Math.round(clamp01(p) * w)) + ']';

// ── DEFRAG ───────────────────────────────────────────────────────────────────
const FREE = 0, USED = 1, FIXED = 2, BAD = 3;

const defrag = {
  ...shared,
  id: 'ascii-defrag',
  since: '0.3.0',
  title: 'Defrag Block Map',
  tags: ['defrag', 'ms-dos', 'disk', 'clusters', 'optimize', 'retro', 'block map'],
  order: 340,
  kind: 'progress',
  loop: 24,
  size: { w: 80, h: 22 },
  minSize: { w: 44, h: 12 },
  description: 'An MS-DOS 6-style DEFRAG condenses a fragmented disk: r reads a run of clusters, W writes it into the leftmost gap until the map is solid, then re-analyzes.',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const gx = 1, gy = 2, gw = W - 2, gh = Math.max(3, H - (W >= 70 ? 7 : 6)), N = gw * gh;
    const start = new Uint8Array(N);
    for (let i = 0; i < N;) {                             // runs of files and gaps, a few fixed and bad clusters
      const used = hash(i, 3) < 0.58, len = 1 + Math.floor(hash(i, 5) * (used ? 8 : 5));
      for (let j = 0; j < len && i < N; j++, i++) start[i] = used ? USED : FREE;
    }
    for (let k = 0; k < 6; k++) start[Math.floor(hash(k, 11) * N)] = FIXED;
    for (let k = 0; k < 3; k++) start[Math.floor(hash(k, 13) * N)] = BAD;
    start[0] = start[1] = FIXED;                          // boot sector and FAT stay put
    // plan: move the next run of used clusters into the leftmost gap until the map is solid
    const cells = start.slice(), ops = [];
    for (let w = 0, guard = 0; guard < N; guard++) {
      while (w < N && cells[w] !== FREE) w++;
      let r = w + 1;
      while (r < N && cells[r] !== USED) r++;
      if (w >= N || r >= N) break;
      let len = 0;
      while (len < 8 && r + len < N && cells[r + len] === USED) len++;
      let gap = 0;
      while (gap < len && w + gap < N && cells[w + gap] === FREE) gap++;
      len = Math.max(1, Math.min(len, gap));
      ops.push([r, w, len]);
      for (let j = 0; j < len; j++) { cells[r + j] = FREE; cells[w + j] = USED; }
    }
    const done = cells, T0 = 0.8, T1 = 20.4, per = (T1 - T0) / Math.max(1, ops.length);
    const GLY = ['.', '#', 'X', 'B'], COL = [th.dim, th.ink, th.neg, th.neg];
    const map = new Uint8Array(N), mark = new Uint8Array(N);
    return (t) => {
      const b = ctx.buffer;
      const tau = phase(t, 24);
      b.fill(0, 0, W, H, ' ', undefined, th.panel2);
      b.text(1, 0, 'Optimize', th.ink, th.panel2, 1);
      const title = 'Microsoft Defrag';
      b.text(Math.floor((W - title.length) / 2), 0, title, th.ink, th.panel2, 1);
      if (W >= 60) b.text(W - 9, 0, 'F1=Help', th.muted, th.panel2);
      // the map at this moment
      map.set(start); mark.fill(0);
      const k = Math.floor((tau - T0) / per), frac = (tau - T0) / per - k;
      const nOps = tau < T0 ? 0 : Math.min(ops.length, k);
      for (let i = 0; i < nOps; i++) { const [r, w, len] = ops[i]; for (let j = 0; j < len; j++) { map[r + j] = FREE; map[w + j] = USED; } }
      if (tau >= T0 && k < ops.length) {
        const [r, w, len] = ops[k];
        for (let j = 0; j < len; j++) { if (frac < 0.5) mark[r + j] = 1; else { mark[w + j] = 2; map[r + j] = FREE; } }
      }
      const wipe = tau >= 22 ? Math.round((1 - (tau - 22) / 2) * gw) : gw;   // right → left re-analysis
      for (let i = 0; i < N; i++) {
        const x = i % gw, y = Math.floor(i / gw);
        let v = tau >= 20.4 ? done[i] : map[i];
        if (x >= wipe) v = start[i];
        const ch = mark[i] === 1 ? 'r' : mark[i] === 2 ? 'W' : GLY[v];
        b.set(gx + x, gy + y, ch, mark[i] === 1 ? th.info : mark[i] === 2 ? th.warn : COL[v], th.panel2);
      }
      // re-analysis (from 22 s) resets the readout with the wipe, so the wrap meets the t = 0 status
      const fresh = tau < T0 || tau >= 22;
      const pct = fresh ? 0 : tau >= T1 ? 100 : Math.floor(((tau - T0) / (T1 - T0)) * 100);
      const cluster = fresh ? 2 : k < ops.length ? Math.round((ops[k][0] / N) * 98304) : 98304;
      const sy = gy + gh + 1;
      const status = `Cluster ${cluster.toLocaleString('en-US')} | ${pct}% | Elapsed ${mmss(fresh ? 0 : Math.min(tau, T1) * 6)} | Full Optimization`;
      b.text(1, sy, status.slice(0, W - 2), th.ink, th.panel2);
      b.text(1, sy + 1, pbar(Math.min(40, W - 10), pct / 100), th.accent, th.panel2);
      if (W >= 70 && sy + 2 < H) b.text(1, sy + 2, '# Used  . Unused  r Reading  W Writing  X Unmovable  B Bad', th.muted, th.panel2);
      if (tau >= 20.4 && tau < 22) {                        // the finish box
        const msg = ' Finished condensing. ', bw = msg.length + 2, bx = Math.floor((W - bw) / 2), byy = gy + Math.floor(gh / 2) - 1;
        box(b, bx, byy, bw, 3, th.ink);
        b.text(bx + 1, byy + 1, msg, th.ink, th.panel, 1);
      }
    };
  },
};

// ── Windows 95 copy dialog ───────────────────────────────────────────────────
const FILES = ['prism-term-0.2.0.tgz', 'README.md', 'themes.json', 'facets-catalog.json', 'prism.wasm', 'CHANGELOG.md'];
const FOLDER = [' __', '|  \\___', '|      |', '|______|'];             // a tabbed folder; the compact strip drops its middle row
const FOLDER_SMALL = [FOLDER[0], FOLDER[1], FOLDER[3]];
const PAGES = [['.-.', '|=|'], ['/-/', '/=/'], ['\\-\\', '\\=\\']];

const fileCopy = {
  ...shared,
  id: 'ascii-file-copy',
  since: '0.3.0',
  title: 'File Copy Dialog',
  tags: ['windows 95', 'copy', 'dialog', 'file transfer', 'eta', 'retro', 'progress'],
  order: 350,
  kind: 'progress',
  loop: 18,
  size: { w: 64, h: 14 },
  minSize: { w: 40, h: 9 },
  description: 'A Windows 95-style copy dialog: a page flies between folders, files tick by, and the ETA lurches from 12 seconds to 47 minutes and back, then it closes.',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const dw = Math.min(60, W - 2), dh = Math.min(12, H - 1), dx = Math.floor((W - dw) / 2), dy = Math.floor((H - 1 - dh) / 2);
    const tall = dh >= 12;
    return (t) => {
      const b = ctx.buffer;
      const tau = phase(t, 18);
      b.fill(0, H - 1, W, 1, ' ', undefined, th.panel2);    // the taskbar
      b.text(0, H - 1, '[Start]', th.ink, th.panel2, 1);
      const open = tau < 15 || tau >= 17.4;
      if (!open) {                                          // the empty desktop
        b.text(2, 1, '[=]', th.muted); b.text(1, 2, 'My Computer', th.dim);
        b.text(2, 4, '\\_/', th.muted); b.text(1, 5, 'Recycle Bin', th.dim);
        return;
      }
      b.text(9, H - 1, '[Copying...]', th.ink, th.panel2);
      const run = tau >= 17.4 ? 0 : tau, p = clamp01((run - 0.4) / 14.6);
      // the window and its title bar; when short, the frame runs under the title bar so a row is free for the strip
      b.fill(dx, dy, dw, dh, ' ', undefined, th.panel);
      if (!tall) box(b, dx, dy, dw, dh, th.line);
      b.fill(dx, dy, dw, 1, ' ', undefined, th.accent);
      b.text(dx + 1, dy, 'Copying...', th.bg, th.accent, 1);
      b.text(dx + dw - 4, dy, '[x]', th.bg, th.accent);
      if (tall) box(b, dx, dy + 1, dw, dh - 1, th.line);
      const fy = tall ? dy + 2 : dy + 1, lx = dx + 3, rx = dx + dw - 11;
      sprite(b, lx, fy, tall ? FOLDER : FOLDER_SMALL, th.warn); sprite(b, rx, fy, tall ? FOLDER : FOLDER_SMALL, th.warn);
      // the page: an eased parabola every 0.8 s (a lower arc in the compact strip), flipping through its sprites
      const k = ((run - 0.4) / 0.8) % 1, flying = run > 0.4 && run < 15;
      if (flying) {
        const e = ease(k), px = Math.round(lx + 6 + e * (rx - lx - 8)), py = Math.round(fy + 1 - Math.sin(Math.PI * e) * (tall ? 2 : 1));
        sprite(b, px, py, PAGES[Math.min(2, Math.floor(e * 3))], th.ink);
      }
      const file = FILES[Math.min(FILES.length - 1, Math.floor(p * FILES.length))];
      const ty = tall ? fy + 5 : fy + 3, last = dy + dh - 2;      // last interior row
      b.text(lx - 1, ty, file, th.ink, th.panel);
      let ry = ty + 1;
      if (tall || last - ty >= 3) b.text(lx - 1, ry++, "From 'Downloads' to 'Backup'".slice(0, dw - 4), th.muted, th.panel);
      const bw = dw - 6, filled = Math.round(p * bw);
      b.text(lx - 1, ry, '[' + '|'.repeat(filled) + ' '.repeat(bw - filled) + ']', th.accent, th.panel);
      const eta = run < 4 ? `${12 - Math.floor(Math.max(0, run - 0.4) * 0.8)} Seconds Remaining` : run < 6.5 ? '47 Minutes Remaining' : (() => { const s = Math.max(1, Math.ceil((9 * (15 - run)) / 8.5)); return `${s} Second${s === 1 ? '' : 's'} Remaining`; })();
      if (ry + 1 <= last) {
        b.text(lx - 1, ry + 1, eta, th.muted, th.panel);
        b.text(dx + dw - 11, ry + 1, '[Cancel]', th.ink, th.panel);
      }
    };
  },
};

// ── quay crane rollout ───────────────────────────────────────────────────────
const MOVE = 1.75;                                         // seconds per container
const craneTimeline = (k) => {
  // phase fractions within one container move: to the stack, lower, hoist, travel, lower, release, hoist
  const f = [0.14, 0.28, 0.4, 0.66, 0.84, 0.9, 1];
  for (let i = 0; i < f.length; i++) if (k < f[i]) return [i, (k - (f[i - 1] ?? 0)) / (f[i] - (f[i - 1] ?? 0))];
  return [6, 1];
};

const crane = {
  ...shared,
  id: 'ascii-container-crane',
  since: '0.3.0',
  title: 'Container Rollout',
  tags: ['crane', 'containers', 'kubernetes', 'rollout', 'deployment', 'ship', 'port'],
  order: 360,
  kind: 'progress',
  loop: 24,
  size: { w: 80, h: 20 },
  minSize: { w: 44, h: 12 },
  description: 'A quay crane loads a container ship as a kubectl rollout: each box hoisted, swung aboard and set down turns green once ready, then the ship sails.',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const cols = W >= 70 ? 5 : 3, n = 2 * cols;
    const wy = H - 4, deck = wy - 1, boomY = Math.max(2, Math.round(H * 0.15));
    // left to right: the quay stack, the crane's legs, the quay edge, the ship
    const stackCols = W >= 70 ? 2 : 1, stackX = 0, legL = stackCols * 6 + 1, legR = legL + 6, qx = legR + 2;
    const shipX0 = qx + 2, hullW = cols * 6 + 9;             // bays plus room aft for the bridge
    const slotX = (c) => shipX0 + 3 + c * 6, slotY = (tier) => deck - 1 - tier;
    const lastLand = n * MOVE;
    return (t) => {
      const b = ctx.buffer;
      const tau = phase(t, 24);
      const k = Math.min(n, Math.floor(tau / MOVE)), within = tau / MOVE - k;
      // the ship: docked while loading, sails out at 18.5, an empty one docks by 23.5
      const shipX = tau < 18.5 ? shipX0 : tau < 20.5 ? shipX0 + ease((tau - 18.5) / 2) * (W - shipX0 + 2) : tau < 21 ? W + 2 : shipX0 + (1 - ease((tau - 21) / 2.5)) * (W - shipX0 + 2);
      const loadedShip = tau < 20.5;
      for (let y = wy; y < H - 1; y++) for (let x = 0; x < W; x++) if (x > qx && (x + y * 3 + Math.floor(tau * 4)) % 7 === 0) b.set(x, y, '~', mix(th.info, th.bg, 0.4));
      for (let x = 0; x <= qx; x++) b.set(x, deck, '=', th.muted);        // the quay
      for (let y = deck + 1; y < H - 1; y++) b.set(qx, y, '|', th.muted);
      // the quay stack of the new image
      // the next image's containers are trucked back onto the quay while the empty ship comes in
      const left = tau >= 20.5 ? Math.min(n, Math.floor((tau - 20.5) / 0.25)) : Math.max(0, n - (k + (within > 0.4 ? 1 : 0)));
      const cap = stackCols * 3;
      for (let i = 0; i < left && i < cap; i++) b.text(stackX + (i % stackCols) * 6, deck - 1 - Math.floor(i / stackCols), '[web]', th.info);
      if (left > cap) b.text(stackX + 1, deck - 4, `+${left - cap}`, th.info);
      b.text(1, deck + 1, 'prism/web:2.4.1', th.muted);
      // ship hull and bays
      const sx = Math.round(shipX);
      b.text(sx, wy, '\\' + '_'.repeat(hullW - 2) + '/', th.ink);
      b.text(sx + 1, wy + 1, '\\' + '~'.repeat(hullW - 4) + '/', th.dim);
      b.text(sx, deck, '|' + '='.repeat(hullW - 2) + '|', th.muted);
      b.text(sx + hullW - 6, deck - 3, '|__', th.muted); b.text(sx + hullW - 6, deck - 2, '|[]|', th.muted); b.text(sx + hullW - 6, deck - 1, '|__|', th.muted);
      const placed = loadedShip ? Math.min(n, k + (within >= 0.84 ? 1 : 0)) : 0;
      for (let i = 0; i < placed; i++) {
        const tier = Math.floor(i / cols), c = i % cols, landAt = i * MOVE + 0.84 * MOVE;
        const ready = tau >= 18.5 || tau - landAt >= 1;   // readiness lags the landing by a second
        b.text(sx - shipX0 + slotX(c), slotY(tier), '[web]', ready ? th.pos : th.info);
      }
      // the crane: legs, boom, trolley, cable, spreader (and its load)
      for (let y = boomY + 1; y < deck; y++) { b.set(legL, y, '|', th.warn); b.set(legR, y, '|', th.warn); if ((y - boomY) % 2 === 0) b.text(legL + 1, y, '\\' + ' '.repeat(Math.max(0, legR - legL - 3)) + '/', mix(th.warn, th.bg, 0.4)); }
      b.text(0, boomY, '='.repeat(Math.min(W - 1, qx + hullW + 6)), th.warn);           // boom, with backreach over the quay stack
      let tx = stackX + 2, hookY = boomY + 2, carry = false, sway = 0;
      if (tau < lastLand) {
        const [ph, u] = craneTimeline(within);
        const target = k, tier = Math.floor(target / cols), c = target % cols;
        const bayX = slotX(c) + 2, stackTop = deck - 1 - Math.min(2, Math.floor(Math.max(0, n - k - 1) / stackCols));
        const fromX = k === 0 ? stackX + 2 : slotX((k - 1) % cols) + 2;
        if (ph === 0) tx = fromX + (stackX + 2 - fromX) * ease(u);
        else if (ph === 3) tx = stackX + 2 + (bayX - stackX - 2) * ease(u);
        else tx = ph < 3 ? stackX + 2 : bayX;
        hookY = ph === 1 ? boomY + 2 + (stackTop - boomY - 2) * ease(u) : ph === 2 ? stackTop - (stackTop - boomY - 2) * ease(u)
          : ph === 4 ? boomY + 2 + (slotY(tier) - boomY - 2) * ease(u) : ph === 5 ? slotY(tier) : ph === 6 ? slotY(tier) - (slotY(tier) - boomY - 2) * ease(u) : boomY + 2;
        carry = ph >= 2 && ph <= 4;
        sway = ph === 4 ? Math.round(Math.sin(u * 9) * (1 - u)) : 0;
      }
      const TX = Math.round(tx), HY = Math.round(hookY);
      b.text(TX - 1, boomY + 1, '[#]', th.warn);
      for (let y = boomY + 2; y < HY; y++) b.set(TX + 1 + (y === HY - 1 ? sway : 0), y, '|', th.muted);
      if (carry) b.text(TX - 1 + sway, HY, '[web]', th.info);
      else b.text(TX + sway, HY, '|=|', th.muted);
      const ready = tau >= 21 ? 0 : tau >= 18.5 ? n : Array.from({ length: n }, (_, i) => tau - (i * MOVE + 0.84 * MOVE) >= 1).filter(Boolean).length;
      const full = `Waiting for deployment "web" rollout to finish: ${ready} of ${n} updated replicas are available...`;
      const short = `deployment "web": ${ready} of ${n} updated replicas are available...`;
      const msg = ready >= n ? 'deployment "web" successfully rolled out' : full.length <= W ? full : short.length <= W ? short : `rollout "web": ${ready}/${n} replicas available`;
      b.text(0, H - 1, msg.slice(0, W), ready >= n ? th.pos : th.ink);   // one status line under the scene
    };
  },
};

// ── marquee chase lights ─────────────────────────────────────────────────────
const marquee = {
  ...shared,
  id: 'ascii-chase-lights',
  since: '0.3.0',
  title: 'Marquee Chase Lights',
  tags: ['marquee', 'chase lights', 'bulbs', 'theater', 'sign', 'please wait'],
  order: 370,
  kind: 'spinner',
  loop: 12,
  size: { w: 64, h: 14 },
  minSize: { w: 32, h: 7 },
  description: 'A theater marquee around PLEASE WAIT: two rings of bulbs run a chase, a theater chase, an alternate flash and a fill-sweep, with an all-on flash between.',
  setup(ctx) {
    const { width: W, height: H, theme: th } = ctx;
    const ring = (x0, y0, w, h) => {                      // bulb positions clockwise from the top-left
      const out = [];
      for (let x = x0; x < x0 + w; x += 2) out.push([x, y0]);
      for (let y = y0 + 1; y < y0 + h - 1; y++) out.push([x0 + w - 1 - ((w - 1) % 2), y]);
      for (let x = x0 + w - 1 - ((w - 1) % 2); x >= x0; x -= 2) out.push([x, y0 + h - 1]);
      for (let y = y0 + h - 2; y > y0; y--) out.push([x0, y]);
      return out;
    };
    const double = W >= 48 && H >= 12;
    const rings = [ring(0, 0, W, H)];
    if (double) rings.push(ring(3, 2, W - 6, H - 4));
    const burnt = new Set(['0:5', '0:17']), flick = '1:9';
    const on = mix(th.warn, th.bg, 0.8);
    const words = ['P L E A S E', 'W A I T'];
    return (t) => {
      const b = ctx.buffer;
      const tau = phase(t, 12), pat = Math.floor(tau / 3), local = tau % 3, s = Math.floor(local * 9);
      const flash = local > 2.75;                         // all on between patterns
      rings.forEach((pts, r) => {
        const N = pts.length, dir = r ? -1 : 1;
        pts.forEach(([x, y], i0) => {
          const i = dir > 0 ? i0 : N - 1 - i0;
          let lit = flash || [((i - s) % 6 + 6) % 6 === 0, (i + s) % 3 === 0, (i + Math.floor(s / 2)) % 2 === 0, i < ((s * 3) % (N + 6))][pat];
          const id = `${r}:${i0}`;
          if (burnt.has(id)) lit = false;
          if (id === flick && hash(Math.floor(tau * 9), 41) < 0.5) lit = false;
          b.set(x, y, lit ? 'o' : '.', lit ? th.warn : on);
        });
      });
      // the sign
      const mid = Math.floor(H / 2);
      if (double) {
        const bx = 6, bw = W - 12;
        box(b, bx, mid - 2, bw, 5, th.muted);
        words.forEach((w, i) => b.text(Math.floor((W - w.length) / 2), mid - 1 + i * 2, w, th.ink, undefined, 1));
      } else {
        const msg = 'PLEASE WAIT';
        b.text(Math.floor((W - msg.length) / 2), mid, msg, th.ink, undefined, 1);
      }
    };
  },
};

export default [defrag, fileCopy, crane, marquee];

