// A four-pane layout where focus moves like Tab in a real TUI: the focused
// pane gets a heavy accent border, the rest recede.
import { panel, glyphs, ATTR, fit, phase, uni } from './_kit.js';

const LOGS = ['GET /cart 200 41ms', 'POST /checkout 201 212ms', 'GET /search?q=tent 200 22ms', 'healthcheck ok', 'GET /account 200 34ms', 'POST /login 200 88ms'];

export default {
  id: 'callouts-focus-panels',
  title: 'Focus Ring Layout',
  category: 'Panels & Borders',
  description: 'A four-pane dashboard where keyboard focus cycles with Tab — heavy accent border on the active pane, dimmed borders on the rest.',
  tags: ['focus', 'layout', 'panes', 'tab', 'dashboard'],
  kind: 'tui',
  size: { w: 76, h: 20 },
  minSize: { w: 40, h: 10 },
  loop: 8,
  color: '16',
  order: 30,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx);
      const focus = Math.floor(phase(t, 8) / 2) % 4;
      const lw = Math.floor(W * 0.42), rw = W - lw - 1;
      const PH = H - 1; // last row is the key hint
      const th1 = Math.floor((PH - 1) / 2), th2 = PH - 1 - th1 - 1;
      const panes = [
        { x: 0, y: 0, w: lw, h: th1, title: 'Services' },
        { x: lw + 1, y: 0, w: rw, h: th1, title: 'Logs' },
        { x: 0, y: th1 + 1, w: lw, h: th2 + 1, title: 'Alerts' },
        { x: lw + 1, y: th1 + 1, w: rw, h: th2 + 1, title: 'Metrics' },
      ];
      panes.forEach((p, i) => {
        const on = i === focus;
        const inner = panel(ctx, b, p.x, p.y, p.w, p.h, { style: on ? 'heavy' : 'round', title: on ? `${g.tri} ${p.title}` : p.title, titleColor: on ? th.accent : th.muted, color: on ? th.accent : th.line });
        const ink = on ? th.ink : th.muted;
        for (let r = 0; r < inner.height; r++) {
          if (i === 0) {
            const svc = ['edge-lb', 'api-gateway', 'checkout', 'payments', 'catalog', 'search'][r];
            if (!svc) break;
            const bad = svc === 'payments' && Math.sin(t * 0.8) > 0.2;
            inner.text(1, r, g.dot, bad ? th.warn : th.pos);
            inner.text(3, r, fit(svc, Math.max(0, inner.width - 12), undefined, ctx), ink);
            inner.text(inner.width - 8, r, bad ? 'degraded' : 'running', bad ? th.warn : th.dim);
          } else if (i === 1) {
            const k = (Math.floor(t * 1.5) + r) % LOGS.length;
            inner.text(1, r, fit(LOGS[k], inner.width - 2, undefined, ctx), r === inner.height - 1 ? th.ink : ink);
          } else if (i === 2) {
            const al = [['warn', 'payments p95 above SLO for 3m'], ['info', 'deploy search v2.3.1 finished'], ['ok', 'cert renewed for edge-lb']][r];
            if (!al) break;
            const c = al[0] === 'warn' ? th.warn : al[0] === 'ok' ? th.pos : th.info;
            inner.text(1, r, al[0].toUpperCase().padEnd(5), c, undefined, ATTR.BOLD);
            inner.text(7, r, fit(al[1], Math.max(0, inner.width - 8), undefined, ctx), ink);
          } else {
            const bars = ['cpu', 'mem', 'disk', 'net'][r];
            if (!bars) break;
            const v = 0.3 + 0.25 * Math.sin(t * (0.6 + r * 0.3) + r) + r * 0.08;
            inner.text(1, r, bars.padEnd(5), th.muted);
            const bw = Math.max(1, inner.width - 13);
            for (let k = 0; k < bw; k++) inner.set(7 + k, r, k < v * bw ? (uni(ctx) ? '▮' : '#') : (uni(ctx) ? '▯' : '.'), k < v * bw ? (on ? th.info : th.dim) : th.line);
            inner.text(8 + bw, r, `${Math.round(v * 100)}%`.padStart(4), ink);
          }
        }
      });
      const hint = `Tab next pane ${g.mid} Shift-Tab previous`;
      b.text(Math.max(0, W - hint.length - 1), H - 1, hint, th.dim);
    };
  },
};

sources.prism-term/src/facets/callouts/key-value:
// Grouped key/value blocks with dotted leaders, live values and status pills.
import { ATTR, uni, phase } from './_kit.js';

export default {
  id: 'callouts-key-value',
  title: 'Key-Value Details',
  category: 'Key-Value',
  description: 'Grouped key/value details with dotted leaders to right-aligned values, live-updating numbers and status pills — the "describe" view of every CLI.',
  tags: ['key value', 'details', 'describe', 'leaders', 'properties'],
  kind: 'widget',
  size: { w: 56, h: 16 },
  minSize: { w: 32, h: 8 },
  loop: 10,
  color: '16',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx);
      const p = phase(t, 10);
      const healthy = !(p > 5.5 && p < 8);
      const groups = [
        ['Service', [
          ['Name', 'checkout'],
          ['Version', 'v2.14.1'],
          ['Replicas', `${healthy ? 2 : 1} / 2`, healthy ? 'pos' : 'warn'],
          ['Status', healthy ? 'Running' : 'Degraded', healthy ? 'pos' : 'warn', true],
        ]],
        ['Traffic', [
          ['Requests', `${(612 + Math.round(Math.sin(t * 1.1) * 24)).toLocaleString('en-US')} rps`],
          ['p95 latency', `${Math.round(healthy ? 212 + Math.sin(t) * 9 : 840 + Math.sin(t * 3) * 60)} ms`, healthy ? null : 'warn'],
          ['Error rate', `${(healthy ? 0.15 : 2.4 + Math.sin(t * 2) * 0.3).toFixed(2)} %`, healthy ? null : 'neg'],
        ]],
        ['Network', [
          ['Address', '10.20.2.31:8085'],
          ['Upstream', 'pg-orders-primary-01'],
        ]],
      ];
      let y = 0;
      for (const [name, rows] of groups) {
        if (y >= H) break;
        b.text(0, y, name.toUpperCase(), th.muted, undefined, ATTR.BOLD);
        y++;
        for (const [k, v, tone, pill] of rows) {
          if (y >= H) break;
          const vw = v.length + (pill ? 2 : 0);
          const lead = Math.max(1, W - 2 - k.length - vw - 2);
          b.text(2, y, k, th.ink);
          b.text(2 + k.length + 1, y, (u ? '·' : '.').repeat(lead), th.line);
          const vx = W - vw;
          if (pill) {
            const c = th[tone];
            b.text(vx, y, ` ${v} `, th.bg, c, ATTR.BOLD);
          } else b.text(vx, y, v, tone ? th[tone] : th.ink, undefined, tone ? ATTR.BOLD : 0);
          y++;
        }
        y++;
      }
    };
  },
};

// A neofetch-style system summary: logo art on the left, key/value facts on the
// right, the color swatch row underneath. The facts tick like a live box.
import { ATTR, uni, mix } from './_kit.js';
import { palette } from '../../palettes.js';

const LOGO = [
  '        /\\        ',
  '       /  \\       ',
  '      / /\\ \\      ',
  '     / /  \\ \\     ',
  '    / /    \\ \\    ',
  '   / /  /\\  \\ \\   ',
  '  / /  /  \\  \\ \\  ',
  ' /_/__/____\\__\\_\\ ',
];

export default {
  id: 'callouts-neofetch',
  title: 'System Summary (neofetch)',
  category: 'Key-Value',
  description: 'A neofetch-style summary: gradient logo art beside aligned key/value system facts and the ANSI color swatch row, with uptime ticking.',
  tags: ['neofetch', 'fastfetch', 'system info', 'key value', 'motd'],
  kind: 'widget',
  size: { w: 64, h: 15 },
  minSize: { w: 38, h: 10 },
  loop: 12,
  color: '256',
  order: 10,
  setup(ctx) {
    const th = ctx.theme;
    const grad = palette('prism', th);
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx);
      const showLogo = W >= 56;
      const lx = 1, ly = Math.max(0, Math.floor((H - Math.max(LOGO.length, 12)) / 2));
      if (showLogo) LOGO.forEach((row, y) => [...row].forEach((ch, x) => { if (ch !== ' ') b.set(lx + x, ly + y, ch, grad((x + y) / 28 + t * 0.05), undefined, ATTR.BOLD); }));
      const kx = showLogo ? lx + 21 : 1;
      const up = 6 * 86400 + 4 * 3600 + 17 * 60 + Math.floor(t);
      const upS = `${Math.floor(up / 86400)} days, ${Math.floor(up / 3600) % 24} hours, ${Math.floor(up / 60) % 60} mins`;
      const mem = 6120 + Math.round(Math.sin(t * 0.6) * 140);
      const facts = [
        ['', 'ops@prism-edge-01', true],
        ['', u ? '─'.repeat(17) : '-'.repeat(17)],
        ['OS', 'Debian GNU/Linux 12 x86_64'],
        ['Host', 'c6i.2xlarge'],
        ['Kernel', '6.1.0-26-cloud-amd64'],
        ['Uptime', upS],
        ['Packages', '612 (dpkg)'],
        ['Shell', 'bash 5.2.15'],
        ['Terminal', 'tmux 3.3a'],
        ['CPU', 'Intel Xeon 8375C (8) @ 2.90GHz'],
        ['Memory', `${mem.toLocaleString('en-US')}MiB / 15,733MiB`],
      ];
      let y = ly;
      for (const [k, v, title] of facts) {
        if (y >= H - 2) break;
        if (title) {
          const [user, host] = v.split('@');
          let x = b.text(kx, y, user, th.accent, undefined, ATTR.BOLD);
          x = b.text(x, y, '@', th.ink);
          b.text(x, y, host, th.accent, undefined, ATTR.BOLD);
        } else if (!k) b.text(kx, y, v, th.muted);
        else {
          const x = b.text(kx, y, k, th.accent, undefined, ATTR.BOLD);
          b.text(x, y, ': ', th.ink);
          b.text(x + 2, y, v.slice(0, Math.max(0, W - x - 3)), th.ink);
        }
        y++;
      }
      // Color swatches: the 8 ANSI-ish tones, then their bright twins.
      const tones = [th.bg, th.neg, th.pos, th.warn, th.info, th.crit, th.accent, th.ink];
      const sy = Math.min(H - 2, y + 1);
      tones.forEach((c, i) => {
        b.text(kx + i * 3, sy, '   ', undefined, c);
        if (sy + 1 < H) b.text(kx + i * 3, sy + 1, '   ', undefined, mix(c, 0xffffff, 0.3));
      });
    };
  },
};

sources.prism-term/src/facets/callouts/section-h:
// Section header styles that type themselves in: numbered, underlined, boxed,
// inverse bar and markdown-setext.
import { ATTR, uni, phase, typed, blink, mix, fit } from './_kit.js';

export default {
  id: 'callouts-section-headers',
  title: 'Section Headers',
  category: 'Dividers & Headers',
  description: 'Five header styles — numbered eyebrow, underlined, boxed, inverse bar and setext — that type in one after another, for reports and CLIs.',
  tags: ['header', 'heading', 'section', 'title', 'typography'],
  kind: 'text',
  size: { w: 60, h: 18 },
  minSize: { w: 30, h: 8 },
  loop: 9,
  color: '16',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx);
      const p = phase(t, 9);
      const typer = (text, at) => typed(text, p, at, 28);
      const caret = (x, y, text, full) => { if (text.length < full.length && text.length && blink(t, 0.5)) b.set(x + text.length, y, u ? '▌' : '_', th.accent); };
      const blocks = [];
      // 1. Numbered eyebrow + title.
      blocks.push((y, at) => {
        const eyebrow = '01 / OVERVIEW', title = 'System health at a glance';
        const e = typer(eyebrow, at), tt = typer(title, at + 0.4);
        b.text(0, y, e, th.accent, undefined, ATTR.BOLD); caret(0, y, e, eyebrow);
        b.text(0, y + 1, tt, th.ink, undefined, ATTR.BOLD); caret(0, y + 1, tt, title);
        return 3;
      });
      // 2. Underlined.
      blocks.push((y, at) => {
        const title = 'Incidents';
        const tt = typer(title, at);
        b.text(0, y, tt, th.ink, undefined, ATTR.BOLD);
        b.fill(0, y + 1, Math.min(W, Math.round(tt.length / title.length * (W * 0.5))), 1, u ? '─' : '-', th.accent);
        return 3;
      });
      // 3. Boxed.
      blocks.push((y, at) => {
        const title = 'Deployments';
        const tt = typer(title, at);
        const w = Math.min(W, title.length + 4);
        if (tt.length) {
          b.text(0, y, (u ? '┌' : '+') + (u ? '─' : '-').repeat(w - 2) + (u ? '┐' : '+'), th.line);
          b.text(0, y + 1, (u ? '│' : '|') + fit(` ${tt}`, w - 2, undefined, ctx) + (u ? '│' : '|'), th.line);
          b.text(2, y + 1, tt, th.ink, undefined, ATTR.BOLD);
          b.text(0, y + 2, (u ? '└' : '+') + (u ? '─' : '-').repeat(w - 2) + (u ? '┘' : '+'), th.line);
        }
        return 4;
      });
      // 4. Inverse bar.
      blocks.push((y, at) => {
        const title = 'CAPACITY';
        const tt = typer(title, at);
        if (tt.length) {
          b.fill(0, y, W, 1, ' ', undefined, mix(th.bg, th.accent, 0.22));
          b.set(0, y, u ? '▌' : '|', th.accent, mix(th.bg, th.accent, 0.22));
          b.text(2, y, tt, th.ink, mix(th.bg, th.accent, 0.22), ATTR.BOLD);
          b.text(W - 9, y, '3 alerts', th.warn, mix(th.bg, th.accent, 0.22));
        }
        return 2;
      });
      // 5. Setext.
      blocks.push((y, at) => {
        const title = 'Runbook: rotate certificates';
        const tt = typer(title, at);
        b.text(0, y, tt, th.ink, undefined, ATTR.BOLD);
        if (tt.length) b.fill(0, y + 1, Math.min(W, tt.length), 1, '=', th.muted);
        return 3;
      });
      let y = 0, at = -0.3;
      const fitAll = blocks.length * 3 + 1 <= H;
      const list = fitAll ? blocks : [blocks[Math.floor(p / 1.8) % blocks.length]];
      list.forEach((draw) => { if (y < H) { y += draw(y, fitAll ? at : 0.05); at += 1.3; } });
    };
  },
};

