      cv.paint(b, axisW, 0);
      if (axisW) for (const g of [100, 50, 0]) b.text(0, Math.round(((H - 1) * (100 - g)) / 100), String(g).padStart(3) + '%', th.dim);
      const v = val(px - 1), tag = ` ${v.toFixed(1)}% `;
      const row = clamp(Math.round(((H - 1) * (100 - v)) / 100), 0, H - 1);
