// Unit and center-zero meters: a connection pool counted slot by slot against its hard limit, and clock
// offsets on a center-zero scale inside a tolerance band. Pure functions of t % loop.
import { glyphs, safe, putR, ATTR } from './_data.js';
import { phase, ease, cyclic } from './_loop.js';
import { stringWidth } from '../../width.js';

// Words are ink; muted only where it holds 4.5:1 on every palette (dark themes). Semantic color goes on glyphs.
const sub = (th) => (th.mode === 'light' ? th.ink : th.muted);

// ── connection pool: one cell per slot against a hard limit, waiters queued past it ──────────────
const PM_LOOP = 14, PM_RATE = 4, PM_P = PM_LOOP * PM_RATE;
const POOLS = [
  { name: 'primary', limit: 30, base: 11, peak: 36.4, seed: 201 },
  { name: 'replica', limit: 20, base: 6, peak: 15, seed: 202 },
];

const poolMeter = {
  id: 'charts-pool-meter',
  since: '0.3.0',
  title: 'Connection Pool Meter',
  category: 'Gauges & Meters',
  description: 'A database connection pool counted slot by slot against its hard limit: in-use climbs with load until every slot fills, then waiters queue past the limit.',
  tags: ['connection pool', 'database', 'saturation', 'unit meter', 'capacity', 'queue'],
  kind: 'chart',
  size: { w: 72, h: 8 },
  minSize: { w: 40, h: 4 },
  loop: PM_LOOP,
  color: '256',
  order: 200,
  setup(ctx) {
    const th = ctx.theme, g = glyphs(ctx), W = ctx.width, H = ctx.height, b = safe(ctx.buffer, g);
    const noise = POOLS.map((p) => cyclic(ctx, { seed: p.seed, amp: 1, period: PM_P }));
    const pools = H >= 6 ? POOLS : POOLS.slice(0, 1), MID = g.u ? '·' : '-';
    const at = (i, T) => {
      const p = POOLS[i], u = T / PM_LOOP, k = Math.floor(T * PM_RATE + 1e-9);
      // load climbs over ~4 s, holds past the limit, then a burst drains it in ~1.5 s
      const load = ease((u - 0.07) / 0.29) * (1 - ease((u - 0.6) / 0.12));
      const demand = p.base + (p.peak - p.base) * load + 1.3 * noise[i](k);
      const inUse = Math.max(0, Math.min(p.limit, Math.round(demand))), waiting = Math.max(0, Math.round(demand - p.limit));
      const p95 = waiting ? Math.round(3 + 7.5 * waiting + 2 * Math.abs(noise[i](k + 7))) : Math.max(1, Math.round(2.4 + noise[i](k + 3)));
      return { ...p, inUse, waiting, p95, sat: inUse >= p.limit && waiting > 0 };
    };
    return (t) => {
      const T = phase(t, PM_LOOP);
      pools.forEach((_, i) => {
        const s = at(i, T), y = i * 3;
        // label row: the p95 readout drops first, then the words compact; the state word stays
        const long = `${s.name} ${s.inUse}/${s.limit} in use ${MID} ${s.waiting} waiting`, p95 = ` ${MID} p95 wait ${s.p95} ms`;
        const opts = [long + p95, long, `${s.name} ${s.inUse}/${s.limit} ${MID} ${s.waiting}w`];
        let stateW = s.sat ? 12 : 0, label = opts.find((o) => stringWidth(o) + stateW <= W);
        if (!label) { stateW = s.sat ? 2 : 0; label = opts.find((o) => stringWidth(o) + stateW <= W) ?? opts[2]; }
        b.text(0, y, label, th.ink);
        if (label.endsWith(p95)) b.text(stringWidth(label) - stringWidth(p95), y, p95, sub(th));
        b.text(0, y, s.name, th.ink, undefined, ATTR.BOLD);
        if (s.sat) {
          const x = W - stateW + 1;
          if (stateW > 2) b.text(x, y, 'SATURATED', th.ink, undefined, ATTR.BOLD);
          b.text(W - 1, y, g.up, th.neg, undefined, ATTR.BOLD);
        }
        // track: one cell per slot (2 columns when the whole limit plus its queue fits), the limit, the queue
        const qW = 9, cw = 2 * s.limit + 1 + qW <= W ? 2 : 1, xL = s.limit * cw;
        for (let j = 0; j < s.limit; j++) b.set(j * cw, y + 1, j < s.inUse ? '▮' : '▯', j < s.inUse ? th.accent : sub(th));
        b.set(xL, y + 1, '┃', th.ink);
        if (s.waiting) {
          let x = xL + 2;
          for (let j = 0; j < Math.min(3, s.waiting); j++) x = b.text(x, y + 1, '▸', th.warn);
          b.text(x + 1, y + 1, `+${s.waiting}`, th.ink, undefined, ATTR.BOLD);
        }
      });
      const ly = H - 1;
      if (ly > (pools.length - 1) * 3 + 1 && W >= 40) {
        let x = 0;
        for (const [gl, c, word] of [['▮', th.accent, 'in use'], ['▯', sub(th), 'idle'], ['┃', th.ink, 'limit'], ['▸', th.warn, 'waiting']]) {
          x = b.text(x, ly, gl, c); x = b.text(x + 1, ly, word, sub(th)) + 2;
        }
      }
    };
  },
};

// ── clock offset: center-zero meters inside a tolerance band, one host drifts and is stepped back ──
const OM_LOOP = 16, OM_RATE = 4, OM_P = OM_LOOP * OM_RATE, OM_RANGE = 50, OM_TOL = 10;
const HOSTS = ['web-01', 'web-02', 'db-01', 'db-02'], DRIFTER = 3, STEP_AT = 10, STEPPED_FOR = 3.5;

const offsetMeter = {
  id: 'charts-offset-meter',
  since: '0.3.0',
  title: 'Clock Offset Meter',
  category: 'Gauges & Meters',
  description: 'Clock offsets of four hosts on center-zero meters: bars grow behind or ahead of 0 inside a ±10 ms band with jitter whiskers, and one host drifts out until it is stepped.',
  tags: ['ntp', 'clock offset', 'time sync', 'center zero', 'tolerance', 'drift', 'jitter'],
  kind: 'chart',
  size: { w: 72, h: 9 },
  minSize: { w: 40, h: 5 },
  loop: OM_LOOP,
  color: '256',
  order: 210,
  setup(ctx) {
    const th = ctx.theme, g = glyphs(ctx), W = ctx.width, H = ctx.height, b = safe(ctx.buffer, g);
    const noise = HOSTS.map((_, i) => cyclic(ctx, { seed: 211 + i, amp: 1, period: OM_P }));
    const MINUS = g.u ? '−' : '-', BAR = g.u ? '━' : '=', SYNC = g.check, DRIFT = g.up, STEPPED = g.u ? '↺' : '@';
    const whiskers = W >= 66, ticks = W >= 56, words = W >= 50, step = H >= 9 ? 2 : 1;
    const nameW = W >= 60 ? 8 : 7, valueW = 9, stateW = words ? 11 : 2;
    let trackW = Math.max(9, W - nameW - valueW - stateW - 1);
    if (trackW % 2 === 0) trackW--;
    const tx = nameW, c0 = tx + (trackW - 1) / 2, per = (trackW - 1) / 2 / OM_RANGE;
    const col = (v) => c0 + Math.max(-OM_RANGE, Math.min(OM_RANGE, v)) * per;
    const fmt = (v) => `${v < 0 ? MINUS : '+'}${Math.abs(v).toFixed(1)} ms`;
    const host = (i, T) => {
      const k = Math.floor(T * OM_RATE + 1e-9);
      let off = (i === DRIFTER ? 1.4 : 3.2) * noise[i](k);
      if (i === DRIFTER && T >= 3 && T < STEP_AT) off += 27 * ease((T - 3) / 6);
      const jit = 1.4 + 0.9 * Math.sin(2 * Math.PI * (T / 8 + i / 4));
      const state = i === DRIFTER && T >= STEP_AT && T < STEP_AT + STEPPED_FOR ? 'stepped' : Math.abs(off) > OM_TOL ? 'drift' : 'synced';
      return { off, jit, state };
    };
    return (t) => {
      const T = phase(t, OM_LOOP);
      // scale row: ends, center, and interior ticks while there is room
      const placed = [], label = (x, s, color, attr = 0) => {
        const w = stringWidth(s);
        if (placed.some(([a, z]) => x < z + 1 && a < x + w + 1)) return;   // never touch a placed label
        placed.push([x, x + w]); b.text(x, 0, s, color, undefined, attr);
      };
      label(tx, `${MINUS}${OM_RANGE} ms`, th.ink);
      label(tx + trackW - stringWidth(`+${OM_RANGE} ms`), `+${OM_RANGE} ms`, th.ink);
      label(Math.round(c0), '0', th.ink, ATTR.BOLD);
      const tk = [-25, 25].map((v) => [Math.round(col(v)) - 1, `${v < 0 ? MINUS : '+'}${Math.abs(v)}`]);   // both or neither
      if (ticks && tk.every(([x, s]) => !placed.some(([a, z]) => x < z + 1 && a < x + stringWidth(s) + 1))) for (const [x, s] of tk) label(x, s, sub(th));
      HOSTS.forEach((name, i) => {
        const y = 1 + i * step;
        if (y >= H) return;
        const { off, jit, state } = host(i, T);
        b.text(0, y, name.slice(0, nameW - 1), th.ink);
        for (const v of [-OM_TOL, OM_TOL]) b.set(Math.round(col(v)), y, g.u ? '┊' : ':', th.dim);
        b.set(Math.round(c0), y, g.v, sub(th));
        // the bar from zero, in half cells, on the warm pole ahead and the cool pole behind
        const half = Math.round(Math.abs(off) * per * 2), dir = off < 0 ? -1 : 1, color = off < 0 ? th.info : th.warn;
        for (let h = 1; h <= Math.floor(half / 2); h++) b.set(Math.round(c0) + dir * h, y, BAR, color);
        if (half % 2) b.set(Math.round(c0) + dir * (Math.floor(half / 2) + 1), y, g.u ? (dir > 0 ? '╸' : '╺') : '-', color);
        if (whiskers) {
          const a = Math.round(col(off - jit)), z = Math.round(col(off + jit)), tip = Math.round(col(off));
          for (let x = a + 1; x < z; x++) if (dir > 0 ? x > tip : x < tip) b.set(x, y, g.h, sub(th));
          if (z > a) { b.set(a, y, g.u ? '├' : '[', sub(th)); b.set(z, y, g.u ? '┤' : ']', sub(th)); }
        }
        putR(b, tx + trackW + 1 + valueW, y, fmt(off), th.ink, undefined, ATTR.BOLD);
        const sx = tx + trackW + 1 + valueW + 1, [gl, gc] = state === 'synced' ? [SYNC, th.pos] : state === 'drift' ? [DRIFT, th.warn] : [STEPPED, th.info];
        if (sx < W) b.text(sx, y, gl, gc, undefined, ATTR.BOLD);
        if (words && sx + 2 < W) b.text(sx + 2, y, state, th.ink);
      });
      if (step === 2 && H >= 9 && W >= 60) {
        let x = tx;
        x = b.text(x, H - 1, g.u ? '┊' : ':', th.dim); x = b.text(x + 1, H - 1, `${g.u ? '±' : '+/-'}${OM_TOL} ms tolerance`, sub(th)) + 2;
        if (whiskers) { x = b.text(x, H - 1, g.u ? '├─┤' : '[-]', sub(th)); x = b.text(x + 1, H - 1, 'jitter', sub(th)) + 2; }
        x = b.text(x, H - 1, g.u ? '◀' : '<', th.info); x = b.text(x + 1, H - 1, 'behind', sub(th)) + 2;
        x = b.text(x, H - 1, 'ahead', sub(th)); b.text(x + 1, H - 1, g.u ? '▶' : '>', th.warn);
      }
    };
  },
};

export default [poolMeter, offsetMeter];

// Sparklines: word-sized trend lines — eighth-block bars, braille, dots, and a wall of them.
import { mix, scale } from '../../color.js';
import { signal, glyphs, safe, vbar, put, putR, num, clamp, light, lift, ATTR, VBLOCKS } from './_data.js';

const METRICS = [
  { key: 'cpu', label: 'cpu', unit: '%', base: 46, amp: 22, max: 100, warn: 75, crit: 90, seed: 1 },
  { key: 'mem', label: 'mem', unit: '%', base: 61, amp: 10, max: 100, warn: 80, crit: 92, seed: 2 },
  { key: 'net', label: 'net', unit: 'MB/s', base: 38, amp: 26, max: 120, warn: 95, crit: 110, seed: 3, spike: 18 },
  { key: 'err', label: 'err', unit: '%', base: 0.6, amp: 0.5, max: 8, warn: 2, crit: 4, seed: 4, spike: 1.2, min: 0 },
];

const levelColor = (th, m, v) => (v >= m.crit ? th.neg : v >= m.warn ? th.warn : th.pos);

const sparkBars = {
  id: 'charts-spark-bars',
  title: 'Sparkline Rows',
  category: 'Sparklines',
  description: 'Four live metrics as eighth-block sparklines with labels, window min/max, current values and threshold coloring — the classic `spark` look.',
  tags: ['sparkline', 'trend', 'metrics', 'eighth blocks', 'cpu'],
  kind: 'chart',
  size: { w: 66, h: 5 },
  minSize: { w: 22, h: 2 },
  loop: 10,
  color: '256',
  order: 10,
  setup(ctx) {
    const th = ctx.theme, g = glyphs(ctx), W = ctx.width, H = ctx.height, b = safe(ctx.buffer, glyphs(ctx));
    const streams = METRICS.map((m) => ({ m, s: signal(ctx, { seed: m.seed, base: m.base, amp: m.amp, spike: m.spike || 0, min: m.min ?? 0, max: m.max, rate: 3 }) }));
    const rows = Math.min(METRICS.length, H);
    const labelW = W >= 30 ? 5 : 0, valueW = W >= 26 ? 9 : 0, rangeW = W >= 60 ? 14 : 0;
    const sw = Math.max(4, W - labelW - valueW - rangeW);
    const short = (v) => (v < 10 ? v.toFixed(1) : String(Math.round(v)));
    return (t) => {
      for (let r = 0; r < rows; r++) {
        const { m, s } = streams[r];
        const data = s.window(t, sw), v = s.now(t);
        const y = r + Math.max(0, Math.floor((H - rows) / 2));
        if (labelW) b.text(0, y, m.label.padEnd(labelW - 1), th.muted);
        // Autoscale with headroom, like `spark`: the shape matters, the readout gives the value.
        let lo = Math.min(...data), hi = Math.max(...data);
        const pad = (hi - lo) * 0.15 || 1;
        lo = Math.max(0, lo - pad); hi += pad;
        for (let i = 0; i < sw; i++) {
          const k = clamp((data[i] - lo) / (hi - lo), 0, 1);
          const idx = Math.max(1, Math.round(k * 8));
          const c = levelColor(th, m, data[i]);
          b.set(labelW + i, y, g.u ? VBLOCKS[idx] : ' ._-=+*#@'[idx], i === sw - 1 ? lift(th, c, 0.35) : th.mode === 'light' ? mix(th.bg, c, 0.55 + 0.45 * (i / sw)) : scale(c, 0.55 + 0.45 * (i / sw)));
        }
        if (rangeW) {
          // Window min and max, like `spark --range`.
          const mn = Math.min(...data), mx = Math.max(...data);
          const x = labelW + sw + 1;
          let e = b.text(x, y, g.down, th.dim);
          e = b.text(e, y, short(mn), th.muted);
          e = b.text(e + 1, y, g.up, th.dim);
          b.text(e, y, short(mx), th.muted);
        }
        if (valueW) {
          const txt = `${v < 10 ? v.toFixed(1) : Math.round(v)}${m.unit === '%' ? '%' : ' ' + m.unit}`;
          putR(b, W, y, txt, levelColor(th, m, v), undefined, ATTR.BOLD);
        }
      }
    };
  },
};

const sparkBraille = {
  id: 'charts-spark-braille',
  title: 'Braille Sparklines',
  category: 'Sparklines',
  description: 'High-resolution braille sparklines (2×4 dots per cell) with min/max markers, a glowing last-value point and a live readout.',
  tags: ['sparkline', 'braille', 'high resolution', 'min max', 'latency'],
  kind: 'chart',
  size: { w: 56, h: 9 },
  minSize: { w: 24, h: 3 },
  loop: 12,
  glyphs: 'braille',
  canvas: 'line',
  order: 20,
  setup(ctx) {
    const th = ctx.theme, g = glyphs(ctx), W = ctx.width, H = ctx.height, b = safe(ctx.buffer, glyphs(ctx));
    const defs = [
      { label: 'p95 latency', unit: 'ms', s: signal(ctx, { seed: 11, base: 180, amp: 70, spike: 90, min: 20, rate: 6 }), c: th.accent },
      { label: 'requests', unit: '/s', s: signal(ctx, { seed: 12, base: 1400, amp: 420, rate: 6 }), c: th.pos },
      { label: 'queue depth', unit: '', s: signal(ctx, { seed: 13, base: 22, amp: 18, spike: 30, min: 0, rate: 6 }), c: th.crit },
    ];
    const per = H >= 9 ? 3 : H >= 6 ? 2 : 1;
    const rows = Math.max(1, Math.min(defs.length, Math.floor(H / per)));
    const textH = per >= 2 ? 1 : 0;
    const cvRows = Math.max(1, per - textH);
    const cv = ctx.canvas('line', { cols: W, rows: cvRows, threshold: 0 });
    return (t) => {
      for (let r = 0; r < rows; r++) {
        const d = defs[r], y0 = r * per;
        const n = cv.width;
        const data = d.s.window(t, n);
        let lo = Infinity, hi = -Infinity, iLo = 0, iHi = 0;
        data.forEach((v, i) => { if (v < lo) { lo = v; iLo = i; } if (v > hi) { hi = v; iHi = i; } });
        const span = hi - lo || 1;
        const py = (v) => (cv.height - 1) - ((v - lo) / span) * (cv.height - 1);
        cv.clear();
        let prev = null;
        for (let i = 0; i < n; i++) {
          const y = py(data[i]);
          const c = mix(scale(d.c, 0.45), d.c, i / n);
          if (prev !== null) cv.line(i - 1, prev, i, y, c); else cv.set(i, y, c);
          prev = y;
        }
        cv.set(iHi, py(hi), th.warn); cv.set(iHi, py(hi) - 1, th.warn);
        cv.set(iLo, py(lo), th.info); cv.set(iLo, py(lo) + 1, th.info);
        cv.set(n - 1, py(data[n - 1]), light(th)); cv.set(n - 2, py(data[n - 1]), light(th));
        cv.paint(b, 0, y0 + textH);
        if (textH) {
          const v = d.s.now(t);
          b.text(0, y0, d.label, th.muted);
          const val = `${num(v, v < 10 ? 1 : 0)}${d.unit}`;
          const right = W >= 40 ? `${g.down}${num(lo, 0)}  ${g.up}${num(hi, 0)}  ` : '';
          putR(b, W - val.length, y0, right, th.dim);
          putR(b, W, y0, val, d.c, undefined, ATTR.BOLD);
        }
      }
    };
  },
};

const sparkDots = {
  id: 'charts-spark-dots',
  title: 'Dot Sparkline & Threshold',
  category: 'Sparklines',
  description: 'A dot-plot sparkline against a dashed SLO threshold: points that breach glow red and are counted live.',
  tags: ['sparkline', 'dots', 'threshold', 'slo', 'breach'],
  kind: 'chart',
  size: { w: 60, h: 6 },
  minSize: { w: 24, h: 3 },
  loop: 10,
  canvas: 'line',
  order: 30,
  setup(ctx) {
    const th = ctx.theme, g = glyphs(ctx), W = ctx.width, H = ctx.height, b = safe(ctx.buffer, glyphs(ctx));
    const s = signal(ctx, { seed: 21, base: 215, amp: 120, spike: 420, min: 40, rate: 5 });
    const LIMIT = 290;
    const rows = Math.max(1, H - 1);
    const cv = ctx.canvas('line', { cols: W, rows, threshold: 0 });
    return (t) => {
      const n = Math.floor(cv.width / 2);
      const data = s.window(t, n);
      const lo = 0, hi = Math.max(LIMIT * 1.35, Math.max(...data) * 1.08);
      const py = (v) => (cv.height - 1) - clamp((v - lo) / (hi - lo), 0, 1) * (cv.height - 1);
      cv.clear();
      const ly = Math.round(py(LIMIT));
      for (let x = 0; x < cv.width; x += 3) cv.set(x, ly, mix(th.bg, th.warn, 0.8));
      let breaches = 0;
      data.forEach((v, i) => {
        const bad = v > LIMIT;
        if (bad) breaches++;
        const x = i * 2 + 1, y = py(v);
        const c = bad ? th.neg : mix(th.info, th.accent, i / n);
        cv.set(x, y, c); cv.set(x, y + 1, scale(c, 0.7));
        if (bad) { cv.set(x, y - 1, c); cv.set(x - 1, y, scale(c, 0.6)); cv.set(x + 1, y, scale(c, 0.6)); }
      });
      cv.paint(b, 0, 1);
      put(b, 0, 0, 'checkout p95', W, th.muted);
      const msg = `${breaches} over ${LIMIT} ms`;
      if (W >= 30) putR(b, W, 0, msg, breaches ? th.neg : th.pos, undefined, ATTR.BOLD);
      if (W >= 46) putR(b, W - msg.length - 2, 0, `${g.dash.repeat(2)} SLO`, th.warn);
    };
  },
};

const SERVICES = ['api-gw', 'auth', 'cart', 'checkout', 'search', 'catalog', 'payments', 'orders', 'rx-orders', 'loyalty', 'notify', 'inventory'];

const sparkWall = {
  id: 'charts-spark-wall',
  title: 'Sparkline Wall',
  category: 'Sparklines',
  description: 'A NOC wall of a dozen services: name, a mini sparkline and the current rate, each tinted by health.',
  tags: ['sparkline', 'wallboard', 'noc', 'services', 'grid'],
  kind: 'chart',
  size: { w: 80, h: 8 },
  minSize: { w: 26, h: 3 },
  loop: 12,
  color: '256',
  order: 40,
  setup(ctx) {
    const th = ctx.theme, g = glyphs(ctx), W = ctx.width, H = ctx.height, b = safe(ctx.buffer, glyphs(ctx));
    const cellW = 26;
    const cols = Math.max(1, Math.floor((W + 1) / cellW));
    const perCol = Math.max(1, H);
    const count = Math.min(SERVICES.length, cols * perCol);
    const streams = SERVICES.slice(0, count).map((name, i) => {
      const base = 300 + (i * 97) % 900;
      return { name, base, s: signal(ctx, { seed: 40 + i, base, amp: base * 0.22, spike: i === 3 ? base * 1.4 : 0, min: 5, rate: 3 }) };
    });
    const w = Math.min(cellW - 1, W);
    return (t) => {
      streams.forEach((st, i) => {
        const cx = Math.floor(i / perCol) * cellW, cy = i % perCol;
        const sw = Math.max(4, w - 16);
        const data = st.s.window(t, sw);
        const max = Math.max(...data), min = Math.min(...data);
        const v = st.s.now(t);
        const health = v > st.base * 1.9 ? 0.3 : v > st.base * 1.45 ? 0.6 : 1;
        const c = health >= 0.8 ? th.pos : health >= 0.5 ? th.warn : th.neg;
        b.set(cx, cy, g.dot, c);
        put(b, cx + 2, cy, st.name, 9, th.ink);
        for (let k = 0; k < sw; k++) {
          const idx = Math.max(1, Math.round(((data[k] - min) / (max - min || 1)) * 7) + 1);
          b.set(cx + 11 + k, cy, g.u ? VBLOCKS[Math.min(8, idx)] : '.:-=+*#%@'[Math.min(8, idx)], scale(c, 0.5 + 0.5 * (k / sw)));
        }
        putR(b, cx + w, cy, num(v, 0), c, undefined, ATTR.BOLD);
      });
    };
  },
};

export default [sparkBars, sparkBraille, sparkDots, sparkWall];

