// A job lifecycle state machine: the current state lights up and a token
// rides each labeled transition — one failure, a retry with backoff, success.
import { ATTR, glyphs, uni, phase, tint, fit } from '../callouts/_kit.js';
import { LineGrid, nodeBox, box, polyline, along } from './_lines.js';

const S = {
  PENDING: [4, 1, 12], RUNNING: [26, 1, 11], SUCCEEDED: [49, 1, 13],
  RETRYING: [4, 9, 12], FAILED: [26, 9, 11], DEAD: [52, 9, 8],
};
// [start time, edge id] — each transition takes HOP seconds.
const HOP = 0.45;
const SCRIPT = [[0.2, 'start'], [0.9, 'schedule'], [1.9, 'exit1'], [2.9, 'retry'], [3.8, 'backoff'], [4.9, 'schedule'], [5.9, 'exit0'], [7.0, 'end']];

export default {
  id: 'diagrams-state-machine',
  title: 'State Machine',
  category: 'Boxes & Flows',
  description: 'A job lifecycle state machine with labeled transitions: the active state lights up and a token rides each edge through a failure, a backoff retry and success.',
  tags: ['state machine', 'fsm', 'lifecycle', 'transitions', 'retry'],
  kind: 'diagram',
  size: { w: 70, h: 14 },
  minSize: { w: 68, h: 14 },
  loop: 10,
  color: '16',
  order: 40,
  setup(ctx) {
    const th = ctx.theme;
    const B = Object.fromEntries(Object.entries(S).map(([k, [x, y, w]]) => [k, box(x, y, w, 3)]));
    const startDot = [1, B.PENDING.cy], endDot = [B.SUCCEEDED.x + B.SUCCEEDED.w + 4, B.SUCCEEDED.cy];
    // id: [from, to, corners, label]
    const E = {
      start: [null, 'PENDING', [[2, B.PENDING.cy], B.PENDING.left], ''],
      schedule: ['PENDING', 'RUNNING', [B.PENDING.right, B.RUNNING.left], 'schedule'],
      exit0: ['RUNNING', 'SUCCEEDED', [B.RUNNING.right, B.SUCCEEDED.left], 'exit 0'],
      end: ['SUCCEEDED', null, [B.SUCCEEDED.right, [endDot[0] - 1, endDot[1]]], ''],
      exit1: ['RUNNING', 'FAILED', [B.RUNNING.bottom, B.FAILED.top], 'exit 1'],
      retry: ['FAILED', 'RETRYING', [B.FAILED.left, B.RETRYING.right], 'retry <=3'],
      backoff: ['RETRYING', 'PENDING', [B.RETRYING.top, B.PENDING.bottom], 'backoff 4s'],
      dead: ['FAILED', 'DEAD', [B.FAILED.right, B.DEAD.left], 'exhausted'],
    };
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 10);
      let state = null, moving = null, f = 0, attempt = 1, last = null;
      for (const [at, id] of SCRIPT) {
        if (p < at) break;
        if (p < at + HOP) { moving = id; f = (p - at) / HOP; state = null; } else { state = E[id][1]; moving = null; }
        if (id === 'backoff') attempt = 2;
        last = id;
      }
      const grid = new LineGrid(W, H - 1);
      for (const [id, [, , corners]] of Object.entries(E)) grid.path(corners, { c: id === moving ? th.accent : undefined, arrow: true });
      grid.paint(ctx, b, 0, 0, { style: 'round' });
      for (const [id, [, , corners, label]] of Object.entries(E)) {
        if (!label) continue;
        const [[ax, ay], [bx, by]] = corners;
        const hot = id === moving;
        const shown = u ? label.replace('<=', '≤') : label;
        if (ay === by) b.text(Math.min(ax, bx) + Math.floor((Math.abs(bx - ax) - shown.length) / 2) + 1, ay - 1, shown, hot ? th.accent : th.muted, undefined, hot ? ATTR.BOLD : 0);
        else b.text(ax + 2, Math.floor((ay + by) / 2), shown, hot ? th.accent : th.muted, undefined, hot ? ATTR.BOLD : 0);
      }
      b.set(startDot[0], startDot[1], u ? '●' : '*', th.ink, undefined, ATTR.BOLD);
      b.text(endDot[0], endDot[1], u ? '◉' : '@', state === null && last === 'end' && !moving ? th.pos : th.muted, undefined, ATTR.BOLD);
      for (const [name, bx] of Object.entries(B)) {
        const on = name === state;
        const tone = name === 'FAILED' || name === 'DEAD' ? th.neg : name === 'SUCCEEDED' ? th.pos : name === 'RETRYING' ? th.warn : th.accent;
        nodeBox(ctx, b, bx.x, bx.y, name, {
          w: bx.w, color: on ? tone : th.line, bg: on ? tint(ctx, tone, 0.22) : undefined,
          fg: on ? th.ink : name === 'DEAD' ? th.dim : th.muted, attr: on ? ATTR.BOLD : 0,
        });
      }
      if (moving) {
        const at = along(polyline(E[moving][2]), f);
        if (at) b.set(at[0], at[1], u ? '●' : 'o', th.accent, undefined, ATTR.BOLD);
      }
      // Event line: the last transition, as a log entry.
      const [from, to] = last ? E[last] : [null, null];
      const ev = !last ? 'job queued' : `${from || 'start'} ${g.right} ${to || 'end'}${E[last][3] ? ` (${E[last][3]})` : ''}`;
      const ts = `12:04:${String(31 + Math.floor(p * 2)).padStart(2, '0')}`;
      let x = b.text(0, H - 1, ts, th.dim);
      x = b.text(x + 1, H - 1, `job/reindex-8812 attempt ${attempt}/3`, th.muted);
      b.text(x + 2, H - 1, fit(ev, Math.max(0, W - x - 2), undefined, ctx), to === 'FAILED' ? th.neg : to === 'SUCCEEDED' || last === 'end' ? th.pos : th.ink);
    };
  },
};

// An incident timeline: a playhead sweeps the axis, events pop in on
// alternating label lanes, and MTTA / MTTR spans draw in once resolved.
import { ATTR, glyphs, uni, phase, fit, stringWidth } from '../callouts/_kit.js';

// [minute after 12:00, label, tone]
const EVENTS = [
  [2, 'deploy v2.14.1', 'info'], [9, 'p99 alert fires', 'neg'], [11, 'on-call paged', 'warn'], [13, 'acknowledged', 'warn'],
  [20, 'cause: db pool', 'accent'], [24, 'fix #142 approved', 'accent'], [27, 'mitigated', 'pos'], [41, 'resolved', 'pos'],
];
const SPANS = [['MTTA', 9, 13], ['MTTR', 9, 41]];
const SPAN_M = 45, SWEEP = 7;
// Label lanes: [row, side] cycling up-far, down-near, up-near, down-far.
const LANES = [[0, 'up'], [7, 'down'], [2, 'up'], [9, 'down']];
const AXIS = 5;

export default {
  id: 'diagrams-timeline',
  title: 'Incident Timeline',
  category: 'Sequence & Timelines',
  description: 'An incident timeline: a playhead sweeps from deploy to resolution, events pop in on alternating label lanes, and MTTA and MTTR spans draw in at the end.',
  tags: ['timeline', 'incident', 'postmortem', 'mttr', 'events'],
  kind: 'diagram',
  size: { w: 76, h: 14 },
  minSize: { w: 64, h: 14 },
  loop: 9,
  color: '16',
  order: 30,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 9);
      const nowM = Math.min(1, p / SWEEP) * SPAN_M;
      const x = (m) => 1 + Math.round((m / SPAN_M) * (W - 3));
      // Axis, bold up to the playhead, with 15-minute ticks.
      for (let i = 0; i < W; i++) b.set(i, AXIS, u ? (i <= x(nowM) ? '━' : '─') : (i <= x(nowM) ? '=' : '-'), i <= x(nowM) ? th.ink : th.line);
      for (let m = 0; m <= SPAN_M; m += 15) {
        b.set(x(m), AXIS, u ? (m <= nowM ? '╋' : '┼') : '+', m <= nowM ? th.ink : th.line);
        b.text(Math.max(0, Math.min(W - 5, x(m) - 2)), AXIS + 1, `12:${String(m).padStart(2, '0')}`, th.dim);
      }
      const laneEnd = LANES.map(() => -2);
      // Events.
      EVENTS.forEach(([m, label, tone], k) => {
        if (nowM < m) return;
        const ex = x(m), c = th[tone];
        const [ly, side] = LANES[k % LANES.length];
        const text = `12:${String(m).padStart(2, '0')} ${label}`;
        const tw = stringWidth(text);
        // Centered on the marker, but never over the previous label in this lane.
        const lane = k % LANES.length;
        const lx = Math.max(laneEnd[lane] + 2, Math.max(0, Math.min(W - tw, ex - Math.floor(tw / 2))));
        b.text(lx, ly, fit(text, Math.max(0, W - lx), undefined, ctx).trimEnd(), c, undefined, nowM - m < 2 ? ATTR.BOLD : 0);
        laneEnd[lane] = lx + tw;
        // Stub from the label to the axis.
        const [y0, y1] = side === 'up' ? [ly + 1, AXIS - 1] : [AXIS + 1, ly - 1];
        for (let y = y0; y <= y1; y++) if (b.get(ex, y)?.ch === ' ') b.set(ex, y, u ? '│' : '|', th.line);
        b.set(ex, AXIS, u ? '●' : 'o', c, undefined, ATTR.BOLD);
      });
      // Playhead.
      if (p < SWEEP) b.set(x(nowM), AXIS, u ? '◆' : '#', th.accent, undefined, ATTR.BOLD);
      // Spans, once resolved.
      if (nowM >= 41) {
        SPANS.forEach(([name, a, z], i) => {
          const y = 11 + i;
          if (y >= H - 1) return;
          const xa = x(a), xz = x(z);
          for (let xx = xa; xx <= xz; xx++) b.set(xx, y, u ? '─' : '-', th.muted);
          b.set(xa, y, u ? '├' : '|', th.muted); b.set(xz, y, u ? '┤' : '|', th.muted);
          const lab = ` ${name} ${z - a}m `;
          const lx = xz - xa > lab.length + 1 ? xa + Math.floor((xz - xa - lab.length) / 2) + 1 : xz + 2;
          b.text(lx, y, lab, name === 'MTTR' ? th.pos : th.warn, undefined, ATTR.BOLD);
        });
      }
      const live = EVENTS.filter(([m]) => nowM >= m).pop();
      const msg = nowM >= 41 ? `${g.check} INC-3127 resolved ${g.mid} customer impact 25m ${g.mid} postmortem due Thu`
        : live ? `INC-3127 ${g.mid} 12:${String(Math.floor(nowM)).padStart(2, '0')} ${g.mid} ${live[1]}` : `INC-3127 ${g.mid} 12:00`;
      b.text(0, H - 1, fit(msg, W, undefined, ctx), nowM >= 41 ? th.pos : th.muted);
    };
  },
};

sources.prism-term/src/facets/fx/aurora.js:
// Aurora borealis: three curtains of light whose folds and rays come from
// per-column fbm noise (cheap: noise is sampled per column, not per pixel),
// hung over a twinkling night sky and a mountain ridge with a lake reflection.
export default {
  title: 'Aurora',
  gallery: 'fx',
  category: 'Light & Sky',
  kind: 'scene',
  tags: ['aurora', 'northern lights', 'sky', 'noise'],
  order: 60,
  description: 'Northern-lights curtains with drifting rays over a twinkling sky, mountains and a mirrored lake.',
  canvas: 'field',
  palette: 'aurora',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const rand = ctx.rng;
    const { noise2, fbm } = ctx.noise;
    const { width: W, height: H, px } = cv;
    const horizon = Math.floor(H * 0.78);
    const sky = new Int32Array(W * H);
    const top = 0x02030c, low = 0x0b1630;
    for (let y = 0; y < H; y++) {
      const k = Math.min(1, y / horizon);
      const r = ((top >> 16) & 255) * (1 - k) + ((low >> 16) & 255) * k;
      const g = ((top >> 8) & 255) * (1 - k) + ((low >> 8) & 255) * k;
      const b = (top & 255) * (1 - k) + (low & 255) * k;
      sky.fill((r << 16) | (g << 8) | (b | 0), y * W, (y + 1) * W);
    }
    const stars = Array.from({ length: Math.floor(W * horizon * 0.012) }, () => ({
      x: Math.floor(rand() * W), y: Math.floor(rand() * horizon * 0.92), p: rand() * 6.28, s: 0.4 + rand() * 0.6, f: 0.5 + rand() * 2,
    }));
    // Ridged noise (1 − |n|) gives sharp peaks rather than rolling hills.
    const ridge = new Float32Array(W);
    for (let x = 0; x < W; x++) {
      const u = x / W;
      const p = 1 - Math.abs(fbm(u * 3.2, 3.1, 0, 2)) * 1.6, q = 1 - Math.abs(fbm(u * 9, 7.7, 0, 2)) * 1.8;
      ridge[x] = horizon - H * (0.03 + 0.13 * Math.max(0, p) ** 2 + 0.035 * Math.max(0, q) ** 2);
    }
    const layers = [
      { base: 0.50, amp: 0.07, len: 0.42, f: 2.2, sp: 0.05, lo: 0.62, hi: 0.9, gain: 1.5 },
      { base: 0.42, amp: 0.06, len: 0.30, f: 3.4, sp: 0.08, lo: 0.55, hi: 0.75, gain: 1.0 },
      { base: 0.32, amp: 0.05, len: 0.26, f: 1.6, sp: 0.035, lo: 0.78, hi: 1.0, gain: 0.7 },
    ];
    const lb = new Float32Array(W), li = new Float32Array(W);
    const acc = new Float32Array(W * horizon * 3);

    return (t) => {
      acc.fill(0);
      for (let L = 0; L < layers.length; L++) {
        const ly = layers[L];
        for (let x = 0; x < W; x++) {
          const u = x / W;
          const fold = fbm(u * ly.f + L * 7.3, t * ly.sp, L, 3);
          lb[x] = H * (ly.base + ly.amp * Math.sin(u * 5 + t * 0.2 + L) + fold * 0.14);
          const rays = 0.5 + 0.5 * noise2(u * 38 + t * 0.6 * (L + 1) * 0.4, t * 0.35 + L * 3);
          li[x] = Math.max(0, fold * 0.9 + 0.55) * (0.35 + rays * rays * 1.3) * ly.gain;
        }
        const c0 = pal(ly.lo), c1 = pal(ly.hi); // bright lower hem → violet crown
        const len = H * ly.len;
        for (let x = 0; x < W; x++) {
          const b = lb[x], inten = li[x];
          if (inten <= 0.01) continue;
          const y0 = Math.max(0, Math.floor(b - len)), y1 = Math.min(horizon - 1, Math.ceil(b + 3));
          for (let y = y0; y <= y1; y++) {
            const d = b - y; // >0 above the curtain's lower edge
            const a = d >= 0 ? Math.exp(-d / (len * 0.35)) * Math.min(1, d / 2 + 0.6) : Math.exp(d * 1.2);
            const k = inten * a;
            if (k < 0.004) continue;
            const m = Math.min(1, Math.max(0, d / len));
            const j = (y * W + x) * 3;
            acc[j] += (((c0 >> 16) & 255) * (1 - m) + ((c1 >> 16) & 255) * m) * k;
            acc[j + 1] += (((c0 >> 8) & 255) * (1 - m) + ((c1 >> 8) & 255) * m) * k;
            acc[j + 2] += ((c0 & 255) * (1 - m) + (c1 & 255) * m) * k;
          }
        }
      }
      for (let y = 0, i = 0; y < H; y++) {
        for (let x = 0; x < W; x++, i++) {
          if (y < horizon) {
            const s = sky[i], j = i * 3;
            const r = ((s >> 16) & 255) + acc[j], g = ((s >> 8) & 255) + acc[j + 1], b = (s & 255) + acc[j + 2];
            px[i] = y >= ridge[x] ? mountain(x, y, acc, j) : ((r > 255 ? 255 : r) << 16) | ((g > 255 ? 255 : g) << 8) | (b > 255 ? 255 : b | 0);
          } else {
            // Lake: mirror the sky above the horizon with ripple wobble and darkening.
            const d = y - horizon;
            const sx = Math.min(W - 1, Math.max(0, Math.round(x + Math.sin(d * 0.9 + t * 2.1) * (1 + d * 0.08))));
            const my = horizon - 1 - d;
            const src = my >= 0 ? px[my * W + sx] : 0;
            const k = 0.55 - (d / (H - horizon)) * 0.3;
            px[i] = ((((src >> 16) & 255) * k) << 16) | ((((src >> 8) & 255) * k) << 8) | (((src & 255) * k) | 0);
          }
        }
      }
      for (const s of stars) {
        if (s.y >= ridge[s.x]) continue;
        const tw = s.s * (0.55 + 0.45 * Math.sin(t * s.f + s.p));
        cv.add(s.x, s.y, ((tw * 200) << 16) | ((tw * 210) << 8) | (tw * 255 | 0));
      }
      cv.paint(ctx.buffer);
    };

    function mountain(x, y, acc, j) {
      // Ridge silhouette, rim-lit by whatever aurora light falls just above it.
      const edge = y - ridge[x];
      const rim = edge < 1.5 ? 0.5 : 0.06;
      const r = 6 + acc[j] * rim, g = 8 + acc[j + 1] * rim, b = 16 + acc[j + 2] * rim;
      return ((r > 255 ? 255 : r) << 16) | ((g > 255 ? 255 : g) << 8) | (b > 255 ? 255 : b | 0);
    }
  },
};

