// Glitch & Noise — digital decay: datamosh block smear across a scene cut,
// chromatic aberration breathing over a lens target, and an LCD panel losing
// pixels, lines and finally its driver before rebooting clean.
import { clamp01, hash2 } from '../retro/_kit.js';

const SPEED = { speed: { default: 1, min: 0.1, max: 4, label: 'Speed' } };
const TAU = Math.PI * 2;
const pack = (r, g, b) =>
  ((r > 255 ? 255 : r < 0 ? 0 : r) << 16) | ((g > 255 ? 255 : g < 0 ? 0 : g) << 8) | ((b > 255 ? 255 : b < 0 ? 0 : b) | 0);

export default [
  {
    id: 'fx-datamosh',
    since: '0.3.0',
    title: 'Datamosh',
    category: 'Glitch & Noise',
    kind: 'scene',
    tags: ['datamosh', 'compression', 'macroblock', 'motion vectors', 'i-frame', 'codec', 'glitch', 'smear'],
    order: 230,
    description: 'A scene cut with the keyframe deleted: motion vectors smear the old shot into soup, wrong blocks bloom through, a sweep finally re-keys it.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 15,
    canvas: 'field',
    palette: 'synthwave',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const rand = ctx.rng;
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const Hu = H * aspect;
      const A = new Int32Array(W * H), B = new Int32Array(W * H);
      for (let y = 0; y < H; y++) {
        const uy = y * aspect, v = y / H;
        for (let x = 0; x < W; x++) {
          const hill = Hu * (0.55 + 0.14 * Math.sin(x * 0.08) + 0.08 * Math.sin(x * 0.21 + 2));
          if (uy > hill) {
            const dp = clamp01((uy - hill) / (Hu * 0.5));
            A[y * W + x] = pack(140 - dp * 90, 80 - dp * 50, 60 - dp * 30);
          } else {
            const dx = x - W * 0.3, dy = uy - Hu * 0.3;
            const d2 = dx * dx + dy * dy, sr = Math.max(2, W * 0.07);
            let r = 250 - v * 120, g = 160 - v * 60, b = 90 + v * 40;
            if (d2 < sr * sr) { r = 255; g = 240; b = 200; }
            else { const gl = Math.exp(-d2 / (sr * sr * 10)) * 70; r += gl; g += gl; b += gl * 0.5; }
            A[y * W + x] = pack(r, g, b);
          }
        }
      }
      const colW = Math.max(2, Math.round(W / 16));
      const colH = Array.from({ length: Math.ceil(W / colW) }, () => 0.25 + rand() * 0.6);
      for (let y = 0; y < H; y++) {
        const uy = y * aspect;
        for (let x = 0; x < W; x++) {
          const ci = Math.floor(x / colW);
          const top = Hu * (1 - colH[ci]);
          let r = 8, g = 10, b = 24 + (y / H) * 20;
          if (uy > top) {
            const c = pal(0.55 + (ci % 5) * 0.09);
            const lit = hash2(x, y, 7) > 0.82;
            r = lit ? (c >> 16) & 255 : 16; g = lit ? (c >> 8) & 255 : 18; b = lit ? c & 255 : 34;
          }
          B[y * W + x] = pack(r, g, b);
        }
      }
      const cur = new Int32Array(W * H), tmp = new Int32Array(W * H);
      cur.set(A);
      const bs = 6;
      const F1 = (TAU / 15) * 3, F2 = (TAU / 15) * 2;
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 15) % 1 + 1) % 1;
        const fr = (tt * 10) | 0;
        if (p < 0.015) cur.set(A);
        const mosh = p >= 0.33;
        const refreshP = mosh ? 0.045 : 0.3;
        const sweepY = p > 0.66 && p < 0.9 ? ((p - 0.66) / 0.24) * H : -1;
        for (let by = 0; by < H; by += bs) {
          for (let bx = 0; bx < W; bx += bs) {
            const yMax = Math.min(H, by + bs), xMax = Math.min(W, bx + bs);
            const fresh = hash2(bx, by, fr) < refreshP;
            const keyed = fresh || (sweepY >= 0 && by < sweepY);
            if (keyed) {
              const src = mosh || sweepY >= 0 ? B : A;
              for (let y = by; y < yMax; y++) for (let x = bx; x < xMax; x++) tmp[y * W + x] = src[y * W + x];
              continue;
            }
            const mvx = Math.round(2.6 * Math.sin(by * 0.35 + tt * F1) + (mosh ? -2.4 : 0));
            const mvy = Math.round(1.8 * Math.cos(bx * 0.3 + tt * F2));
            const dr = mosh ? (hash2(bx, by, 17) - 0.45) * 6 : 0;
            for (let y = by; y < yMax; y++) {
              const sy = Math.min(H - 1, Math.max(0, y + mvy));
              for (let x = bx; x < xMax; x++) {
                const sx = Math.min(W - 1, Math.max(0, x + mvx));
                const c = cur[sy * W + sx];
                tmp[y * W + x] = dr === 0 ? c : pack(((c >> 16) & 255) + dr, ((c >> 8) & 255) + dr * 0.6, (c & 255) + dr * 1.4);
              }
            }
          }
        }
        cur.set(tmp);
        px.set(cur);
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-chroma-drift',
    since: '0.3.0',
    title: 'Chroma Drift',
    category: 'Glitch & Noise',
    kind: 'scene',
    tags: ['chromatic aberration', 'rgb split', 'lens', 'fringing', 'drift', 'glitch', 'optics'],
    order: 240,
    description: 'A lens-test target whose color channels come unglued: red and blue drift apart radially, breathing in and out as the target slowly rotates.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 10,
    canvas: 'field',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const Hu = H * aspect;
      const cx = W * 0.5, cyU = Hu * 0.5;
      const F = new Float32Array(W * H);
      const maxD = Math.hypot(cx, cyU) || 1;
      const ringK = 42 / maxD;
      for (let y = 0; y < H; y++) {
        const uy = y * aspect;
        for (let x = 0; x < W; x++) {
          const dx = x - cx, dy = uy - cyU;
          const d = Math.hypot(dx, dy);
          let v = clamp01(Math.sin(d * ringK) * 2.2 - 0.5) * clamp01(1.25 - d / maxD);
          if (Math.abs(dx) < 0.8 || Math.abs(dy) < 0.8) v = Math.max(v, d > maxD * 0.12 ? 0.85 : v);
          const d1 = Math.hypot(dx - W * 0.3, dy + Hu * 0.22), d2 = Math.hypot(dx + W * 0.3, dy - Hu * 0.22);
          if (d1 < Math.max(1.5, W * 0.05) || d2 < Math.max(1.5, W * 0.05)) v = 1;
          if (x < 1 || y < 1 || x >= W - 1 || y >= H - 1) v = 0.7;
          F[y * W + x] = v;
        }
      }
      const samp = (xs, ys) => {
        const xi = xs < 0 ? 0 : xs >= W ? W - 1 : xs | 0;
        const yi = ys < 0 ? 0 : ys >= H ? H - 1 : ys | 0;
        return F[yi * W + xi];
      };
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 10) % 1 + 1) % 1;
        const ca = Math.cos(TAU * p), sa = Math.sin(TAU * p);
        const ab = 0.5 - 0.5 * Math.cos(TAU * p * 2);
        const split = 0.004 + ab * 0.055;
        const trx = Math.sin(TAU * p * 3) * 2.2 * ab, trY = Math.cos(TAU * p * 3) * 1.1 * ab;
        for (let y = 0; y < H; y++) {
          const uy = y * aspect;
          const flick = 0.93 + 0.07 * Math.sin(y * 0.9 + tt * (TAU / 10) * 6);
          for (let x = 0; x < W; x++) {
            const dx = x - cx, dy = uy - cyU;
            const xr = dx * ca - dy * sa, yr = dx * sa + dy * ca;
            const rS = 1 + split, bS = 1 - split;
            const rV = samp(cx + xr * rS + trx, (cyU + yr * rS + trY) / aspect);
            const gV = samp(cx + xr, (cyU + yr) / aspect);
            const bV = samp(cx + xr * bS - trx, (cyU + yr * bS - trY) / aspect);
            const vig = 1 - (dx * dx + dy * dy) / (maxD * maxD) * 0.45;
            px[y * W + x] = pack(
              (12 + rV * 235) * vig * flick,
              (14 + gV * 230) * vig * flick,
              (20 + bV * 245) * vig * flick,
            );
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-dead-pixels',
    since: '0.3.0',
    title: 'Panel Decay',
    category: 'Glitch & Noise',
    kind: 'scene',
    tags: ['dead pixels', 'lcd', 'stuck pixel', 'panel', 'subpixel', 'decay', 'hardware', 'glitch'],
    order: 250,
    description: 'An ambient gradient plays while the panel dies around it: stuck and dead pixels accumulate, blotches spread, whole lines fail, driver reboots.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 20,
    canvas: 'field',
    palette: 'candy',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const rand = ctx.rng;
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const STUCK = [pack(2, 2, 3), pack(235, 24, 24), pack(26, 225, 40), pack(30, 60, 240), pack(248, 248, 248)];
      const fails = Array.from({ length: Math.max(30, Math.min(700, Math.round(W * H * 0.045))) }, () => {
        const tv = rand();
        return {
          x: Math.floor(rand() * W), y: Math.floor(rand() * H),
          die: 0.9 * 20 * Math.sqrt(rand()),
          type: tv < 0.5 ? 0 : tv < 0.62 ? 1 : tv < 0.72 ? 2 : tv < 0.8 ? 3 : tv < 0.92 ? 4 : 5,
          grow: rand() < 0.14 ? 0.3 + rand() * 0.7 : 0,
        };
      });
      const lines = [
        { col: true, at: Math.floor(rand() * W), die: 9 + rand() * 6, c: pack(60, 200, 220) },
        { col: true, at: Math.floor(rand() * W), die: 11 + rand() * 6, c: pack(230, 70, 160) },
        { col: true, at: Math.floor(rand() * W), die: 13 + rand() * 5, c: pack(4, 4, 6) },
        { col: false, at: Math.floor(rand() * H), die: 14 + rand() * 4, c: pack(4, 4, 6) },
      ];
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 20) % 1 + 1) % 1;
        const pt = p * 20;
        if (p > 0.957) {
          const on = ((tt * 14) | 0) & 1;
          px.fill(on ? pack(3, 3, 4) : pack(14, 14, 18));
          if (!on) for (let x = 0; x < W; x++) px[(H >> 1) * W + x] = pack(120, 124, 132);
          cv.paint(ctx.buffer);
          return;
        }
        const tP = TAU * p;
        for (let y = 0; y < H; y++) {
          const uy = y * aspect;
          for (let x = 0; x < W; x++) {
            const v = 0.5 + 0.3 * Math.sin(x * 0.045 + tP * 2 + Math.sin(uy * 0.06)) + 0.2 * Math.sin(uy * 0.07 - tP * 3);
            px[y * W + x] = pal(clamp01(v));
          }
        }
        for (const ln of lines) {
          if (ln.die > pt) continue;
          const c = ln.c, cr = (c >> 16) & 255, cg = (c >> 8) & 255, cb = c & 255;
          if (ln.col) {
            for (let y = 0; y < H; y++) {
              const i = y * W + ln.at, o = px[i];
              px[i] = pack(((o >> 16) & 255) * 0.25 + cr * 0.75, ((o >> 8) & 255) * 0.25 + cg * 0.75, (o & 255) * 0.25 + cb * 0.75);
            }
          } else {
            for (let x = 0; x < W; x++) {
              const i = ln.at * W + x, o = px[i];
              px[i] = pack(((o >> 16) & 255) * 0.25 + cr * 0.75, ((o >> 8) & 255) * 0.25 + cg * 0.75, (o & 255) * 0.25 + cb * 0.75);
            }
          }
        }
        const fr = (tt * 10) | 0;
        for (const f of fails) {
          if (f.die > pt) continue;
          const c = f.type === 5 ? (hash2(f.x, f.y, fr) > 0.5 ? STUCK[4] : STUCK[0]) : STUCK[f.type];
          if (f.grow > 0) {
            const rad = Math.min(3.5, (pt - f.die) * f.grow);
            const ry = Math.max(0, Math.ceil(rad / aspect));
            for (let dy = -ry; dy <= ry; dy++) {
              for (let dx = -Math.ceil(rad); dx <= Math.ceil(rad); dx++) {
                if (dx * dx + dy * dy * aspect * aspect <= rad * rad) cv.set(f.x + dx, f.y + dy, c);
              }
            }
          } else {
            cv.set(f.x, f.y, c);
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

sources.prism-term/src/facets/fx/burning-ship.js:
// The Burning Ship fractal (z → (|Re z| + i|Im z|)² + c), flipped upright and
// colored like its name. The camera breathes from the whole hull down into
// the little ship riding the antenna off its bow and back, on a log-scale zoom.
export default {
  title: 'Burning Ship',
  gallery: 'fx',
  category: 'Fractals',
  kind: 'scene',
  tags: ['burning ship', 'fractal', 'escape time', 'zoom', 'fire'],
  order: 50,
  description: 'The Burning Ship fractal in flame colors, breathing from the whole hull down to the little ship on its antenna.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: 30,
  canvas: 'field',
  palette: 'fire',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 1024 });
    const { width: W, height: H, px, aspect } = cv;
    const C0 = [-0.5, -0.5], W0 = 3.4;                // the whole hull
    const C1 = [-1.755, -0.03], W1 = 0.12;            // the little ship on the bow's antenna
    const inside = ctx.theme.bg;
    return (t) => {
      const s = 0.5 - 0.5 * Math.cos(((t % 30) / 30) * Math.PI * 2);
      const w = W0 * Math.pow(W1 / W0, s);
      const k = (w - W1) / (W0 - W1);                  // zooms toward the target point
      const cx = C1[0] + (C0[0] - C1[0]) * k, cy = C1[1] + (C0[1] - C1[1]) * k;
      const unit = w / Math.min(W, (H * aspect) * 1.6);
      const maxIt = Math.round(70 + 110 * s);
      for (let y = 0, i = 0; y < H; y++) {
        const ci = cy + (y - H / 2 + 0.5) * aspect * unit;
        for (let x = 0; x < W; x++, i++) {
          const cr = cx + (x - W / 2 + 0.5) * unit;
          let zr = 0, zi = 0, n = 0, r2 = 0, i2 = 0;
          while (n < maxIt) {
            r2 = zr * zr; i2 = zi * zi;
            if (r2 + i2 > 64) break;
            zi = Math.abs(2 * zr * zi) + ci;
            zr = r2 - i2 + cr;
            n++;
          }
          if (n >= maxIt) { px[i] = inside; continue; }
          const mu = n + 1 - Math.log(Math.log(r2 + i2) * 0.5) / Math.LN2;
          const v = Math.min(1, Math.pow(mu / maxIt, 0.42) * 1.15);
          px[i] = pal(v);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/caustics.js:
// The bottom of a swimming pool on a sunny day: tiles and grout bent by the
// moving surface, overlaid with the bright network of caustics — light focused
// where the surface's wave crests act as lenses. Two noise layers drift
// against each other; caustic lines live where their sum crosses zero.
import { lerpc, clamp01 } from '../retro/_kit.js';

export default {
  title: 'Pool Caustics',
  gallery: 'fx',
  category: 'Fire & Water',
  kind: 'scene',
  tags: ['caustics', 'pool', 'water', 'light', 'refraction', 'summer', 'tiles'],
  order: 100,
  description: 'A sunlit pool floor: tiles bent by the moving surface under a dancing network of bright caustic light.',
  size: { w: 72, h: 24 },
  minSize: { w: 16, h: 6 },
  loop: 16,
  canvas: 'field',
  palette: 'ocean',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { noise3 } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const S = Math.min(W, H * aspect);
    const tile = Math.max(4, S / 5);
    const water = pal(0.42), deep = pal(0.28), light = pal(0.95), grout = lerpc(pal(0.22), 0x000000, 0.2);
    // The three noise fields are smooth, so on big canvases they're evaluated on a
    // coarse lattice and interpolated; tile edges and ridges stay per-pixel.
    const g = W * H > 9000 ? 2 : 1;
    const GW = Math.ceil(W / g) + 2, GH = Math.ceil(H / g) + 2;
    const OX = new Float32Array(GW * GH), OY = new Float32Array(GW * GH), NN = new Float32Array(GW * GH);
    const lerp2 = (A, x, y) => {
      const gx = x / g, gy = y / g, ix = gx | 0, iy = gy | 0, fx = gx - ix, fy = gy - iy, j = iy * GW + ix;
      return (A[j] * (1 - fx) + A[j + 1] * fx) * (1 - fy) + (A[j + GW] * (1 - fx) + A[j + GW + 1] * fx) * fy;
    };
    return (t) => {
      const u = (t / 16) * Math.PI * 2;
      const ca = Math.cos(u), sa = Math.sin(u);
      for (let gy = 0; gy < GH; gy++) for (let gx = 0; gx < GW; gx++) {
        const vx = (gx * g + 0.5) / S, vy = ((gy * g + 0.5) * aspect) / S, j = gy * GW + gx;
        OX[j] = noise3(vx * 2.2 + ca * 0.4, vy * 2.2, sa * 0.4 + 1) * 0.06;
        OY[j] = noise3(vx * 2.2, vy * 2.2 + sa * 0.4, ca * 0.4 + 5) * 0.06;
        NN[j] = noise3(vx * 3.1 + ca * 0.7, vy * 3.1 + sa * 0.7, 0.5) + noise3(vx * 3.7 - sa * 0.6, vy * 3.7 + ca * 0.6, 7.5) * 0.8 + noise3(vx * 5.3 + sa, vy * 5.3 - ca, 3.1) * 0.35;
      }
      for (let y = 0, i = 0; y < H; y++) {
        const vy = ((y + 0.5) * aspect) / S;
        for (let x = 0; x < W; x++, i++) {
          const vx = (x + 0.5) / S;
          // Refraction wobble for the tiles.
          const gx = ((vx + lerp2(OX, x, y)) * S) / tile, gy = ((vy + lerp2(OY, x, y)) * S) / tile;
          const fx = gx - Math.floor(gx), fy = gy - Math.floor(gy);
          const line = Math.min(fx, 1 - fx, fy, 1 - fy) * tile;
          let c = lerpc(deep, water, 0.5 + 0.5 * Math.sin(Math.floor(gx) * 1.7 + Math.floor(gy) * 2.3) * 0.3);
          if (line < Math.max(0.6, tile * 0.07)) c = grout;
          // Caustic network: sharp ridges where drifting noise layers cancel.
          const ridge = Math.pow(clamp01(1 - Math.abs(lerp2(NN, x, y)) * 3.2), 3);
          c = lerpc(c, light, Math.min(0.85, ridge * 0.95));
          px[i] = c;
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/crt-static.js:
// Between channels on an old CRT: snow, a darker hum bar crawling up the
// tube, scanlines and a vignette — then the set catches a station for a beat,
// a test card rolls into lock with the channel number, and it's gone again.
import { lerpc, clamp01, hash2 } from '../retro/_kit.js';

const LOOP = 12;

export default {
  title: 'CRT Static',
  gallery: 'fx',
  category: 'Glitch & Noise',
  kind: 'scene',
  tags: ['static', 'snow', 'crt', 'tv', 'noise', 'analog', 'channel'],
  order: 40,
  description: 'Between channels on an old CRT: snow, a crawling hum bar and scanlines, until a test card rolls into lock.',
  size: { w: 64, h: 20 },
  minSize: { w: 16, h: 6 },
  loop: LOOP,
  canvas: 'field',
  setup(ctx) {
    const cv = ctx.canvas();
    const b = ctx.buffer;
    const { theme } = ctx;
    const { width: W, height: H, px, aspect } = cv;
    const tint = lerpc(0xffffff, theme.info, 0.12);
    // A simple test card: bars, a gray ramp, a circle with a cross.
    const card = (x, y) => {
      const u = x / W, v = y / H;
      const dx = (u - 0.5) * W, dy = (v - 0.5) * H * aspect, r = Math.hypot(dx, dy), R = Math.min(W, H * aspect) * 0.36;
      if (Math.abs(r - R) < 0.9 || (r < R && (Math.abs(dx) < 0.6 || Math.abs(dy) < 0.6))) return 0xffffff;
      if (v > 0.38 && v < 0.62 && r < R) return lerpc(0x101010, 0xf0f0f0, Math.floor(u * 8) / 7);
      if (v < 0.5) return [0xb0b0b0, 0xb0b000, 0x00b0b0, 0x00b000, 0xb000b0, 0xb00000, 0x0000b0][Math.min(6, Math.floor(u * 7))];
      return [0x0000b0, 0x101010, 0xb000b0, 0x101010, 0x00b0b0, 0x101010, 0xb0b0b0][Math.min(6, Math.floor(u * 7))];
    };
    return (t) => {
      const lt = t % LOOP, frame = Math.floor(t * 30);
      // Station lock: fades in from 6.0 s, rolls into place, holds, drops at 8.4 s.
      const lock = lt > 6 && lt < 8.4 ? clamp01((lt - 6) * 3) * clamp01((8.4 - lt) * 5) : 0;
      const roll = lt > 6 ? Math.floor(Math.max(0, 1 - (lt - 6) * 1.4) * H * 1.5) : 0;
      const hum = ((-lt / 3) % 1 + 1) % 1 * H * 1.4 - H * 0.2;
      for (let y = 0, i = 0; y < H; y++) {
        const bar = Math.exp(-Math.pow((y - hum) / (H * 0.12), 2));
        const scan = y % 2 ? 0.86 : 1;
        for (let x = 0; x < W; x++, i++) {
          let v = hash2(x, y, frame);
          v = v * v * 0.9 + (hash2(x >> 1, y, frame + 99) > 0.97 ? 0.4 : 0);
          let c = lerpc(0x000000, tint, clamp01(v) * (1 - bar * 0.45) * scan);
          if (lock > 0) c = lerpc(c, card(x, (y + roll) % H), lock * (0.9 - bar * 0.2) * scan);
          // Vignette toward the tube's corners.
          const vx = (x / W - 0.5) * 2, vy = (y / H - 0.5) * 2;
          px[i] = lerpc(c, 0x000000, clamp01((vx * vx + vy * vy - 0.55) * 0.55));
        }
      }
      cv.paint(b);
      if (lock > 0.5) b.text(Math.max(1, ctx.width - 7), 1, 'CH 03', theme.pos);
      else if (ctx.width >= 24) b.text(Math.max(1, ctx.width - 7), 1, `CH ${String(2 + (Math.floor(lt / 1.5) % 11)).padStart(2, '0')}`, lerpc(theme.pos, 0x000000, 0.3));
    };
  },
};

sources.prism-term/src/facets/fx/daylight.js:
// Light & Sky — the sun's side of the sky: a full dawn-to-dusk day over calm
// water, a total solar eclipse end to end, and white light fanning through a
// glass prism. All three are field canvases driven by one looping phase.
import { clamp01, hash2 } from '../retro/_kit.js';

const SPEED = { speed: { default: 1, min: 0.1, max: 4, label: 'Speed' } };
const TAU = Math.PI * 2;
const pack = (r, g, b) =>
  ((r > 255 ? 255 : r) << 16) | ((g > 255 ? 255 : g) << 8) | ((b > 255 ? 255 : b) | 0);

export default [
  {
    id: 'fx-daybreak',
    since: '0.3.0',
    title: 'Daybreak',
    category: 'Light & Sky',
    kind: 'scene',
    tags: ['sunrise', 'sunset', 'sun', 'sea', 'ocean', 'day cycle', 'glitter path', 'dawn', 'dusk', 'stars'],
    order: 200,
    description: 'A whole day over a calm sea: dawn flares, the sun arcs west with a glitter path tracking it on the water, dusk burns down to stars.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 30,
    canvas: 'field',
    palette: 'sunset',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const rand = ctx.rng;
      const { fbm } = ctx.noise;
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const horizon = Math.max(2, Math.min(H - 2, Math.round(H * 0.6)));
      const seaH = Math.max(1, H - horizon);
      const R = Math.max(1.4, Math.min(W * 0.045, H * aspect * 0.09));
      const stars = Array.from({ length: Math.max(10, Math.round(W * horizon * 0.02)) }, () => ({
        x: Math.floor(rand() * W), y: Math.floor(rand() * horizon),
        p: rand() * TAU, f: (7 + Math.floor(rand() * 3) * 7) * (TAU / 30), s: 0.5 + rand() * 0.5,
      }));
      const row = new Float32Array(horizon * 3);
      const c0 = Math.round(horizon * 0.14), c1 = Math.round(horizon * 0.74);
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 30) % 1 + 1) % 1;
        const u = clamp01((p - 0.06) / 0.88);
        const e = -0.25 + 1.25 * Math.sin(Math.PI * u);     // sun elevation
        const k = clamp01(e * 1.6 + 0.22);                  // daylight amount
        const w = (u > 0 && u < 1 ? 1 : 0) * Math.exp(-((e / 0.26) ** 2)); // dawn/dusk warmth
        const sx = W * (0.16 + 0.68 * u);
        const sy = horizon - e * horizon * 0.96;
        const sg = 246 - 120 * (1 - clamp01(e * 1.4 + 0.3));
        const sb = 214 - 174 * (1 - clamp01(e * 1.4 + 0.2));
        const zR = 4 + 58 * k, zG = 7 + 120 * k, zB = 20 + 192 * k;
        let lR = 10 + 158 * k, lG = 16 + 190 * k, lB = 38 + 196 * k;
        lR += (255 - lR) * w * 0.85; lG += (150 - lG) * w * 0.8; lB += (64 - lB) * w * 0.8;
        for (let y = 0; y < horizon; y++) {
          const v = (y / horizon) ** 1.35, j = y * 3;
          row[j] = zR + (lR - zR) * v; row[j + 1] = zG + (lG - zG) * v; row[j + 2] = zB + (lB - zB) * v;
        }
        let cR = 24 + 212 * k, cG = 24 + 206 * k, cB = 32 + 214 * k;
        cR += (255 - cR) * w * 0.75; cG += (164 - cG) * w * 0.6; cB += (92 - cB) * w * 0.6;
        const zx = Math.sin(TAU * p) * 1.7, zz = Math.cos(TAU * p) * 0.8;
        const R2 = R * R;
        for (let y = 0; y < horizon; y++) {
          const j = y * 3, dyU = (y - sy) * aspect, inBand = y >= c0 && y <= c1;
          for (let x = 0; x < W; x++) {
            let r = row[j], g = row[j + 1], b = row[j + 2];
            if (inBand) {
              const dens = clamp01(fbm(x * 0.055 + zx, y * 0.16, zz, 2) * 1.5 - 0.22);
              if (dens > 0.01) { r += (cR - r) * dens * 0.9; g += (cG - g) * dens * 0.9; b += (cB - b) * dens * 0.9; }
            }
            const dx = x - sx, d2 = dx * dx + dyU * dyU;
            const glow = Math.exp(-d2 / (R2 * 22)) * (90 + 130 * w);
            r += glow; g += glow * (0.62 + 0.3 * k); b += glow * (0.35 + 0.42 * k);
            if (d2 < R2) {
              const limb = 1 - 0.3 * (d2 / R2);
              r = 255 * limb; g = sg * limb; b = sb * limb;
            }
            px[y * W + x] = pack(r, g, b);
          }
        }
        if (k < 0.5) {
          const sa = 1 - k * 2;
          for (const s of stars) {
            const tw = sa * s.s * (0.55 + 0.45 * Math.sin(tt * s.f + s.p));
            if (tw > 0.05) cv.add(s.x, s.y, pack(tw * 190, tw * 200, tw * 235));
          }
        }
        for (let y = horizon; y < H; y++) {
          const d = y - horizon + 1;
          const wob = Math.sin(y * 1.9 + tt * (TAU / 30) * 7) * (0.35 + d * 0.16);
          const dk = 0.55 - (d / seaH) * 0.3;
          const my = Math.max(0, horizon - 1 - Math.round(d * 1.45));
          const gw = Math.max(1.2, R * (1.05 + d * 0.3));
          for (let x = 0; x < W; x++) {
            const sxm = Math.min(W - 1, Math.max(0, Math.round(x + wob)));
            const src = px[my * W + sxm];
            let r = ((src >> 16) & 255) * dk, g = ((src >> 8) & 255) * dk + 2, b = (src & 255) * dk + 6;
            if (e > -0.06) {
              const ax = Math.abs(x - sx);
              if (ax < gw && hash2(x, y, (tt * 7) | 0) > 0.9 + (ax / gw) * 0.09 - clamp01(e) * 0.04) {
                r = 255; g = sg * 0.98; b = sb * 0.92;
              }
            }
            px[y * W + x] = pack(r, g, b);
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-eclipse',
    since: '0.3.0',
    title: 'Totality',
    category: 'Light & Sky',
    kind: 'scene',
    tags: ['eclipse', 'solar eclipse', 'corona', 'diamond ring', 'moon', 'sun', 'totality', 'astronomy'],
    order: 210,
    description: 'A total solar eclipse end to end: the moon bites in, daylight collapses, the diamond ring flashes and the corona blooms over a dark land.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 24,
    canvas: 'field',
    palette: 'gold',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const rand = ctx.rng;
      const { noise3, fbm } = ctx.noise;
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const Hu = H * aspect;
      const sunX = W * 0.5, sunY = Hu * 0.42;
      const R = Math.max(2, Math.min(W * 0.13, Hu * 0.17));
      const Rm = R * 1.12;
      const gy = Math.max(1, Math.min(H - 1, Math.round(H * 0.84)));
      const ridge = new Float32Array(W);
      for (let x = 0; x < W; x++) {
        ridge[x] = Math.min(H - 1, gy + (fbm((x / Math.max(8, W)) * 5, 4.2, 0, 2) * 0.5 + 0.5) * (H - gy) * 0.6);
      }
      const stars = Array.from({ length: Math.max(12, Math.round(W * gy * 0.015)) }, () => ({
        x: Math.floor(rand() * W), y: Math.floor(rand() * Math.max(1, gy - 1)),
        s: 0.4 + rand() * 0.6, p: rand() * TAU, f: (8 + Math.floor(rand() * 6)) * (TAU / 24),
      }));
      const ca = Math.cos(0.18), sa = Math.sin(0.18);
      const row = new Float32Array(H * 3);
      const box = R * 3.4;
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 24) % 1 + 1) % 1;
        const off = (p - 0.5) * 2 * 3.1 * R;
        const mx = sunX + off * ca, myU = sunY + off * sa;
        const dcc = Math.abs(off);
        const cover = clamp01((R + Rm - dcc) / (2 * R));
        const L = Math.max(0.02, (1 - cover) ** 0.62);
        const cor = clamp01((cover - 0.86) / 0.14);
        const fl = Math.exp(-(((cover - 0.972) / 0.014) ** 2));
        const ring = clamp01(1.3 - L * 3.2) * cover;
        for (let y = 0; y < H; y++) {
          const v = Math.min(1, y / gy), j = y * 3, rr = (v ** 5) * ring;
          row[j] = 90 * L + 6 + (60 * L + 4) * v + 200 * rr;
          row[j + 1] = 150 * L + 8 + (40 * L + 4) * v + 92 * rr;
          row[j + 2] = 220 * L + 26 + (15 * L + 4) * v + 30 * rr;
        }
        for (let y = 0; y < H; y++) {
          const uy = y * aspect, j = y * 3, dyS = uy - sunY, dyM = uy - myU;
          for (let x = 0; x < W; x++) {
            if (y >= ridge[x]) {
              const vn = 0.75 + 0.25 * hash2(x, y, 9);
              px[y * W + x] = pack((7 + 48 * L) * vn, (9 + 56 * L) * vn, (9 + 38 * L) * vn);
              continue;
            }
            let r = row[j], g = row[j + 1], b = row[j + 2];
            const dxS = x - sunX, dxM = x - mx;
            if (dxS > -box && dxS < box && dyS > -box && dyS < box) {
              const d1 = Math.sqrt(dxS * dxS + dyS * dyS);
              if (cor > 0 && d1 > R * 0.92 && d1 < box) {
                const ang = Math.atan2(dyS, dxS);
                const n = 0.5 + 0.5 * noise3(Math.cos(ang) * 1.6, Math.sin(ang) * 1.6, tt * 0.1);
                const ci = cor * Math.exp(-(d1 - R) / (R * (0.22 + 0.85 * n * n))) * (0.5 + 0.5 * n);
                r += 225 * ci; g += 232 * ci; b += 255 * ci;
              }
              if (d1 < R) {
                const limb = 1 - 0.35 * ((d1 / R) ** 2);
                r = 255; g = 243 * limb; b = 205 * limb;
              }
              const gl = Math.exp(-(d1 * d1) / (R * R * 9)) * 120 * (1 - cover);
              r += gl; g += gl * 0.9; b += gl * 0.7;
              const dm2 = dxM * dxM + dyM * dyM;
              if (dm2 < Rm * Rm && (d1 < R * 1.05 || cor > 0.25)) {
                const ed = Math.sqrt(dm2) / Rm;
                r = 10 + 20 * (ed ** 8); g = r; b = r + 4;
              }
            }
            px[y * W + x] = pack(r, g, b);
          }
        }
        if (fl > 0.02) {
          const inv = dcc > 0.001 ? 1 / dcc : 0;
          const dirx = (sunX - mx) * inv, diry = (sunY - myU) * inv;
          const cxP = Math.round(sunX + dirx * R * 0.98);
          const cyP = Math.round((sunY + diry * R * 0.98) / aspect);
          const span = Math.max(2, Math.round(R * 1.3));
          for (let q = -span; q <= span; q++) {
            const fall = fl * Math.max(0, 1 - Math.abs(q) / span) ** 2;
            const c = pack(255 * fall, 250 * fall, 235 * fall);
            cv.add(cxP + q, cyP, c);
            cv.add(cxP, cyP + Math.round(q / (aspect * 1.5)), c);
          }
          for (let oy = -2; oy <= 2; oy++) for (let ox = -3; ox <= 3; ox++) {
            const dd = Math.exp(-(ox * ox + oy * oy * aspect * aspect) / 6) * fl;
            cv.add(cxP + ox, cyP + oy, pack(255 * dd, 252 * dd, 240 * dd));
          }
        }
        const starA = clamp01((0.3 - L) / 0.27);
        if (starA > 0.02) {
          for (const s of stars) {
            if (s.y >= ridge[s.x]) continue;
            const tw = starA * s.s * (0.6 + 0.4 * Math.sin(tt * s.f + s.p));
            cv.add(s.x, s.y, pack(tw * 185, tw * 195, tw * 230));
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-prism-beam',
    since: '0.3.0',
    title: 'Refraction',
    category: 'Light & Sky',
    kind: 'scene',
    tags: ['prism', 'refraction', 'spectrum', 'rainbow', 'dispersion', 'optics', 'light', 'beam', 'dust'],
    order: 220,
    description: 'White light meets a glass prism and fans out into a breathing spectrum, dust motes riding the beam and the bands shimmering in the dark.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 12,
    canvas: 'field',
    palette: 'prism',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const rand = ctx.rng;
      const { noise3 } = ctx.noise;
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const Hu = H * aspect;
      const cx = W * 0.42, cy = Hu * 0.52;
      const s = Math.max(2, Math.min(W * 0.2, Hu * 0.3));
      const Ax = cx, Ay = cy - s, Bx = cx - s * 0.866, By = cy + s * 0.5, Cx = cx + s * 0.866, Cy = cy + s * 0.5;
      const E1x = (Ax + Bx) / 2, E1y = (Ay + By) / 2;
      const E2x = (Ax + Cx) / 2, E2y = (Ay + Cy) / 2;
      const P0y = Math.min(Hu - 1, E1y + E1x * 0.22);
      const inLen = Math.hypot(E1x, E1y - P0y) || 1;
      const idx = E1x / inLen, idy = (E1y - P0y) / inLen;
      const gLen = Math.hypot(E2x - E1x, E2y - E1y) || 1;
      const gx = (E2x - E1x) / gLen, gyv = (E2y - E1y) / gLen;
      const bw = Math.max(0.8, Hu * 0.03);
      const mseed = Array.from({ length: 24 }, () => [rand(), rand(), rand(), rand()]);
      const F1 = (TAU / 12) * 4, F2 = (TAU / 12) * 5, F3 = (TAU / 12) * 2;
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 12) % 1 + 1) % 1;
        const spread = 0.5 * (1 + 0.07 * Math.sin(TAU * p));
        const a0 = 0.06 - spread / 2;
        for (let y = 0; y < H; y++) {
          const uy = y * aspect;
          for (let x = 0; x < W; x++) {
            const vdx = (x - W / 2) / W, vdy = (uy - Hu / 2) / Hu;
            let r = 3 + 6 * (1 - (vdx * vdx + vdy * vdy) * 2);
            let g = r * 0.9, b = r * 1.35;
            const s1 = (Bx - Ax) * (uy - Ay) - (By - Ay) * (x - Ax);
            const s2 = (Cx - Bx) * (uy - By) - (Cy - By) * (x - Bx);
            const s3 = (Ax - Cx) * (uy - Cy) - (Ay - Cy) * (x - Cx);
            const inside = (s1 <= 0 && s2 <= 0 && s3 <= 0) || (s1 >= 0 && s2 >= 0 && s3 >= 0);
            if (inside) {
              const shade = 0.5 + 0.5 * clamp01((uy - Ay) / (s * 1.5));
              r = 16 + 18 * shade; g = 20 + 24 * shade; b = 30 + 34 * shade;
              const nz = noise3(x * 0.14, uy * 0.14, tt * 0.25);
              r += nz * 6 + 6; g += nz * 8 + 8; b += nz * 10 + 10;
              const rx = x - E1x, ry = uy - E1y;
              const sp = rx * gx + ry * gyv;
              if (sp > -1 && sp < gLen + 1) {
                const lat = Math.abs(rx * gyv - ry * gx);
                const I = Math.exp(-((lat / (bw * 1.1)) ** 2)) * 200;
                const hue = clamp01(sp / gLen);
                r += I * (1 - hue * 0.1); g += I * (1 - hue * 0.25); b += I;
              }
              if (Math.min(Math.abs(s1), Math.abs(s2), Math.abs(s3)) < s * s * 0.07) { r += 60; g += 72; b += 95; }
            } else if (x <= E1x) {
              const rx = x, ry = uy - P0y;
              const sp = rx * idx + ry * idy;
              if (sp > 0 && sp <= inLen) {
                const lat = Math.abs(rx * idy - ry * idx);
                const I = Math.exp(-((lat / bw) ** 2)) * (195 + 25 * Math.sin(tt * F1 + sp * 0.2));
                r += I; g += I * 0.97; b += I * 0.9;
              }
            }
            if (!inside && x >= E2x - 1) {
              const rx = x - E2x, ry = uy - E2y;
              const rr = Math.hypot(rx, ry);
              if (rr > 0.6) {
                const uu = (Math.atan2(ry, rx) - a0) / spread;
                if (uu > 0 && uu < 1) {
                  const env = Math.min(1, uu * 7, (1 - uu) * 7);
                  const fade = clamp01(1.25 - rr / (W * 0.95));
                  const shim = 0.82 + 0.18 * Math.sin(uu * 26 - tt * F2 + rr * 0.1);
                  const c = pal(0.03 + (1 - uu) * 0.88);
                  const I = env * fade * shim;
                  const core = Math.max(0, 1 - rr / (s * 0.5));
                  r += ((c >> 16) & 255) * I + 220 * core;
                  g += ((c >> 8) & 255) * I + 220 * core;
                  b += (c & 255) * I + 225 * core;
                }
              }
            }
            px[y * W + x] = pack(r, g, b);
          }
        }
        for (let i = 0; i < 24; i++) {
          const m = mseed[i];
          if (i < 10) {
            const q = ((m[0] + tt * ((1 + Math.floor(m[1] * 2)) / 12)) % 1 + 1) % 1;
            const ux = idx * q * inLen + Math.sin(tt * F3 + i) * (m[2] - 0.5) * 2;
            const uyv = P0y + idy * q * inLen + (m[3] - 0.5) * 2;
            const br = 120 + 100 * Math.sin(tt * F3 + i * 2.4);
            cv.add(Math.round(ux), Math.round(uyv / aspect), pack(br, br * 0.97, br * 0.9));
          } else {
            const uu = m[0];
            const ang = a0 + uu * spread;
            const rr = (((m[1] + tt * ((1 + Math.floor(m[2] * 2)) / 12)) % 1 + 1) % 1) * W * 0.6;
            const ux = E2x + Math.cos(ang) * rr, uyv = E2y + Math.sin(ang) * rr;
            const c = pal(0.03 + (1 - uu) * 0.88);
            cv.add(Math.round(ux), Math.round(uyv / aspect),
              pack(((c >> 16) & 255) * 0.7, ((c >> 8) & 255) * 0.7, (c & 255) * 0.7));
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

sources.prism-term/src/facets/fx/embers-and-rain:
// Fire & Water — two close-up night moods: rain runnels wandering down a
// window over city bokeh, and embers drifting on the wind above a dying bed
// of coals.
import { mix, scale } from '../../color.js';
import { clamp } from '../../easing.js';

const TAU = Math.PI * 2;

export default [
  {
    id: 'fx-rain-on-glass',
    since: '0.3.0',
    title: 'Rain on Glass',
    category: 'Fire & Water',
    kind: 'scene',
    tags: ['rain', 'window', 'glass', 'bokeh', 'droplets', 'night', 'rivulets'],
    order: 230,
    description: 'Runnels slide and stick down a windowpane, refracting blurred city bokeh, while micro-droplets bead and twinkle on the glass.',
    loop: 12,
    canvas: 'field',
    palette: 'synthwave',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { noise2 } = ctx.noise;
      const { width: W, height: H, px, aspect } = cv;
      const rand = ctx.rng;
      const N = W * H;
      const day = ctx.theme.mode === 'light' && ctx.bg >= 0;
      const S = Math.max(8, Math.min(W, H * aspect));
      // The city beyond the glass: a dim gradient with soft out-of-focus lights.
      const bgA = new Int32Array(N);
      for (let y = 0, i = 0; y < H; y++) {
        const yn = H > 1 ? y / (H - 1) : 0;
        let c = mix(scale(pal(0.08), 0.7), pal(0.24), yn * yn);
        if (day) c = mix(c, ctx.bg, 0.3);
        for (let x = 0; x < W; x++, i++) bgA[i] = c;
      }
      const K = Math.max(5, Math.round(N / 1500));
      for (let b = 0; b < K; b++) {
        const bx = rand() * W, by = H * (0.15 + rand() * 0.75);
        const r = Math.max(2, (2.5 + rand() * 5) * (S / 50));
        const col = pal(0.4 + rand() * 0.55);
        const x0 = Math.max(0, Math.floor(bx - r)), x1 = Math.min(W - 1, Math.ceil(bx + r));
        const y0 = Math.max(0, Math.floor(by - r)), y1 = Math.min(H - 1, Math.ceil(by + r));
        for (let y = y0; y <= y1; y++) {
          for (let x = x0; x <= x1; x++) {
            const dx = x - bx, dy = (y - by) * aspect;
            const f = 1 - (dx * dx + dy * dy) / (r * r);
            if (f > 0) bgA[y * W + x] = mix(bgA[y * W + x], col, f * f * 0.55);
          }
        }
      }
      const beads = [];
      const nmd = Math.min(140, Math.max(20, Math.round(N / 110)));
      for (let i = 0; i < nmd; i++) {
        beads.push({ j: Math.floor(rand() * H) * W + Math.floor(rand() * W), ph: rand() * TAU, k: 1 + Math.floor(rand() * 2), br: 0.4 + rand() * 0.6 });
      }
      const runnels = [];
      const nr = Math.max(6, Math.min(16, Math.round(W / 10)));
      for (let i = 0; i < nr; i++) {
        runnels.push({
          x0: rand() * W, off: rand(), dur: 0.45 + rand() * 0.45,
          wob: 0.8 + rand() * 1.6, seed: rand() * 90, len: 0.2 + rand() * 0.2,
        });
      }
      const wet = pal(0.92), head = pal(0.98);
      return (t) => {
        px.set(bgA);
        for (const bd of beads) {
          const tw = 0.5 + 0.5 * Math.sin(TAU * bd.k * (t / 12) + bd.ph);
          px[bd.j] = mix(bgA[bd.j], wet, (0.14 + 0.18 * tw) * bd.br);
        }
        for (const r of runnels) {
          const ag = ((t / 12 + r.off) % 1 + 1) % 1;
          if (ag > r.dur) continue;
          const prog = ag / r.dur;
          const pe = prog * prog * 0.6 + prog * 0.4; // picks up speed as it swells
          const hy = pe * (H + 4) - 2;
          const hx = r.x0 + r.wob * Math.sin(prog * 9 + r.seed) + 1.4 * noise2(r.seed, prog * 5);
          const L = Math.max(2, r.len * H * Math.min(1, prog * 3 + 0.2));
          for (let k = 0; k <= L; k++) {
            const ty = Math.floor(hy - k);
            if (ty < 0) break;
            if (ty >= H) continue;
            const txi = Math.floor(hx + 0.6 * Math.sin((prog * 9 + r.seed) - k * 0.12));
            if (txi < 0 || txi >= W) continue;
            const j = ty * W + txi;
            const j2 = Math.min(N - 1, j + 2 * W); // the streak bends light from below
            const a = 1 - k / L;
            px[j] = mix(bgA[j2], wet, 0.12 + 0.26 * a);
          }
          cv.blend(hx, hy, head, 0.9);
          cv.blend(hx, hy - 1, head, 0.45);
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-ember-drift',
    since: '0.3.0',
    title: 'Ember Drift',
    category: 'Fire & Water',
    kind: 'scene',
    tags: ['embers', 'sparks', 'coals', 'fire', 'night', 'wind', 'glow'],
    order: 240,
    description: 'Sparks lift off a breathing bed of coals and ride gusts into the dark, wobbling and winking out as the cracks pulse below.',
    loop: 12,
    canvas: 'field',
    palette: 'fire',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { noise2 } = ctx.noise;
      const { width: W, height: H, px } = cv;
      const rand = ctx.rng;
      const day = ctx.theme.mode === 'light' && ctx.bg >= 0;
      const cH = Math.max(2, Math.round(H * 0.14));
      const bedY = H - cH;
      const bed = new Float32Array(W * cH), crack = new Float32Array(W * cH);
      for (let y = 0; y < cH; y++) {
        for (let x = 0; x < W; x++) {
          bed[y * W + x] = 0.5 + 0.5 * noise2(x * 0.5, y * 0.9 + 3);
          crack[y * W + x] = Math.pow(clamp(1 - Math.abs(noise2(x * 0.16, y * 0.5 + 7)) * 3), 4);
        }
      }
      const embers = [];
      const P = Math.max(24, Math.min(110, Math.round((W * H) / 150)));
      for (let i = 0; i < P; i++) {
        embers.push({
          x0: rand() * W, t0: rand() * 12, life: 2.2 + rand() * 2.6,
          v: H * (0.18 + 0.14 * rand()), drift: (rand() - 0.5) * 3,
          wob: 1.1 + rand() * 1.4, wph: rand() * TAU, h0: 0.55 + rand() * 0.45,
        });
      }
      const skyDark = day ? mix(ctx.bg, pal(0.3), 0.16) : scale(pal(0.06), 0.55);
      const glowC = pal(0.3), crackC = pal(0.9);
      return (t) => {
        const u = TAU * (t / 12);
        const breathe = 0.85 + 0.15 * Math.sin(2 * u);
        for (let y = 0, i = 0; y < H; y++) {
          if (y < bedY) {
            const g = clamp(1 - (bedY - y) / Math.max(1, H * 0.55));
            const glow = g * g;
            for (let x = 0; x < W; x++, i++) {
              let c = mix(skyDark, glowC, glow * 0.45 * breathe);
              const sh = 1 + 0.05 * Math.sin(y * 1.1 + 3 * u + x * 0.07) * glow;
              px[i] = sh > 1.001 || sh < 0.999 ? scale(c, sh) : c;
            }
          } else {
            const by = y - bedY;
            for (let x = 0; x < W; x++, i++) {
              const bb = bed[by * W + x];
              const pulse = 0.72 + 0.28 * Math.sin(2 * u + bb * 5 + x * 0.06);
              const heat = bb * pulse;
              let c = pal(0.1 + 0.5 * heat);
              const cr = crack[by * W + x];
              if (cr > 0.03) c = mix(c, crackC, cr * pulse * 0.8);
              px[i] = c;
            }
          }
        }
        const wind = 5 * Math.sin(u) + 2.2 * Math.sin(2 * u + 1.3);
        for (const e of embers) {
          const age = (((t - e.t0) % 12) + 12) % 12;
          if (age >= e.life) continue;
          const an = age / e.life;
          const ey = bedY - e.v * age * (1 - 0.22 * an);
          if (ey < -2) continue;
          const ex = e.x0 + e.drift * age + wind * an * 0.6 + 2.2 * Math.sin(age * e.wob * 3 + e.wph);
          const heat = e.h0 * (1 - an) * (0.72 + 0.28 * Math.sin(age * 8 + e.wph));
          if (heat <= 0.02) continue;
          const col = pal(0.32 + 0.6 * clamp(heat));
          cv.blend(ex, ey, col, Math.min(1, heat * 1.8));
          if (heat > 0.5) {
            const ga = (heat - 0.5) * 0.5;
            cv.blend(ex + 1, ey, col, ga);
            cv.blend(ex - 1, ey, col, ga);
            cv.blend(ex, ey + 1, col, ga);
            cv.blend(ex, ey - 1, col, ga);
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

sources.prism-term/src/facets/fx/fire.js:
// Old-school fire: each pixel averages the heat beneath it (drifting with a
// gusting wind) minus a scrolling cooling map, which tears the rising heat into
// tongues of flame; a flickering fuel bed feeds it and embers spiral off the top.
// On light themes the flame burns in daylight: its cool edge melts into the page
// instead of a soot-black band.
import { mix } from '../../color.js';

export default {
  title: 'Fire',
  gallery: 'fx',
  category: 'Fire & Water',
  kind: 'scene',
  tags: ['fire', 'doom', 'embers', 'heat'],
  order: 20,
  description: 'Classic demoscene fire — heat rises, averages and cools through a scrolling noise map, throwing embers on the wind.',
  canvas: 'field',
  palette: 'fire',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const day = ctx.theme.mode === 'light' && ctx.bg >= 0, paper = ctx.bg;
    const rand = ctx.rng;
    const { noise3 } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const heat = new Float32Array(W * (H + 2)); // two extra rows = fuel bed
    const rate = 32 * Math.max(1, H / 70);   // simulation steps (rows of rise) per second
    // Cooling texture, seamlessly tiled vertically so it can scroll forever.
    const CH = H * 2;
    const cool = new Float32Array(W * CH);
    const strength = ctx.param('height', 1);
    const base = 255 / Math.max(10, H * 0.62 * strength);
    for (let y = 0; y < CH; y++)
      for (let x = 0; x < W; x++) {
        const f = (yy) => {
          const n = noise3(x * 0.19, yy * 0.075 * aspect, 0.5) * 0.5 + 0.5;
          return n * n;
        };
        const k = y / CH;
        cool[y * W + x] = base * (0.35 + 2.3 * (f(y) * (1 - k) + f(y + CH) * k));
      }
    const embers = [];
    let acc = 0, scroll = 0, steps = 0;

    const step = (t) => {
      const fuel = H * W;
      for (let x = 0; x < W; x++) {
        const n = noise3(x * 0.05, t * 1.3, 2.7);
        const v = 205 + n * 150 + (rand() - 0.5) * 70;
        heat[fuel + x] = v < 0 ? 0 : v > 255 ? 255 : v;
        heat[fuel + W + x] = heat[fuel + x];
      }
      scroll = (scroll + 1) % CH;
      for (let y = 0; y < H; y++) {
        const wind = noise3(y * 0.04, t * 0.35, 9.1) * 1.8 + Math.sin(t * 0.5) * 0.6;
        const shift = wind > 0.5 ? 1 : wind < -0.5 ? -1 : 0;
        const r1 = (y + 1) * W, r2 = (y + 2) * W;
        const cr = ((y + scroll) % CH) * W;
        for (let x = 0; x < W; x++) {
          const xs = x - shift;
          const a = xs > 0 ? xs - 1 : 0, b = xs < 0 ? 0 : xs >= W ? W - 1 : xs, c = xs + 1 < W ? xs + 1 : W - 1;
          const v = (heat[r1 + a] + heat[r1 + b] + heat[r1 + c] + heat[r2 + b]) * 0.25 - cool[cr + x];
          heat[y * W + x] = v > 0 ? v : 0;
        }
      }
      if (rand() < 0.3 * Math.max(1, W / 80)) {
        embers.push({ x: rand() * W, y: H * (0.55 + rand() * 0.3), vx: (rand() - 0.5) * 8, vy: -(12 + rand() * 20) * Math.max(1, H / 60), life: 1, p: rand() * 6 });
      }
      steps++;
    };

    return (t, dt) => {
      acc += dt * rate;
      let n = 0;
      while (acc >= 1 && n < 4) { step(t); acc -= 1; n++; }
      if (acc > 4) acc = 0;
      if (steps === 0) for (let k = 0; k < H; k++) step(t); // start with flames already up

      for (let i = 0; i < W * H; i++) {
        const h = heat[i];
        px[i] = h < 10 ? -1 : day ? mix(paper, pal(0.36 + 0.64 * (h / 255)), Math.min(1, (h - 10) / 110)) : pal(h / 255);
      }
      for (let i = embers.length - 1; i >= 0; i--) {
        const e = embers[i];
        e.x += (e.vx + Math.sin(t * 2.5 + e.p) * 6) * dt;
        e.y += e.vy * dt;
        e.life -= dt * 0.6;
        if (e.life <= 0 || e.y < 0) { embers.splice(i, 1); continue; }
        cv.set(e.x, e.y, pal(0.45 + e.life * 0.5));
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/fractal-escapes:
// Fractals as full-color fields: a seamless bitwise dive through the
// Sierpinski gasket, a drifting window over Markus–Lyapunov space, and the
// Ushiki phoenix set breathing through a slow zoom.
import { mix, scale } from '../../color.js';
import { clamp } from '../../easing.js';

const TAU = Math.PI * 2;

export default [
  {
    id: 'fx-sierpinski-zoom',
    since: '0.3.0',
    title: 'Sierpinski Dive',
    category: 'Fractals',
    kind: 'scene',
    tags: ['sierpinski', 'gasket', 'zoom', 'fractal', 'bitwise', 'self-similar', 'triangles'],
    order: 200,
    description: 'An endless dive into the Sierpinski gasket by bitwise AND: triangular holes stream outward in color bands, seamless every loop.',
    loop: 6,
    canvas: 'field',
    palette: 'prism',
    credits: 'after Wacław Sierpiński (and HAKMEM munching squares)',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { width: W, height: H, px, aspect } = cv;
      const S = Math.max(8, Math.min(W, H * aspect));
      const SC = 262144; // 2^18 — plenty of bits above and below the visible scales
      const inkTone = mix(ctx.theme.ink, pal(0.82), 0.4);
      return (t) => {
        const f = ((t / 6) % 1 + 1) % 1;
        const unit = 1.3 / (S * Math.pow(2, f)); // view halves each loop: ×2 dive, anchored at the corner
        for (let y = 0, i = 0; y < H; y++) {
          const iy = ((H - y - 0.5) * aspect * unit * SC) | 0;
          for (let x = 0; x < W; x++, i++) {
            const ix = ((x + 0.5) * unit * SC) | 0;
            const m = ix & iy;
            if (m === 0) { px[i] = inkTone; continue; } // on the gasket's lattice itself
            const d = 31 - Math.clz32(m); // coarsest colliding bit = the hole this point sits in
            const age = d + f;            // advances one band per loop, so color closes seamlessly
            const c = pal(age * 0.09);
            px[i] = scale(c, 0.52 + 0.45 * (0.5 + 0.5 * Math.sin(age * 1.9 - TAU * f)));
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-lyapunov-space',
    since: '0.3.0',
    title: 'Lyapunov Space',
    category: 'Fractals',
    kind: 'scene',
    tags: ['lyapunov', 'logistic map', 'chaos', 'markus', 'fractal', 'zircon', 'stability'],
    order: 210,
    description: 'A window drifting over Markus–Lyapunov space for sequence BBABA: golden ridges of stability swim through ink-blue chaos.',
    loop: 32,
    canvas: 'field',
    palette: 'gold',
    credits: 'after Mario Markus and Benno Hess',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { width: W, height: H, px, aspect } = cv;
      const S = Math.max(8, Math.min(W, H * aspect));
      const seq = [1, 1, 0, 1, 0]; // b b a b a
      const SL = seq.length;
      const chaos = mix(pal(0.08), ctx.theme.info, 0.5);
      const dark = pal(0.12);
      // Fixed per-pixel iteration count sized to the canvas, so cost stays bounded.
      const iters = Math.max(36, Math.min(80, Math.round(9e5 / Math.max(1, W * H))));
      const warm = 8, cnt = iters - warm;
      return (t) => {
        const u = (t / 32) * TAU;
        const ca = 3.52 + 0.22 * Math.cos(u), cb = 3.12 + 0.28 * Math.sin(u);
        for (let y = 0, i = 0; y < H; y++) {
          const nyv = ((y - H / 2 + 0.5) * aspect) / S;
          let b = cb + nyv * 0.52;
          b = b < 2.52 ? 2.52 : b > 3.985 ? 3.985 : b;
          for (let x = 0; x < W; x++, i++) {
            const nxv = (x - W / 2 + 0.5) / S;
            let a = ca + nxv * 0.52;
            a = a < 2.52 ? 2.52 : a > 3.985 ? 3.985 : a;
            let v = 0.5, si = 0;
            for (let n = 0; n < warm; n++) {
              v = (seq[si] ? b : a) * v * (1 - v);
              si = si + 1 === SL ? 0 : si + 1;
            }
            let prod = 1;
            for (let n = 0; n < cnt; n++) {
              const r = seq[si] ? b : a;
              si = si + 1 === SL ? 0 : si + 1;
              v = r * v * (1 - v);
              const dv = r * (1 - 2 * v);
              prod *= dv < 0 ? -dv : dv;
            }
            const la = Math.log(prod) / cnt; // one log per pixel instead of one per iteration
            px[i] = la < 0
              ? pal(0.3 + 0.68 * Math.pow(Math.min(1, -la * 0.75), 0.55))
              : mix(chaos, dark, Math.min(1, la * 1.6));
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-phoenix-fractal',
    since: '0.3.0',
    title: 'Phoenix Fractal',
    category: 'Fractals',
    kind: 'scene',
    tags: ['phoenix', 'julia', 'fractal', 'escape time', 'ushiki', 'feathers'],
    order: 220,
    description: 'The Ushiki phoenix set rendered wings-up, breathing through a slow zoom while its twin parameters circle the classic values.',
    loop: 28,
    canvas: 'field',
    palette: 'fire',
    credits: 'after Shigehiro Ushiki',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 1024 });
      const { width: W, height: H, px, aspect } = cv;
      const inside = ctx.theme.bg;
      const budget = 3.0e6; // iterations per frame, steered like the Mandelbrot dive
      let cap = 120;
      return (t) => {
        const u = (t / 28) * TAU;
        const p = -0.5 + 0.045 * Math.cos(u), q = 0.045 * Math.sin(u);
        const cr0 = 0.5667 + 0.012 * Math.sin(2 * u);
        const zoom = Math.exp(Math.log(3.2) * (1 - Math.cos(u)) / 2);
        const unit = 3.1 / (Math.max(8, Math.min(W, H * aspect)) * zoom);
        const maxIt = Math.max(26, Math.min(240, cap));
        const drift = 0.35 * Math.sin(2 * u);
        let work = 0;
        for (let y = 0, i = 0; y < H; y++) {
          const vy = (y - H / 2 + 0.5) * aspect * unit;
          for (let x = 0; x < W; x++, i++) {
            const vx = (x - W / 2 + 0.5) * unit;
            // Axes swapped so the bird stands upright.
            let zr = vy, zi = vx, pr = 0, pi = 0;
            let n = 0, r2 = 0, i2 = 0;
            while (n < maxIt) {
              r2 = zr * zr; i2 = zi * zi;
              if (r2 + i2 > 64) break;
              const nr = r2 - i2 + cr0 + p * pr - q * pi;
              const ni = 2 * zr * zi + p * pi + q * pr;
              pr = zr; pi = zi; zr = nr; zi = ni;
              n++;
            }
            work += n;
            if (n >= maxIt) { px[i] = inside; continue; }
            const mu = n + 1 - Math.log(Math.log(r2 + i2) * 0.5) / Math.LN2;
            const s = Math.log2(Math.max(1, mu) + 1) * 0.3 + drift;
            px[i] = pal(1 - Math.abs(((s % 2) + 2) % 2 - 1));
          }
        }
        if (work > budget) cap = Math.max(26, Math.floor(cap * 0.85));
        else if (work < budget * 0.6) cap = Math.min(240, Math.ceil(cap * 1.08) + 1);
        cv.paint(ctx.buffer);
      };
    },
  },
];

sources.prism-term/src/facets/fx/fractal-gardens:
// Fractals that grow instead of iterate: a Barnsley fern sprouting point by
// point, the Koch snowflake blooming a generation of spikes at a time, and a
// de Jong strange attractor smeared into glowing smoke.
import { mix, scale } from '../../color.js';
import { clamp, smoothstep } from '../../easing.js';

const TAU = Math.PI * 2;

export default [
  {
    id: 'fx-barnsley-fern',
    since: '0.3.0',
    title: 'Barnsley Fern',
    category: 'Fractals',
    kind: 'scene',
    tags: ['fern', 'ifs', 'barnsley', 'fractal', 'growth', 'plant', 'nature'],
    order: 230,
    description: 'An iterated-function-system fern that sprouts from the stem upward, sways in a breeze, then furls away to grow again.',
    loop: 16,
    canvas: 'field',
    palette: 'matrix',
    credits: 'after Michael Barnsley',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { width: W, height: H, px, aspect } = cv;
      const rand = ctx.rng;
      const M = Math.max(2500, Math.min(26000, Math.round(W * H * 1.8)));
      const wx = new Float32Array(M), wy = new Float32Array(M);
      let fx = 0, fy = 0;
      for (let i = 0; i < M; i++) {
        const r = rand();
        let nx, ny;
        if (r < 0.01) { nx = 0; ny = 0.16 * fy; }
        else if (r < 0.86) { nx = 0.85 * fx + 0.04 * fy; ny = -0.04 * fx + 0.85 * fy + 1.6; }
        else if (r < 0.93) { nx = 0.2 * fx - 0.26 * fy; ny = 0.23 * fx + 0.22 * fy + 1.6; }
        else { nx = -0.15 * fx + 0.28 * fy; ny = 0.26 * fx + 0.24 * fy + 0.44; }
        fx = nx; fy = ny;
        wx[i] = fx; wy[i] = fy;
      }
      // Growth order: sap rises — sort points bottom-up so the fern unfurls.
      const order = Array.from({ length: M }, (_, i) => i)
        .sort((a, b) => (wy[a] + Math.abs(wx[a]) * 0.35) - (wy[b] + Math.abs(wx[b]) * 0.35));
      const k2 = Math.max(0.3, Math.min((H - 1.5) / 10.3, (W * 0.95) / (5.6 * aspect)));
      const kx = k2 * aspect;
      const SX = new Float32Array(M), SY = new Float32Array(M), CI = new Uint8Array(M),
        WP = new Float32Array(M), PH = new Float32Array(M);
      for (let n = 0; n < M; n++) {
        const i = order[n];
        SX[n] = W * 0.5 + (wx[i] - 0.24) * kx;
        SY[n] = (H - 1) - wy[i] * k2;
        CI[n] = Math.max(0, Math.min(32, Math.round((wy[i] / 10) * 32)));
        WP[n] = (wy[i] / 10) * (wy[i] / 10);
        PH[n] = wy[i] * 0.55;
      }
      const cols = Array.from({ length: 33 }, (_, j) => pal(0.2 + (0.68 * j) / 32));
      const glow = Array.from({ length: 33 }, (_, j) => mix(pal(0.2 + (0.68 * j) / 32), pal(0.97), 0.65));
      const bgTop = scale(pal(0.05), 0.75), bgBot = pal(0.14);
      const amp = kx * 0.45;
      return (t) => {
        const u = ((t / 16) % 1 + 1) % 1;
        const frac = smoothstep(0.0, 0.58, u) * (1 - smoothstep(0.86, 0.995, u));
        const count = Math.min(M, Math.floor(M * frac));
        for (let y = 0, i = 0; y < H; y++) {
          const c = mix(bgTop, bgBot, H > 1 ? y / (H - 1) : 0);
          for (let x = 0; x < W; x++, i++) px[i] = c;
        }
        const st = TAU * 2 * (t / 16);
        const glowFrom = count - Math.max(40, M * 0.05);
        for (let n = 0; n < count; n++) {
          const sx = SX[n] + amp * Math.sin(st + PH[n]) * WP[n];
          cv.set(sx, SY[n], n > glowFrom ? glow[CI[n]] : cols[CI[n]]);
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-koch-bloom',
    since: '0.3.0',
    title: 'Koch Bloom',
    category: 'Fractals',
    kind: 'scene',
    tags: ['koch', 'snowflake', 'fractal', 'bloom', 'ice', 'crystal', 'geometry'],
    order: 240,
    description: 'A triangle blooms into the Koch snowflake, each generation of spikes easing outward while frost sparkles breathe behind it.',
    loop: 10,
    canvas: 'field',
    palette: 'ice',
    credits: 'after Helge von Koch',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { width: W, height: H, px, aspect } = cv;
      const rand = ctx.rng;
      const S = Math.max(8, Math.min(W, H * aspect));
      const R = S * 0.4;
      const cx = W / 2, cyW = 0; // geometry in square world units centered on the canvas
      const maxD = S >= 60 ? 5 : S >= 30 ? 4 : 3;
      const nSpark = Math.max(8, Math.round((W * H) / 260));
      const spark = [];
      for (let i = 0; i < nSpark; i++) {
        spark.push({ x: rand() * W, y: rand() * H, ph: rand() * TAU, k: 1 + Math.floor(rand() * 3), s: 0.35 + rand() * 0.6 });
      }
      const bgA = new Int32Array(W * H);
      for (let y = 0, i = 0; y < H; y++) {
        for (let x = 0; x < W; x++, i++) {
          const dx = x - cx, dy = (y - H / 2) * aspect;
          const rr = Math.sqrt(dx * dx + dy * dy) / Math.max(1, S * 0.72);
          bgA[i] = pal(Math.max(0.02, 0.24 - rr * 0.2));
        }
      }
      const tcol = new Int32Array(maxD + 2);
      const plot = (x1, y1, x2, y2, col) => {
        const dx = x2 - x1, dy = y2 - y1;
        const n = Math.max(1, Math.ceil(Math.max(Math.abs(dx), Math.abs(dy) / aspect) * 1.3));
        for (let k = 0; k <= n; k++) {
          const gx = x1 + (dx * k) / n, gy = y1 + (dy * k) / n;
          cv.add(cx + gx, H / 2 + (gy + cyW) / aspect, col);
        }
      };
      const emit = (x1, y1, x2, y2, depth, tint) => {
        if (depth <= 0) { plot(x1, y1, x2, y2, tcol[Math.min(tint, maxD + 1)]); return; }
        const dx = x2 - x1, dy = y2 - y1;
        const z = Math.min(1, depth);
        const h = z * z * (3 - 2 * z); // new spikes ease outward
        const ax = x1 + dx / 3, ay = y1 + dy / 3;
        const bx = x1 + (dx * 2) / 3, by = y1 + (dy * 2) / 3;
        const mx = x1 + dx / 2 + dy * 0.288675 * h, my = y1 + dy / 2 - dx * 0.288675 * h;
        const d2 = depth - 1;
        emit(x1, y1, ax, ay, d2, tint);
        emit(ax, ay, mx, my, d2, tint + 1);
        emit(mx, my, bx, by, d2, tint + 1);
        emit(bx, by, x2, y2, d2, tint);
      };
      return (t) => {
        const ph = ((t / 10) % 1 + 1) % 1;
        const half = ph < 0.5 ? ph * 2 : 2 - ph * 2;
        const dd = maxD * half * half * (3 - 2 * half);
        const rot = 0.35 * Math.sin(TAU * ph) - TAU / 4;
        for (let g = 0; g <= maxD + 1; g++) {
          tcol[g] = scale(pal(clamp(0.3 + g * 0.13 + 0.04 * Math.sin(TAU * 2 * ph + g))), 0.8);
        }
        px.set(bgA);
        for (const sp of spark) {
          const tw = 0.5 + 0.5 * Math.sin(TAU * sp.k * ph + sp.ph);
          cv.blend(sp.x, sp.y, pal(0.88), tw * sp.s * 0.55);
        }
        const vx = [], vy = [];
        for (let s = 0; s < 3; s++) {
          const ang = rot + (s * TAU) / 3;
          vx.push(R * Math.cos(ang)); vy.push(R * Math.sin(ang));
        }
        for (let s = 0; s < 3; s++) {
          const e = (s + 1) % 3;
          emit(vx[s], vy[s], vx[e], vy[e], dd, 0);
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-strange-attractor',
    since: '0.3.0',
    title: 'Strange Attractor',
    category: 'Fractals',
    kind: 'scene',
    tags: ['attractor', 'de jong', 'chaos', 'phase space', 'density', 'orbit', 'smoke'],
    order: 250,
    description: 'A Peter de Jong attractor breathing through its parameter space, its orbit smeared into glowing smoke with fading trails.',
    loop: 24,
    canvas: 'field',
    palette: 'synthwave',
    credits: 'after Peter de Jong',
    params: { trail: { default: 0.88, min: 0.5, max: 0.97, label: 'Trail' } },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { width: W, height: H, aspect } = cv;
      const fadeK = clamp(ctx.param('trail', 0.88), 0.3, 0.97);
      const N = Math.max(4000, Math.min(22000, Math.round(W * H * 1.4)));
      const sc = Math.max(4, Math.min(W, H * aspect)) * 0.235;
      const cxp = W / 2, cyp = H / 2;
      const dim = new Int32Array(24);
      for (let j = 0; j < 24; j++) dim[j] = scale(pal(j / 23), 0.17);
      return (t) => {
        const u = (t / 24) * TAU;
        const a = 1.4 + 0.35 * Math.sin(u);
        const b = -2.3 + 0.3 * Math.sin(2 * u + 1.2);
        const c = 2.4 + 0.4 * Math.sin(u + 2.1);
        const d = -2.1 + 0.28 * Math.sin(3 * u + 0.7);
        cv.fade(fadeK, 8);
        let x = 0.12, y = 0.31;
        for (let i = 0; i < N; i++) {
          const nx = Math.sin(a * y) - Math.cos(b * x);
          const ny = Math.sin(c * x) - Math.cos(d * y);
          x = nx; y = ny;
          if (i < 40) continue; // let the orbit settle onto the attractor
          const hue = 0.5 + 0.5 * Math.sin(x * 1.3 + y * 0.9 + u);
          cv.add(cxp + x * sc, cyp + (y * sc) / aspect, dim[(hue * 23.99) | 0]);
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

sources.prism-term/src/facets/fx/fractal-tree.js:
// A recursive blossom tree: ten generations of branches, each a little shorter
// and thinner, swaying more the further they are from the trunk. Blossoms at
// the tips, petals drifting down on the wind.
import { lerpc, hash2 } from '../retro/_kit.js';

const LOOP = 16;

export default {
  title: 'Blossom Tree',
  gallery: 'fx',
  category: 'Fractals',
  kind: 'scene',
  tags: ['tree', 'fractal', 'recursive', 'l-system', 'blossom', 'sakura', 'wind'],
  order: 70,
  description: 'A recursive blossom tree swaying in the wind — ten generations of branches, blooming tips and drifting petals.',
  size: { w: 64, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: LOOP,
  canvas: 'line',
  palette: 'candy',
  params: { depth: { default: 10, min: 5, max: 12, label: 'Generations' } },
  setup(ctx) {
    const cv = ctx.canvas('line');
    const pal = ctx.palette();
    const { theme } = ctx;
    const { width: PW, height: PH, aspect } = cv;
    const depth = Math.max(5, Math.min(12, Math.round(ctx.param('depth', 10))));
    const bark = lerpc(0x6b4a2e, theme.ink, 0.15), twig = lerpc(0x9a7a5a, theme.ink, 0.2);
    const blossom = [pal(0), pal(0.15), lerpc(pal(0), 0xffffff, 0.5)];
    const ground = lerpc(theme.bg, theme.pos, 0.35);
    const len0 = Math.min(PH * 0.3 * aspect, PW * 0.2);
    const petals = Array.from({ length: Math.round(PW * 0.25) }, (_, i) => ({ x: hash2(i, 1), ph: hash2(i, 2), sp: 1 + Math.floor(hash2(i, 3) * 2), c: blossom[i % 3] }));
    return (t) => {
      cv.clear();
      const u = (t / LOOP) * Math.PI * 2;
      const wind = Math.sin(u) * 0.6 + Math.sin(u * 3 + 1) * 0.25;
      // Ground line with a little grass.
      const gy = PH - 1;
      for (let x = 0; x < PW; x++) { cv.set(x, gy, ground); if (hash2(x, 5) < 0.3) cv.set(x, gy - 1, ground); }
      const tips = [];
      const grow = (x, y, ang, len, d, seed) => {
        const sway = wind * 0.035 * (depth - d + 1) * (1 + 0.3 * Math.sin(u * 2 + seed));
        const a = ang + sway;
        const x2 = x + Math.sin(a) * len, y2 = y - (Math.cos(a) * len) / aspect;
        const thick = Math.max(1, Math.round((d / depth) ** 2 * 3.2));
        const c = d > depth * 0.5 ? bark : twig;
        for (let o = 0; o < thick; o++) cv.line(x + o - (thick >> 1), y, x2 + o - (thick >> 1), y2, c);
        if (d <= 1) { tips.push([x2, y2, seed]); return; }
        const spread = 0.42 + 0.08 * Math.sin(seed * 3.1);
        const shrink = 0.72 + 0.06 * hash2(seed, d);
        grow(x2, y2, a - spread, len * shrink, d - 1, seed * 2 + 1);
        grow(x2, y2, a + spread * 0.9, len * (shrink - 0.03), d - 1, seed * 2 + 2);
      };
      grow(PW / 2, gy - 1, 0, len0, depth, 1);
      for (const [x, y, s] of tips) {
        const c = blossom[s % 3];
        cv.set(x, y, c); cv.set(x + 1, y, c); cv.set(x, y - 1, c);
        if (hash2(s, 7) < 0.5) cv.set(x - 1, y + 1, c);
      }
      // Petals: each falls on its own loop, sliding with the wind.
      for (const p of petals) {
        const f = ((t / LOOP) * p.sp + p.ph) % 1;
        const y = PH * 0.15 + f * PH * 0.85;
        const x = (p.x * PW + f * PW * 0.25 + Math.sin(f * 12 + p.ph * 9) * PW * 0.02 + wind * PW * 0.03 * f) % PW;
        cv.set(x, y, p.c);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/god-rays.js:
// Crepuscular rays through a forest: the low sun behind swaying canopy and
// trunks, its light marched pixel by pixel back toward the sun through the
// gaps, so shafts of light fan out through the haze. Dust motes drift in them.
import { lerpc, clamp01, hash2 } from '../retro/_kit.js';

const LOOP = 20, STEPS = 14;

export default {
  title: 'God Rays',
  gallery: 'fx',
  category: 'Light & Sky',
  kind: 'scene',
  tags: ['god rays', 'crepuscular', 'volumetric', 'light shafts', 'forest', 'sun', 'haze'],
  order: 90,
  description: 'Volumetric light: the low sun behind a swaying forest canopy, shafts fanning through the gaps and dust drifting in them.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: LOOP,
  canvas: 'field',
  palette: 'gold',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const occ = new Float32Array(W * H);                      // 1 = blocked, 0 = open sky
    const trunks = Array.from({ length: Math.max(3, Math.round(W / 9)) }, (_, i) => ({ x: (i + 0.3 + hash2(i, 1) * 0.4) * (W / Math.max(3, Math.round(W / 9))), w: 1 + hash2(i, 2) * Math.max(1, W / 40), lean: (hash2(i, 3) - 0.5) * 0.15 }));
    const motes = Array.from({ length: Math.round(W * H * 0.008) }, (_, i) => [hash2(i, 4), hash2(i, 5), hash2(i, 6)]);
    const haze = pal(0.45), dark = lerpc(pal(0.04), 0x000000, 0.4), sunC = pal(0.98);
    const emit = new Float32Array(W * H);
    // The canopy noise is smooth: on big canvases it's computed every other pixel.
    const g = W * H > 9000 ? 2 : 1, GW = Math.ceil(W / g) + 1, GH = Math.ceil(H / g) + 1;
    const leafG = new Float32Array(GW * GH), lightG = new Float32Array(GW * GH);
    return (t) => {
      const u = (t / LOOP) * Math.PI * 2;
      const sunX = W * (0.5 + 0.08 * Math.sin(u)), sunY = H * 0.2;
      for (let gy = 0; gy < GH; gy++) for (let gx = 0; gx < GW; gx++) {
        const x = gx * g, y = gy * g, sway = Math.sin(u + y * 0.1) * 1.5;
        leafG[gy * GW + gx] = fbm((x + sway) * 0.06, y * aspect * 0.06, Math.cos(u) * 0.3 + Math.sin(u) * 0.3, 3);
      }
      // Occluders: a canopy thickest at the top with gaps, trunks, the forest floor.
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        const v = y / H, gx = x / g, gy = y / g, ix = gx | 0, iy = gy | 0, fx = gx - ix, fy = gy - iy, j = iy * GW + ix;
        const leaf = (leafG[j] * (1 - fx) + leafG[j + 1] * fx) * (1 - fy) + (leafG[j + GW] * (1 - fx) + leafG[j + GW + 1] * fx) * fy;
        let o = clamp01((leaf + 0.2 - v * 0.6) * 5);
        if (v > 0.86) o = 1;
        occ[y * W + x] = o;
      }
      for (const tr of trunks) for (let y = Math.floor(H * 0.2); y < H; y++) {
        const cx = tr.x + (y - H) * tr.lean;
        for (let dx = 0; dx < tr.w; dx++) { const x = Math.round(cx + dx); if (x >= 0 && x < W) occ[y * W + x] = 1; }
      }
      // Only open sky near the sun emits; marching toward the sun smears it into shafts.
      for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i++) {
        const d = Math.hypot((x - sunX) / W, ((y - sunY) * aspect) / W);
        emit[i] = (1 - occ[i]) * Math.pow(clamp01(1 - d / 0.55), 2.2);
      }
      // The light march runs on the same lattice — shafts are smooth along their length.
      for (let gy = 0; gy < GH; gy++) for (let gx = 0; gx < GW; gx++) {
        const x = Math.min(W - 1, gx * g), y = Math.min(H - 1, gy * g);
        const dx = (sunX - x) / STEPS, dy = (sunY - y) / STEPS;
        let light = 0, sx = x, sy = y, w = 1;
        for (let s = 0; s < STEPS; s++) {
          const ix = sx | 0, iy = sy | 0;
          if (ix >= 0 && iy >= 0 && ix < W && iy < H) light += emit[iy * W + ix] * w;
          sx += dx; sy += dy; w *= 0.95;
        }
        lightG[gy * GW + gx] = light / 4.7;
      }
      for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i++) {
        const gx = x / g, gy = y / g, ix = gx | 0, iy = gy | 0, fx = gx - ix, fy = gy - iy, j = iy * GW + ix;
        const light = (lightG[j] * (1 - fx) + lightG[j + 1] * fx) * (1 - fy) + (lightG[j + GW] * (1 - fx) + lightG[j + GW + 1] * fx) * fy;
        const d = Math.hypot((x - sunX) / W, ((y - sunY) * aspect) / W);
        const open = 1 - occ[i];
        let c = lerpc(dark, haze, open * 0.4 * (1 - y / H));            // dim far forest air
        c = lerpc(c, haze, clamp01(light * 1.1));                         // the shafts
        c = lerpc(c, sunC, clamp01(light * 1.6 - 0.6));
        c = lerpc(c, sunC, clamp01(1 - d * 11) * open);                   // the sun's disc
        px[i] = c;
      }
      // Dust motes catching the light inside the shafts.
      for (const [mx, my, k] of motes) {
        const x = (mx * W + Math.sin(u + k * 9) * 3 + W) % W, y = ((((my + (t / LOOP) * (k > 0.5 ? 1 : -1)) % 1) + 1) % 1) * H * 0.85;
        const i = Math.floor(y) * W + Math.floor(x);
        cv.blend(x, y, sunC, clamp01((((px[i] >> 8) & 255) - 90) / 120) * 0.7);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/interference.js:
// Ripple-tank interference: three point sources on slow Lissajous orbits, each
// sending out concentric waves. Where crests meet they reinforce, where crest
// meets trough they cancel — the moiré of nodal lines sweeps as sources move.
import { lerpc } from '../retro/_kit.js';

export default {
  title: 'Interference',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['interference', 'waves', 'moire', 'ripple tank', 'physics', 'rings'],
  order: 60,
  description: 'A ripple tank: three orbiting sources whose concentric waves reinforce and cancel into sweeping moiré nodal lines.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: 20,
  canvas: 'field',
  palette: 'ocean',
  params: {
    sources: { default: 3, min: 2, max: 5, label: 'Sources' },
    wavelength: { default: 1, min: 0.4, max: 3, label: 'Wavelength' },
  },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const { width: W, height: H, px, aspect } = cv;
    const n = Math.max(2, Math.min(5, Math.round(ctx.param('sources', 3))));
    const S = Math.min(W, H * aspect);
    const k = (Math.PI * 2) / (Math.max(5, S * 0.17) * ctx.param('wavelength', 1));
    const src = Array.from({ length: n }, (_, i) => ({ a: 1 + (i % 3), b: 2 + ((i + 1) % 2), ph: i * 2.1, r: 0.22 + 0.06 * i }));
    const pos = new Float32Array(n * 2);
    const omega = (Math.PI * 2) / 1.25;   // a crest every 1.25 s
    // Night: crests glow out of shadowed nodal lines. Day: the nodes are the page and
    // the waves are drawn in the palette's ink range (no washed-out whites).
    const day = ctx.theme.mode === 'light';
    const node = day ? ctx.theme.bg : lerpc(ctx.theme.bg, pal(0), 0.5);
    const spot = day ? ctx.theme.accent : 0xffffff;
    return (t) => {
      const u = (t / 20) * Math.PI * 2;
      src.forEach((s, i) => {
        pos[i * 2] = W / 2 + Math.sin(u * s.a + s.ph) * W * s.r * 1.2;
        pos[i * 2 + 1] = (H * aspect) / 2 + Math.cos(u * s.b + s.ph * 0.7) * H * aspect * s.r;
      });
      const wt = omega * t;
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y + 0.5) * aspect;
        for (let x = 0; x < W; x++, i++) {
          let v = 0;
          for (let j = 0; j < n; j++) {
            const dx = x + 0.5 - pos[j * 2], dy = vy - pos[j * 2 + 1];
            const d = Math.sqrt(dx * dx + dy * dy);
            v += Math.sin(d * k - wt) / (1 + d * 0.012);
          }
          v /= n;
          // Amplitude picks the color; near-zero (the nodal lines) falls into shadow.
          const a = Math.abs(v);
          px[i] = lerpc(node, pal(day ? 0.45 + v * 0.3 : 0.5 + v * 0.55), Math.min(1, a * 2.4));
        }
      }
      // Bright dots at the sources themselves.
      for (let j = 0; j < n; j++) cv.set(pos[j * 2], pos[j * 2 + 1] / aspect, spot);
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/kaleidoscope.js:
// A kaleidoscope: a slowly flowing field of interleaved waves and noise, folded
// through mirrored wedges around the center and turning — the classic tube,
// with a soft vignette like the eyepiece.
import { lerpc } from '../retro/_kit.js';

export default {
  title: 'Kaleidoscope',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['kaleidoscope', 'mirror', 'symmetry', 'mandala', 'psychedelic', 'polar'],
  order: 90,
  description: 'A turning kaleidoscope: a flowing field folded through mirrored wedges into a mandala, with an eyepiece vignette.',
  size: { w: 72, h: 24 },
  minSize: { w: 16, h: 6 },
  loop: 24,
  canvas: 'field',
  palette: 'prism',
  params: { segments: { default: 6, min: 3, max: 12, label: 'Mirrors' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const { noise3 } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const seg = Math.max(3, Math.min(12, Math.round(ctx.param('segments', 6))));
    const wedge = Math.PI / seg;
    const R = Math.min(W, H * aspect) / 2;
    const bg = ctx.theme.bg;
    return (t) => {
      const u = (t / 24) * Math.PI * 2;
      const rot = u, flow = Math.sin(u) * 0.8;
      for (let y = 0, i = 0; y < H; y++) {
        const dy = ((y + 0.5) * aspect - (H * aspect) / 2) / R;
        for (let x = 0; x < W; x++, i++) {
          const dx = (x + 0.5 - W / 2) / R;
          const r = Math.sqrt(dx * dx + dy * dy);
          if (r > 1.11) { px[i] = bg; continue; }
          // Fold the angle into one mirrored wedge.
          let a = Math.atan2(dy, dx) + rot;
          a = ((a % (2 * wedge)) + 2 * wedge) % (2 * wedge);
          if (a > wedge) a = 2 * wedge - a;
          const fx = Math.cos(a) * r * 2.2, fy = Math.sin(a) * r * 2.2;
          const n = noise3(fx * 1.3 + flow, fy * 1.3, Math.cos(u) * 0.6 + 2) * 1.4;
          const v = Math.sin(fx * 3.1 + Math.sin(fy * 4.2 + u) + n * 2) + Math.sin(fy * 5.3 - u * 2 + n);
          const band = (v * 0.25 + r * 0.4 - t / 24 + 10) % 1;
          const light = 0.55 + 0.45 * Math.cos(v * 2.4);
          let c = lerpc(bg, pal(band), light);
          if (r > 0.86) c = lerpc(c, bg, Math.min(1, (r - 0.86) * 4));
          px[i] = c;
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/lava-lamp.js:
// Lava lamps on a shelf: wax blobs warm at the bulb, rise, cool, stretch and
// sink again — metaballs inside a tapered glass, lit from below, with the
// metal cap and base. One lamp when narrow, a row of three when there's room.
import { lerpc, clamp01 } from '../retro/_kit.js';

const LOOP = 30;

export default {
  title: 'Lava Lamp',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['lava lamp', 'metaballs', 'wax', 'blobs', 'retro', '1970s', 'groovy'],
  order: 80,
  description: 'Lava lamps on a shelf: metaball wax warms at the bulb, rises, stretches and sinks inside tapered glass lit from below.',
  size: { w: 64, h: 24 },
  minSize: { w: 16, h: 8 },
  loop: LOOP,
  canvas: 'field',
  palette: 'magma',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const rand = ctx.rng;
    const { theme } = ctx;
    const { width: W, height: H, px, aspect } = cv;
    const count = W / (H * aspect) > 1.05 ? 3 : 1;
    const lamps = Array.from({ length: count }, (_, i) => {
      const cx = W * ((i + 0.5) / count);
      const half = Math.min((W / count) * 0.34, H * aspect * 0.15);
      const hue = count === 1 ? 0 : [0.08, 0, 0.16][i];
      return {
        cx, half, hue,
        top: H * 0.05, cap: H * 0.17, bot: H * 0.8, base: H * 0.97,
        blobs: Array.from({ length: 5 }, (_, j) => ({ ph: rand(), sp: 1 + (j % 3), sw: rand() * 6.28, r: 0.26 + rand() * 0.2 })),
      };
    });
    const wall = lerpc(theme.bg, theme.panel, 0.6);
    const metal = [0x3a3a46, 0x8a8a9e, 0xd8d8e8];
    // Glass radius at height v (0 = top of glass, 1 = bottom): a tall tapered rocket shape.
    const radius = (v) => (0.5 + 0.5 * v) * Math.sqrt(Math.min(1, v * 12, (1 - v) * 14 + 0.3));
    return (t) => {
      // Back wall with a warm pool of light behind each lamp.
      for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i++) px[i] = wall;
      for (const L of lamps) {
        const liquid = pal(0.18 + L.hue), waxLo = pal(0.62 + L.hue), waxHi = pal(0.9 + L.hue * 0.5);
        for (let y = 0; y < H; y++) for (let x = Math.max(0, Math.floor(L.cx - L.half * 3.2)); x < Math.min(W, L.cx + L.half * 3.2); x++) {
          const dx = (x + 0.5 - L.cx) / (L.half * 3.2), dy = (y - L.bot) / H;
          px[y * W + x] = lerpc(px[y * W + x], waxLo, clamp01(0.22 - (dx * dx + dy * dy) * 0.3));
        }
        // Blob centers: each rides a slow heat cycle, rising from the bulb and sinking back.
        const bl = L.blobs.map((b) => {
          const ph = ((t / LOOP) * b.sp + b.ph) % 1;
          const rise = 0.5 - 0.5 * Math.cos(ph * Math.PI * 2);
          return { x: Math.sin(((t * Math.PI * 2) / LOOP) * b.sp + b.sw) * 0.35, y: 0.93 - rise * 0.86, r: b.r * (0.75 + 0.35 * Math.sin(ph * Math.PI * 4 + b.sw)) };
        });
        const gh = L.bot - L.cap;
        for (let y = Math.floor(L.cap); y < Math.ceil(L.bot); y++) {
          const v = (y + 0.5 - L.cap) / gh, rw = L.half * radius(v);
          for (let x = Math.max(0, Math.floor(L.cx - rw)); x < Math.min(W, Math.ceil(L.cx + rw)); x++) {
            const lx = (x + 0.5 - L.cx) / L.half, ux = (x + 0.5 - L.cx) / rw;
            let f = 0;
            for (const b of bl) {
              const dx = lx - b.x, dy = ((v - b.y) * gh * aspect) / L.half;
              f += (b.r * b.r) / (dx * dx + dy * dy + 0.02);
            }
            f += Math.max(0, (v - 0.93) * 14) * 1.2;           // the molten pool on the bottom
            const glow = clamp01(v * 0.6 + 0.1);               // lit from the bulb below
            let c = lerpc(liquid, waxLo, glow * 0.25);
            if (f > 1) {
              const core = clamp01((f - 1) * 0.6);
              c = lerpc(waxLo, waxHi, core * (0.55 + 0.45 * glow));
            } else if (f > 0.8) c = lerpc(c, waxLo, (f - 0.8) / 0.2 * 0.6);
            // Glass: a highlight down the left, darkening at the rim.
            const rim = Math.abs(ux);
            if (rim > 0.82) c = lerpc(c, 0x000000, (rim - 0.82) * 2.2);
            if (ux > -0.62 && ux < -0.48) c = lerpc(c, 0xffffff, 0.22);
            px[y * W + x] = c;
          }
        }
        // Cap and base: brushed metal cones.
        const metalAt = (u) => (u < -0.3 ? lerpc(metal[0], metal[1], (u + 1) / 0.7) : u < 0.25 ? lerpc(metal[1], metal[2], (u + 0.3) / 0.55) : lerpc(metal[2], metal[0], (u - 0.25) / 0.75));
        for (let y = Math.floor(L.top); y < Math.ceil(L.cap); y++) {
          const k = (y - L.top) / (L.cap - L.top), rw = L.half * (0.3 + 0.13 * k);
          for (let x = Math.floor(L.cx - rw); x < L.cx + rw; x++) if (x >= 0 && x < W) px[y * W + x] = metalAt((x + 0.5 - L.cx) / rw);
        }
        for (let y = Math.floor(L.bot); y < Math.min(H, Math.ceil(L.base)); y++) {
          const k = (y - L.bot) / (L.base - L.bot), rw = L.half * (0.5 + 0.55 * Math.sin(k * Math.PI * 0.6 + 0.35));
          for (let x = Math.floor(L.cx - rw); x < L.cx + rw; x++) if (x >= 0 && x < W) px[y * W + x] = metalAt((x + 0.5 - L.cx) / rw);
        }
      }
      // The shelf.
      for (let y = Math.floor(H * 0.97); y < H; y++) px.fill(lerpc(theme.panel, 0x000000, 0.3), y * W, (y + 1) * W);
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/lightning.js:
// A thunderstorm over the hills: rolling cloud decks, slanting rain, and every
// few seconds a forked bolt built by midpoint displacement — it flickers two or
// three times, lighting the clouds from inside and the land beneath.
import { lerpc, clamp01, hash2 } from '../retro/_kit.js';

const LOOP = 24, EVERY = 3;

function bolt(k, W, top, bottom) {
  // Midpoint displacement from cloud base to ground, plus a few forks.
  let seed = 0;
  const r = () => hash2(k, seed++, 77);
  const x0 = W * (0.15 + r() * 0.7);
  let pts = [[x0, top], [x0 + (r() - 0.5) * W * 0.25, bottom]];
  for (let pass = 0; pass < 6; pass++) {
    const out = [pts[0]];
    for (let i = 1; i < pts.length; i++) {
      const [ax, ay] = pts[i - 1], [bx, by] = pts[i];
      const len = Math.hypot(bx - ax, by - ay);
      out.push([(ax + bx) / 2 + (r() - 0.5) * len * 0.55, (ay + by) / 2 + (r() - 0.5) * len * 0.1], pts[i]);
    }
    pts = out;
  }
  const forks = [];
  for (let f = 0; f < 3; f++) {
    const start = pts[Math.floor((0.15 + r() * 0.5) * pts.length)];
    let [x, y] = start;
    const dir = r() < 0.5 ? -1 : 1, seg = [];
    seg.push([x, y]);
    for (let i = 0; i < 10; i++) { x += dir * (0.6 + r() * 2.2); y += 0.8 + r() * 2.4; seg.push([x, y]); }
    forks.push(seg);
  }
  return { main: pts, forks, x: x0 };
}

export default {
  title: 'Thunderstorm',
  gallery: 'fx',
  category: 'Light & Sky',
  kind: 'scene',
  tags: ['lightning', 'storm', 'thunder', 'rain', 'clouds', 'weather', 'bolt'],
  order: 70,
  description: 'A thunderstorm: rolling clouds, slanting rain and forked bolts that flicker, lighting the clouds from inside.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: LOOP,
  canvas: 'field',
  palette: 'ice',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const base = Math.floor(H * 0.42), ground = H * 0.82;
    // Cloud deck, tiled horizontally so it can roll forever.
    const cloud = new Float32Array(W * H);
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      const k = x / W, f = (xx) => fbm(xx * 0.035, y * aspect * 0.06, 1.7, 5);
      cloud[y * W + x] = (f(x) * (1 - k) + f(x - W) * k) * 0.5 + 0.5;
    }
    const hills = new Float32Array(W);
    for (let x = 0; x < W; x++) hills[x] = ground + (Math.sin(x * 0.07 + 1) * 0.5 + Math.sin(x * 0.19) * 0.25) * H * 0.05;
    const drops = Array.from({ length: Math.round(W * H * 0.012) }, (_, i) => [hash2(i, 1), hash2(i, 2), 1 + Math.floor(hash2(i, 3) * 2)]);
    const skyDark = lerpc(pal(0.1), 0x000000, 0.2), cloudLit = pal(0.85), cloudDim = pal(0.34), boltC = 0xf4f8ff, glowC = pal(0.7);
    const land = lerpc(0x0a0f0a, pal(0.1), 0.3);
    let cacheK = -1, cache = null;
    return (t) => {
      const lt = t % LOOP;
      const k = Math.floor(lt / EVERY), at = k * EVERY + hash2(k, 5) * 0.8, age = lt - at;
      // Flash envelope: two or three quick pulses.
      let flash = 0;
      if (age >= 0 && age < 0.6) {
        const pulses = 2 + Math.floor(hash2(k, 6) * 2);
        for (let p = 0; p < pulses; p++) { const pt = p * 0.13, d = age - pt; if (d >= 0 && d < 0.09) flash = Math.max(flash, 1 - d / 0.09); }
        flash = Math.max(flash, Math.max(0, 0.25 - age * 0.4));
      }
      if (k !== cacheK) { cacheK = k; cache = bolt(k, W, base * 0.9, ground); }
      const roll = (lt / LOOP) * W;
      for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i++) {
        const cv0 = cloud[y * W + (Math.floor(x + roll) % W)];
        const depth = clamp01(1 - y / (base * 1.4));
        let c = lerpc(skyDark, cloudDim, clamp01((cv0 - 0.3) * 2.4) * (0.55 + depth * 0.45));
        if (flash > 0) {
          const near = Math.exp(-Math.pow((x - cache.x) / (W * 0.25), 2));
          c = lerpc(c, cloudLit, flash * clamp01(cv0 * 1.3 - 0.2) * (0.25 + 0.75 * near) * (0.4 + 0.6 * clamp01(1.6 - y / base)));
        }
        if (y >= hills[x]) c = lerpc(land, pal(0.5), flash * 0.25);
        px[i] = c;
      }
      // Rain: short slanting streaks, brighter during a flash.
      const rainC = lerpc(cloudDim, cloudLit, 0.25 + flash * 0.5);
      for (const [rx, ry, sp] of drops) {
        const y = ((ry + (lt / LOOP) * 12 * sp) % 1) * H, x = (rx * W + y * 0.35) % W;
        for (let j = 0; j < 2; j++) cv.blend(x - j * 0.35, y - j, rainC, 0.6);
      }
      // The bolt.
      if (age >= 0 && age < 0.55 && flash > 0.05) {
        const draw = (pts, c, w) => { for (let i = 1; i < pts.length; i++) { cv.line(pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1], c); if (w) cv.line(pts[i - 1][0] + 1, pts[i - 1][1], pts[i][0] + 1, pts[i][1], lerpc(glowC, c, 0.4)); } };
        for (const f of cache.forks) draw(f, lerpc(glowC, boltC, flash * 0.7), false);
        draw(cache.main, lerpc(glowC, boltC, 0.5 + flash * 0.5), true);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/mandelbrot.js:
// Endless Mandelbrot dive into Seahorse Valley with smooth (normalized
// iteration count) coloring. The zoom breathes in and out on a log scale, and
// the iteration cap adapts to the work done last frame so cost stays bounded.
// `--set set=julia` swaps in an animated Julia set.
export default {
  title: 'Mandelbrot Dive',
  gallery: 'fx',
  category: 'Fractals',
  kind: 'scene',
  tags: ['mandelbrot', 'julia', 'fractal', 'zoom'],
  order: 40,
  description: 'Continuous zoom into Seahorse Valley with smooth iteration coloring; --set set=julia for a morphing Julia set.',
  canvas: 'field',
  palette: 'magma',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 1024 });
    const julia = ctx.param('set', 'mandelbrot') === 'julia';
    const period = ctx.param('period', 36);
    const { width: W, height: H, px, aspect } = cv;
    const FX = -0.743643887037151, FY = 0.13182590420533;
    const maxLog = Math.log(julia ? 6 : 3e4);
    const budget = 3.6e6; // iterations per frame (~6 ms)
    const inside = ctx.theme.bg;
    let cap = 220;

    return (t) => {
      const phase = (t % period) / period;
      const zoom = Math.exp(maxLog * (1 - Math.cos(phase * Math.PI * 2)) / 2);
      const want = Math.min(900, Math.floor(90 + 110 * Math.log10(zoom)));
      const maxIt = Math.max(24, Math.min(want, cap));
      const unit = (julia ? 3.1 : 3.0) / (Math.min(W, H * aspect) * zoom);
      const rot = julia ? 0 : phase * Math.PI * 2;
      const cr = Math.cos(rot), sr = Math.sin(rot);
      // Julia c walks the main cardioid's boundary (c = e^iθ/2 − e^2iθ/4), where the
      // sets are connected and most intricate.
      const jt = t * 0.12 + 1.2;
      const jr = 0.5 * Math.cos(jt) - 0.25 * Math.cos(2 * jt), ji = 0.5 * Math.sin(jt) - 0.25 * Math.sin(2 * jt);
      const cx0 = julia ? 0 : FX, cy0 = julia ? 0 : FY;
      const shift = t * 0.015;
      let work = 0;

      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y - H / 2 + 0.5) * aspect * unit;
        for (let x = 0; x < W; x++, i++) {
          const vx = (x - W / 2 + 0.5) * unit;
          const ox = cx0 + vx * cr - vy * sr, oy = cy0 + vx * sr + vy * cr;
          let zr, zi, ar, ai;
          if (julia) { zr = ox; zi = oy; ar = jr; ai = ji; }
          else {
            zr = 0; zi = 0; ar = ox; ai = oy;
            // Skip the main cardioid and period-2 bulb outright.
            const q = (ox - 0.25) * (ox - 0.25) + oy * oy;
            if (q * (q + (ox - 0.25)) <= 0.25 * oy * oy || (ox + 1) * (ox + 1) + oy * oy <= 0.0625) { px[i] = inside; continue; }
          }
          let n = 0, r2 = 0, i2 = 0;
          while (n < maxIt) {
            r2 = zr * zr; i2 = zi * zi;
            if (r2 + i2 > 256) break;
            zi = 2 * zr * zi + ai;
            zr = r2 - i2 + ar;
            n++;
          }
          work += n;
          if (n >= maxIt) { px[i] = inside; continue; }
          const mu = n + 1 - Math.log(Math.log(r2 + i2) * 0.5) / Math.LN2;
          const s = Math.log2(Math.max(1, mu) + 1) * 0.3 + shift;
          px[i] = pal(1 - Math.abs(((s % 2) + 2) % 2 - 1));
        }
      }
      // Steer next frame's cap toward the budget (deterministic: depends only on content).
      if (work > budget) cap = Math.max(24, Math.floor(cap * 0.85));
      else if (work < budget * 0.6) cap = Math.min(900, Math.ceil(cap * 1.08) + 1);
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/matrix.js:
// Digital rain with real glyphs: halfwidth katakana, digits and symbols fall
// in per-column streams. Every lit cell decays at its stream's own rate, so
// trail lengths vary; heads burn white, glyphs mutate as they fade, and dimmer
// slow columns read as a second, more distant layer.
const KATAKANA = Array.from({ length: 0xff9d - 0xff66 + 1 }, (_, i) => String.fromCodePoint(0xff66 + i));
const UNICODE_GLYPHS = [...KATAKANA, ...'0123456789', ...'=+-*<>:."|¦_'];
const ASCII_GLYPHS = [...'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%&*+=-<>?'];

export default {
  title: 'Digital Rain',
  gallery: 'fx',
  category: 'Glitch & Noise',
  kind: 'scene',
  tags: ['matrix', 'digital rain', 'katakana', 'hacker'],
  order: 20,
  description: 'Matrix digital rain in real halfwidth katakana — white-hot heads, per-column speeds and trail lengths, mutating glyphs.',
  canvas: 'ascii',
  palette: 'matrix',
  setup(ctx) {
    const W = ctx.width, H = ctx.height;
    const rand = ctx.rng;
    const pal = ctx.palette();
    const speedK = ctx.param('speed', 1);
    const glyphs = ctx.caps.unicode === false || ctx.mode === 'ascii' ? ASCII_GLYPHS : UNICODE_GLYPHS;
    const pick = () => glyphs[Math.floor(rand() * glyphs.length)];
    const N = W * H;
    const I = new Float32Array(N); // intensity 0..1
    const R = new Float32Array(N); // decay rate (1/s) of the stream that last lit the cell
    const G = new Array(N);
    for (let i = 0; i < N; i++) G[i] = pick();
    const head = new Uint8Array(N);
    // Column depth: a dim, slow back layer and a bright, fast front layer.
    const depth = new Float32Array(W);
    for (let x = 0; x < W; x++) depth[x] = rand() < 0.35 ? 0.35 + rand() * 0.25 : 0.75 + rand() * 0.25;

    const D = W + Math.ceil(W * 0.4 * Math.min(1, H / 30));
    const dc = new Int32Array(D), dy = new Float32Array(D), dv = new Float32Array(D), dl = new Float32Array(D);
    const respawn = (d, initial) => {
      dc[d] = d < W ? d : Math.floor(rand() * W);
      const z = depth[dc[d]];
      dv[d] = (5 + rand() * 18) * (0.45 + z * 0.75);
      dl[d] = 5 + rand() * Math.max(6, H * 0.9);
      dy[d] = initial ? rand() * H * 1.4 - H * 0.4 : -rand() * H * 0.6;
    };
    for (let d = 0; d < D; d++) respawn(d, true);

    let mutateAcc = 0;
    return (t, dt) => {
      // Decay every lit cell at its stream's rate.
      for (let i = 0; i < N; i++) {
        head[i] = 0;
        if (I[i] > 0) { I[i] *= Math.exp(-R[i] * dt); if (I[i] < 0.02) I[i] = 0; }
      }
      // Advance drops, lighting every cell the head passed this frame.
      for (let d = 0; d < D; d++) {
        const x = dc[d], v = dv[d] * speedK;
        const y0 = Math.floor(dy[d]);
        dy[d] += v * dt;
        const y1 = Math.floor(dy[d]);
        const rate = (Math.log(40) * v) / dl[d];
        for (let y = Math.max(0, y0); y <= Math.min(H - 1, y1); y++) {
          const i = y * W + x;
          I[i] = 1; R[i] = rate;
          if (y !== y0) G[i] = pick();
        }
        if (y1 >= 0 && y1 < H) head[y1 * W + x] = 1;
        if (dy[d] - dl[d] > H) respawn(d, false);
      }
      // Glyph mutation: a few percent of lit cells flicker to new symbols per second.
      mutateAcc += N * 0.05 * dt;
      while (mutateAcc >= 1) { mutateAcc--; const i = Math.floor(rand() * N); if (I[i] > 0) G[i] = pick(); }

      const buf = ctx.buffer;
      for (let y = 0, i = 0; y < H; y++) {
        for (let x = 0; x < W; x++, i++) {
          const v = I[i];
          if (v <= 0) continue;
          if (head[i]) buf.set(x, y, G[i], pal(1), undefined, depth[x] > 0.7 ? 1 : 0);
          else buf.set(x, y, G[i], pal(0.12 + 0.82 * Math.pow(v, 0.65) * depth[x]));
        }
      }
    };
  },
};

sources.prism-term/src/facets/fx/metaballs.js:
// Metaballs: an inverse-square field from orbiting blobs. Color is the
// field-weighted blend of each ball's palette hue, so merging blobs mix
// smoothly; the iso-surface gets a hot rim and the outside a soft halo.
export default {
  title: 'Metaballs',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['metaballs', 'blobs', 'isosurface', 'glow'],
  order: 50,
  description: 'Orbiting metaballs that merge with blended hues, a glowing iso-contour rim and soft halo.',
  canvas: 'field',
  palette: 'candy',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const rand = ctx.rng;
    const count = Math.max(2, Math.min(12, ctx.param('count', 6)));
    const { width: W, height: H, px, aspect } = cv;
    const S = Math.min(W, H * aspect);
    const balls = Array.from({ length: count }, (_, i) => {
      const c = pal(i / count);
      return {
        r: S * (0.1 + rand() * 0.06),
        ax: 0.25 + rand() * 0.2, ay: 0.22 + rand() * 0.18,
        fx: 0.3 + rand() * 0.5, fy: 0.25 + rand() * 0.5, p: rand() * 6.28,
        cr: (c >> 16) & 255, cg: (c >> 8) & 255, cb: c & 255,
        x: 0, y: 0, r2: 0,
      };
    });
    const bg = ctx.theme.bg;
    const bR = (bg >> 16) & 255, bG = (bg >> 8) & 255, bB = bg & 255;

    return (t) => {
      for (const b of balls) {
        b.x = W / 2 + Math.sin(t * b.fx + b.p) * W * b.ax * 0.95;
        b.y = (H * aspect) / 2 + Math.cos(t * b.fy + b.p * 1.3) * H * aspect * b.ay * 0.95;
        const pulse = 1 + 0.12 * Math.sin(t * 1.7 + b.p);
        b.r2 = b.r * b.r * pulse * pulse;
      }
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y + 0.5) * aspect;
        for (let x = 0; x < W; x++, i++) {
          let f = 0, r = 0, g = 0, bl = 0;
          for (let k = 0; k < count; k++) {
            const b = balls[k];
            const dx = x + 0.5 - b.x, dy = vy - b.y;
            const w = b.r2 / (dx * dx + dy * dy + 1);
            f += w; r += b.cr * w; g += b.cg * w; bl += b.cb * w;
          }
          r /= f; g /= f; bl /= f;
          let k, wh;
          if (f >= 1) {
            const e = Math.min(1, (f - 1) * 3);       // 0 at the rim → 1 deep inside
            const rim = Math.exp(-(f - 1) * (f - 1) * 90);
            k = 0.55 + 0.45 * e;
            wh = rim * 0.7;
          } else {
            const halo = f * f * f;
            k = halo * 0.55;
            wh = Math.exp(-(f - 1) * (f - 1) * 260) * 0.35;
          }
          const rr = bR * (1 - Math.min(1, k)) + r * k + (255 - r) * wh;
          const gg = bG * (1 - Math.min(1, k)) + g * k + (255 - g) * wh;
          const bb = bB * (1 - Math.min(1, k)) + bl * k + (255 - bl) * wh;
          px[i] = ((rr > 255 ? 255 : rr) << 16) | ((gg > 255 ? 255 : gg) << 8) | (bb > 255 ? 255 : bb | 0);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

