// Deep field: a domain-warped emission nebula with dark dust lanes, painted
// once into a texture larger than the screen, then slowly turned and breathed
// through. Twinkling stars in front, a few bright ones with diffraction spikes.
import { lerpc, clamp01, hash2 } from '../retro/_kit.js';

const LOOP = 40;

export default {
  title: 'Nebula',
  gallery: 'fx',
  category: 'Light & Sky',
  kind: 'scene',
  tags: ['nebula', 'space', 'stars', 'cosmos', 'galaxy', 'deep field', 'ambient'],
  order: 80,
  description: 'A domain-warped emission nebula with dust lanes, slowly turning, with twinkling stars and diffraction spikes.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: LOOP,
  canvas: 'field',
  palette: 'magma',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const VH = H * aspect;
    // Texture in visual units: a square that covers the screen at any rotation.
    // It's smooth, so it's painted at most 200 texels across and sampled bilinearly.
    const T = Math.ceil(Math.hypot(W, VH) * 1.15), S = Math.min(W, VH);
    const N = Math.min(T, 200), q = T / N;
    const R = new Float32Array(N * N), G = new Float32Array(N * N), B = new Float32Array(N * N);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
      const u = ((x * q) / S) * 1.6, v = ((y * q) / S) * 1.6;
      const wx = fbm(u + 3.1, v + 1.7, 0.5, 4), wy = fbm(u - 2.3, v + 4.4, 1.5, 4);
      const gas = fbm(u + wx * 1.4, v + wy * 1.4, 2.5, 5) * 0.5 + 0.5;
      const dust = clamp01(fbm(u * 2.2 + wy, v * 2.2 - wx, 7.5, 4) * 1.8 + 0.1);
      const glow = Math.pow(clamp01(gas * 1.25 - 0.18), 1.6);
      const c = pal(clamp01(glow * 0.95 + 0.04));
      const o = lerpc(c, 0x000000, clamp01(dust * 0.85) * clamp01(glow * 2)), j = y * N + x;
      R[j] = (o >> 16) & 255; G[j] = (o >> 8) & 255; B[j] = o & 255;
    }
    const sample = (tx, ty) => {
      const fx = Math.min(N - 1.001, Math.max(0, tx / q)), fy = Math.min(N - 1.001, Math.max(0, ty / q));
      const ix = fx | 0, iy = fy | 0, ax = fx - ix, ay = fy - iy, j = iy * N + ix;
      const w00 = (1 - ax) * (1 - ay), w10 = ax * (1 - ay), w01 = (1 - ax) * ay, w11 = ax * ay;
      const r = R[j] * w00 + R[j + 1] * w10 + R[j + N] * w01 + R[j + N + 1] * w11;
      const g = G[j] * w00 + G[j + 1] * w10 + G[j + N] * w01 + G[j + N + 1] * w11;
      const b = B[j] * w00 + B[j + 1] * w10 + B[j + N] * w01 + B[j + N + 1] * w11;
      return (r << 16) | (g << 8) | b;
    };
    const stars = Array.from({ length: Math.round(W * H * 0.02) }, (_, i) => [hash2(i, 1), hash2(i, 2), hash2(i, 3)]);
    const bright = Array.from({ length: Math.max(2, Math.round((W * H) / 900)) }, (_, i) => [hash2(i, 11) * W, hash2(i, 12) * H, hash2(i, 13)]);
    return (t) => {
      const u = (t / LOOP) * Math.PI * 2;
      const rot = Math.sin(u) * 0.12, zoom = 1 + 0.06 * Math.sin(u * 2 + 1);
      const cr = Math.cos(rot) / zoom, sr = Math.sin(rot) / zoom;
      const ox = T / 2 + Math.cos(u) * S * 0.04, oy = T / 2 + Math.sin(u) * S * 0.03;
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y + 0.5) * aspect - VH / 2;
        for (let x = 0; x < W; x++, i++) {
          const vx = x + 0.5 - W / 2;
          px[i] = sample(ox + vx * cr - vy * sr, oy + vx * sr + vy * cr);
        }
      }
      for (const [sx, sy, k] of stars) {
        const tw = 0.55 + 0.45 * Math.sin((t * Math.PI * 2 * (1 + Math.floor(k * 4))) / 8 + k * 50);
        cv.add(sx * W, sy * H, lerpc(0x000000, k > 0.7 ? 0xbfd8ff : 0xfff0d8, tw * (0.35 + k * 0.6)));
      }
      for (const [bx, by, k] of bright) {
        const tw = 0.75 + 0.25 * Math.sin((t * Math.PI * 2) / 4 + k * 20);
        const c = lerpc(0x000000, 0xffffff, tw), arm = Math.max(2, Math.round(Math.min(W, H) * 0.05));
        cv.set(bx, by, 0xffffff);
        for (let d = 1; d <= arm; d++) {
          const a = tw * (1 - d / (arm + 1));
          cv.blend(bx + d, by, c, a); cv.blend(bx - d, by, c, a);
          cv.blend(bx, by + d / aspect, c, a); cv.blend(bx, by - d / aspect, c, a);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

// Newton's method as art: every point is a guess that slides toward one of a
// polynomial's roots. Color says which root it reaches, shade says how fast.
// The roots orbit and breathe, so the fractal basin boundaries writhe.
import { lerpc } from '../retro/_kit.js';

export default {
  title: 'Newton Basins',
  gallery: 'fx',
  category: 'Fractals',
  kind: 'scene',
  tags: ['newton', 'fractal', 'basins', 'roots', 'complex', 'polynomial'],
  order: 60,
  description: "Newton's method basins for a polynomial whose roots orbit and breathe — color by root, shade by speed.",
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: 24,
  canvas: 'field',
  palette: 'prism',
  params: { roots: { default: 3, min: 3, max: 6, label: 'Roots' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { width: W, height: H, px, aspect } = cv;
    const n = Math.max(3, Math.min(6, Math.round(ctx.param('roots', 3))));
    const colors = Array.from({ length: n }, (_, k) => pal(k / n));
    const dark = lerpc(ctx.theme.bg, 0x000000, 0.4);
    const rr = new Float64Array(n), ri = new Float64Array(n);
    const MAX = 28;
    return (t) => {
      const u = (t / 24) * Math.PI * 2;
      for (let k = 0; k < n; k++) {
        const a = (k / n) * Math.PI * 2 + u * 0.5, m = 1 + 0.28 * Math.sin(u * (k % 2 ? 1 : 2) + k);
        rr[k] = Math.cos(a) * m; ri[k] = Math.sin(a) * m;
      }
      const unit = 3.4 / Math.min(W, H * aspect * 1.4);
      for (let y = 0, i = 0; y < H; y++) {
        const y0 = (y - H / 2 + 0.5) * aspect * unit;
        for (let x = 0; x < W; x++, i++) {
          let zr = (x - W / 2 + 0.5) * unit, zi = y0, it = 0, hit = -1, near = 1;
          for (; it < MAX; it++) {
            // z ← z − 1 / Σ 1/(z − r_k)
            let sr = 0, si = 0;
            for (let k = 0; k < n; k++) {
              const dr = zr - rr[k], di = zi - ri[k], d = dr * dr + di * di;
              if (d < 1e-6) { hit = k; near = d; break; }
              sr += dr / d; si -= di / d;
            }
            if (hit >= 0) break;
            const s2 = sr * sr + si * si;
            if (s2 < 1e-12) break;
            zr -= sr / s2; zi += si / s2;
          }
          if (hit < 0) { px[i] = dark; continue; }
          // Smooth the iteration count with the last step's distance.
          const f = (it + Math.log(-Math.log(near + 1e-12) + 1) * 0.1) / MAX;
          px[i] = lerpc(colors[hit], dark, Math.min(0.92, Math.pow(f, 0.55) * 1.05));
        }
      }
      // Root markers.
      for (let k = 0; k < n; k++) cv.set(W / 2 + rr[k] / unit, H / 2 + ri[k] / unit / aspect, 0xffffff);
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/night-sky.js:
// Light & Sky — the night shift: a radiant meteor shower, searchlights
// sweeping a cloud deck over a skyline, and cloud banks drifting across a
// full moon. Everything is scheduled inside the loop so the cycle closes.
import { clamp01, hash2 } from '../retro/_kit.js';

const SPEED = { speed: { default: 1, min: 0.1, max: 4, label: 'Speed' } };
const TAU = Math.PI * 2;
const pack = (r, g, b) =>
  ((r > 255 ? 255 : r) << 16) | ((g > 255 ? 255 : g) << 8) | ((b > 255 ? 255 : b) | 0);

export default [
  {
    id: 'fx-meteor-shower',
    since: '0.3.0',
    title: 'Meteor Shower',
    category: 'Light & Sky',
    kind: 'scene',
    tags: ['meteor', 'shooting star', 'radiant', 'bolide', 'night sky', 'stars', 'astronomy'],
    order: 230,
    description: 'A radiant-point meteor shower over a dark ridge: streaks fan out across twinkling stars and one bolide flares, leaving a drifting train.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 18,
    canvas: 'field',
    palette: 'ice',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const rand = ctx.rng;
      const { fbm } = ctx.noise;
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const Hu = H * aspect;
      const rowCol = new Int32Array(H);
      for (let y = 0; y < H; y++) {
        const v = y / H;
        rowCol[y] = pack(3 + 9 * v, 5 + 12 * v, 14 + 28 * v);
      }
      const ridge = new Float32Array(W);
      for (let x = 0; x < W; x++) {
        ridge[x] = Math.max(2, Math.min(H - 1, H * (0.84 + fbm(x * 0.045, 7.7, 0, 2) * 0.09)));
      }
      const stars = Array.from({ length: Math.max(16, Math.round(W * H * 0.035)) }, () => ({
        x: Math.floor(rand() * W), y: Math.floor(rand() * H * 0.8),
        s: 0.35 + rand() * 0.65, p: rand() * TAU, f: (6 + Math.floor(rand() * 4) * 6) * (TAU / 18),
      }));
      const radX = W * 0.6, radY = Hu * 0.24;
      const mets = Array.from({ length: 14 }, (_, i) => {
        const a = rand() * TAU;
        return {
          s0: rand() * 18, dur: 0.45 + rand() * 0.75,
          dx: Math.cos(a), dy: Math.sin(a),
          v: (0.55 + rand() * 0.75) * Math.max(W, Hu) * 0.9,
          r0: 3 + rand() * 9, big: i === 0,
        };
      });
      mets[0].dur = 1.7; mets[0].v *= 0.7; mets[0].s0 = 11.2; mets[0].dy = Math.abs(mets[0].dy) * 0.7 + 0.2;
      mets[0].dx = -Math.abs(mets[0].dx) - 0.3;
      const n0 = Math.hypot(mets[0].dx, mets[0].dy); mets[0].dx /= n0; mets[0].dy /= n0;
      return (t) => {
        const tt = t * speed;
        const tl = (((tt / 18) % 1 + 1) % 1) * 18;
        for (let y = 0; y < H; y++) px.fill(rowCol[y], y * W, y * W + W);
        for (const s of stars) {
          const tw = s.s * (0.5 + 0.5 * Math.sin(tt * s.f + s.p));
          if (tw > 0.06) cv.add(s.x, s.y, pack(tw * 170, tw * 180, tw * 215));
        }
        for (const m of mets) {
          let d0 = tl - m.s0; if (d0 < 0) d0 += 18;
          if (d0 > m.dur) {
            if (m.big && d0 < m.dur + 2.4) {
              const q = (d0 - m.dur) / 2.4;
              const head = m.r0 + m.v * m.dur;
              for (let k = 0; k < 14; k++) {
                const qq = k / 14;
                const dd = head - qq * 22;
                const ux = radX + m.dx * dd + Math.sin(qq * 9 + tt * (TAU / 18) * 3) * q * 3;
                const uy = radY + m.dy * dd + q * 2;
                const I = (1 - q) * (1 - qq) * 0.6;
                cv.add(Math.round(ux), Math.round(uy / aspect), pack(90 * I, 230 * I, 160 * I));
              }
            }
            continue;
          }
          const env = Math.sin(Math.PI * Math.min(1, d0 / m.dur));
          const head = m.r0 + m.v * d0;
          const hx = radX + m.dx * head, hy = radY + m.dy * head;
          const len = m.big ? 26 : 9 + m.v * 0.05;
          const steps = Math.min(48, Math.max(6, len | 0));
          for (let k = 0; k <= steps; k++) {
            const q = k / steps;
            const I = env * ((1 - q) ** 2) * (m.big ? 1.25 : 1);
            cv.add(Math.round(hx - m.dx * q * len), Math.round((hy - m.dy * q * len) / aspect),
              pack(255 * I, (225 + 20 * q) * I, 255 * I * (0.75 + q * 0.3)));
          }
          if (m.big && d0 / m.dur > 0.7) {
            const fe = Math.sin(Math.PI * clamp01((d0 / m.dur - 0.7) / 0.3));
            for (let oy = -2; oy <= 2; oy++) for (let ox = -4; ox <= 4; ox++) {
              const dd = Math.exp(-(ox * ox + oy * oy * aspect * aspect) / 7) * fe;
              cv.add(Math.round(hx) + ox, Math.round(hy / aspect) + oy, pack(255 * dd, 245 * dd, 210 * dd));
            }
          }
        }
        for (let x = 0; x < W; x++) {
          for (let y = Math.round(ridge[x]); y < H; y++) {
            const deep = (y - ridge[x]) / Math.max(1, H - ridge[x]);
            px[y * W + x] = pack(6 - deep * 3, 8 - deep * 4, 11 - deep * 5);
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-searchlights',
    since: '0.3.0',
    title: 'Searchlights',
    category: 'Light & Sky',
    kind: 'scene',
    tags: ['searchlight', 'beams', 'night', 'clouds', 'skyline', 'city', 'volumetric', 'sweep'],
    order: 240,
    description: 'Rooftop searchlights sweep and cross over a night skyline, dust shimmering in the cones and bright spots crawling along the cloud deck.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 16,
    canvas: 'field',
    palette: 'ice',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const rand = ctx.rng;
      const { fbm } = ctx.noise;
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const Hu = H * aspect;
      const bh = new Int32Array(W);
      let x0 = 0;
      while (x0 < W) {
        const bwid = 3 + Math.floor(rand() * 8);
        const h2 = Math.max(1, Math.round((0.05 + rand() * 0.2) * H));
        for (let x = x0; x < Math.min(W, x0 + bwid); x++) bh[x] = h2;
        x0 += bwid;
      }
      const nB = W > 60 ? 4 : 3;
      const beams = Array.from({ length: nB }, (_, i) => {
        const bx = Math.min(W - 1, Math.max(0, Math.round(W * (0.14 + 0.72 * (i / Math.max(1, nB - 1))) + (rand() - 0.5) * W * 0.05)));
        return {
          bx, byU: (H - 1 - bh[bx]) * aspect,
          amp: 0.3 + rand() * 0.22, n: 1 + Math.floor(rand() * 2), ph: rand() * TAU,
          tint: i % 2 ? [255, 236, 200] : [215, 234, 255],
          dx: 0, dyU: -1,
        };
      });
      const cloudBot = Hu * 0.52;
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 16) % 1 + 1) % 1;
        for (const bm of beams) {
          const a = bm.amp * Math.sin(TAU * p * bm.n + bm.ph);
          bm.dx = Math.sin(a); bm.dyU = -Math.cos(a);
        }
        const zx = Math.sin(TAU * p) * 1.4, zz = Math.cos(TAU * p) * 0.8;
        const fr = (tt * 9) | 0;
        for (let y = 0; y < H; y++) {
          const uy = y * aspect, v = y / H;
          const sR = 4 + 6 * v, sG = 6 + 8 * v, sB = 16 + 24 * v;
          const inCloud = uy < cloudBot;
          for (let x = 0; x < W; x++) {
            let r = sR, g = sG, b = sB, dens = 0;
            if (inCloud) {
              dens = clamp01(fbm(x * 0.05 + zx, uy * 0.1, zz, 2) * 1.4 + 0.12);
              r += dens * 9; g += dens * 10; b += dens * 14;
            }
            for (const bm of beams) {
              const rx = x - bm.bx, ryU = uy - bm.byU;
              const sp = rx * bm.dx + ryU * bm.dyU;
              if (sp > 2) {
                const lat = Math.abs(rx * bm.dyU - ryU * bm.dx);
                const hw = 1.1 + sp * 0.055;
                if (lat < hw * 2.4) {
                  let I = Math.exp(-((lat / hw) ** 2)) * Math.max(0, 1 - sp / (Hu * 1.35));
                  I *= 0.8 + 0.4 * hash2(x, y, fr);
                  if (inCloud) I *= 1 + dens * 2.2;
                  r += bm.tint[0] * I * 0.55; g += bm.tint[1] * I * 0.55; b += bm.tint[2] * I * 0.55;
                }
              }
            }
            px[y * W + x] = pack(r, g, b);
          }
        }
        for (let x = 0; x < W; x++) {
          const top = H - 1 - bh[x];
          for (let y = Math.max(0, top); y < H; y++) {
            if (y > top + 1 && hash2(x, y, 5) > 0.93 && ((x + y) & 1)) px[y * W + x] = pack(240, 205, 120);
            else px[y * W + x] = pack(6, 7, 10);
          }
        }
        for (const bm of beams) {
          const sy = Math.round(bm.byU / aspect);
          cv.add(bm.bx, sy, pack(255, 250, 230));
          cv.add(bm.bx + 1, sy, pack(140, 135, 120));
          cv.add(bm.bx - 1, sy, pack(140, 135, 120));
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-moonlit-clouds',
    since: '0.3.0',
    title: 'Moonlit Drift',
    category: 'Light & Sky',
    kind: 'scene',
    tags: ['moon', 'clouds', 'night', 'moonlight', 'silver lining', 'halo', 'drift', 'craters'],
    order: 250,
    description: 'Cloud banks drift across a full cratered moon: silver linings flare at their edges, the halo dims when it is swallowed, stars own the gaps.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 28,
    canvas: 'field',
    palette: 'ice',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const rand = ctx.rng;
      const { fbm } = ctx.noise;
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const Hu = H * aspect;
      const mX = W * 0.64, mY = Hu * 0.3;
      const Rm = Math.max(1.6, Math.min(W * 0.09, Hu * 0.16));
      const craters = Array.from({ length: 6 }, () => {
        const a = rand() * TAU, rr = rand() * 0.62;
        return { ox: Math.cos(a) * rr * Rm, oy: Math.sin(a) * rr * Rm, r: Rm * (0.1 + rand() * 0.2), d: 0.72 + rand() * 0.16 };
      });
      const stars = Array.from({ length: Math.max(14, Math.round(W * H * 0.03)) }, () => ({
        x: Math.floor(rand() * W), y: Math.floor(rand() * H),
        s: 0.35 + rand() * 0.6, p: rand() * TAU, f: (7 + Math.floor(rand() * 3) * 7) * (TAU / 28),
      }));
      const wrap = W * 1.6;
      const clouds = [];
      for (let l = 0; l < 2; l++) {
        const count = 4 + l;
        for (let i = 0; i < count; i++) {
          clouds.push({
            x0: rand() * wrap, yU: Hu * (0.1 + rand() * 0.42),
            rw: W * (0.12 + rand() * 0.13) * (l ? 0.7 : 1), rh: Hu * (0.06 + rand() * 0.07) * (l ? 0.8 : 1),
            seed: rand() * 20, k: l ? 1 : 2, soft: l ? 0.55 : 0.8,
          });
        }
      }
      const dens = new Float32Array(W * H);
      const densAt = (ux, uy, p) => {
        let d = 0;
        for (const c of clouds) {
          const cxp = ((c.x0 + p * c.k * wrap) % wrap + wrap) % wrap - wrap * 0.3;
          const dx = ux - cxp, dy = uy - c.yU;
          const e = 1 - (dx * dx) / (c.rw * c.rw) - (dy * dy) / (c.rh * c.rh);
          if (e > 0) d += e * c.soft * (0.55 + 0.75 * (fbm(dx * 0.09 + c.seed, dy * 0.16, c.seed, 2) * 0.5 + 0.5));
        }
        return Math.min(1.3, d);
      };
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 28) % 1 + 1) % 1;
        const occl = clamp01(densAt(mX, mY, p));
        const glowK = 1 / (1 + occl * 4);
        for (let y = 0; y < H; y++) {
          const uy = y * aspect, v = y / H;
          for (let x = 0; x < W; x++) {
            let r = 4 + 5 * v, g = 6 + 7 * v, b = 15 + 19 * v;
            const dx = x - mX, dyU = uy - mY;
            const d = Math.sqrt(dx * dx + dyU * dyU);
            const hal = Math.exp(-Math.max(0, d - Rm) / (Rm * 1.9)) * glowK;
            r += hal * 46; g += hal * 50; b += hal * 58;
            if (d < Rm) {
              const limb = 1 - 0.25 * ((d / Rm) ** 2);
              let mr = 228 * limb, mg = 230 * limb, mb = 236 * limb;
              for (const c of craters) {
                const dc = Math.hypot(dx - c.ox, dyU - c.oy);
                if (dc < c.r) { mr *= c.d; mg *= c.d; mb *= c.d * 1.02; }
              }
              r = mr * glowK + r * 0.2; g = mg * glowK + g * 0.2; b = mb * glowK + b * 0.2;
            }
            const de = densAt(x, uy, p);
            dens[y * W + x] = de;
            if (de > 0.01) {
              const a = Math.min(0.94, de * 1.25);
              const rim = clamp01(de * (1.15 - de) * 3) * hal;
              const cr = 14 + 176 * rim, cg = 16 + 184 * rim, cb = 22 + 204 * rim;
              r += (cr - r) * a; g += (cg - g) * a; b += (cb - b) * a;
            }
            px[y * W + x] = pack(r, g, b);
          }
        }
        for (const s of stars) {
          if (dens[s.y * W + s.x] > 0.28) continue;
          const tw = s.s * (0.5 + 0.5 * Math.sin(tt * s.f + s.p));
          if (tw > 0.06) cv.add(s.x, s.y, pack(tw * 165, tw * 175, tw * 210));
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

sources.prism-term/src/facets/fx/ocean-waves.js:
// Open sea at sunset, looking toward the horizon. Every water pixel is a
// point on a sum-of-waves height field seen in perspective: its normal
// reflects the sky (more of it at grazing angles), and where it tilts toward
// the low sun the glitter path flickers. Distant waves fade so nothing aliases.
import { lerpc, clamp01 } from '../retro/_kit.js';

const WAVES = [
  [0.9, 0.42, 0.55, 1.0], [-0.6, 0.8, 0.9, 0.55], [0.2, 1, 1.7, 0.3], [-0.95, 0.3, 2.9, 0.16], [0.7, -0.7, 4.3, 0.09],
].map(([dx, dz, k, a]) => {
  // Deep-water dispersion (ω = √gk), rounded so every wave repeats over the 20 s loop.
  const l = Math.hypot(dx, dz), w = Math.max(1, Math.round((Math.sqrt(9.8 * k) * 1.2 * 20) / (2 * Math.PI))) * ((2 * Math.PI) / 20);
  return { dx: dx / l, dz: dz / l, k, a, w };
});

export default {
  title: 'Ocean at Sunset',
  gallery: 'fx',
  category: 'Fire & Water',
  kind: 'scene',
  tags: ['ocean', 'sea', 'waves', 'sunset', 'reflection', 'glitter', 'water'],
  order: 80,
  description: 'Open sea at sunset in perspective: a height field of waves reflecting the sky, with a flickering sun-glitter path.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: 20,
  canvas: 'field',
  palette: 'sunset',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const hz = Math.floor(H * 0.42);
    const sunX = W * 0.5, sunR = Math.min(W * 0.09, hz * aspect * 0.5);
    const sky = (e) => pal(clamp01(0.86 - e * 1.9));                 // elevation 0 = horizon
    const deep = lerpc(pal(0.04), 0x000814, 0.4);
    const clouds = new Float32Array(W * hz);
    // Cloud bands, tiled horizontally (two fbm copies cross-faded) so they can drift forever.
    for (let y = 0; y < hz; y++) for (let x = 0; x < W; x++) {
      const k = x / W, f = (xx) => fbm(xx * 0.03, y * aspect * 0.22, 3.3, 4);
      clouds[y * W + x] = clamp01((f(x) * (1 - k) + f(x - W) * k) * 1.6 - 0.05) * clamp01((y / hz) * 1.6 - 0.15);
    }
    const focal = W * 0.6, camH = 2.2;
    return (t) => {
      const drift = (t / 20) * W;
      // Sky: gradient, banks of cloud lit from below, and a sun sitting on the horizon.
      for (let y = 0; y < hz; y++) {
        const e = (hz - y) / (H * 0.9);
        for (let x = 0; x < W; x++) {
          let c = sky(e);
          const dx = x + 0.5 - sunX, dy = (y + 0.5 - hz + sunR * 0.35 / aspect) * aspect, d = Math.hypot(dx, dy);
          if (d < sunR) c = lerpc(pal(0.97), pal(0.85), clamp01(dy / sunR + 0.5));
          else c = lerpc(c, pal(0.9), clamp01(1 - (d - sunR) / (sunR * 2.5)) * 0.35);
          const cl = clouds[y * W + (Math.floor(x + drift) % W)];
          if (cl > 0) c = lerpc(c, lerpc(pal(0.25), pal(0.75), clamp01(1 - e * 2.5)), Math.min(0.5, cl * 0.7));
          px[y * W + x] = c;
        }
      }
      // Sea.
      for (let y = hz; y < H; y++) {
        const r = y - hz + 0.5, z = (camH * focal) / (r * aspect);
        const fade = clamp01(1 - z / 140);                            // far waves average out to flat
        for (let x = 0; x < W; x++) {
          const wx = ((x + 0.5 - W / 2) * z) / focal;
          let sx = 0, sz = 0, h = 0;
          for (const wv of WAVES) {
            const lod = clamp01(1.4 - (z * wv.k) / 60);
            if (lod <= 0) continue;
            const ph = (wx * wv.dx + z * wv.dz) * wv.k - wv.w * t;
            const a = wv.a * lod * fade;
            h += Math.sin(ph) * a;
            const g = Math.cos(ph) * a * wv.k;
            sx += g * wv.dx; sz += g * wv.dz;
          }
          // Normal, view ray, reflection.
          let nx = -sx * 0.22, ny = 1, nz = -sz * 0.22;
          const nl = Math.hypot(nx, ny, nz); nx /= nl; ny /= nl; nz /= nl;
          let vx = wx, vy = -camH, vz = z;
          const vl = Math.hypot(vx, vy, vz); vx /= vl; vy /= vl; vz /= vl;
          const dn = vx * nx + vy * ny + vz * nz;
          const ry = vy - 2 * dn * ny, rx = vx - 2 * dn * nx;
          const fres = 0.25 + 0.75 * Math.pow(1 - Math.max(0, -dn), 4);
          let c = lerpc(deep, sky(Math.min(0.42, Math.max(0, ry) * 0.7)), fres);
          // Sun glitter: reflections that point back at the low sun.
          const toSun = Math.max(0, 1 - Math.hypot((rx - (sunX - W / 2) / focal) * 1.6, ry - 0.04) * 6);
          if (toSun > 0) c = lerpc(c, pal(0.98), Math.min(1, Math.pow(toSun, 2.5) * 2.6));
                    px[y * W + x] = c;
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/pixel-sort.js:
// Pixel sorting, the glitch-art staple: a sunset scene whose rows are sorted
// by brightness wherever they fall inside a moving threshold window — but only
// within drifting bands, so the clean image and the smeared streaks alternate.
import { lerpc, clamp01 } from '../retro/_kit.js';

const LOOP = 16;
const lum = (c) => ((c >> 16) & 255) * 0.3 + ((c >> 8) & 255) * 0.59 + (c & 255) * 0.11;

export default {
  title: 'Pixel Sort',
  gallery: 'fx',
  category: 'Glitch & Noise',
  kind: 'scene',
  tags: ['pixel sort', 'glitch', 'databend', 'melt', 'sort', 'glitch art'],
  order: 50,
  description: 'Glitch-art pixel sorting: a sunset whose rows sort by brightness inside a moving threshold, in drifting smeared bands.',
  size: { w: 80, h: 24 },
  minSize: { w: 16, h: 6 },
  loop: LOOP,
  canvas: 'field',
  palette: 'sunset',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    // The source: sky, sun, ridge and a lake — painted once.
    const src = new Int32Array(W * H), L = new Float32Array(W * H);
    const hz = Math.floor(H * 0.62), sunR = Math.min(W * 0.14, hz * aspect * 0.55);
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      const ridge = hz - H * (0.06 + 0.12 * Math.abs(fbm(x * 0.03, 0.5, 0, 3)) * 2.2);
      let c;
      if (y < hz) {
        c = pal(0.1 + (y / hz) * 0.75);
        const cl = clamp01(fbm(x * 0.045, y * aspect * 0.16, 4.2, 4) * 2.2 + 0.1);   // banks of cloud
        c = lerpc(c, cl > 0.5 ? pal(0.92) : pal(0.12), Math.abs(cl - 0.5) * 0.9);
        const d = Math.hypot(x + 0.5 - W * 0.62, (y + 0.5 - hz * 0.62) * aspect);
        if (d < sunR) c = lerpc(pal(0.98), pal(0.85), d / sunR);
        if (y > ridge) c = lerpc(pal(0.06), 0x000000, 0.3);
      } else {
        const my = 2 * hz - y, ripple = Math.sin(y * 1.7) * 0.5 + 0.5;
        c = lerpc(pal(0.1 + (my / hz) * 0.75), pal(0.04), 0.25 + ((y - hz) / (H - hz)) * 0.3 + ripple * 0.2);
        if (Math.abs(x + 0.5 - W * 0.62) < sunR * (0.9 - (y - hz) / (H - hz) * 0.4) * (0.6 + 0.4 * ripple)) c = lerpc(c, pal(0.95), 0.6);
      }
      src[y * W + x] = c; L[y * W + x] = lum(c);
    }
    const idx = new Int32Array(W), keys = new Float32Array(W);
    return (t) => {
      px.set(src);
      const u = (t / LOOP) * Math.PI * 2;
      const lo = 55 + 40 * Math.sin(u), hi = 235 + 20 * Math.sin(u * 2 + 1);
      for (let y = 0; y < H; y++) {
        // Only rows inside the drifting glitch bands get sorted; the rest stay clean for contrast.
        const band = Math.sin(y * 0.19 + u * 2) * Math.cos(y * 0.061 - u);
        if (band < 0.12) continue;
        const reach = clamp01(0.3 + band);
        let x = 0;
        while (x < W) {
          while (x < W && !(L[y * W + x] >= lo && L[y * W + x] <= hi)) x++;
          const x0 = x;
          while (x < W && L[y * W + x] >= lo && L[y * W + x] <= hi) x++;
          const span = x - x0, n = Math.max(1, Math.floor(span * reach));
          if (span < 3) continue;
          for (let k = 0; k < n; k++) { idx[k] = src[y * W + x0 + k]; keys[k] = L[y * W + x0 + k]; }
          // Insertion sort, darkest first: light streams off to the right.
          for (let a = 1; a < n; a++) {
            const kv = keys[a], iv = idx[a];
            let j = a - 1;
            while (j >= 0 && keys[j] > kv) { keys[j + 1] = keys[j]; idx[j + 1] = idx[j]; j--; }
            keys[j + 1] = kv; idx[j + 1] = iv;
          }
          // Stretch the sorted run across the whole span: the smear.
          for (let k = 0; k < span; k++) px[y * W + x0 + k] = idx[Math.min(n - 1, Math.floor((k / span) * n))];
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

