// Classic demoscene plasma: four interfering sine fields, palette-cycled.
export default {
  title: 'Plasma',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['plasma', 'demoscene', 'sine', 'palette'],
  order: 10,
  description: 'Four interfering sine fields cycling through an Oklab palette — the demoscene classic.',
  canvas: 'field',
  palette: 'prism',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px, aspect } = cv;
    const k = 16 / Math.max(W, H * aspect);
    return (t) => {
      const tt = t * speed;
      const cx = Math.sin(tt * 0.3) * W * 0.3, cy = Math.cos(tt * 0.23) * H * 0.3;
      for (let y = 0, i = 0; y < H; y++) {
        const fy = y * aspect * k;
        for (let x = 0; x < W; x++, i++) {
          const fx = x * k;
          const dx = (x - W / 2 - cx) * k, dy = (y - H / 2 - cy) * aspect * k;
          const v = Math.sin(fx + tt) + Math.sin(fy * 0.8 + tt * 1.3)
            + Math.sin((fx + fy) * 0.6 + tt * 0.7) + Math.sin(Math.sqrt(dx * dx + dy * dy) * 1.6 - tt * 1.9);
          px[i] = pal(v * 0.125 + 0.5 + tt * 0.05);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/ripple.js:
// Rain on a pond: a damped 2D wave equation (two height buffers) disturbed by
// random drops. Each pixel refracts a pebbled riverbed through the surface
// slope and adds a specular glint, so ripples read as real water.
export default {
  title: 'Ripple Pond',
  gallery: 'fx',
  category: 'Fire & Water',
  kind: 'scene',
  tags: ['water', 'ripple', 'rain', 'wave equation'],
  order: 70,
  description: 'Rain on water — damped wave-equation ripples refracting a pebbled bed, with specular glints.',
  canvas: 'field',
  palette: 'ocean',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const rand = ctx.rng;
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    let cur = new Float32Array(W * H), prev = new Float32Array(W * H);
    const rate = ctx.param('rain', 1);
    const damp = 0.986;
    // Riverbed texture: water-tinted pebbles from two noise octaves.
    const bed = new Int32Array(W * H);
    for (let y = 0, i = 0; y < H; y++)
      for (let x = 0; x < W; x++, i++) {
        const u = x / 14, v = (y * aspect) / 14;
        const n = fbm(u, v, 0, 3) * 0.5 + 0.5;
        const cell = Math.abs(Math.sin(u * 3.1 + Math.sin(v * 2.3) * 1.7) * Math.cos(v * 2.9 + Math.sin(u * 1.9)));
        bed[i] = pal(0.22 + n * 0.16 + cell * 0.07);
      }
    let acc = 0, rain = 1;

    const drop = (x, y, r, s) => {
      for (let dy = -r; dy <= r; dy++)
        for (let dx = -r; dx <= r; dx++) {
          const xx = x + dx, yy = y + Math.round(dy / aspect);
          if (xx < 1 || yy < 1 || xx >= W - 1 || yy >= H - 1) continue;
          const d = Math.hypot(dx, dy) / (r + 0.5);
          if (d < 1) cur[yy * W + xx] -= s * (Math.cos(d * Math.PI) * 0.5 + 0.5);
        }
    };

    const step = () => {
      for (let y = 1; y < H - 1; y++) {
        const row = y * W;
        for (let x = 1; x < W - 1; x++) {
          const i = row + x;
          prev[i] = ((cur[i - 1] + cur[i + 1] + cur[i - W] + cur[i + W]) * 0.5 - prev[i]) * damp;
        }
      }
      const tmp = cur; cur = prev; prev = tmp;
    };

    return (t, dt) => {
      rain += dt * rate * (1.5 + (W * H) / 3000);
      while (rain >= 1) {
        drop(1 + Math.floor(rand() * (W - 2)), 1 + Math.floor(rand() * (H - 2)), 1 + Math.floor(rand() * 2.5), 90 + rand() * 120);
        rain -= 1;
      }
      acc += dt * 40;
      let n = 0;
      while (acc >= 1 && n < 3) { step(); acc -= 1; n++; }
      if (acc > 3) acc = 0;

      for (let y = 0, i = 0; y < H; y++) {
        for (let x = 0; x < W; x++, i++) {
          const l = x > 0 ? cur[i - 1] : cur[i], r = x < W - 1 ? cur[i + 1] : cur[i];
          const u = y > 0 ? cur[i - W] : cur[i], d = y < H - 1 ? cur[i + W] : cur[i];
          const gx = r - l, gy = d - u;
          let sx = x + Math.round(gx * 0.1), sy = y + Math.round(gy * 0.1 / aspect);
          sx = sx < 0 ? 0 : sx >= W ? W - 1 : sx;
          sy = sy < 0 ? 0 : sy >= H ? H - 1 : sy;
          const c = bed[sy * W + sx];
          // Light from the upper-left: brighten slopes facing it, plus a tight glint.
          const shade = 1 + (-gx - gy) * 0.011;
          const spec = Math.max(0, (-gx - gy) * 0.02 - 0.3);
          const g2 = spec * spec * 255;
          const rr = ((c >> 16) & 255) * shade + g2, gg = ((c >> 8) & 255) * shade + g2, bb = (c & 255) * shade + g2;
          px[i] = ((rr < 0 ? 0 : rr > 255 ? 255 : rr) << 16) | ((gg < 0 ? 0 : gg > 255 ? 255 : gg) << 8) | (bb < 0 ? 0 : bb > 255 ? 255 : bb | 0);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/signal-decay.js:
// Glitch & Noise — broadcast failure modes: vertical sync losing its grip on a
// dusk skyline, interlaced fields tearing apart on motion, and a test card
// rotting through copy generations until the signal gives out.
import { clamp01, hash2, textMask, maskAt } from '../retro/_kit.js';

const SPEED = { speed: { default: 1, min: 0.1, max: 4, label: 'Speed' } };
const TAU = Math.PI * 2;
const pack = (r, g, b) =>
  ((r > 255 ? 255 : r < 0 ? 0 : r) << 16) | ((g > 255 ? 255 : g < 0 ? 0 : g) << 8) | ((b > 255 ? 255 : b < 0 ? 0 : b) | 0);

export default [
  {
    id: 'fx-sync-roll',
    since: '0.3.0',
    title: 'Sync Roll',
    category: 'Glitch & Noise',
    kind: 'scene',
    tags: ['sync', 'vhold', 'roll', 'analog', 'tv', 'tear', 'blanking', 'glitch', 'crt'],
    order: 200,
    description: 'A dusk-skyline broadcast loses vertical hold: the frame rolls through the blanking bar, shears at the fold, then snaps back into lock.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 14,
    canvas: 'field',
    palette: 'synthwave',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const rand = ctx.rng;
      const { width: W, height: H, px } = cv;
      const speed = ctx.param('speed', 1);
      const base = new Int32Array(W * H);
      const hor = Math.max(2, Math.round(H * 0.72));
      const sunX = W * 0.63, sunY = hor * 0.82, sunR = Math.max(1.5, W * 0.055);
      for (let y = 0; y < hor; y++) {
        const v = y / hor;
        const c = pal(0.1 + v * 0.52);
        for (let x = 0; x < W; x++) {
          let r = (c >> 16) & 255, g = (c >> 8) & 255, b = c & 255;
          const dx = x - sunX, dy = (y - sunY) * 2;
          const d2 = dx * dx + dy * dy;
          if (d2 < sunR * sunR) { r = 255; g = 214; b = 120; }
          else { const gl = Math.exp(-d2 / (sunR * sunR * 14)) * 90; r += gl; g += gl * 0.7; b += gl * 0.3; }
          base[y * W + x] = pack(r, g, b);
        }
      }
      let x0 = 0;
      while (x0 < W) {
        const bwid = 2 + Math.floor(rand() * 7);
        const bh = Math.max(1, Math.round((0.1 + rand() * 0.5) * (H - hor) + H * 0.1));
        for (let x = x0; x < Math.min(W, x0 + bwid); x++) {
          for (let y = Math.max(0, hor - bh); y < H; y++) {
            const lit = y > hor - bh + 1 && hash2(x, y, 1) > 0.9;
            base[y * W + x] = lit ? pack(250, 208, 110) : pack(10, 9, 20);
          }
        }
        x0 += bwid;
      }
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 14) % 1 + 1) % 1;
        const fr = (tt * 24) | 0;
        let vr = 0, tear = 0, agc = 1;
        if (p < 0.35) {
          vr = Math.round(Math.sin(TAU * p * 16) * 0.6);
        } else if (p < 0.72) {
          const q = (p - 0.35) / 0.37;
          vr = Math.round(q * q * (3 - 2 * q) * H * 4);
          tear = Math.sin(Math.PI * q);
          agc = 1 - 0.3 * tear;
        } else if (p < 0.8) {
          const q = (p - 0.72) / 0.08;
          vr = Math.round(H * 4 + Math.sin(q * Math.PI * 3) * (1 - q) * H * 0.12);
          tear = (1 - q) * 0.4;
        }
        const vroll = ((vr % H) + H) % H;
        const barY = (H - vroll) % H;
        const hum0 = Math.floor(p * 2 * H);
        const humW = Math.max(1, H * 0.09);
        for (let y = 0; y < H; y++) {
          const sy = (y + vroll) % H;
          const dBar = (y - barY + H) % H;
          if (dBar < 2 && (tear > 0.02 || vroll !== 0)) {
            for (let x = 0; x < W; x++) px[y * W + x] = pack(hash2(x, y, fr) * 44, hash2(x, y, fr + 1) * 40, hash2(x, y, fr + 2) * 52);
            continue;
          }
          let off = (hash2(y, fr, 1) - 0.5) * 1.3;
          if (tear > 0.02) off += tear * Math.exp(-dBar / 3.2) * W * 0.14 * (hash2(y, fr, 2) - 0.3) * 2;
          const hum = ((y + hum0) % H) < humW ? 13 : 0;
          for (let x = 0; x < W; x++) {
            const sxx = Math.min(W - 1, Math.max(0, Math.round(x + off)));
            const c = base[sy * W + sxx];
            const n = (hash2(x, y, fr) - 0.5) * 14;
            px[y * W + x] = pack(
              ((c >> 16) & 255) * agc + n + hum,
              ((c >> 8) & 255) * agc + n + hum,
              (c & 255) * agc + n + hum,
            );
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-interlace',
    since: '0.3.0',
    title: 'Field Tear',
    category: 'Glitch & Noise',
    kind: 'scene',
    tags: ['interlace', 'combing', 'fields', 'deinterlace', 'scanlines', 'tv', 'glitch', 'temporal'],
    order: 210,
    description: 'Interlaced fields come unstuck: a bouncing ball combs apart as odd and even scanlines sample different moments, swap parity and drop lines.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 12,
    canvas: 'field',
    palette: 'neon',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const Hu = H * aspect;
      const floorY = Hu * 0.78;
      const br = Math.max(1.6, Hu * 0.17);
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 12) % 1 + 1) % 1;
        const delta = 0.03 + 0.55 * ((0.5 - 0.5 * Math.cos(TAU * p)) ** 2);
        const swap = p > 0.44 && p < 0.56;
        const drop = p > 0.68 && p < 0.78;
        for (let y = 0; y < H; y++) {
          const uy = y * aspect;
          let par = y & 1;
          if (swap) par ^= 1;
          if (drop && (y & 1)) {
            for (let x = 0; x < W; x++) {
              const c = px[(y - 1) * W + x];
              px[y * W + x] = pack(((c >> 16) & 255) * 0.88, ((c >> 8) & 255) * 0.88, (c & 255) * 0.88);
            }
            continue;
          }
          const T = tt - par * delta;
          const bx = W * (0.5 + 0.38 * Math.sin(TAU * T / 6));
          const byU = Hu * (0.56 - 0.34 * Math.abs(Math.sin(TAU * T / 3)));
          const scan = par ? 0.9 : 1;
          for (let x = 0; x < W; x++) {
            let r, g, b;
            if (uy >= floorY) {
              const chk = ((Math.floor(x * 0.5 - T * 10) + Math.floor(uy * 0.45)) & 1);
              r = chk ? 36 : 20; g = chk ? 30 : 16; b = chk ? 52 : 30;
            } else {
              const v = uy / floorY;
              r = 10 + 16 * v; g = 12 + 18 * v; b = 26 + 34 * v;
              const band = Math.sin(x * 0.3 - T * (TAU / 3) + uy * 0.12);
              if (band > 0.55) { r += 14; g += 8; b += 22; }
            }
            const dx = x - bx, dyU = uy - byU;
            const d = Math.sqrt(dx * dx + dyU * dyU);
            if (d < br) {
              const sh = 1 - 0.6 * clamp01((d + dx * 0.4 + dyU * 0.3) / br);
              r = 255 * sh; g = 120 * sh + 30; b = 60 * sh;
              if (d < br * 0.4 && dx < 0 && dyU < 0) { r = 255; g = 220; b = 190; }
            }
            px[y * W + x] = pack(r * scan, g * scan, b * scan);
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-generation-loss',
    since: '0.3.0',
    title: 'Generation Loss',
    category: 'Glitch & Noise',
    kind: 'scene',
    tags: ['generation loss', 'degradation', 'posterize', 'bitrot', 'copy of a copy', 'noise', 'test card', 'glitch'],
    order: 220,
    description: 'A test card recopied until it dies: each generation posterizes harder, blocks coarsen, ghosts smear and noise climbs until the signal is lost.',
    size: { w: 80, h: 24 },
    minSize: { w: 20, h: 6 },
    loop: 16,
    canvas: 'field',
    palette: 'prism',
    params: SPEED,
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const Hu = H * aspect;
      const base = new Int32Array(W * H);
      const ccx = W * 0.5, ccy = Hu * 0.46, cr = Math.min(W, Hu) * 0.34;
      const rampY = Math.round(H * 0.82);
      for (let y = 0; y < H; y++) {
        const uy = y * aspect;
        for (let x = 0; x < W; x++) {
          let r = 24 + (y / H) * 14, g = 26 + (y / H) * 14, b = 34 + (y / H) * 16;
          if (((x >> 3) + (y >> 2)) & 1) { r += 6; g += 6; b += 7; }
          if (y >= rampY) {
            const l = (x / Math.max(1, W - 1)) * 255;
            r = l; g = l; b = l;
          } else {
            const d = Math.hypot(x - ccx, uy - ccy);
            if (d < cr) {
              const c = pal(clamp01(d / cr) * 0.9);
              r = (c >> 16) & 255; g = (c >> 8) & 255; b = c & 255;
              if (d < cr * 0.18) { r = 235; g = 235; b = 235; }
            }
          }
          base[y * W + x] = pack(r, g, b);
        }
      }
      const mask = textMask('CH 07', { font: 'tiny' });
      if (mask.w + 3 < W && mask.h + 3 < H) {
        for (let y = 0; y < mask.h; y++) for (let x = 0; x < mask.w; x++) {
          if (maskAt(mask, x, y)) base[(y + 1) * W + (x + 2)] = pack(240, 240, 240);
        }
      }
      return (t) => {
        const tt = t * speed;
        const p = ((tt / 16) % 1 + 1) % 1;
        const fr = (tt * 12) | 0;
        const gen = 1 + Math.floor(p * 7.999);
        const levels = Math.max(2, Math.round(26 - p * 24));
        const stepQ = 255 / (levels - 1);
        const bs = 1 + Math.min(4, Math.floor(p * 5.2));
        const noiseAmp = p * p * 110;
        const ghost = Math.round(p * 8);
        const ghostA = p * 0.45;
        const sat = 1 - p * 0.85;
        const corruptP = p * 0.3;
        const rollSeed = (p * 20) | 0;
        const staticA = clamp01((p - 0.9) / 0.08);
        for (let by = 0; by < H; by += bs) {
          for (let bx = 0; bx < W; bx += bs) {
            const c = base[Math.min(H - 1, by + (bs >> 1)) * W + Math.min(W - 1, bx + (bs >> 1))];
            let r = (c >> 16) & 255, g = (c >> 8) & 255, b = c & 255;
            const l = (r + g + b) / 3;
            r = l + (r - l) * sat; g = l + (g - l) * sat; b = l + (b - l) * sat;
            const h = hash2(bx, by, rollSeed);
            if (h < corruptP) {
              const h2 = hash2(bx, by, rollSeed + 31);
              if (h2 < 0.3) {
                const c2 = base[(Math.floor(h2 * 3137) % H) * W + (Math.floor(h2 * 7919) % W)];
                r = (c2 >> 16) & 255; g = (c2 >> 8) & 255; b = c2 & 255;
              } else if (h2 < 0.55) { r = 255 - r; g = 255 - g; b = 255 - b; }
              else if (h2 < 0.78) { r = 225; g = 45; b = 200; }
              else { r = g = b = h2 * 255; }
            }
            const n = (hash2(bx, by, fr) - 0.5) * noiseAmp;
            r = Math.round((r + n) / stepQ) * stepQ;
            g = Math.round((g + n) / stepQ) * stepQ;
            b = Math.round((b + n) / stepQ) * stepQ;
            const yMax = Math.min(H, by + bs), xMax = Math.min(W, bx + bs);
            for (let y = by; y < yMax; y++) {
              for (let x = bx; x < xMax; x++) {
                let rr = r, gg = g, bb = b;
                if (ghost > 0) {
                  const gc = base[y * W + Math.max(0, x - ghost)];
                  rr += ((gc >> 16) & 255) * ghostA; gg += ((gc >> 8) & 255) * ghostA; bb += (gc & 255) * ghostA;
                }
                if (staticA > 0) {
                  const sn = hash2(x, y, fr + 5) * 235;
                  rr += (sn - rr) * staticA; gg += (sn - gg) * staticA; bb += (sn - bb) * staticA;
                }
                px[y * W + x] = pack(rr, gg, bb);
              }
            }
          }
        }
        cv.paint(ctx.buffer);
        const b2 = ctx.buffer;
        if (ctx.width >= 14) b2.text(1, 0, 'GEN ' + gen, 0xe8e8e8);
        if (staticA > 0.45 && ctx.width >= 14) {
          const msg = 'NO SIGNAL';
          b2.text(Math.max(0, (ctx.width - msg.length) >> 1), Math.max(0, ctx.height >> 1), msg, 0xf2f2f2);
        }
      };
    },
  },
];

sources.prism-term/src/facets/fx/smoke.js:
// Incense smoke: a thin laminar ribbon leaves the glowing tip, wavers, then
// breaks into curling turbulence as it climbs — the column is advected through
// a noise flow that strengthens with height, widening and thinning to nothing.
import { lerpc, clamp01 } from '../retro/_kit.js';

export default {
  title: 'Incense Smoke',
  gallery: 'fx',
  category: 'Fire & Water',
  kind: 'scene',
  tags: ['smoke', 'incense', 'turbulence', 'wisps', 'calm', 'ambient'],
  order: 90,
  description: 'Incense smoke: a laminar ribbon leaves the glowing tip, wavers and breaks into curling turbulence as it rises.',
  size: { w: 48, h: 24 },
  minSize: { w: 12, h: 8 },
  loop: 24,
  canvas: 'field',
  palette: 'ice',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { noise3 } = ctx.noise;
    const { theme } = ctx;
    const { width: W, height: H, px, aspect } = cv;
    const baseY = H * 0.86, tipX = W / 2;
    const smokeC = lerpc(pal(0.75), theme.ink, 0.3);
    const S = Math.min(W, H * aspect);
    const strands = [{ a: 1, b: 0, k: 1, ph: 0 }, { a: -0.8, b: 0.15, k: 0.7, ph: 1.4 }, { a: 0.6, b: -0.22, k: 0.5, ph: 2.9 }];
    const T = 8, D = 1.6;                                           // flow cycle (s) and rise per cycle (noise units)
    const flow = (x, yy, off) => noise3(x * 0.05, yy + off, 0.5) + noise3(x * 0.11, yy * 2.1 + off * 2.1 + 3.3, 2.5) * 0.5;
    return (t) => {
      const u = (t / 24) * Math.PI * 2;
      const f = (t % T) / T;
      for (let y = 0, i = 0; y < H; y++) {
        const hgt = clamp01((baseY - y) / baseY);                  // 0 at the tip, 1 at the top
        const turb = Math.pow(hgt, 1.6) * 2.6;
        const width = (0.45 + hgt * 3.4) * (S / 48);
        const reach = hgt * S * 0.12 + turb * S * 0.26 + width * 3;
        const x0 = Math.max(0, Math.floor(tipX - reach)), x1 = Math.min(W, Math.ceil(tipX + reach));
        px.fill(theme.bg, y * W, (y + 1) * W);
        if (y > baseY) continue;
        const yy = y * aspect * 0.06;
        for (let x = x0; x < x1; x++) {
          i = y * W + x;
          let d = 0;
          // Two copies of the flow, scrolled upward and cross-faded, so the smoke climbs and still loops.
          const n0 = flow(x, yy, f * D) * (1 - f) + flow(x, yy, (f - 1) * D) * f;
          for (const s of strands) {
            const n = n0 * s.a + s.b * hgt;
            const centre = tipX + Math.sin(hgt * 6 - u * 3 + s.ph) * hgt * S * 0.1 + n * turb * S * 0.16;
            const q = (x + 0.5 - centre) / width;
            d += Math.exp(-q * q) * s.k * (1 - hgt * 0.8) * (s.a === 1 ? 1 : clamp01(hgt * 4));
          }
          if (d > 0.02) px[i] = lerpc(theme.bg, smokeC, Math.min(0.92, d * 1.1));
        }
      }
      // The stick, its holder, and the glowing tip.
      for (let y = Math.floor(baseY); y < H; y++) cv.set(tipX, y, 0x6a4a30);
      for (let x = Math.floor(tipX - S * 0.18); x <= tipX + S * 0.18; x++) cv.set(x, H - 1, lerpc(theme.panel, 0x8a6a40, 0.5));
      const glow = 0.7 + 0.3 * Math.sin(t * 5) * Math.sin(t * 3.1);
      cv.set(tipX, baseY, lerpc(0xff5a1a, 0xffd080, glow));
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/torrents.js:
// Fire & Water — moving bodies of water: a full-height waterfall pounding into
// mist, a whirlpool spiralling down a dark throat, and a geyser on a strict
// eruption timetable.
import { mix, scale } from '../../color.js';
import { clamp, smoothstep } from '../../easing.js';

const TAU = Math.PI * 2;

export default [
  {
    id: 'fx-waterfall',
    since: '0.3.0',
    title: 'Waterfall',
    category: 'Fire & Water',
    kind: 'scene',
    tags: ['waterfall', 'water', 'mist', 'foam', 'spray', 'cascade'],
    order: 200,
    description: 'Streaked water pours past in distinct streams, bursts on the plunge pool and throws mist and arcing spray back up the face.',
    loop: 12,
    canvas: 'field',
    palette: 'ocean',
    params: { speed: { default: 1, min: 0.2, max: 3, label: 'Speed' } },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { noise2, noise3 } = ctx.noise;
      const { width: W, height: H, px } = cv;
      const rand = ctx.rng;
      const speed = ctx.param('speed', 1);
      const ys = H - Math.max(2, Math.round(H * 0.2)); // waterline row
      const mh = Math.max(2, Math.round(H * 0.14));    // mist band above it
      const ve = new Float32Array(W);                  // static per-stream weight
      for (let x = 0; x < W; x++) ve[x] = 0.72 + 0.28 * (0.5 + 0.5 * noise2(x * 0.17, 3.3));
      const drops = [];
      const nd = Math.max(8, Math.min(26, Math.round(W / 6)));
      for (let i = 0; i < nd; i++) {
        drops.push({
          x0: rand() * W, o: rand(), dx: (rand() - 0.5) * W * 0.12,
          h: (0.5 + rand() * 0.9) * Math.max(2, H * 0.14), p: 1.1 + rand() * 0.5,
        });
      }
      const white = pal(0.96), mist = pal(0.9);
      return (t) => {
        const tt = t * speed;
        for (let y = 0, i = 0; y < H; y++) {
          if (y < ys) {
            const fy1 = y * 0.045 - tt * 2.6, fy2 = y * 0.09 - tt * 4.0;
            const fall = y / ys;
            for (let x = 0; x < W; x++, i++) {
              const v1 = 0.5 + 0.5 * noise3(x * 0.34, fy1, 1.5);
              const v2 = 0.5 + 0.5 * noise3(x * 0.74, fy2, 4.2);
              const w = (v1 * 0.62 + v2 * 0.38) * ve[x] + fall * 0.1;
              let c = pal(0.28 + 0.6 * clamp(w));
              if (w > 0.8) c = mix(c, white, Math.min(1, (w - 0.8) * 4));
              if (y >= ys - mh) {
                const env = 1 - (ys - y) / mh;
                const m = (0.5 + 0.5 * noise3(x * 0.1, y * 0.14 + tt * 0.9, 7.7)) * env;
                c = mix(c, mist, m * 0.5);
              }
              px[i] = c;
            }
          } else {
            const depth = (y - ys) / Math.max(1, H - 1 - ys);
            const wl = 1 - depth;
            for (let x = 0; x < W; x++, i++) {
              const fo = 0.5 + 0.5 * noise3(x * 0.26, tt * 1.5, 12 + y * 0.3);
              const base = pal(0.33 - 0.16 * depth);
              px[i] = mix(base, white, clamp(fo * (0.18 + 0.52 * wl)));
            }
          }
        }
        for (const d of drops) {
          const age = ((tt / d.p + d.o) % 1 + 1) % 1;
          const ax = d.x0 + d.dx * age;
          const ay = ys - d.h * 4 * age * (1 - age);
          cv.blend(ax, ay, white, (1 - age) * 0.7);
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-whirlpool',
    since: '0.3.0',
    title: 'Whirlpool',
    category: 'Fire & Water',
    kind: 'scene',
    tags: ['whirlpool', 'vortex', 'spiral', 'water', 'maelstrom', 'foam'],
    order: 210,
    description: 'A maelstrom seen from above: foam-laced spiral bands accelerate into a dark throat while debris bubbles ride the current down.',
    loop: 8,
    canvas: 'field',
    palette: 'ocean',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { width: W, height: H, px, aspect } = cv;
      const rand = ctx.rng;
      const cx = W / 2, cy = H / 2;
      const RMAX = Math.max(4, Math.min(W, H * aspect)) * 0.52;
      const N = W * H;
      const RD = new Float32Array(N), THV = new Float32Array(N), LG = new Float32Array(N);
      for (let y = 0, i = 0; y < H; y++) {
        for (let x = 0; x < W; x++, i++) {
          const dx = x - cx + 0.5, dy = (y - cy + 0.5) * aspect;
          const r = Math.sqrt(dx * dx + dy * dy) / RMAX;
          RD[i] = r;
          THV[i] = Math.atan2(dy, dx);
          LG[i] = Math.log(r + 0.04);
        }
      }
      const bubbles = [];
      const nb = Math.max(12, Math.min(36, Math.round((W * H) / 420)));
      for (let i = 0; i < nb; i++) {
        bubbles.push({ o: rand(), th0: rand() * TAU, spr: 0.55 + rand() * 0.42 });
      }
      const throat = pal(0.03), foamC = pal(0.95), rim = pal(0.2);
      return (t) => {
        const tt = TAU * (t / 8); // whole turns per loop: everything closes
        for (let i = 0; i < N; i++) {
          const r = RD[i];
          if (r > 1) {
            px[i] = scale(rim, 0.84 + 0.1 * Math.sin(3 * THV[i] + 5.5 * LG[i] - 2 * tt));
            continue;
          }
          const band = Math.sin(3 * THV[i] + 5.5 * LG[i] - 2 * tt);
          const sw = 0.5 + 0.5 * Math.sin(9 * r - 3 * tt + THV[i]);
          let c = pal(clamp(0.16 + 0.4 * r + 0.1 * band));
          c = mix(c, throat, smoothstep(0.3, 0.07, r));
          const bp = band > 0 ? band * band * band : 0;
          const foam = bp * clamp(4 * r * (1 - r)) * (0.55 + 0.45 * sw);
          px[i] = mix(c, foamC, Math.min(0.85, foam));
        }
        for (const b of bubbles) {
          const age = ((t / 8 + b.o) % 1 + 1) % 1;
          const rr = b.spr * (1 - 0.88 * age);
          const ang = b.th0 + 2.4 * age / (0.18 + rr) + tt * 0.5;
          const bx = cx + Math.cos(ang) * rr * RMAX;
          const by = cy + (Math.sin(ang) * rr * RMAX) / aspect;
          cv.blend(bx, by, foamC, Math.sin(Math.PI * age) * 0.8);
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-geyser',
    since: '0.3.0',
    title: 'Geyser',
    category: 'Fire & Water',
    kind: 'scene',
    tags: ['geyser', 'eruption', 'water', 'steam', 'spray', 'thermal', 'spring'],
    order: 220,
    description: 'A thermal spring on a timetable: the pool shivers, the column bursts skyward with ballistic spray, then drifts away as steam.',
    loop: 14,
    canvas: 'field',
    palette: 'ice',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { noise3 } = ctx.noise;
      const { width: W, height: H, px } = cv;
      const rand = ctx.rng;
      const ys = Math.max(2, Math.min(H - 2, Math.round(H * 0.74)));
      const cx = W * 0.5;
      const poolH = H - ys;
      const jetHmax = (ys - 1) * 0.92;
      const w0 = Math.max(1.2, W * 0.025);
      const spray = [];
      const np = Math.max(16, Math.min(48, Math.round((W * H) / 320)));
      for (let i = 0; i < np; i++) {
        spray.push({
          l: 0.36 + rand() * 0.3, tf: 0.9 + rand() * 1.1,
          vx: (rand() - 0.5) * W * 0.09, top: (0.55 + rand() * 0.4),
          vy: (0.4 + rand() * 0.5) * jetHmax,
        });
      }
      const gg = Math.max(2, jetHmax * 1.4);
      const white = pal(0.97), steamC = pal(0.9), reflC = pal(0.8);
      return (t) => {
        const p = ((t / 14) % 1 + 1) % 1;
        const zc = Math.cos(TAU * p), zs = Math.sin(TAU * p);
        const e = smoothstep(0.3, 0.4, p) * (1 - smoothstep(0.6, 0.76, p));
        const rumble = smoothstep(0.2, 0.36, p) * (1 - smoothstep(0.38, 0.46, p));
        const mistE = smoothstep(0.58, 0.72, p) * (1 - smoothstep(0.85, 0.99, p));
        const jetH = e * jetHmax;
        const steamA = 0.16 + 0.55 * mistE + 0.12 * rumble;
        const span = Math.max(2, W * 0.32);
        for (let y = 0, i = 0; y < H; y++) {
          if (y < ys) {
            const grad = pal(0.05 + 0.13 * (1 - y / ys));
            for (let x = 0; x < W; x++, i++) {
              const xf = 1 - Math.abs(x - cx) / span;
              if (xf <= 0) { px[i] = grad; continue; }
              const wisp = noise3(x * 0.085, y * 0.13, zc * 0.6 + zs * 0.4 + 2);
              const m = clamp(wisp) * steamA * xf * (0.35 + 0.65 * (y / ys));
              px[i] = m > 0.01 ? mix(grad, steamC, m) : grad;
            }
          } else {
            const depth = (y - ys) / Math.max(1, poolH - 1);
            const amp = 0.05 + 0.1 * rumble + 0.05 * e;
            for (let x = 0; x < W; x++, i++) {
              const b = 0.3 - 0.12 * depth + amp * Math.sin(x * 0.4 + TAU * 3 * p + depth * 5);
              let c = pal(clamp(b));
              const rr = Math.abs(x - cx);
              const ring = Math.max(0, Math.sin(rr * 0.55 - TAU * 4 * p));
              c = mix(c, white, ring * ring * ring * (e + mistE * 0.5) * clamp(1 - rr / (W * 0.5)) * 0.5);
              const refl = e * (1 - depth) * clamp(1 - rr / (w0 * 2.2));
              px[i] = mix(c, reflC, refl * 0.55);
            }
          }
        }
        if (jetH >= 1) {
          const rows = Math.floor(jetH);
          for (let k = 0; k <= rows; k++) {
            const yq = ys - 1 - k;
            if (yq < 0) break;
            const q = k / jetHmax;
            const tear = 1 + 0.32 * noise3(k * 0.14, 11, zc * 0.8 + zs * 0.5);
            const wq = w0 * (0.55 + 0.6 * q + 2.0 * q * q * q * q) * tear * clamp((jetH - k) / 3 + 0.25);
            const xoff = 1.2 * Math.sin(q * 5 + TAU * 2 * p) * q;
            for (let dx = -Math.ceil(wq); dx <= Math.ceil(wq); dx++) {
              const s = Math.min(1, Math.abs(dx) / Math.max(0.6, wq));
              cv.blend(cx + xoff + dx, yq, mix(white, pal(0.5), s * s), 0.92 - 0.4 * s);
            }
          }
        }
        for (const sp of spray) {
          let a = p - sp.l;
          if (a < 0) a += 1;
          const sec = a * 14;
          if (sec >= sp.tf) continue;
          const sy = ys - sp.top * jetHmax * 0.9 - sp.vy * sec + 0.5 * gg * sec * sec;
          cv.blend(cx + sp.vx * sec, sy, white, (1 - sec / sp.tf) * 0.85 * Math.max(e, 0.2));
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

sources.prism-term/src/facets/fx/tunnel.js:
// Demoscene tunnel: an angle/depth lookup table over a 2× oversized window, so
// the camera can wobble by sliding the viewport. Checkered walls stream toward
// the viewer through a cycling palette; neon ribs are anti-aliased to a constant
// pixel width (their world-space width is derived per pixel from the LUT).
export default {
  title: 'Tunnel',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['tunnel', 'demoscene', 'texture', 'lut'],
  order: 30,
  description: 'Textured demoscene tunnel — precomputed angle/depth LUT, neon ribs, palette cycling and camera wobble.',
  canvas: 'field',
  palette: 'prism',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const segs = 8;
    const { width: W, height: H, px, aspect } = cv;
    const LW = W * 2, LH = H * 2;
    const ang = new Float32Array(LW * LH), dep = new Float32Array(LW * LH);
    const fog = new Float32Array(LW * LH), wu = new Float32Array(LW * LH), wv = new Float32Array(LW * LH);
    const R = Math.min(W, H * aspect) * 0.5;
    const lineW = Math.max(0.7, R / 40); // rib half-width in pixels
    for (let y = 0, i = 0; y < LH; y++) {
      const dy = (y - LH / 2 + 0.5) * aspect;
      for (let x = 0; x < LW; x++, i++) {
        const dx = x - LW / 2 + 0.5;
        const r = Math.sqrt(dx * dx + dy * dy) + 0.0001;
        ang[i] = Math.atan2(dy, dx) / (Math.PI * 2) + 0.5;
        dep[i] = (R * 0.8) / r;
        // Pixels per texture unit: depth changes as R·0.8/r², angle as 2πr/segs.
        wv[i] = lineW / Math.max(1e-4, (r * r) / (R * 0.8));
        wu[i] = lineW / ((2 * Math.PI * r) / segs);
        const f = Math.min(1, r / (R * 1.1));
        fog[i] = f * f * (3 - 2 * f);
      }
    }
    const bg = ctx.theme.bg;
    const br = (bg >> 16) & 255, bgc = (bg >> 8) & 255, bb = bg & 255;

    return (t) => {
      const tt = t * speed;
      const ox = Math.floor(W / 2 + Math.sin(tt * 0.61) * W * 0.16);
      const oy = Math.floor(H / 2 + Math.sin(tt * 0.47 + 1) * H * 0.14);
      const twist = tt * 0.06, move = tt * 1.6;
      for (let y = 0, i = 0; y < H; y++) {
        let j = (y + oy) * LW + ox;
        for (let x = 0; x < W; x++, i++, j++) {
          const d = dep[j];
          const u = ang[j] * segs + twist + d * 0.12;
          const v = d + move;
          const fu = u - Math.floor(u), fv = v - Math.floor(v);
          const check = ((Math.floor(u * 2) + Math.floor(v * 2)) & 1) ? 0.16 : 0.34;
          const eu = Math.min(fu, 1 - fu) / wu[j], ev = Math.min(fv, 1 - fv) / wv[j];
          const rib = Math.max(0, 1 - Math.min(eu, ev));
          const c = pal(v * 0.11 - tt * 0.04);
          const f = fog[j];
          const k = f * (check + rib * 0.95);
          const hot = rib * rib * f * 120; // white-hot core on the ribs
          const r = ((c >> 16) & 255) * k + br * (1 - f) + hot;
          const g = ((c >> 8) & 255) * k + bgc * (1 - f) + hot;
          const b = (c & 255) * k + bb * (1 - f) + hot;
          px[i] = ((r > 255 ? 255 : r) << 16) | ((g > 255 ? 255 : g) << 8) | (b > 255 ? 255 : b | 0);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/fx/vhs-glitch.js:
// A worn VHS tape of color bars: per-line jitter, chroma bleeding off the
// luma, a tracking band rolling down the frame, head-switching noise along the
// bottom, dropout specks, and the deck's on-screen display over it all.
import { lerpc, clamp01, hash2 } from '../retro/_kit.js';

const LOOP = 12;
const BARS = [0xc0c0c0, 0xc0c000, 0x00c0c0, 0x00c000, 0xc000c0, 0xc00000, 0x0000c0];
const REV = [0x0000c0, 0x131313, 0xc000c0, 0x131313, 0x00c0c0, 0x131313, 0xc0c0c0];
const PLUGE = [[0.25, 0x00214c], [0.25, 0xffffff], [0.25, 0x32006a], [0.25, 0x131313]];

export default {
  title: 'VHS Tracking',
  gallery: 'fx',
  category: 'Glitch & Noise',
  kind: 'scene',
  tags: ['vhs', 'glitch', 'tracking', 'analog', 'color bars', 'vcr', 'retro'],
  order: 30,
  description: 'Worn VHS color bars: line jitter, chroma bleed, a rolling tracking band, head-switch noise and the deck OSD.',
  size: { w: 80, h: 24 },
  minSize: { w: 24, h: 8 },
  loop: LOOP,
  canvas: 'field',
  setup(ctx) {
    const cv = ctx.canvas();
    const b = ctx.buffer;
    const { width: W, height: H, px } = cv;
    const bars = (x, y) => {
      const u = x / W, v = y / H;
      if (v < 0.67) return BARS[Math.min(6, Math.floor(u * 7))];
      if (v < 0.75) return REV[Math.min(6, Math.floor(u * 7))];
      if (u < 5 / 7) { let a = 0; for (const [w, c] of PLUGE) { a += w * (5 / 7); if (u < a) return c; } }
      return 0x131313;
    };
    const R = new Float32Array(W), G = new Float32Array(W), B = new Float32Array(W);
    return (t) => {
      const lt = t % LOOP, frame = Math.floor(t * 30);
      const band = ((lt / LOOP) * 1.6 - 0.3) * H, bandH = Math.max(2, H * 0.08);
      const burst = lt > 7.2 && lt < 7.6;                 // a hard tracking slip once a loop
      const roll = burst ? Math.floor((lt - 7.2) * H * 2.5) : 0;
      for (let y = 0; y < H; y++) {
        const sy = (y + roll) % H;
        const inBand = Math.abs(y - band) < bandH;
        const head = y >= H - Math.max(2, Math.round(H * 0.05));
        let off = (hash2(y, frame, 1) - 0.5) * 1.2 + Math.sin(y * 0.3 + t * 2) * 0.6;
        if (inBand) off += (hash2(y, frame, 2) - 0.2) * W * 0.06;
        if (head) off += (y - (H - H * 0.05)) * W * 0.03;
        for (let x = 0; x < W; x++) {
          const c = bars(Math.min(W - 1, Math.max(0, Math.round(x - off))), sy);
          R[x] = (c >> 16) & 255; G[x] = (c >> 8) & 255; B[x] = c & 255;
        }
        for (let x = 0; x < W; x++) {
          // Chroma bleeds right, smeared; luma stays sharper.
          const xr = Math.max(0, x - 2), xb = Math.min(W - 1, x + 1);
          let r = (R[xr] * 0.6 + R[Math.max(0, xr - 1)] * 0.4), g = G[x], bl = (B[xb] * 0.6 + B[Math.max(0, x)] * 0.4);
          let n = (hash2(x, y, frame) - 0.5) * 26;
          if (inBand) n += hash2(x >> 1, y, frame + 7) > 0.82 ? 150 : 0;
          if (head) n += (hash2(x, y, frame + 3) - 0.5) * 160;
          if (hash2(x, y * 7, frame) > 0.9985) n += 220;      // dropouts
          const k = inBand ? 0.82 : 1;
          px[y * W + x] = (clamp01((r * k + n) / 255) * 255) << 16 | (clamp01((g * k + n) / 255) * 255) << 8 | (clamp01((bl * k + n) / 255) * 255);
        }
      }
      cv.paint(b);
      // Deck OSD, drawn straight over the picture the way VCRs did.
      const CW = ctx.width, CH = ctx.height;
      const osd = (x, y, s) => b.text(x, y, s, 0xf4f4f4);
      if (Math.floor(t * 2) % 2 === 0 || lt > 2) osd(2, 1, 'PLAY ▶');
      const secs = 754 + Math.floor(lt);
      const tc = `SP  ${Math.floor(secs / 3600)}:${String(Math.floor(secs / 60) % 60).padStart(2, '0')}:${String(secs % 60).padStart(2, '0')}`;
      if (CW >= 30) osd(CW - tc.length - 3, CH - 2, tc);
      if (burst && CW >= 30) osd(Math.floor(CW / 2) - 4, Math.floor(CH / 2), 'TRACKING');
    };
  },
};

sources.prism-term/src/facets/fx/voronoi.js:
// Living Voronoi: drifting seeds carve the plane into cells. Each cell is shaded
// like a bevelled tile (bright at its seed, darker toward its edge) and the
// borders — where the nearest and second-nearest seeds tie — glow.
import { lerpc } from '../retro/_kit.js';

export default {
  title: 'Voronoi Cells',
  gallery: 'fx',
  category: 'Fields',
  kind: 'scene',
  tags: ['voronoi', 'worley', 'cells', 'tiles', 'stained glass', 'procedural'],
  order: 70,
  description: 'Drifting seeds carve living Voronoi cells — bevelled stained-glass tiles with glowing borders where neighbors meet.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 6 },
  loop: 24,
  canvas: 'field',
  palette: 'prism',
  params: { cells: { default: 1, min: 0.3, max: 3, label: 'Cell density' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette(undefined, { size: 512 });
    const rand = ctx.rng;
    const { width: W, height: H, px, aspect } = cv;
    const VH = H * aspect;
    const n = Math.max(6, Math.min(48, Math.round(((W * VH) / 260) * ctx.param('cells', 1) * (80 / Math.max(80, W)) ** 0.5)));
    const seeds = Array.from({ length: n }, () => ({ x: rand(), y: rand(), ax: 0.05 + rand() * 0.07, ay: 0.05 + rand() * 0.07, fa: 1 + Math.floor(rand() * 2), fb: 1 + Math.floor(rand() * 2), ph: rand() * 6.28, hue: rand() }));
    const sx = new Float32Array(n), sy = new Float32Array(n);
    const S = Math.sqrt((W * VH) / n);               // typical cell size
    // The lead between the panes is dark in daylight too: stained glass, not frosted.
    const edge = lerpc(0xffffff, ctx.theme.ink, 0.3);
    const lead = ctx.theme.mode === 'light' ? lerpc(ctx.theme.ink, ctx.theme.bg, 0.2) : lerpc(ctx.theme.bg, 0x000000, 0.4);
    return (t) => {
      const u = (t / 24) * Math.PI * 2;
      for (let j = 0; j < n; j++) {
        const s = seeds[j];
        sx[j] = (s.x + Math.sin(u * s.fa + s.ph) * s.ax) * W;
        sy[j] = (s.y + Math.cos(u * s.fb + s.ph * 1.3) * s.ay) * VH;
      }
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y + 0.5) * aspect;
        for (let x = 0; x < W; x++, i++) {
          let d1 = 1e9, d2 = 1e9, best = 0;
          for (let j = 0; j < n; j++) {
            const dx = x + 0.5 - sx[j], dy = vy - sy[j], d = dx * dx + dy * dy;
            if (d < d1) { d2 = d1; d1 = d; best = j; } else if (d < d2) d2 = d;
          }
          const f1 = Math.sqrt(d1), f2 = Math.sqrt(d2), gap = (f2 - f1) / S;
          const base = pal((seeds[best].hue + t / 48) % 1);
          let c = lerpc(base, lead, Math.min(0.75, (f1 / S) * 0.9));       // bevel: darker away from the seed
          if (gap < 0.08) c = lead;                                               // the leading between panes
          else if (gap < 0.2) c = lerpc(c, edge, (1 - (gap - 0.08) / 0.12) * 0.35); // light catching the pane's edge
          px[i] = c;
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

// Fields — three ways a flat plane comes alive: fbm folded through itself
// (ink-marble domain warping), a live Gray–Scott reaction–diffusion dish,
// and layered silk ribbons carrying a travelling sheen.
import { mix, scale } from '../../color.js';
import { clamp } from '../../easing.js';

const TAU = Math.PI * 2;

export default [
  {
    id: 'fx-domain-warp',
    since: '0.3.0',
    title: 'Domain Warp',
    category: 'Fields',
    kind: 'scene',
    tags: ['noise', 'fbm', 'domain warp', 'marble', 'ink', 'veins', 'flow'],
    order: 200,
    description: 'fbm fed through itself twice: ink-marble veins fold and drift, lit where the warp dragged the field furthest.',
    loop: 24,
    canvas: 'field',
    palette: 'aurora',
    credits: 'after Inigo Quilez',
    params: { speed: { default: 1, min: 0.1, max: 4, label: 'Speed' } },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { fbm } = ctx.noise;
      const { width: W, height: H, px, aspect } = cv;
      const speed = ctx.param('speed', 1);
      const S = Math.max(8, Math.min(W, H * aspect));
      // The field is smooth, so sample fbm on a coarse lattice and lerp per pixel.
      const g = W * H > 12000 ? 3 : W * H > 5000 ? 2 : 1;
      const GW = Math.ceil(W / g) + 2, GH = Math.ceil(H / g) + 2;
      const V = new Float32Array(GW * GH);
      const Q = new Float32Array(GW * GH);
      const R = new Float32Array(GW * GH);
      const lp = (A, x, y) => {
        const gx = x / g, gy = y / g, ix = gx | 0, iy = gy | 0, fx = gx - ix, fy = gy - iy, j = iy * GW + ix;
        return (A[j] * (1 - fx) + A[j + 1] * fx) * (1 - fy) + (A[j + GW] * (1 - fx) + A[j + GW + 1] * fx) * fy;
      };
      return (t) => {
        const u = ((t * speed) / 24) * TAU; // one slow orbit per loop
        const ca = Math.cos(u), sa = Math.sin(u);
        for (let gy = 0; gy < GH; gy++) {
          for (let gx = 0; gx < GW; gx++) {
            const j = gy * GW + gx;
            const x = (gx * g * 2.6) / S, y = (gy * g * aspect * 2.6) / S;
            const qx = fbm(x + ca * 0.9, y + sa * 0.9, 0, 3);
            const qy = fbm(x + 5.2 + sa * 0.7, y + 1.3 + ca * 0.7, 2.1, 3);
            const rx = fbm(x + 1.7 * qx + 9.2, y + 1.7 * qy + 2.8, 4.4 + sa * 0.3, 3);
            const ry = fbm(x + 1.7 * qx + 3.1, y + 1.7 * qy + 7.6, 1.9 - ca * 0.3, 3);
            V[j] = fbm(x + 1.9 * rx, y + 1.9 * ry, 6.5, 3);
            Q[j] = qx * qx + qy * qy;
            R[j] = rx * rx + ry * ry;
          }
        }
        const breath = 0.07 * sa;
        for (let y = 0, i = 0; y < H; y++) {
          for (let x = 0; x < W; x++, i++) {
            const v = lp(V, x, y), q = lp(Q, x, y), r = lp(R, x, y);
            const vein = Math.pow(clamp(1 - Math.abs(v) * 2.1), 3);
            let c = pal(clamp(0.2 + 0.58 * (v * 0.5 + 0.5) + breath));
            c = mix(c, pal(clamp(0.9 + breath)), vein * clamp(q * 1.5) * 0.85);
            px[i] = scale(c, 0.68 + 0.52 * clamp(r));
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-reaction-diffusion',
    since: '0.3.0',
    title: 'Turing Bloom',
    category: 'Fields',
    kind: 'scene',
    tags: ['reaction diffusion', 'gray-scott', 'turing', 'pattern', 'coral', 'mitosis', 'cells'],
    order: 210,
    description: 'A live Gray–Scott dish: spots split, worms crawl and coral fronts advance down a feed-rate gradient, lit by concentration slope.',
    loop: 30,
    canvas: 'field',
    palette: 'viridis',
    credits: 'after Gray & Scott; parameter sweep after Karl Sims',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { width: W, height: H, px } = cv;
      const N = W * H;
      let U = new Float32Array(N).fill(1), Vc = new Float32Array(N);
      let U2 = new Float32Array(N), V2 = new Float32Array(N);
      const rand = ctx.rng;
      // Seed a few dots of catalyst around the dish (lightly, so small dishes survive).
      const blobs = Math.max(2, Math.round(N / 1400));
      for (let b = 0; b < blobs; b++) {
        const bx = Math.floor(rand() * W), by = Math.floor(rand() * H);
        const rr = N < 600 ? 1 : 1 + Math.floor(rand() * 2.4);
        for (let dy = -rr; dy <= rr; dy++) {
          for (let dx = -rr; dx <= rr; dx++) {
            if (dx * dx + dy * dy > rr * rr) continue;
            const j = ((by + dy + H) % H) * W + ((bx + dx + W) % W);
            Vc[j] = 0.9; U[j] = 0.4;
          }
        }
      }
      // Feed/kill sweep down the dish crosses several Pearson regimes.
      const FR = new Float32Array(H), KR = new Float32Array(H);
      for (let y = 0; y < H; y++) {
        const yn = H > 1 ? y / (H - 1) : 0;
        FR[y] = 0.030 + 0.028 * yn;
        KR[y] = 0.057 + 0.006 * yn;
      }
      // Petri-dish lighting baked per pixel, so the field reads even where the
      // chemistry has gone quiet.
      const vign = new Float32Array(N);
      for (let y = 0, i = 0; y < H; y++) {
        for (let x = 0; x < W; x++, i++) {
          const dx = (x / Math.max(1, W - 1)) * 2 - 1, dy = (y / Math.max(1, H - 1)) * 2 - 1;
          vign[i] = 0.78 + 0.22 * clamp(1 - (dx * dx + dy * dy) * 0.55);
        }
      }
      const step = () => {
        for (let y = 0; y < H; y++) {
          const up = (y ? y - 1 : H - 1) * W, dn = (y + 1 < H ? y + 1 : 0) * W, ro = y * W;
          const f = FR[y], k = KR[y];
          for (let x = 0; x < W; x++) {
            const l = x ? x - 1 : W - 1, r = x + 1 < W ? x + 1 : 0;
            const i = ro + x;
            const u = U[i], v = Vc[i];
            const lu = 0.2 * (U[up + x] + U[dn + x] + U[ro + l] + U[ro + r])
              + 0.05 * (U[up + l] + U[up + r] + U[dn + l] + U[dn + r]) - u;
            const lv = 0.2 * (Vc[up + x] + Vc[dn + x] + Vc[ro + l] + Vc[ro + r])
              + 0.05 * (Vc[up + l] + Vc[up + r] + Vc[dn + l] + Vc[dn + r]) - v;
            const uvv = u * v * v;
            U2[i] = u + (lu - uvv + f * (1 - u));
            V2[i] = v + (0.5 * lv + uvv - (f + k) * v);
          }
        }
        let s = U; U = U2; U2 = s;
        s = Vc; Vc = V2; V2 = s;
      };
      for (let n = 0; n < 180; n++) step(); // arrive with the colony already alive
      let acc = 0;
      return (t, dt) => {
        acc += dt * 90; // simulation steps per second
        let n = 0;
        while (acc >= 1 && n < 4) { step(); acc -= 1; n++; }
        if (acc > 4) acc = 0;
        const breath = 0.04 * Math.sin((t / 30) * TAU);
        for (let y = 0, i = 0; y < H; y++) {
          const yd = y + 1 < H ? y + 1 : y;
          for (let x = 0; x < W; x++, i++) {
            const v = Vc[i];
            const gx = Vc[y * W + (x + 1 < W ? x + 1 : x)] - v;
            const gy = Vc[yd * W + x] - v;
            const lit = clamp(0.5 + (gx - gy) * 5.5);
            const c = pal(clamp(v * 2.4, 0, 0.92) + breath + 0.04);
            px[i] = scale(c, (0.55 + 0.75 * lit) * vign[i]);
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'fx-silk-ribbons',
    since: '0.3.0',
    title: 'Silk Ribbons',
    category: 'Fields',
    kind: 'scene',
    tags: ['silk', 'ribbon', 'fabric', 'sheen', 'wave', 'layers', 'translucent'],
    order: 220,
    description: 'Layered silk bands ripple across a dim stage, round in cross-section, translucent at the hems, each chased by a specular sheen.',
    loop: 12,
    canvas: 'field',
    palette: 'synthwave',
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette(undefined, { size: 512 });
      const { noise2 } = ctx.noise;
      const { width: W, height: H, px } = cv;
      const rand = ctx.rng;
      const n = Math.max(2, Math.min(6, Math.floor(H / 13) + 2));
      const base = TAU / 12; // every rate a whole multiple of the loop
      const ribs = [];
      for (let r = 0; r < n; r++) {
        ribs.push({
          cy: H * (0.16 + 0.68 * ((r + 0.5) / n)),
          hue: clamp(0.3 + 0.62 * ((r + rand() * 0.5) / n), 0.12, 0.97),
          k1: ((1.4 + rand() * 1.5) * TAU) / Math.max(24, W),
          k2: ((3 + rand() * 2.4) * TAU) / Math.max(24, W),
          w1: base * (1 + (r % 3)),
          w2: base * (2 + (r % 2) * 3),
          hk: ((0.8 + rand()) * TAU) / Math.max(24, W),
          ph: rand() * TAU,
          ph2: rand() * TAU,
          amp: H * (0.055 + rand() * 0.07),
          th: Math.max(1.1, H * (0.05 + rand() * 0.05)),
          dir: r % 2 ? 1 : -1,
        });
      }
      const bgA = scale(pal(0.04), 0.8), bgB = pal(0.13);
      return (t) => {
        for (let y = 0, i = 0; y < H; y++) {
          const c = mix(bgA, bgB, H > 1 ? y / (H - 1) : 0);
          for (let x = 0; x < W; x++, i++) px[i] = c;
        }
        for (let r = 0; r < n; r++) {
          const R = ribs[r];
          const col = pal(R.hue);
          const hi = mix(col, 0xffffff, 0.72);
          const lo = scale(col, 0.32);
          for (let x = 0; x < W; x++) {
            const yC = R.cy
              + R.amp * Math.sin(x * R.k1 + R.ph + R.dir * R.w1 * t)
              + R.amp * 0.5 * Math.sin(x * R.k2 + R.ph2 - R.dir * R.w2 * t)
              + 1.2 * noise2(x * 0.03, r * 9.1); // static waviness, loop-safe
            const th = R.th * (0.75 + 0.25 * Math.sin(x * R.k2 * 0.7 - R.dir * R.w1 * t + R.ph2));
            const sheen = Math.pow(0.5 + 0.5 * Math.sin(x * R.hk - R.dir * base * 3 * t + R.ph), 10);
            const y0 = Math.max(0, Math.ceil(yC - th)), y1 = Math.min(H - 1, Math.floor(yC + th));
            for (let y = y0; y <= y1; y++) {
              const s = (y - yC) / th;
              const shade = 1 - s * s;
              let c = mix(lo, col, shade);
              c = mix(c, hi, sheen * shade * 0.9);
              const edge = Math.min(1, (1 - Math.abs(s)) * th * 1.8);
              cv.blend(x, y, c, 0.84 * Math.min(1, edge + 0.22));
            }
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

