// Shell completion: a fish-style ghost suggestion from history, then a
// zsh-style completion menu that Tab cycles through, then the command runs.
import { ATTR, glyphs, uni, phase, typed, blink, tint, mix, fit } from './_input.js';

const PS1 = '~/infra $ ';
const HISTORY = [
  ['kubectl get deploy -n checkout', 0],
  ['NAME           READY   UP-TO-DATE   AVAILABLE', 1],
  ['checkout-api   2/3     3            2', 1],
];
const SUGGEST = 'kubectl rollout status deploy/checkout-api';
const SUBS = [
  ['history', 'view rollout history'],
  ['pause', 'mark as paused'],
  ['restart', 'restart a resource'],
  ['resume', 'resume a paused resource'],
  ['status', 'show rollout status'],
  ['undo', 'undo a previous rollout'],
];
// Script (seconds into the loop).
const T = { type1: 0.3, tab1: 1.8, cycle: [2.4, 2.9, 3.4], type2: 3.8, accept: 5.2, enter: 5.8 };

export default {
  id: 'input-autocomplete',
  title: 'Shell Autocomplete',
  category: 'Command Palettes',
  description: 'A shell prompt with a fish-style ghost suggestion from history, a zsh-style completion menu that Tab cycles, then → accepts and the command runs.',
  tags: ['autocomplete', 'completion', 'shell', 'zsh', 'fish'],
  kind: 'tui',
  size: { w: 64, h: 12 },
  minSize: { w: 40, h: 8 },
  loop: 8,
  color: '16',
  order: 20,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx), u = uni(ctx);
      const p = phase(t, 8);
      // Line, ghost text and menu state for this moment (menu: -2 hidden, -1 open, n highlighted).
      let line = typed('kubectl ro', p, T.type1, 7), ghost = '', menu = -2, hint = '';
      if (line && SUGGEST.startsWith(line) && p < T.tab1) {
        ghost = SUGGEST.slice(line.length);
        hint = `${g.right} accept suggestion ${g.mid} tab complete`;
      }
      if (p >= T.tab1) {
        line = 'kubectl rollout ';
        menu = -1;
        T.cycle.forEach((at, i) => { if (p >= at) menu = i; });
        if (menu >= 0) line += SUBS[menu][0];
        hint = menu < 0 ? `tab cycle ${g.mid} ${SUBS.length} completions` : `tab next ${g.mid} enter accept ${g.mid} esc cancel`;
      }
      if (p >= T.type2) {
        menu = -2;
        const arg = typed('deploy/ch', p, T.type2, 9);
        line = 'kubectl rollout restart ' + arg;
        hint = '';
        if (arg.length >= 7) { ghost = 'deploy/checkout-api'.slice(arg.length); hint = `${g.right} accept completion`; }
      }
      if (p >= T.accept) { line = 'kubectl rollout restart deploy/checkout-api'; ghost = ''; hint = `enter run`; }
      const ran = p >= T.enter;

      // History above the prompt, as much as fits with the menu open.
      const room = H - (menu > -2 ? Math.min(SUBS.length, H - 3) + 2 : 3);
      const keep = Math.max(0, Math.min(HISTORY.length, room - 1));
      const hist = keep ? HISTORY.slice(-keep) : [];
      if (keep === HISTORY.length) hist[0] = [PS1 + HISTORY[0][0], 0];
      let y = 0;
      for (const [txt, out] of hist) b.text(0, y++, fit(txt, W, undefined, ctx), out ? th.muted : th.dim);
      if (keep) y++;
      const py = y;

      // The command line scrolls left when it no longer fits.
      const room2 = W - PS1.length - 1;
      const off = Math.max(0, line.length - room2);
      const lx = PS1.length - off;
      const [cmd, ...rest] = line.split(' ');
      let x = b.text(lx, py, cmd, th.pos, undefined, ATTR.BOLD);
      if (rest.length) x = b.text(x, py, ' ' + rest.join(' '), th.ink);
      if (ghost) b.text(x, py, fit(ghost, Math.max(0, W - x), undefined, ctx).trimEnd(), mix(th.bg, th.muted, 0.6));
      // Block cursor over the ghost text (inverse, so it survives NO_COLOR); a bar otherwise.
      if (!ran && blink(t, 0.9)) {
        if (ghost) b.set(x, py, undefined, undefined, undefined, ATTR.INVERSE);
        else b.set(x, py, u ? '▏' : '_', th.ink);
      }
      b.fill(0, py, PS1.length, 1, ' ');
      let px = b.text(0, py, '~/infra', th.info, undefined, ATTR.BOLD);
      b.text(px + 1, py, '$', th.pos, undefined, ATTR.BOLD);
      if (off) b.text(PS1.length - 1, py, u ? '…' : '<', th.dim);

      if (menu > -2) {
        // Menu aligned under the word being completed, as far as the width allows.
        const mw = Math.min(W, 40);
        const mx = Math.max(0, Math.min(W - mw, PS1.length + 'kubectl rollout '.length - 1));
        const rows = Math.min(SUBS.length, H - py - 2);
        const first = Math.max(0, Math.min(SUBS.length - rows, menu - rows + 1));
        for (let r = 0; r < rows; r++) {
          const i = first + r, [name, desc] = SUBS[i];
          const on = i === menu;
          const bg = on ? th.accent : tint(ctx, th.panel2, 0.9);
          b.fill(mx, py + 1 + r, mw, 1, ' ', undefined, bg);
          b.text(mx + 1, py + 1 + r, name.padEnd(9), on ? th.bg : th.ink, bg, ATTR.BOLD);
          b.text(mx + 10, py + 1 + r, fit(`-- ${desc}`, mw - 11, undefined, ctx), on ? th.bg : th.dim, bg);
        }
      } else if (ran) {
        b.text(0, py + 1, fit('deployment.apps/checkout-api restarted', W, undefined, ctx), th.ink);
        if (py + 2 < H) {
          px = b.text(0, py + 2, '~/infra', th.info, undefined, ATTR.BOLD);
          px = b.text(px + 1, py + 2, '$', th.pos, undefined, ATTR.BOLD) + 1;
          if (blink(t, 0.9)) b.set(px, py + 2, u ? '▏' : '_', th.ink);
        }
      }
      if (hint && !ran) b.text(0, H - 1, fit(hint, W, undefined, ctx), th.dim);
    };
  },
};

// A breadcrumb bar whose middle collapses into … as it grows: ←/→ walk the segments, Enter jumps, ↓ opens siblings.
import { ATTR, uni, glyphs, phase, stringWidth } from './_input.js';
import { sub, fitText, inv } from './_kit6.js';

const LOOP = 12;
const FULL = ['prod', 'us-east-1', 'payments', 'api', 'deployments', 'api-7f3c', 'pods', 'api-7f3c-x8k2p'];
const CHILDREN = { payments: ['api', 'worker', 'ledger'], api: ['deployments', 'services', 'config'], deployments: ['api-7f3c', 'api-6e1b'], 'api-7f3c': ['pods', 'events'], pods: ['api-7f3c-x8k2p', 'api-7f3c-m4q9z'], 'api-7f3c-x8k2p': ['logs', 'env', 'events'] };
const SIBLINGS = ['billing', 'payments', 'ledger-svc'];
// [time, key]: drill down five levels (the middle collapses), focus the bar, walk ← to payments, open its siblings, close, Enter trims back.
const KEYS = [[1.0, 'IN'], [2.0, 'IN'], [3.0, 'IN'], [4.0, 'IN'], [5.0, 'IN'], [6.0, 'BAR'], [6.4, 'LEFT'], [6.8, 'LEFT'], [7.2, 'LEFT'], [7.6, 'LEFT'], [7.9, 'LEFT'],
  [8.4, 'DOWN'], [9.4, 'ESC'], [10.0, 'ENTER'], [10.6, 'CONTENT']];

function stateAt(p) {
  let depth = 3, bar = false, focus = 0, sib = false;
  for (const [t, k] of KEYS) {
    if (t > p) break;
    if (k === 'IN') depth = Math.min(FULL.length, depth + 1);
    else if (k === 'BAR') { bar = true; focus = depth - 1; } else if (k === 'LEFT') focus = Math.max(0, focus - 1);
    else if (k === 'DOWN') sib = true; else if (k === 'ESC') sib = false;
    else if (k === 'ENTER') depth = focus + 1; else if (k === 'CONTENT') bar = false;
  }
  return { depth, bar, focus, sib };
}

export default {
  id: 'input-breadcrumbs',
  since: '0.3.0',
  title: 'Breadcrumb Bar',
  category: 'Tabs & Bars',
  description: 'A location breadcrumb whose middle collapses into an ellipsis as it grows: the arrows walk the segments, Enter jumps back to one, and the down arrow opens its siblings.',
  tags: ['breadcrumbs', 'location bar', 'navigation', 'path', 'hierarchy', 'collapse'],
  kind: 'tui',
  size: { w: 72, h: 8 },
  minSize: { w: 40, h: 5 },
  loop: LOOP,
  color: '16',
  order: 200,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx), g = glyphs(ctx), SEP = u ? ' › ' : ' > ', ELL = u ? '…' : '~';   // a 1-col twin: both modes collapse the same segments
      const st = stateAt(phase(t, LOOP)), path = FULL.slice(0, st.depth), last = path.length - 1;
      // which segments show: all if they fit; else the first, …, the last two, and the focused one
      const width = (idx) => idx.reduce((n, i, k) => n + (i < 0 ? stringWidth(ELL) : stringWidth(path[i])) + (k ? stringWidth(SEP) : 0), 0);
      let idx = path.map((_, i) => i);
      if (width(idx) > W) {
        const keep = new Set([0, last - 1, last, st.bar ? st.focus : last]);
        idx = [];
        path.forEach((_, i) => { if (keep.has(i)) idx.push(i); else if (idx[idx.length - 1] !== -1) idx.push(-1); });
        if (width(idx) > W) idx = [0, -1, last];
      }
      let x = 0, fx = 0;
      idx.forEach((i, k) => {
        if (k) x = b.text(x, 0, SEP, sub(th));
        if (i < 0) { x = b.text(x, 0, ELL, th.ink); return; }
        const on = st.bar && i === st.focus, cur = i === last;
        if (on) fx = x;
        if (on) x = inv(ctx, b, x, 0, path[i]); else x = b.text(x, 0, path[i], th.ink, undefined, cur ? ATTR.BOLD : 0);
      });
      b.text(0, 1, (u ? '─' : '-').repeat(W), th.line);
      // the content: this location's items (drops first)
      const kids = CHILDREN[path[last]] ?? [];
      const next = FULL[st.depth];
      if (!(st.bar && st.sib)) kids.slice(0, Math.max(0, H - 3)).forEach((k, i) => {
        const y = 2 + i, on = !st.bar && k === next;
        if (on) { b.text(0, y, '›', th.accent, undefined, ATTR.BOLD); inv(ctx, b, 2, y, ` ${k} `); } else b.text(3, y, k, th.ink);
      });
      // the siblings dropdown under the focused segment
      if (st.bar && st.sib) {
        const sx = Math.max(0, Math.min(W - 16, fx - 1));   // under the focused segment
        SIBLINGS.forEach((s, i) => {
          const y = 2 + i; if (y >= H) return;
          b.fill(sx, y, 16, 1, ' ');
          b.text(sx, y, u ? '│' : '|', th.accent);
          if (s === path[st.focus]) { b.text(sx + 1, y, '›', th.accent, undefined, ATTR.BOLD); inv(ctx, b, sx + 2, y, ` ${s} `); } else b.text(sx + 3, y, s, th.ink);
          b.text(sx + 15, y, u ? '│' : '|', th.accent);
        });
      }
      if (H >= 7) fitText(b, 0, H - 1, W, [`${u ? '←/→' : '</>'} segment ${u ? '·' : '-'} Enter jump ${u ? '·' : '-'} ${u ? '↓' : 'v'} siblings`, 'Enter jump'], sub(th));
    };
  },
};

