// A keyboard-reorderable list: Space grabs a row, the arrows move it while the others make room, Space drops.
import { ATTR, uni, glyphs, phase, stepAt, stringWidth } from './_input.js';

const ITEMS = [['db-primary', 'writer'], ['db-replica', 'reader'], ['api-01', 'stateless'], ['api-02', 'stateless'], ['web-01', 'edge'], ['web-02', 'edge']];
// [time, key]. db-primary is grabbed and carried to the end (it should restart last), dropped, then carried back.
const SCRIPT = [[1.0, 'grab'], [1.6, 'down'], [2.2, 'down'], [2.8, 'down'], [3.4, 'down'], [4.0, 'down'], [4.7, 'drop'],
  [6.5, 'grab'], [7.1, 'up'], [7.7, 'up'], [8.3, 'up'], [8.9, 'up'], [9.5, 'up'], [10.1, 'drop']];
const LOOP = 12;

function stateAt(p) {
  const order = ITEMS.map((_, i) => i);
  let cur = 0, held = false, moved = -Infinity, dropped = -Infinity;
  const n = stepAt(p, SCRIPT.map((s) => s[0]));
  for (let k = 0; k <= n; k++) {
    const key = SCRIPT[k][1];
    if (key === 'grab') held = true;
    else if (key === 'drop') { held = false; dropped = SCRIPT[k][0]; }
    else {
      const to = key === 'down' ? Math.min(order.length - 1, cur + 1) : Math.max(0, cur - 1);
      if (held && to !== cur) { [order[cur], order[to]] = [order[to], order[cur]]; moved = SCRIPT[k][0]; }
      cur = to;
    }
  }
  return { order, cur, held, moved: p - moved, dropped: p - dropped };
}

export default {
  id: 'input-reorder-list',
  since: '0.3.0',
  title: 'Reorderable List',
  category: 'Selects & Lists',
  description: 'Setting a rolling-restart order by keyboard: Space grabs a row, the arrows carry it while the other rows make room and renumber, and Space drops it in its new place.',
  tags: ['reorder', 'sortable', 'drag', 'keyboard', 'list', 'restart order'],
  kind: 'tui',
  size: { w: 52, h: 11 },
  minSize: { w: 34, h: 7 },
  loop: LOOP,
  color: '16',
  order: 220,
  setup(ctx) {
    const th = ctx.theme;
    const sub = th.mode === 'light' ? th.ink : th.muted;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx), g = glyphs(ctx);
      const st = stateAt(phase(t, LOOP)), handles = W >= 40, notes = W >= 44, foot = H >= 7, MID = u ? '·' : '-';
      const top = H >= 10 ? 2 : 0;
      if (top) {
        b.text(0, 0, 'Restart order', th.ink, undefined, ATTR.BOLD);
        const nm = ITEMS[st.order[st.cur]][0];
        const say = (st.held ? [`${MID} moving ${nm}`, `${MID} moving`] : st.dropped < 1.8 ? [`${MID} ${nm} is now #${st.cur + 1}`, `${MID} now #${st.cur + 1}`] : [`${MID} top to bottom`, '']).find((m) => 14 + stringWidth(m) <= W);
        if (say) b.text(14, 0, say, sub);
      }
      const rows = Math.min(ITEMS.length, H - top - (foot ? 1 : 0));
      for (let r = 0; r < rows; r++) {
        const [name, note] = ITEMS[st.order[r]], on = r === st.cur, grabbed = on && st.held, y = top + r;
        const num = `${r + 1}`.padStart(2), handle = handles ? (u ? '⋮⋮' : '::') : '';
        const nudge = grabbed ? 1 : 0;
        b.text(0, y, on ? g.caret : ' ', th.accent, undefined, ATTR.BOLD);
        b.text(2, y, num, sub);
        let x = 5 + nudge;
        if (handles) { b.text(x, y, handle, grabbed ? th.accent : sub, undefined, grabbed ? ATTR.BOLD : 0); x += 3; }
        const text = `${name}${notes ? ` ${MID} ${note}` : ''}`;
        if (grabbed) {
          const mark = u ? '≡' : '=';
          b.text(x, y, ` ${text} `.padEnd(Math.min(W - x - 3, 26)), th.ink, undefined, ATTR.INVERSE | ATTR.BOLD);
          b.text(Math.min(W - 2, x + Math.min(W - x - 3, 26) + 1), y, mark, th.accent, undefined, ATTR.BOLD);
        } else {
          b.text(x + 1, y, name, th.ink, undefined, on ? ATTR.BOLD | ATTR.UNDERLINE : 0);
          if (notes) b.text(x + 1 + stringWidth(name), y, ` ${MID} ${note}`, sub);
        }
      }
      if (foot) {
        const keys = [`Space grab ${MID} ${u ? '↑↓' : '^v'} move ${MID} Space drop`, `Space grab/drop ${MID} ${u ? '↑↓' : '^v'}`];
        const k = keys.find((s) => stringWidth(s) <= W);
        if (k) b.text(0, H - 1, k, sub);
      }
    };
  },
};

// A service list with row actions: the selected row shows Restart / Logs / Delete, and a delete can be undone.
import { ATTR, uni, glyphs, phase, stepAt, stringWidth } from './_input.js';

const SERVICES = [['api', 'running', 3, 3], ['web', 'running', 4, 4], ['worker', 'degraded', 1, 3], ['cron', 'stopped', 0, 1], ['mailer', 'running', 2, 2], ['search', 'running', 2, 2]];
const UNDO_S = 5, LOOP = 12;
// [time, key]. Walk the rows, come back to api, open its actions, delete it, undo 3 s in, close the actions.
const SCRIPT = [[1.0, 'down'], [1.5, 'down'], [2.0, 'up'], [2.5, 'up'], [3.0, 'open'], [3.8, 'delete'], [7.0, 'undo'], [8.6, 'close']];

function stateAt(p) {
  let cur = 0, open = false, deleted = -1, delAt = -Infinity, undoAt = -Infinity;
  const n = stepAt(p, SCRIPT.map((s) => s[0]));
  for (let k = 0; k <= n; k++) {
    const key = SCRIPT[k][1];
    if (key === 'down') cur = Math.min(SERVICES.length - 1, cur + 1);
    else if (key === 'up') cur = Math.max(0, cur - 1);
    else if (key === 'open') open = true;
    else if (key === 'close') open = false;
    else if (key === 'delete') { deleted = cur; delAt = SCRIPT[k][0]; open = false; }
    else if (key === 'undo') { deleted = -1; undoAt = SCRIPT[k][0]; open = true; }
  }
  return { cur, open, deleted, sinceDel: p - delAt, sinceUndo: p - undoAt };
}

export default {
  id: 'input-row-actions',
  since: '0.3.0',
  title: 'List with Row Actions',
  category: 'Selects & Lists',
  description: 'A service list where the selected row shows inline actions, restart, logs and delete: a delete collapses the row behind an undo countdown, and undo brings it back.',
  tags: ['row actions', 'inline actions', 'undo', 'delete', 'list', 'services'],
  kind: 'tui',
  size: { w: 64, h: 12 },
  minSize: { w: 40, h: 8 },
  loop: LOOP,
  color: '16',
  order: 250,
  setup(ctx) {
    const th = ctx.theme;
    const sub = th.mode === 'light' ? th.ink : th.muted;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx), g = glyphs(ctx);
      const st = stateAt(phase(t, LOOP)), MID = u ? '·' : '-', labels = W >= 56, statusWords = W >= 48;
      const top = H >= 10 ? 2 : 0;
      if (top) {
        b.text(0, 0, 'Services', th.ink, undefined, ATTR.BOLD);
        b.text(9, 0, `${MID} prod-east ${MID} ${SERVICES.length - (st.deleted >= 0 ? 1 : 0)} services`, sub);
      }
      // the delete collapses the row (it dims, then the rows below close up) behind an undo bar
      const collapsing = st.deleted >= 0 && st.sinceDel < 0.35;
      const rows = SERVICES.map((s, i) => i).filter((i) => i !== st.deleted || collapsing);
      // with the selected row deleted, the cursor rests on the row that took its place
      const cur = st.deleted === st.cur && !collapsing ? SERVICES.findIndex((_, i) => i > st.cur && i !== st.deleted) : st.cur;
      const DEL = u ? '×' : '-';
      rows.forEach((i, r) => {
        const [name, state, up, want] = SERVICES[i], y = top + r, gone = i === st.deleted, on = i === cur && (!gone || collapsing);
        const [dot, dc] = state === 'running' ? [u ? '●' : '*', th.pos] : state === 'degraded' ? [u ? '◐' : '~', th.warn] : [u ? '○' : '-', sub];
        b.text(0, y, on ? g.caret : ' ', th.accent, undefined, ATTR.BOLD);
        const nameW = 10, line = `${name.padEnd(nameW)}`;
        b.text(2, y, line, gone ? sub : th.ink, undefined, on ? ATTR.INVERSE | ATTR.BOLD : gone ? ATTR.STRIKE : 0);
        b.text(2 + nameW + 1, y, dot, gone ? sub : dc, undefined, ATTR.BOLD);
        const sx = 2 + nameW + 3, stTxt = statusWords ? `${state.padEnd(9)}${up}/${want}` : `${up}/${want}`;
        b.text(sx, y, stTxt, gone ? sub : th.ink, undefined, gone ? ATTR.STRIKE : 0);
        if (gone) { const dx = b.text(sx + stringWidth(stTxt) + 2, y, DEL, th.neg, undefined, ATTR.BOLD); b.text(dx + 1, y, 'deleting', th.ink, undefined, ATTR.BOLD); }
        if (on && st.open && !gone) {
          // inline actions on the selected row; labels shrink to their keys when narrow
          let ax = sx + stringWidth(stTxt) + 2;
          const acts = labels ? [['r', 'estart'], ['l', 'ogs'], ['d', 'elete']] : [['r', ''], ['l', ''], ['d', '']];
          acts.forEach(([key, rest], j) => {
            if (j === 2) ax = b.text(ax, y, u ? '×' : '-', th.neg, undefined, ATTR.BOLD) + 1;
            ax = b.text(ax, y, `[${key}]`, th.ink, undefined, ATTR.BOLD);
            ax = b.text(ax, y, rest, th.ink) + (labels ? 1 : 0);
          });
        }
      });
      // the undo bar, counting down; undo restores the row where it was
      const by = H - 1;
      if (st.deleted >= 0) {
        const left = Math.max(0, Math.ceil(UNDO_S - st.sinceDel)), name = SERVICES[st.deleted][0];
        let x = b.text(0, by, g.warn, th.warn, undefined, ATTR.BOLD);
        const msg = [`Deleted ${name} ${MID} u to undo (${left}s)`, `Deleted ${name} ${MID} u undo ${left}s`].find((m) => stringWidth(m) + 2 <= W);
        const end = b.text(x + 1, by, msg ?? `u undo ${left}s`, th.ink, undefined, ATTR.BOLD), bw = Math.min(10, W - end - 2);
        if (bw >= 3) { const f = Math.max(0, 1 - st.sinceDel / UNDO_S) * bw; for (let i = 0; i < bw; i++) b.set(end + 2 + i, by, i < Math.round(f) ? (u ? '█' : '#') : (u ? '░' : '.'), i < Math.round(f) ? th.warn : th.muted); }
      } else if (st.sinceUndo < 1.4) {
        const x = b.text(0, by, g.check, th.pos, undefined, ATTR.BOLD);
        b.text(x + 1, by, `Restored ${SERVICES[st.cur][0]}`, th.ink, undefined, ATTR.BOLD);
      } else if (H >= 10) {
        b.text(0, by, `${u ? '↑/↓' : '^/v'} move ${MID} enter actions ${MID} r l d`, sub);
      }
    };
  },
};

// A save-as dialog: places, a folder listing, a filename field and a type select; an existing name turns Save into Replace.
import { ATTR, uni, glyphs, phase, panel, stringWidth } from './_input.js';
import { sub, fitText, inv } from './_kit6.js';

const LOOP = 14, NAME = 'q4-latency.csv';
const PLACES = ['home', '/srv/reports', 'recent'];
const FILES = {
  home: [['Documents/', '', ''], ['Downloads/', '', ''], ['notes.md', '4 KB', 'Nov 10']],
  '/srv/reports': [['q3-latency.csv', '1.2 MB', 'Oct 2'], ['q4-latency.csv', '1.4 MB', 'Nov 9'], ['q4-errors.csv', '220 KB', 'Nov 9'], ['README.md', '2 KB', 'Sep 1']],
};
// [time, key]: down to /srv/reports, Tab to the name, type an existing name, edit it to -v2, Enter saves, then reset.
const KEYS = (() => {
  const out = [[1.2, 'DOWN'], [2.0, 'TAB']];
  let t = 2.4;
  for (const c of NAME) { out.push([t, c]); t += 0.15; }
  t = 7.2; for (let i = 0; i < 4; i++) { out.push([t, 'BS']); t += 0.15; }
  t = 8.0; for (const c of '-v2.csv') { out.push([t, c]); t += 0.14; }
  out.push([9.8, 'ENTER'], [12.6, 'RESET']);
  return out;
})();

function stateAt(p) {
  let place = 0, focus = 'places', name = '', saved = -Infinity;
  for (const [t, k] of KEYS) {
    if (t > p) break;
    if (k === 'DOWN') place = Math.min(PLACES.length - 1, place + 1);
    else if (k === 'TAB') focus = 'name';
    else if (k === 'BS') name = name.slice(0, -1);
    else if (k === 'ENTER') saved = t;
    else if (k === 'RESET') { place = 0; focus = 'places'; name = ''; saved = -Infinity; }
    else name += k;
  }
  const files = FILES[PLACES[place]] ?? [];
  return { place, focus, name, files, exists: files.some(([f]) => f === name), saved: saved > -Infinity ? p - saved : -1 };
}

export default {
  id: 'input-save-dialog',
  since: '0.3.0',
  title: 'Save Dialog',
  category: 'Dialogs & Prompts',
  description: 'A save-as dialog with places, a folder listing, a filename field and a type select: typing a name that already exists turns Save into Replace until the name changes.',
  tags: ['save as', 'file dialog', 'overwrite', 'filename', 'dialog', 'form'],
  kind: 'tui',
  size: { w: 64, h: 14 },
  minSize: { w: 44, h: 10 },
  loop: LOOP,
  color: '16',
  order: 200,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, u = uni(ctx), g = glyphs(ctx);
      const st = stateAt(phase(t, LOOP)), inner = panel(ctx, b, 0, 0, W, H, { title: 'Save report as', color: th.accent, titleColor: th.ink });
      const iw = inner.width, ih = inner.height, places = iw >= 56, cols = iw >= 50;
      const listX = places ? 17 : 0, rows = Math.max(1, ih - 5);
      // places: the selected place is ink-inverse while the places list has focus
      if (places) {
        inner.text(0, 0, 'Places', th.ink, undefined, ATTR.BOLD);
        PLACES.forEach((pl, i) => {
          const on = i === st.place, y = 1 + i;
          if (on && st.focus === 'places') { inner.text(0, y, '›', th.accent, undefined, ATTR.BOLD); inv(ctx, inner, 1, y, ` ${pl} `); }
          else inner.text(2, y, pl, th.ink, undefined, on ? ATTR.BOLD : 0);
        });
        for (let y = 0; y < rows + 1; y++) inner.text(15, y, u ? '│' : '|', th.line);
      }
      // the listing; size and date columns drop before the rows do
      if (!places && st.focus === 'places') { inner.text(listX, 0, '›', th.accent, undefined, ATTR.BOLD); inv(ctx, inner, listX + 1, 0, ` ${PLACES[st.place]} `); }   // Places hidden: its focus shows on the folder
      else inner.text(listX, 0, PLACES[st.place], th.ink, undefined, ATTR.BOLD);
      st.files.slice(0, rows).forEach(([f, sz, dt], i) => {
        const y = 1 + i, hit = f === st.name;
        inner.text(listX, y, f, th.ink, undefined, hit ? ATTR.BOLD | ATTR.UNDERLINE : 0);
        if (cols && sz) { inner.text(iw - 16, y, sz.padStart(7), sub(th)); inner.text(iw - 7, y, dt.padStart(6), sub(th)); }
      });
      // the name field and the type select
      const fy = ih - 3, nameFocus = st.focus === 'name';
      let x = inner.text(0, fy, 'Name', th.ink, undefined, ATTR.BOLD);
      const fw = Math.max(12, iw - 20);
      x = inner.text(x + 1, fy, '[', nameFocus ? th.accent : th.line, undefined, ATTR.BOLD);
      const shown = st.name.length > fw - 2 ? st.name.slice(-(fw - 2)) : st.name;
      inner.text(x + 1, fy, shown, th.ink);
      if (nameFocus && st.saved < 0) inner.text(x + 1 + stringWidth(shown), fy, u ? '▏' : '_', th.ink, undefined, ATTR.BOLD);
      inner.text(x + fw, fy, ']', nameFocus ? th.accent : th.line, undefined, ATTR.BOLD);
      inner.text(x + fw + 2, fy, `[CSV ${g.triDown}]`, th.ink);
      // the overwrite warning, and the buttons: Save becomes Replace while the name exists
      const wy = ih - 2, by = ih - 1;
      if (st.saved >= 0) { const c = inner.text(0, wy, g.check, th.pos, undefined, ATTR.BOLD); fitText(inner, c + 1, wy, iw - c - 1, [`saved ${st.name}`, 'saved'], th.ink); }
      else if (st.exists) { const c = inner.text(0, wy, g.warn, th.warn, undefined, ATTR.BOLD); fitText(inner, c + 1, wy, iw - c - 1, [`${st.name} exists ${u ? '—' : '-'} Replace?`, 'exists - Replace?'.replace('-', u ? '—' : '-')], th.ink); }
      const label = st.exists ? 'Replace' : 'Save', primary = `[ ${label} ]`;
      const px = iw - stringWidth(primary), cx = px - 12;
      inner.text(cx, by, '[ Cancel ]', th.ink);
      if (nameFocus && st.name) { inv(ctx, inner, px, by, primary); } else inner.text(px, by, primary, th.ink, undefined, ATTR.BOLD);
    };
  },
};

// A long list in a short window: the cursor runs down, the view scrolls, the
// scrollbar thumb tracks it.
import { ATTR, glyphs, phase, panel, scrollbar, tint, fit } from './_input.js';

const PODS = Array.from({ length: 26 }, (_, i) => {
  const svc = ['checkout', 'payments', 'catalog', 'search', 'cart', 'auth', 'orders', 'notify'][i % 8];
  return [`${svc}-7d9f${(i * 7919 % 9000 + 1000).toString(36)}`, ['Running', 'Running', 'Running', 'Pending', 'Running'][i % 5], `${(i * 13) % 59 + 1}m`];
});

export default {
  id: 'input-scroll-list',
  title: 'Scrolling List',
  category: 'Selects & Lists',
  description: 'A long pod list in a short framed window: the cursor runs down and back, the view scrolls with it and the scrollbar thumb tracks position.',
  tags: ['list', 'scroll', 'scrollbar', 'pods', 'cursor'],
  kind: 'tui',
  size: { w: 52, h: 12 },
  minSize: { w: 34, h: 6 },
  loop: 10,
  color: '16',
  order: 30,
  setup(ctx) {
    const th = ctx.theme;
    return (t) => {
      const b = ctx.buffer, W = ctx.width, H = ctx.height, g = glyphs(ctx);
      const p = phase(t, 10);
      const pos = p < 5 ? p / 5 : 1 - (p - 5) / 5;
      const cur = Math.round(pos * (PODS.length - 1));
      const inner = panel(ctx, b, 0, 0, W, H, { title: 'pods', footer: `${cur + 1}/${PODS.length}`, color: th.line });
      const vis = inner.height;
      const first = Math.max(0, Math.min(PODS.length - vis, cur - Math.floor(vis / 2)));
      for (let r = 0; r < vis; r++) {
        const i = first + r;
        if (i >= PODS.length) break;
        const [name, status, age] = PODS[i];
        const on = i === cur;
        if (on) inner.fill(0, r, inner.width - 1, 1, ' ', undefined, tint(ctx, th.accent, 0.16));
        inner.text(0, r, on ? g.pointer : ' ', th.accent, undefined, ATTR.BOLD);
        inner.text(2, r, fit(name, Math.max(4, inner.width - 18), undefined, ctx), on ? th.ink : th.muted, undefined, on ? ATTR.BOLD : 0);
        inner.text(inner.width - 15, r, status.padEnd(8), status === 'Running' ? th.pos : th.warn);
        inner.text(inner.width - 5, r, age.padStart(3), th.dim);
      }
      scrollbar(ctx, inner, inner.width - 1, 0, vis, PODS.length, first, vis);
    };
  },
};

