    tags: ['braille', 'ecg', 'heartbeat', 'health', 'original'], labels: ['Health check passing…', 'Monitoring vitals…'] }),
  spinnerFacet({ id: 'loaders-pong', name: 'pong', title: 'Pong', category: O, order: 100,
