// World Maps: a dotted world with pulsing data centers, a follow-the-sun
// choropleth of pseudo-regions, and a day/night terminator with city lights.
import { mix } from '../../color.js';
import { glyphs, put, putR, safe, clamp, smooth, NONE, ATTR } from '../charts/_data.js';
import { project, landMask, coastOf, inLand, HUBS } from './_world.js';

const RAD = Math.PI / 180;

/** Simulated UTC hour for a time t (hoursPerSecond of sim time), starting at 14:00. */
const utcHour = (t, hps) => (14 + t * hps) % 24;
const hhmm = (h) => `${String(Math.floor(h) % 24).padStart(2, '0')}:${String(Math.floor((h % 1) * 60)).padStart(2, '0')}`;

const cities = {
  id: 'maps-world-cities',
  title: 'Data Center Map',
  category: 'World Maps',
  description: 'A dotted braille world map with pulsing data-center markers, health-colored ripples, region codes and a live traffic footer.',
  tags: ['world map', 'braille', 'data centers', 'pulse', 'regions'],
  kind: 'scene',
  size: { w: 80, h: 22 },
  minSize: { w: 40, h: 10 },
  loop: 12,
  glyphs: 'braille',
  canvas: 'line',
  order: 10,
  setup(ctx) {
    const th = ctx.theme, g = glyphs(ctx), W = ctx.width, H = ctx.height, b = safe(ctx.buffer, g);
    const foot = H >= 14 ? 2 : 0;
    const rows = H - foot;
    const cv = ctx.canvas('line', { cols: W, rows });
    const P = project(cv, { stretch: 1.25 });
    const mask = landMask(cv, P), coast = coastOf(mask, cv.width, cv.height);
    // A dot lattice reads as "map" without turning continents into solid blobs.
    const landPx = [];
    for (let y = 0; y < cv.height; y++) for (let x = 0; x < cv.width; x++) {
      const i = y * cv.width + x;
      if (coast[i]) landPx.push(i, 1);
      else if (mask[i] && x % 2 === 0 && y % 2 === 0) landPx.push(i, 0);
    }
    const landC = mix(th.bg, th.muted, 0.55), coastC = mix(th.bg, th.muted, 0.85);
    const sites = HUBS.slice(0, W >= 60 ? 12 : 8).map(([code, , lon, lat], i) => ({ code, x: P.x(lon), y: P.y(lat), ph: i * 0.37, lon }));
    // Health over the loop: Mumbai degrades for a while, Sao Paulo blips.
    const health = (s, lt) => (s.code === 'BOM' && lt > 4 && lt < 9 ? 'warn' : s.code === 'GRU' && lt > 7.5 && lt < 8.5 ? 'neg' : 'pos');
    const labelDx = { LHR: -4, FRA: 1, IAD: 1, DFW: -4, PDX: -4, NRT: 1, SIN: -4, SYD: 1, BOM: -4, JNB: 1, GRU: 1, SCL: -4 };
    return (t) => {
      const lt = t % 12;
      cv.clear();
      const px = cv.px;
      for (let k = 0; k < landPx.length; k += 2) px[landPx[k]] = landPx[k + 1] ? coastC : landC;
      for (const s of sites) {
        const c = th[health(s, lt)];
        const cycle = ((t * 0.5 + s.ph) % 1);
        const r = 1.5 + cycle * (s.code === 'BOM' && health(s, lt) !== 'pos' ? 11 : 7);
        cv.ellipse(s.x, s.y, r, r / cv.aspect, mix(th.bg, c, 1 - smooth(cycle) * 0.85));
        for (let dy = -1; dy <= 0; dy++) for (let dx = -1; dx <= 0; dx++) cv.set(s.x + dx + 0.5, s.y + dy + 0.5, 0xffffff);
      }
      cv.paint(b);
      if (W >= 60) {
        for (const s of sites) {
          const cx = Math.round(s.x / cv.sx) + labelDx[s.code], cy = Math.round(s.y / cv.sy);
          if (cy >= 0 && cy < rows && cx >= 0 && cx + 3 <= W) b.text(cx, cy, s.code, health(s, lt) === 'pos' ? th.ink : th[health(s, lt)], undefined, ATTR.BOLD);
        }
      }
      if (foot) {
        const y = H - 2;
        const bad = sites.filter((s) => health(s, lt) !== 'pos');
        let x = b.text(0, y, g.dot, th.pos);
        x = b.text(x + 1, y, `${sites.length - bad.length} healthy`, th.muted);
        for (const s of bad) { x = b.text(x + 3, y, g.dot, th[health(s, lt)]); x = b.text(x + 1, y, `${s.code} ${health(s, lt) === 'warn' ? 'degraded' : 'down'}`, th[health(s, lt)], undefined, ATTR.BOLD); }
        const rps = 1.18 + 0.12 * Math.sin(t * 0.9) + 0.03 * ctx.noise.noise2(t, 3);
        if (W >= 70) putR(b, W, y, `edge ${rps.toFixed(2)}M req/s · p50 ${Math.round(38 + 6 * Math.sin(t * 0.7))} ms`, th.muted);
        put(b, 0, H - 1, `${sites.length} regions · ${sites.length * 3} zones · anycast 192.0.2.0/24`, W, th.dim);
      }
    };
  },
};

const choropleth = {
  id: 'maps-world-choropleth',
  title: 'Follow-the-Sun Choropleth',
  category: 'World Maps',
  description: 'Active users by region as a choropleth of pseudo-regions: demand rolls west with the daylight while a legend and UTC clock keep score.',
  tags: ['choropleth', 'world map', 'regions', 'diurnal', 'half blocks'],
  kind: 'scene',
  size: { w: 80, h: 22 },
  minSize: { w: 40, h: 10 },
  loop: 12,
  canvas: 'field',
  palette: 'viridis',
  order: 20,
  setup(ctx) {
    const th = ctx.theme, g = glyphs(ctx), W = ctx.width, H = ctx.height, b = safe(ctx.buffer, g);
    const foot = H >= 14 ? 2 : 1;
    const rows = H - foot;
    const cv = ctx.canvas('field', { cols: W, rows });
    const P = project(cv, { stretch: 1.25 });
    const mask = landMask(cv, P);
    // Pseudo-regions: Voronoi cells around seeded land points, each with a population weight.
    const seeds = [];
    while (seeds.length < 64) {
      const lon = ctx.rng.range(-170, 180), lat = ctx.rng.range(-55, 75);
      if (inLand(lon, lat)) seeds.push({ lon, lat, x: P.x(lon), y: P.y(lat), pop: 0.25 + 0.75 * ctx.rng() ** 1.6 });
    }
    const region = new Int16Array(cv.width * cv.height).fill(-1);
    for (let y = 0; y < cv.height; y++) for (let x = 0; x < cv.width; x++) {
      const i = y * cv.width + x;
      if (!mask[i]) continue;
      let best = 0, bd = Infinity;
      for (let k = 0; k < seeds.length; k++) { const dx = seeds[k].x - x, dy = (seeds[k].y - y) / cv.aspect; const d = dx * dx + dy * dy; if (d < bd) { bd = d; best = k; } }
      region[i] = best;
    }
    const border = new Uint8Array(cv.width * cv.height);
    for (let y = 1; y < cv.height; y++) for (let x = 1; x < cv.width; x++) {
      const i = y * cv.width + x;
      if (region[i] >= 0 && ((region[i - 1] >= 0 && region[i - 1] !== region[i]) || (region[i - cv.width] >= 0 && region[i - cv.width] !== region[i]))) border[i] = 1;
    }
    const pal = ctx.palette('viridis');
    const CLASSES = 6, LIMITS = ['<5k', '5k', '20k', '50k', '100k', '200k+'];
    const ocean = mix(th.bg, th.info, 0.08);
    const cls = new Uint8Array(seeds.length);
    const shades = Array.from({ length: CLASSES }, (_, k) => pal(0.12 + (k / (CLASSES - 1)) * 0.86));
    const borderC = shades.map((c) => mix(c, th.bg, 0.45));
    return (t) => {
      const hour = utcHour(t, 2);
      let total = 0;
      for (let k = 0; k < seeds.length; k++) {
        const local = (hour + seeds[k].lon / 15 + 24) % 24;
        // Usage peaks in the evening and bottoms out before dawn.
        const day = 0.08 + 0.92 * Math.max(0, Math.sin(((local - 7) / 17) * Math.PI)) ** 1.3 * (local > 7 ? 1 : 0);
        const v = seeds[k].pop * day;
        total += v * 380;
        cls[k] = clamp(Math.floor(v * CLASSES * 1.05), 0, CLASSES - 1);
      }
      cv.clear(ocean);
      const px = cv.px;
      for (let i = 0; i < px.length; i++) { const r = region[i]; if (r >= 0) px[i] = border[i] ? borderC[cls[r]] : shades[cls[r]]; }
      if (cv.mode === 'ascii') {
        // One pixel per cell: the class as a density glyph over a tinted cell, so it reads with or without color.
        for (let y = 0; y < cv.height; y++) for (let x = 0; x < cv.width; x++) {
          const i = y * cv.width + x, r = region[i];
          if (r < 0) b.set(x, y, ' ', undefined, ocean);
          else b.set(x, y, '.:-=+#'[cls[r]], shades[cls[r]], mix(th.bg, shades[cls[r]], border[i] ? 0.15 : 0.35));
        }
      } else cv.paint(b);
      const y = H - foot;
      let x = b.text(0, y, 'users', th.muted);
      const sw = W >= 70 ? 6 : 3;
      for (let k = 0; k < CLASSES; k++) {
        for (let j = 0; j < sw; j++) b.set(x + 1 + k * sw + j, y, g.u ? '█' : '#', shades[k]);
        if (foot > 1 && sw >= 6) b.text(x + 1 + k * sw, y + 1, LIMITS[k], th.dim);
      }
      putR(b, W, y, `UTC ${hhmm(hour)}`, th.ink, undefined, ATTR.BOLD);
      if (foot > 1 && W >= 70) putR(b, W, y + 1, `${(total / 1000).toFixed(2)}M active`, th.muted);
    };
  },
};

const daynight = {
  id: 'maps-world-daynight',
  title: 'Day / Night Terminator',
  category: 'World Maps',
  description: 'The sun sweeps west over a half-block world: a soft terminator with twilight, city lights on the night side and world clocks below.',
  tags: ['terminator', 'day night', 'world clock', 'sun', 'city lights'],
  kind: 'scene',
  size: { w: 80, h: 22 },
  minSize: { w: 40, h: 10 },
  loop: 12,
  canvas: 'field',
  order: 30,
  setup(ctx) {
    const th = ctx.theme, g = glyphs(ctx), W = ctx.width, H = ctx.height, b = safe(ctx.buffer, g);
    const foot = H >= 14 ? 2 : 1;
    const rows = H - foot;
    const cv = ctx.canvas('field', { cols: W, rows });
    const P = project(cv, { stretch: 1.25 });
    const mask = landMask(cv, P);
    const decl = -7.8 * RAD; // mid-October
    // Per-pixel sin/cos of latitude and longitude, computed once.
    const N = cv.width * cv.height;
    const sLat = new Float32Array(N), cLat = new Float32Array(N), lonA = new Float32Array(N), inMap = new Uint8Array(N);
    for (let y = 0; y < cv.height; y++) for (let x = 0; x < cv.width; x++) {
      const i = y * cv.width + x, lat = P.lat(y + 0.5), lon = P.lon(x + 0.5);
      if (lat > P.view.lat0 || lat < P.view.lat1 || lon < -180 || lon > 180) continue;
      inMap[i] = 1; sLat[i] = Math.sin(lat * RAD); cLat[i] = Math.cos(lat * RAD); lonA[i] = lon * RAD;
    }
    const dayLand = mix(th.bg, th.pos, 0.42), nightLand = mix(th.bg, th.line, 0.55);
    const daySea = mix(th.bg, th.info, 0.3), nightSea = mix(th.bg, th.info, 0.06);
    const dusk = mix(th.bg, th.warn, 0.35);
    const LV = 16;
    const ramp = (a, c) => Array.from({ length: LV + 1 }, (_, k) => mix(a, c, k / LV));
    const landR = ramp(nightLand, dayLand), seaR = ramp(nightSea, daySea);
    const lights = [];
    while (lights.length < 46) {
      const lon = ctx.rng.range(-125, 150), lat = ctx.rng.range(-40, 60);
      if (inLand(lon, lat)) lights.push([P.x(lon), P.y(lat), lon * RAD, lat * RAD, ctx.rng()]);
    }
    for (const [, , lon, lat] of HUBS) lights.push([P.x(lon), P.y(lat), lon * RAD, lat * RAD, 1]);
    const clocks = ['PDX', 'IAD', 'LHR', 'BOM', 'SIN', 'NRT', 'SYD'];
    // ASCII terminals get one glyph per cell instead of half-block pixels.
    const glyph = cv.mode === 'ascii' ? new Array(N).fill(' ') : null;
    return (t) => {
      const hour = utcHour(t, 2);
      const sunLon = ((12 - hour) * 15) * RAD;
      const sD = Math.sin(decl), cD = Math.cos(decl);
      const px = cv.px;
      for (let i = 0; i < N; i++) {
        if (!inMap[i]) { px[i] = NONE; continue; }
        const z = sLat[i] * sD + cLat[i] * cD * Math.cos(lonA[i] - sunLon);
        const k = clamp((z + 0.12) / 0.24, 0, 1);
        const base = mask[i] ? landR[Math.round(smooth(k) * LV)] : seaR[Math.round(smooth(k) * LV)];
        px[i] = Math.abs(z) < 0.05 && mask[i] ? mix(base, dusk, 0.5) : base;
        if (glyph) glyph[i] = mask[i] ? (k > 0.5 ? '#' : ':') : k > 0.5 ? '~' : ' ';
      }
      for (const [x, y, lon, lat, w] of lights) {
        const z = Math.sin(lat) * sD + Math.cos(lat) * cD * Math.cos(lon - sunLon);
        if (z < -0.04) {
          cv.set(x, y, mix(nightLand, th.warn, clamp(0.25 + w * 0.6 + 0.08 * Math.sin(t * 3 + x), 0, 1)));
          if (glyph) glyph[Math.floor(y) * cv.width + Math.floor(x)] = '*';
        }
      }
      if (glyph) {
        for (let y = 0; y < cv.height; y++) for (let x = 0; x < cv.width; x++) {
          const i = y * cv.width + x;
          if (inMap[i]) b.set(x, y, glyph[i], glyph[i] === '*' ? px[i] : mix(px[i], th.ink, 0.25), px[i]);
        }
      } else cv.paint(b);
      // The subsolar point.
      const sx = Math.round(P.x(((sunLon / RAD) + 540) % 360 - 180) / cv.sx), sy = Math.round(P.y(decl / RAD) / cv.sy);
      if (sx >= 0 && sx < W && sy >= 0 && sy < rows) b.set(sx, sy, g.u ? '☼' : '*', 0xffffff, undefined, ATTR.BOLD);
      // World clocks.
      const y = H - foot;
      const per = Math.floor(W / clocks.length);
      clocks.forEach((code, i) => {
        const h = HUBS.find((c) => c[0] === code);
        const local = (hour + Math.round(h[2] / 15) + 24) % 24;
        const z = Math.sin(h[3] * RAD) * sD + Math.cos(h[3] * RAD) * cD * Math.cos(h[2] * RAD - sunLon);
        const day = z > 0;
        if (per >= 10) {
          b.text(i * per, y, code, th.muted);
          b.text(i * per + 4, y, hhmm(local), day ? th.ink : th.info, undefined, ATTR.BOLD);
          if (foot > 1) b.text(i * per, y + 1, day ? (g.u ? '☼ day' : 'day') : (g.u ? '☾ night' : 'night'), day ? th.warn : th.dim);
        } else if (i < 4) b.text(i * 10, y, `${code} ${hhmm(local)}`, day ? th.ink : th.info);
      });
    };
  },
};

export default [cities, choropleth, daynight];

sources.prism-term/src/facets/objects/_raster.js:
// Shared software-3D helpers for the objects/sim/lab galleries: a z-buffered
// triangle rasterizer with interpolated intensity (flat or Gouraud), a mesh
// drawer with camera-facing lighting normals, an analytic lit sphere, and a
// deterministic star backdrop. Everything writes straight into a Canvas.

import { NONE, luminance } from '../../color.js';

export function zbuffer(cv) {
  const z = new Float32Array(cv.width * cv.height);
  z.fill(Infinity);
  return z;
}

/**
 * Fill a triangle. a/b/c are projected [x, y, depth] (smaller depth = nearer);
 * ia/ib/ic are per-vertex values interpolated into shade(value, x, y) → color.
 */
export function tri(cv, z, a, b, c, ia, ib, ic, shade) {
  const W = cv.width, H = cv.height, px = cv.px;
  const x0 = Math.max(0, Math.floor(Math.min(a[0], b[0], c[0])));
  const x1 = Math.min(W - 1, Math.ceil(Math.max(a[0], b[0], c[0])));
  const y0 = Math.max(0, Math.floor(Math.min(a[1], b[1], c[1])));
  const y1 = Math.min(H - 1, Math.ceil(Math.max(a[1], b[1], c[1])));
  const area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
  if (!(Math.abs(area) > 1e-9) || x0 > x1 || y0 > y1) return;
  const inv = 1 / area;
  for (let y = y0; y <= y1; y++) {
    const py = y + 0.5;
    for (let x = x0; x <= x1; x++) {
      const pxc = x + 0.5;
      const w0 = ((b[0] - pxc) * (c[1] - py) - (b[1] - py) * (c[0] - pxc)) * inv;
      const w1 = ((c[0] - pxc) * (a[1] - py) - (c[1] - py) * (a[0] - pxc)) * inv;
      const w2 = 1 - w0 - w1;
      if (w0 < -1e-4 || w1 < -1e-4 || w2 < -1e-4) continue;
      const d = w0 * a[2] + w1 * b[2] + w2 * c[2];
      const i = y * W + x;
      if (d >= z[i]) continue;
      const col = shade(w0 * ia + w1 * ib + w2 * ic, x, y);
      if (col === NONE) continue;
      z[i] = d;
      px[i] = col;
    }
  }
}

const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const norm = (a) => { const l = Math.hypot(a[0], a[1], a[2]) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
export { sub, cross, dot, norm };

/**
 * Draw a polygon mesh. `transform` maps model → camera space (camera at
 * z = -distance looking +z), `project` maps camera space → [x, y, depth].
 * Normals are oriented towards the camera, which for a closed mesh behind a
 * z-buffer is the outward normal of every visible face.
 *   light      unit vector pointing *towards* the light, camera space
 *   shade(i, faceIndex, x, y) → color, with i the lit intensity in 0..1+
 *   normals    optional per-vertex model normals → Gouraud shading
 */
export function drawMesh(cv, z, mesh, { transform, project, light, shade, ambient = 0.16, specular = 0, shininess = 24, camera = [0, 0, -3.2], normals = null, faces = null }) {
  const V = mesh.vertices.map(transform);
  const P = V.map(project);
  const lit = (n, p) => {
    let l = Math.max(0, dot(n, light));
    let s = 0;
    if (specular > 0) {
      const v = norm(sub(camera, p));
      const h = norm([light[0] + v[0], light[1] + v[1], light[2] + v[2]]);
      s = specular * Math.pow(Math.max(0, dot(n, h)), shininess);
    }
    return ambient + (1 - ambient) * l + s;
  };
  const VN = normals ? normals.map((n) => norm(sub(transform(n), transform([0, 0, 0])))) : null;
  const list = faces || mesh.faces;
  list.forEach((f, fi) => {
    const a = V[f[0]], b = V[f[1]], c = V[f[2]];
    let n = norm(cross(sub(b, a), sub(c, a)));
    if (dot(n, sub(a, camera)) > 0) n = [-n[0], -n[1], -n[2]];
    const flat = lit(n, a);
    for (let k = 1; k + 1 < f.length; k++) {
      const i0 = f[0], i1 = f[k], i2 = f[k + 1];
      let ia = flat, ib = flat, ic = flat;
      if (VN) {
        const o = (i) => (dot(VN[i], n) < 0 ? [-VN[i][0], -VN[i][1], -VN[i][2]] : VN[i]);
        ia = lit(o(i0), V[i0]); ib = lit(o(i1), V[i1]); ic = lit(o(i2), V[i2]);
      }
      tri(cv, z, P[i0], P[i1], P[i2], ia, ib, ic, (i, x, y) => shade(i, fi, x, y));
    }
  });
  return P;
}

/**
 * Analytic sphere at canvas (cx, cy) with radius r (horizontal pixels).
 * shade(nx, ny, nz, x, y) gets the camera-space unit normal (nz < 0 faces the
 * viewer) and returns a color (or NONE to leave the pixel). zr is the radius
 * in depth units, so overlapping spheres intersect correctly in the z-buffer.
 */
export function sphere(cv, z, cx, cy, r, depth, shade, zr = r * 0.01) {
  const W = cv.width, H = cv.height, px = cv.px, asp = cv.aspect;
  const ry = r / asp;
  const x0 = Math.max(0, Math.floor(cx - r - 1)), x1 = Math.min(W - 1, Math.ceil(cx + r + 1));
  const y0 = Math.max(0, Math.floor(cy - ry - 1)), y1 = Math.min(H - 1, Math.ceil(cy + ry + 1));
  for (let y = y0; y <= y1; y++) {
    const ny = ((y + 0.5 - cy) * asp) / r;
    for (let x = x0; x <= x1; x++) {
      const nx = (x + 0.5 - cx) / r;
      const q = nx * nx + ny * ny;
      if (q > 1) continue;
      const nz = -Math.sqrt(1 - q);
      const d = depth + nz * zr;
      const i = y * W + x;
      if (z && d >= z[i]) continue;
      const col = shade(nx, ny, nz, x, y);
      if (col === NONE) continue;
      if (z) z[i] = d;
      px[i] = col;
    }
  }
}

/** Deterministic twinkling stars; call draw(cv, t) each frame (before the subject). */
export function starfield(rng, n, tint = 0xc8d4ff) {
  const stars = Array.from({ length: n }, () => ({ x: rng(), y: rng(), b: 0.25 + rng() * 0.75, ph: rng() * 6.28, sp: 0.6 + rng() * 2.4 }));
  // bg: pass the theme background — stars fade in from it, and on a light
  // theme (a daylight sky) only the brightest show, as faint gray specks.
  return (cv, t, strength = 1, bg = 0x000000) => {
    const day = luminance(bg) > 0.5;
    for (const s of stars) {
      const tw = 0.55 + 0.45 * Math.sin(t * s.sp + s.ph);
      const k = s.b * tw * strength;
      if (day && k < 0.6) continue;
      cv.set(s.x * cv.width, s.y * cv.height, day ? blend(bg, 0x7a8494, (k - 0.6) * 0.8) : blend(bg, tint, k));
    }
  };
}

/** Scale a packed color, saturating. */
export function lit(c, k) {
  if (c === NONE) return NONE;
  const r = Math.min(255, ((c >> 16) & 255) * k), g = Math.min(255, ((c >> 8) & 255) * k), b = Math.min(255, (c & 255) * k);
  return (r << 16) | (g << 8) | (b | 0);
}

/** Linear mix of two packed colors, t clamped to [0, 1] (no NONE handling — callers pass real colors). */
export function blend(a, b, t) {
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  const r = ((a >> 16) & 255) + ((((b >> 16) & 255) - ((a >> 16) & 255)) * t);
  const g = ((a >> 8) & 255) + ((((b >> 8) & 255) - ((a >> 8) & 255)) * t);
  const bl = (a & 255) + (((b & 255) - (a & 255)) * t);
  return (r << 16) | (g << 8) | (bl | 0);
}

/** Rotation matrix helpers (row-major 3×3 arrays). */
export function rotX(a) { const c = Math.cos(a), s = Math.sin(a); return [1, 0, 0, 0, c, -s, 0, s, c]; }
export function rotY(a) { const c = Math.cos(a), s = Math.sin(a); return [c, 0, s, 0, 1, 0, -s, 0, c]; }
export function rotZ(a) { const c = Math.cos(a), s = Math.sin(a); return [c, -s, 0, s, c, 0, 0, 0, 1]; }
export function mul(A, B) {
  const out = new Array(9);
  for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) out[r * 3 + c] = A[r * 3] * B[c] + A[r * 3 + 1] * B[3 + c] + A[r * 3 + 2] * B[6 + c];
  return out;
}
export function apply(M, p) { return [M[0] * p[0] + M[1] * p[1] + M[2] * p[2], M[3] * p[0] + M[4] * p[1] + M[5] * p[2], M[6] * p[0] + M[7] * p[1] + M[8] * p[2]]; }
export function transpose(M) { return [M[0], M[3], M[6], M[1], M[4], M[7], M[2], M[5], M[8]]; }

/** Perspective projector onto a canvas: unit radius ≈ fill × the shorter visual side. */
export function perspective(cv, { distance = 3.2, fill = 0.42, cx, cy } = {}) {
  const W = cv.width, H = cv.height, asp = cv.aspect;
  const s = Math.min(W, H * asp) * fill * distance;
  const ox = cx ?? W / 2, oy = cy ?? H / 2;
  return (p) => { const d = p[2] + distance; const k = s / Math.max(0.05, d); return [ox + p[0] * k, oy + (p[1] * k) / asp, d]; };
}

/**
 * Scanline-fill a polygon ([[x,y],…], even-odd) calling fn(x, y, old) → color
 * for every covered pixel — for blended/glassy fills that need the pixel below.
 */
export function fillPoly(cv, pts, fn) {
  if (pts.length < 3) return;
  const W = cv.width, H = cv.height, px = cv.px;
  let minY = Infinity, maxY = -Infinity;
  for (const p of pts) { if (p[1] < minY) minY = p[1]; if (p[1] > maxY) maxY = p[1]; }
  const ya = Math.max(0, Math.ceil(minY - 0.5)), yb = Math.min(H - 1, Math.floor(maxY - 0.5));
  const xs = [];
  for (let y = ya; y <= yb; y++) {
    const sy = y + 0.5;
    xs.length = 0;
    for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
      const [xi, yi] = pts[i], [xj, yj] = pts[j];
      if ((yi > sy) !== (yj > sy)) xs.push(xi + ((sy - yi) / (yj - yi)) * (xj - xi));
    }
    xs.sort((a, b) => a - b);
    for (let k = 0; k + 1 < xs.length; k += 2) {
      const xa = Math.max(0, Math.ceil(xs[k] - 0.5)), xb = Math.min(W - 1, Math.floor(xs[k + 1] - 0.5));
      for (let x = xa; x <= xb; x++) {
        const i = y * W + x;
        const c = fn(x, y, px[i]);
        if (c !== NONE) px[i] = c;
      }
    }
  }
}

/**
 * Soft elliptical floor shadow. `under` is the color behind transparent
 * pixels (pass ctx.theme.bg) so the shadow darkens the real background.
 */
export function shadow(cv, cx, cy, rx, ry, strength, under) {
  const x0 = Math.max(0, Math.floor(cx - rx)), x1 = Math.min(cv.width - 1, Math.ceil(cx + rx));
  const y0 = Math.max(0, Math.floor(cy - ry)), y1 = Math.min(cv.height - 1, Math.ceil(cy + ry));
  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
    const dx = (x + 0.5 - cx) / rx, dy = (y + 0.5 - cy) / ry;
    const q = dx * dx + dy * dy;
    if (q >= 1) continue;
    const a = strength * (1 - q) * (1 - q);
    const i = y * cv.width + x;
    const old = cv.px[i] === NONE ? under : cv.px[i];
    cv.px[i] = blend(old, 0x000000, a);
  }
}

sources.prism-term/src/facets/objects/analog-clo:
// A wall clock in braille: a double bezel, minute and hour ticks, numerals,
// tapered baton hands that pass over the numerals, a sweeping second hand with
// a counterweight, and a date window. Time starts at 10:08:36 — the
// watchmaker's favorite pose — and runs in real seconds.
import { ATTR } from '../../buffer.js';
import { blend } from './_raster.js';

export default {
  title: 'Analog Clock',
  gallery: 'objects',
  category: 'Mechanical',
  kind: 'widget',
  tags: ['clock', 'time', 'watch', 'braille', 'hands'],
  order: 20,
  description: 'A braille wall clock with a bezel, ticks, numerals, tapered baton hands and a smoothly sweeping second hand.',
  size: { w: 40, h: 20 },
  minSize: { w: 14, h: 7 },
  loop: 60,
  canvas: 'line',
  palette: 'prism',
  params: { rate: { default: 1, min: 1, max: 600, label: 'Time multiplier' } },
  setup(ctx) {
    const cv = ctx.canvas('line');
    const rate = ctx.param('rate', 1);
    const th = ctx.theme;
    const W = cv.width, H = cv.height, asp = cv.aspect;
    const R = Math.min(W / 2 - 1.5, (H * asp) / 2 - 1.5);
    const cx = W / 2, cy = H / 2;
    // Clock-face polar → canvas pixels (angle 0 at twelve, clockwise).
    const P = (a, r) => [cx + Math.sin(a) * r, cy - (Math.cos(a) * r) / asp];
    // Baton hand: a quad from a short tail behind the hub to a narrow tip.
    const hand = (a, len, tail, width, color) => {
      const ox = Math.cos(a) * width * 0.5, oy = (Math.sin(a) * width * 0.5) / asp;
      const t0 = P(a + Math.PI, tail), t1 = P(a, len);
      cv.polygon([[t0[0] - ox, t0[1] - oy], [t0[0] + ox, t0[1] + oy], [t1[0] + ox * 0.25, t1[1] + oy * 0.25], [t1[0] - ox * 0.25, t1[1] - oy * 0.25]], color);
      cv.line(t0[0], t0[1], t1[0], t1[1], color);
    };
    const bezel = blend(th.line, th.ink, 0.35);
    const minor = blend(th.bg, th.muted, 0.85);
    const start = 10 * 3600 + 8 * 60 + 36;
    const cellX = (x) => Math.round(x / cv.sx - 0.5), cellY = (y) => Math.round(y / cv.sy - 0.5);
    return (t) => {
      cv.clear();
      const b = ctx.buffer, cw = ctx.width, ch = ctx.height;
      const secs = start + t * rate;
      // Layered like a real dial: bezel and ticks, then numerals and date over
      // them (as text), then the hands painted over everything.
      cv.ellipse(cx, cy, R, R / asp, bezel);
      if (R > 12) for (const d of [0.7, 1.4]) cv.ellipse(cx, cy, R - d, (R - d) / asp, bezel);
      for (let m = 0; m < 60; m++) {
        const a = (m / 60) * Math.PI * 2;
        const major = m % 5 === 0;
        if (!major && R < 12) continue;
        const [x0, y0] = P(a, R * (major ? (m % 15 ? 0.82 : 0.78) : 0.89)), [x1, y1] = P(a, R * 0.94);
        cv.line(x0, y0, x1, y1, major ? th.ink : minor);
      }
      cv.paint(b);
      cv.clear();
      if (R > 8) {
        const all = R >= 30;
        for (let n = 1; n <= 12; n++) {
          if (!all && n % 3) continue;
          const label = String(n);
          const [x, y] = P((n / 12) * Math.PI * 2, R * 0.7);
          const X = Math.min(cw - label.length, Math.max(0, cellX(x) - (label.length >> 1)));
          b.text(X, Math.min(ch - 1, Math.max(0, cellY(y))), label, n % 3 ? th.muted : th.ink, undefined, ATTR.BOLD);
        }
      }
      if (R >= 22) {
        const day = String(13 + (Math.floor(secs / 86400) % 18));
        const [x, y] = P(Math.PI / 2, R * 0.42);
        b.text(cellX(x) - 1, cellY(y), day, th.bg, th.muted, ATTR.BOLD);
      }
      // Hands: the hour and minute advance continuously, the second hand sweeps.
      const s = secs % 60, mi = (secs / 60) % 60, h = (secs / 3600) % 12;
      hand((h / 12) * Math.PI * 2, R * 0.5, R * 0.1, Math.max(1, R * 0.12), th.ink);
      hand((mi / 60) * Math.PI * 2, R * 0.8, R * 0.12, Math.max(1, R * 0.08), blend(th.ink, th.info, 0.3));
      const sa = (s / 60) * Math.PI * 2;
      const st = P(sa, R * 0.88), sb = P(sa + Math.PI, R * 0.2);
      cv.line(sb[0], sb[1], st[0], st[1], th.neg);
      if (R > 12) { const [wx, wy] = P(sa + Math.PI, R * 0.17); cv.circle(wx, wy, R * 0.035 + 0.6, th.neg, true); }
      cv.circle(cx, cy, Math.max(1, R * 0.05), th.neg, true);
      cv.paint(b);
    };
  },
};

sources.prism-term/src/facets/objects/atom.js:
// The atom symbol, built for real: a nucleus of lit, z-buffered protons and
// neutrons, three tilted orbits drawn as anti-aliased (bilinear-splatted) rings
// that pass behind and in front of it, and electrons with glowing heads and
// fading trails. Everything loops exactly every twelve seconds.
import { zbuffer, sphere, perspective, rotX, rotY, rotZ, mul, apply, norm, blend } from './_raster.js';
import { NONE, luminance } from '../../color.js';

const LOOP = 12;

export default {
  title: 'Atom',
  gallery: 'objects',
  category: 'Icons & Logos',
  kind: 'art',
  tags: ['atom', 'science', 'orbit', 'electron', 'nucleus', 'physics'],
  order: 20,
  description: 'A lit nucleus of protons and neutrons inside three tilted orbits, with glowing electrons trailing light.',
  size: { w: 56, h: 22 },
  minSize: { w: 18, h: 7 },
  loop: LOOP,
  canvas: 'field',
  palette: 'prism',
  params: { electrons: { default: 3, min: 1, max: 6, label: 'Electrons' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const z = zbuffer(cv);
    const W = cv.width, H = cv.height, asp = cv.aspect, th = ctx.theme;
    const pal = ctx.palette();
    const nE = Math.round(ctx.param('electrons', 3));
    const dist = 5;
    const project = perspective(cv, { distance: dist, fill: 0.43 });
    const scale = Math.min(W, H * asp) * 0.43; // pixels per world unit at the origin
    const light = norm([-0.5, -0.65, -0.6]);
    const half = norm([light[0], light[1], light[2] - 1]); // Blinn half-vector (viewer at -z)
    const dark = luminance(th.bg) < 0.5;
    const proton = blend(0xe8505b, th.neg, 0.35), neutron = blend(0x9fb3c8, th.muted, 0.3);
    // Nucleons packed on two shells; protons and neutrons alternate (seeded).
    const nucleons = [];
    const shell = (n, rad) => {
      for (let i = 0; i < n; i++) {
        const y = 1 - (2 * (i + 0.5)) / n, r = Math.sqrt(1 - y * y), a = i * 2.39996;
        nucleons.push({ p: [Math.cos(a) * r * rad, y * rad, Math.sin(a) * r * rad], c: ctx.rng() < 0.5 ? proton : neutron });
      }
    };
    shell(10, 0.2); shell(3, 0.07);
    const nr = Math.max(0.12, 0.9 / scale); // nucleon radius (world), never below ~1px
    const orbitCol = [0.02, 0.36, 0.68].map((f) => blend(pal(f), th.info, 0.2));
    const tilt = [0, 1, 2].map((k) => mul(rotZ((k * Math.PI) / 3 + 0.1), rotX(1.08)));
    const spd = [4, -3, 5, 6, -4, 7];

    const acc = new Float32Array(W * H * 4); // r, g, b, alpha (premultiplied)
    const splat1 = (i, d, col, a) => {
      if (z[i] < d - 0.02) return; // hidden behind the nucleus
      const o = i * 4;
      acc[o] += ((col >> 16) & 255) * a; acc[o + 1] += ((col >> 8) & 255) * a; acc[o + 2] += (col & 255) * a; acc[o + 3] += a;
    };
    const splat = (x, y, d, col, a) => {
      x -= 0.5; y -= 0.5;
      const x0 = Math.floor(x), y0 = Math.floor(y), fx = x - x0, fy = y - y0;
      for (let j = 0; j < 4; j++) {
        const xx = x0 + (j & 1), yy = y0 + (j >> 1);
        if (xx < 0 || yy < 0 || xx >= W || yy >= H) continue;
        splat1(yy * W + xx, d, col, a * ((j & 1) ? fx : 1 - fx) * ((j >> 1) ? fy : 1 - fy));
      }
    };
    const glow = (x, y, d, col, a, sigma) => {
      const R = Math.ceil(sigma * 2.5), Ry = Math.ceil(R / asp);
      for (let yy = Math.floor(y) - Ry; yy <= Math.floor(y) + Ry; yy++) for (let xx = Math.floor(x) - R; xx <= Math.floor(x) + R; xx++) {
        if (xx < 0 || yy < 0 || xx >= W || yy >= H) continue;
        const dx = xx + 0.5 - x, dy = (yy + 0.5 - y) * asp;
        const w = Math.exp(-(dx * dx + dy * dy) / (2 * sigma * sigma));
        if (w > 0.02) splat1(yy * W + xx, d, col, a * w);
      }
    };

    // Splat orbit M from angle a0 to a1 in n steps, each weighted by the screen
    // distance it covers, so the line is evenly bright even where it is seen edge-on.
    const arc = (M, a0, a1, n, col, k) => {
      let prev = null;
      for (let s = 0; s <= n; s++) {
        const f = s / n, a = a0 + (a1 - a0) * f;
        const q = apply(M, [Math.cos(a), Math.sin(a), 0]);
        const p = project(q);
        if (prev) splat((p[0] + prev[0]) / 2, (p[1] + prev[1]) / 2, p[2], col, Math.hypot(p[0] - prev[0], p[1] - prev[1]) * k(f, q));
        prev = p;
      }
    };

    return (t) => {
      cv.clear();
      z.fill(Infinity);
      acc.fill(0);
      const ph = (t / LOOP) * Math.PI * 2;
      const G = mul(rotY(Math.sin(ph) * 0.45), mul(rotX(0.18 + Math.cos(ph) * 0.14), rotZ(Math.sin(ph * 2) * 0.08)));
      // Nucleus: slowly tumbling, lit spheres, z-buffered against each other.
      const N = mul(G, mul(rotY(ph), rotX(ph * 2)));
      for (const n of nucleons) {
        const q = apply(N, n.p), [sx, sy, sd] = project(q);
        const rp = (nr * scale * dist) / sd;
        sphere(cv, z, sx, sy, rp, sd, (nx, ny, nz) => {
          const dif = Math.max(0, nx * light[0] + ny * light[1] + nz * light[2]);
          const spec = Math.pow(Math.max(0, nx * half[0] + ny * half[1] + nz * half[2]), 28);
          return blend(blend(0x000000, n.c, 0.22 + 0.78 * dif), 0xffffff, spec * 0.8);
        }, nr);
      }
      // Orbits, brighter on the near side.
      const orbits = tilt.map((T) => mul(G, T));
      const steps = Math.ceil(Math.PI * 2 * scale * 4);
      orbits.forEach((M, k) => arc(M, 0, Math.PI * 2, steps, orbitCol[k], (f, q) => 0.42 - q[2] * 0.22));
      // Electrons: a glowing head and a trail fading back along the orbit.
      for (let e = 0; e < nE; e++) {
        const k = e % 3, M = orbits[k], w = (spd[e] * Math.PI * 2) / LOOP;
        const a0 = w * t + e * 2.1;
        const col = blend(orbitCol[k], 0xffffff, 0.55);
        arc(M, a0 - Math.sign(w) * 1.3, a0, Math.ceil(scale * 2.5), col, (f) => 0.6 * Math.pow(f, 2.2));
        const q = apply(M, [Math.cos(a0), Math.sin(a0), 0]);
        const [x, y, d] = project(q);
        glow(x, y, d, col, 1.1, Math.max(0.7, scale * 0.06));
      }
      // Composite the light: additive on dark themes, ink-like on light ones.
      const px = cv.px;
      for (let i = 0; i < W * H; i++) {
        const o = i * 4, a = acc[o + 3];
        if (a < 0.01) continue;
        const base = px[i] === NONE ? th.bg : px[i];
        if (dark) {
          const r = Math.min(255, ((base >> 16) & 255) + acc[o]), g = Math.min(255, ((base >> 8) & 255) + acc[o + 1]), b = Math.min(255, (base & 255) + acc[o + 2]);
          px[i] = (r << 16) | (g << 8) | (b | 0);
        } else {
          const col = ((acc[o] / a) << 16) | ((acc[o + 1] / a) << 8) | ((acc[o + 2] / a) | 0);
          px[i] = blend(base, blend(col, th.ink, 0.35), Math.min(1, a * 1.8));
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

