// A BBS login screen, 1993: block-letter board logo, caller stats in a double
// frame, and a login that types itself — handle, password, credential check,
// welcome — then hangs up and does it again. VGA colors (or --set colors=theme).
import { textMask, bbsPalette } from './_kit.js';
import { blockLogo, frame } from './_bbs.js';

const HANDLE = 'LIGHTMAN';
const SPIN = '|/-\\';

export default {
  title: 'BBS Login',
  gallery: 'retro',
  category: 'BBS & ANSI Art',
  kind: 'art',
  tags: ['bbs', 'ansi', 'login', 'dial-up', '1993', 'sysop'],
  order: 10,
  description: 'A 1993 BBS login: block-letter board logo, caller stats in a double frame and a login that types itself.',
  size: { w: 80, h: 24 },
  minSize: { w: 40, h: 12 },
  loop: 12,
  color: '16',
  params: { colors: { default: 'vga', options: ['vga', 'theme'], label: 'Colors' } },
  setup(ctx) {
    const P = bbsPalette(ctx);
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const logo = textMask('PRISM', { font: 'bold' });
    const sx = logo.w * 2 + 2 <= W ? 2 : 1;
    const showLogo = H >= 18 && logo.w * sx + 2 <= W;
    const ramp = (v) => (v < 0.2 ? P[15] : v < 0.45 ? P[11] : v < 0.75 ? P[3] : P[9]);
    return (t) => {
      const lt = t % 12;
      b.fill(0, 0, W, H, ' ', P[7], P[0]);
      // Status bar.
      const mins = 41 + Math.floor(t / 60);
      const clock = `${String((23 + Math.floor(mins / 60)) % 24).padStart(2, '0')}:${String(mins % 60).padStart(2, '0')}`;
      b.fill(0, 0, W, 1, ' ', P[15], P[1]);
      b.text(1, 0, (W >= 56 ? ' PRISM BBS · Node 3 of 8 · 2400 bps · ANSI ' : ' PRISM BBS · Node 3 · 2400 bps ').slice(0, W - 2), P[15], P[1]);
      if (W > 56) b.text(W - 7, 0, clock, P[14], P[1]);
      let y = 2;
      if (showLogo) {
        const lx = Math.floor((W - logo.w * sx) / 2);
        blockLogo(b, lx, y, logo, { sx, ramp, shadow: P[8] });
        y += 5;
        const tag = 'THE TERMINAL ART UNDERGROUND · EST. 1991';
        if (tag.length < W) b.text(Math.floor((W - tag.length) / 2), y, tag, P[6]);
        y += 2;
      } else {
        b.text(2, y, 'P R I S M   B B S', P[11]);
        y += 2;
      }
      // Caller stats.
      const fw = Math.min(W - 4, 46), fx = Math.floor((W - fw) / 2);
      const stats = [['Last caller', 'CRASH OVERRIDE'], ['Calls today', '42'], ['Your node', '3 of 8'], ['Software', 'PRISM/BBS 0.42']];
      const rows = H - y >= 13 ? stats : stats.slice(0, Math.max(0, H - y - 8));
      if (rows.length) {
        frame(b, fx, y, fw, rows.length + 2, P[1], 'SYSTEM', P[14]);
        rows.forEach(([k, v], i) => {
          const dots = '.'.repeat(Math.max(2, 16 - k.length));
          b.text(fx + 2, y + 1 + i, `${k} ${dots} `, P[7]);
          b.text(fx + 2 + k.length + dots.length + 2, y + 1 + i, v.slice(0, fw - k.length - dots.length - 6), P[15]);
        });
        y += rows.length + 3;
      }
      // The login, scripted on a 12-second loop.
      const px = Math.max(1, fx);
      const blink = Math.floor(t * 2.5) % 2 === 0;
      const typed = (from, text, cps) => text.slice(0, Math.max(0, Math.min(text.length, Math.floor((lt - from) * cps))));
      const line = (text, color, cursor) => {
        if (y >= H - 1) return;
        const end = b.text(px, y, text, color);
        if (cursor && blink) b.set(end, y, '█', P[7]);
        y++;
      };
      const handle = lt >= 1.4 ? typed(1.4, HANDLE, 6) : '';
      const ask = W - px >= 46 ? 'Enter your handle (NEW to apply): ' : 'Handle: ';
      line(ask, P[11], false);
      if (y - 1 < H - 1) {
        const end = b.text(px + ask.length, y - 1, handle, P[15]);
        if (lt < 3.3 && blink) b.set(end, y - 1, '█', P[7]);
      }
      if (lt >= 3.3) {
        const stars = '*'.repeat(typed(3.8, 'xxxxxxxx', 7).length);
        line(`Password: ${stars}`, P[11], lt < 5.2);
      }
      if (lt >= 5.2 && lt < 6.8) line(`Checking credentials... ${SPIN[Math.floor(t * 8) % 4]}`, P[7], false);
      if (lt >= 6.8) {
        line(`Welcome back, ${HANDLE}!`, P[10], false);
        if (lt >= 7.4) line(W - px > 62 ? 'You have 3 new messages and 12 new files since your last call.' : '3 new messages, 12 new files.', P[7], lt > 10.8);
      }
      // Footer.
      if (H > 12) {
        const foot = '[ESC] hang up   [?] help   SysOp is AVAILABLE';
        b.text(Math.max(0, Math.floor((W - foot.length) / 2)), H - 1, foot.slice(0, W), P[8]);
      }
    };
  },
};

sources.prism-term/src/facets/retro/bbs-menu.js:
// BBS main menu: a shaded header, two columns of hotkey commands with a
// lightbar walking through them, a who's-online panel and the classic
// time-left status line.
import { bbsPalette } from './_kit.js';
import { frame } from './_bbs.js';

const ITEMS = [
  ['M', 'Message Bases'], ['F', 'File Areas'], ['D', 'Door Games'], ['C', 'Chat with SysOp'],
  ['B', 'Bulletins'], ['W', "Who's Online"], ['N', 'New Files Scan'], ['U', 'User Settings'],
  ['L', 'Last Callers'], ['G', 'Goodbye (Log Off)'],
];
const ONLINE = [['1', 'ZERO COOL', 'Playing L.O.R.D.'], ['2', 'ACID BURN', 'Reading msgs'], ['3', 'LIGHTMAN', 'Main menu'], ['4', 'THE PHREAK', 'Downloading']];

export default {
  title: 'BBS Main Menu',
  gallery: 'retro',
  category: 'BBS & ANSI Art',
  kind: 'art',
  tags: ['bbs', 'ansi', 'menu', 'lightbar', 'hotkeys', 'sysop'],
  order: 20,
  description: 'A BBS main menu: shaded header, hotkey commands with a walking lightbar, who-is-online and time left.',
  size: { w: 80, h: 22 },
  minSize: { w: 40, h: 12 },
  loop: 10,
  color: '16',
  params: { colors: { default: 'vga', options: ['vga', 'theme'], label: 'Colors' } },
  setup(ctx) {
    const P = bbsPalette(ctx);
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const twoCols = W >= 60;
    const panel = W >= 72 && H >= 16;
    return (t) => {
      b.fill(0, 0, W, H, ' ', P[7], P[0]);
      // Header: ░▒▓█ MAIN MENU █▓▒░ across the top.
      const title = ' MAIN MENU ';
      const side = Math.max(0, Math.floor((W - title.length) / 2));
      const grad = '░▒▓█';
      for (let x = 0; x < W; x++) {
        const d = x < side ? side - x : x - side - title.length;
        if (x >= side && x < side + title.length) continue;
        b.set(x, 0, grad[Math.max(0, 3 - Math.min(3, Math.floor(d / Math.max(1, side / 4))))], x % 2 ? P[1] : P[9]);
      }
      b.text(side, 0, title, P[15], P[1]);
      b.text(Math.max(0, Math.floor((W - 37) / 2)), 1, 'PRISM BBS · terminal art since 1991'.slice(0, W), P[8]);
      // Menu.
      const menuW = panel ? Math.min(52, W - 28) : W - 2;
      const colW = twoCols ? Math.floor((menuW - 4) / 2) : menuW - 4;
      const perCol = twoCols ? Math.ceil(ITEMS.length / 2) : ITEMS.length;
      const visible = Math.min(perCol, Math.max(1, H - 7));
      frame(b, 1, 3, menuW, visible + 2, P[1], 'COMMANDS', P[14]);
      const sel = Math.floor(t / 0.8) % ITEMS.length;
      ITEMS.forEach(([key, label], i) => {
        const col = twoCols ? Math.floor(i / perCol) : 0, row = twoCols ? i % perCol : i;
        if (row >= visible) return;
        const x = 3 + col * (colW + 1), y = 4 + row;
        const on = i === sel;
        if (on) b.fill(x - 1, y, colW, 1, ' ', P[0], P[3]);
        b.text(x, y, '[', on ? P[0] : P[1], on ? P[3] : undefined);
        b.text(x + 1, y, key, on ? P[0] : P[14], on ? P[3] : undefined);
        b.text(x + 2, y, ']', on ? P[0] : P[1], on ? P[3] : undefined);
        b.text(x + 4, y, label.slice(0, colW - 6), on ? P[0] : P[7], on ? P[3] : undefined);
      });
      // Who's online.
      if (panel) {
        const px = menuW + 3, pw = W - px - 1;
        frame(b, px, 3, pw, ONLINE.length * 2 + 2, P[5], 'ONLINE', P[13]);
        ONLINE.forEach(([n, who, what], i) => {
          const y = 4 + i * 2;
          const live = Math.floor(t * 1.5 + i) % 5 !== 0;
          b.text(px + 2, y, `${n}`, P[8]);
          b.text(px + 4, y, who.slice(0, pw - 6), i === 2 ? P[11] : P[15]);
          b.text(px + 4, y + 1, what.slice(0, pw - 6), live ? P[7] : P[8]);
        });
      }
      // Prompt + status line.
      const py = Math.min(H - 3, 4 + visible + 2);
      const blink = Math.floor(t * 2.5) % 2 === 0;
      const end = b.text(2, py, 'Command ', P[11]);
      const end2 = b.text(end, py, '» ', P[14]);
      b.text(end2, py, ITEMS[sel][0], P[15]);
      if (blink) b.set(end2 + 1, py, '█', P[7]);
      const left = 58 - Math.floor(t / 60);
      b.fill(0, H - 1, W, 1, ' ', P[0], P[7]);
      b.text(1, H - 1, `Time left: ${left} min  ·  Node 3  ·  3 new msgs  ·  ↑↓ select  Enter`.slice(0, W - 2), P[0], P[7]);
    };
  },
};

sources.prism-term/src/facets/retro/boing-ball.j:
// Homage to the 1984 Amiga Boing demo: a red-and-white checkered sphere spins
// and bounces across a purple grid room, casting a soft shadow on the wall.
import { lerpc } from './_kit.js';

export default {
  title: 'Boing Ball',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['boing', 'amiga', 'ball', 'checker', '1984'],
  order: 30,
  description: 'The 1984 Amiga Boing Ball: a spinning checkered sphere bouncing across a grid room with its shadow.',
  size: { w: 64, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: 6,
  canvas: 'hires',
  palette: 'prism',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px, aspect } = cv;
    const th = ctx.theme;
    const wall = lerpc(th.bg, 0xb0b0b0, 0.12), line = lerpc(th.bg, th.crit, 0.75);
    const red = 0xe0262b, white = 0xf2f2f2;
    const VH = H * aspect;                       // height in horizontal-pixel units
    const R = Math.min(W * 0.17, VH * 0.24);
    const floor = VH * 0.9;
    const gridX = Math.max(4, Math.round(W / 14)), gridY = Math.max(3, Math.round(H / 9));
    return (t) => {
      const tt = t * speed;
      // Room: wall grid + floor grid in perspective.
      const floorRow = Math.floor(floor / aspect);
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        let c = wall;
        if (y < floorRow) { if (x % gridX === 0 || y % gridY === 0) c = line; }
        else {
          const k = (y - floorRow + 1) / (H - floorRow + 1);
          const fx = (x - W / 2) / (0.6 + k * 1.4) + W / 2;
          if (Math.abs(fx % gridX) < 0.6 || (y - floorRow) % Math.max(1, Math.round(gridY * 0.5 * k + 1)) === 0) c = line;
        }
        px[y * W + x] = c;
      }
      // Bounce: horizontal ping-pong, vertical |sin|.
      const span = W - 2 * R - 2;
      const ph = (tt * 0.22) % 2;
      const bx = R + 1 + (ph < 1 ? ph : 2 - ph) * span;
      const by = floor - R - Math.abs(Math.sin(tt * 2.4)) * (floor - 2 * R - 2);
      const dir = ph < 1 ? 1 : -1;
      // Shadow on the wall (offset right) — drawn first.
      const sx0 = bx + R * 0.45, sy0 = by + R * 0.18;
      for (let y = Math.floor((sy0 - R) / aspect); y <= Math.ceil((sy0 + R) / aspect); y++) {
        for (let x = Math.floor(sx0 - R); x <= Math.ceil(sx0 + R); x++) {
          const dx = x + 0.5 - sx0, dy = (y + 0.5) * aspect - sy0;
          if (dx * dx + dy * dy < R * R && x >= 0 && x < W && y >= 0 && y < H) px[y * W + x] = lerpc(px[y * W + x], 0x000000, 0.45);
        }
      }
      // The ball: checker in (longitude, latitude), tilted, spinning.
      const spin = tt * 3 * dir, tilt = 0.35;
      for (let y = Math.floor((by - R) / aspect); y <= Math.ceil((by + R) / aspect); y++) {
        for (let x = Math.floor(bx - R); x <= Math.ceil(bx + R); x++) {
          if (x < 0 || x >= W || y < 0 || y >= H) continue;
          const nx = (x + 0.5 - bx) / R, ny = ((y + 0.5) * aspect - by) / R;
          const r2 = nx * nx + ny * ny;
          if (r2 > 1) continue;
          const nz = Math.sqrt(1 - r2);
          // Tilt around z then read longitude/latitude.
          const tx = nx * Math.cos(tilt) - ny * Math.sin(tilt), ty = nx * Math.sin(tilt) + ny * Math.cos(tilt);
          const lon = Math.atan2(tx, nz) + spin, lat = Math.asin(Math.max(-1, Math.min(1, ty)));
          const check = ((Math.floor(lon / (Math.PI / 8)) + Math.floor(lat / (Math.PI / 8))) & 1) === 0;
          const light = 0.45 + 0.55 * Math.max(0, nz * 0.8 - nx * 0.25 - ny * 0.35);
          px[y * W + x] = lerpc(0x000000, check ? red : white, Math.min(1, light + 0.15));
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/checker-floo:
// The infinite checkerboard floor: a perspective-mapped checker plane racing
// toward the horizon and slowly banking, under a raster-gradient sunset sky.
// Distance fog keeps the far squares from shimmering.
import { lerpc } from './_kit.js';

export default {
  title: 'Checker Floor',
  gallery: 'retro',
  category: 'Raster & Copper',
  kind: 'scene',
  tags: ['checkerboard', 'floor', 'perspective', 'amiga', 'mode 7'],
  order: 40,
  description: 'A perspective checkerboard plane racing to the horizon and banking, under a raster-gradient sky.',
  size: { w: 80, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: 12,
  canvas: 'field',
  palette: 'sunset',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px, aspect } = cv;
    const hz = Math.floor(H * 0.45);
    const a = ctx.theme.accent, b = lerpc(ctx.theme.bg, ctx.theme.ink, 0.9);
    return (t) => {
      const tt = t * speed;
      const bank = Math.sin(tt * 0.35) * 0.18;
      const cs = Math.cos(bank), sn = Math.sin(bank);
      const mid = lerpc(a, b, 0.5), haze = pal(0.66);
      for (let y = 0; y < H; y++) {
        if (y < hz) {
          px.fill(pal(0.08 + (y / hz) * 0.62), y * W, (y + 1) * W);
          continue;
        }
        const dy = (y - hz + 0.5) * aspect;
        const z = (H * aspect * 0.55) / dy;      // depth of this row
        // Far squares shrink below a pixel: fade their contrast first, then haze to the horizon.
        const contrast = 1 - Math.min(1, Math.pow(z / 7, 1.3));
        const hazeK = Math.min(1, Math.pow(z / 14, 1.2));
        for (let x = 0; x < W; x++) {
          const sx = (x - W / 2) / (W / 2);
          let wx = sx * z * 1.8, wz = z * 1.2 + tt * 4;
          [wx, wz] = [wx * cs - wz * sn, wx * sn + wz * cs];
          const check = ((Math.floor(wx) + Math.floor(wz)) & 1) === 0;
          px[y * W + x] = lerpc(lerpc(mid, check ? a : b, contrast), haze, hazeK);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

// Chiptune analysis gear on the shared tracker tune (_music.js): a tracker
// sample editor whose playhead scrubs the waveform every time the instrument
// fires; the spectrum as a night skyline of window-lit towers; and a quad of
// per-channel triggered scopes in the famitracker style.
import { lerpc, fract, hash2, shade } from './_kit.js';
import { songAt, bands, PATTERN, ROWS, ROW, LOOP as SL, noteName, INSTRUMENTS } from './_music.js';
import { glyphs, frame, light } from '../charts/_data.js';

const TAU = Math.PI * 2;
const wrap = (x) => ((x % SL) + SL) % SL;
const hx = (n) => Math.round(n).toString(16).toUpperCase();

/** Rows since channel `ch` last fired an event matching `match`, per pattern row. */
function backTable(ch, match = () => true) {
  const out = new Int32Array(ROWS);
  let last = -ROWS;
  for (let i = 0; i < ROWS * 2; i++) {
    const ev = PATTERN[i % ROWS][ch];
    if (ev && match(ev)) last = i;
    if (i >= ROWS) out[i % ROWS] = i - last;
  }
  return out;
}
const ageAt = (tbl, t) => {
  const lt = wrap(t), pos = lt / ROW, row = Math.floor(pos) % ROWS;
  return (tbl[row] + (pos - Math.floor(pos))) * ROW;
};

// ──────────────────────────────────────────────────────────  sample editor ──
const scrubber = {
  id: 'retro-sample-scrubber',
  since: '0.3.0',
  title: 'Sample Scrubber',
  category: 'Chiptune Visuals',
  kind: 'scene',
  order: 230,
  tags: ['sample', 'editor', 'waveform', 'scrub', 'tracker', 'st-01', 'amiga', 'chiptune'],
  description: 'A tracker sample editor: each bar swaps in an instrument, and the playhead scrubs its waveform live on every hit, loop region and all.',
  size: { w: 72, h: 18 },
  minSize: { w: 28, h: 8 },
  loop: SL,
  canvas: 'line',
  setup(ctx) {
    const th = ctx.theme, b = ctx.buffer, W = ctx.width, H = ctx.height;
    const cv = ctx.canvas('line');
    const N = 512;
    const mk = (f) => Float32Array.from({ length: N }, (_, i) => Math.max(-1, Math.min(1, f(i / N))));
    const SAMPLES = [
      { key: 3, dur: 0.42, loopR: null, rate: 8363, back: backTable(0, (e) => e.inst === 3),
        wav: mk((u) => { const a = u * 0.42; return Math.sin(TAU * (46 * a + 120 * 0.04 * (1 - Math.exp(-a / 0.04)))) * Math.exp(-a / 0.17); }) },
      { key: 2, dur: 0.48, loopR: [0.56, 0.94], rate: 8363, back: backTable(1),
        wav: mk((u) => (fract(u * 6) < 0.5 ? 1 : -1) * (0.28 + 0.72 * Math.exp(-u * 2.2))) },
      { key: 4, dur: 0.3, loopR: null, rate: 11025, back: backTable(0, (e) => e.inst === 4),
        wav: mk((u) => { const a = u * 0.3; return (hash2(Math.floor(u * N), 1, 3) * 2 - 1) * Math.exp(-a / 0.09) * 0.85 + Math.sin(TAU * 190 * a) * Math.exp(-a / 0.05) * 0.5; }) },
      { key: 5, dur: 0.12, loopR: null, rate: 16726, back: backTable(3, (e) => e.inst === 5),
        wav: mk((u) => (hash2(Math.floor(u * N), 2, 7) * 2 - 1) * Math.exp(-u / 0.22) * 0.8) },
    ];
    const ruler = H >= 12 ? 1 : 0;
    const footer = H >= 10 ? 1 : 0;
    const wy0 = 1 + ruler, waveH = Math.max(2, H - wy0 - footer);
    const loopBg = lerpc(th.bg, th.panel, 0.85);
    return (t) => {
      const s = songAt(t);
      const sm = SAMPLES[s.bar % SAMPLES.length];
      const a = ageAt(sm.back, t);
      let pos = a / sm.dur;
      if (sm.loopR && pos > sm.loopR[1]) pos = sm.loopR[0] + fract((pos - sm.loopR[0]) / (sm.loopR[1] - sm.loopR[0])) * (sm.loopR[1] - sm.loopR[0]);
      const playing = pos <= 1.001;
      const hot = a < 0.1;
      b.fill(0, 0, W, 1, ' ', th.ink, th.panel);
      b.text(1, 0, `SMP ED ▸ 0${sm.key}:${INSTRUMENTS[sm.key]}`.slice(0, W - 2), hot ? light(th) : th.ink, th.panel);
      const rt = `${sm.rate}Hz 8-BIT`;
      if (W >= 46) b.text(W - rt.length - 1, 0, rt, th.muted, th.panel);
      if (sm.loopR) b.fill(Math.round(sm.loopR[0] * (W - 1)), wy0, Math.max(1, Math.round((sm.loopR[1] - sm.loopR[0]) * (W - 1))), waveH, ' ', th.ink, loopBg);
      if (ruler) for (let k = 0; k <= 4; k++) {
        const lx = Math.min(W - 5, Math.round((k * (W - 1)) / 4));
        b.text(lx, 1, `$${hx((k * N) / 4).padStart(3, '0')}`, lerpc(th.bg, th.muted, 0.85));
      }
      cv.clear();
      const X1 = W * cv.sx - 1;
      const midY = (wy0 + waveH / 2) * cv.sy;
      const amp = Math.max(1, (waveH * cv.sy) / 2 - 1);
      const posX = Math.round(Math.min(1, pos) * X1);
      for (let x = 0; x < X1; x += 3) cv.set(x, midY, lerpc(th.bg, th.muted, 0.7));
      const step = N / (X1 + 1);
      for (let x = 0; x <= X1; x++) {
        const i0 = Math.floor(x * step), i1 = Math.max(i0 + 1, Math.floor((x + 1) * step));
        let lo = 1, hi = -1;
        for (let i = i0; i < i1 && i < N; i++) { const v = sm.wav[i]; if (v < lo) lo = v; if (v > hi) hi = v; }
        const played = playing && x <= posX;
        const col = played ? lerpc(th.accent, light(th), 0.35) : lerpc(th.bg, th.accent, 0.8);
        cv.line(x, midY - hi * amp, x, midY - lo * amp, col);
      }
      if (playing) cv.line(posX, wy0 * cv.sy, posX, (wy0 + waveH) * cv.sy - 1, light(th));
      cv.paint(b);
      if (playing) b.set(Math.round(Math.min(1, pos) * (W - 1)), wy0, '▼', light(th));
      if (footer) {
        const y = H - 1;
        const lp = sm.loopR ? `LOOP $${hx(sm.loopR[0] * N).padStart(3, '0')}-$${hx(sm.loopR[1] * N).padStart(3, '0')}` : 'LOOP OFF';
        b.text(1, y, `${lp}  VOL 64`.slice(0, W - 2), th.muted);
        const ps = `POS $${hx(Math.min(1, pos) * N).padStart(3, '0')}`;
        if (W >= 40) b.text(W - ps.length - 1, y, ps, playing ? th.ink : th.muted);
      }
    };
  },
};

// ─────────────────────────────────────────────────────────  equalizer city ──
const eqTowers = {
  id: 'retro-eq-towers',
  since: '0.3.0',
  title: 'Equalizer City',
  category: 'Chiptune Visuals',
  kind: 'scene',
  order: 240,
  tags: ['equalizer', 'spectrum', 'skyline', 'towers', 'windows', 'night', 'beacon', 'chiptune'],
  description: 'The spectrum as a skyline: every band is a tower whose windows light floor by floor, with peak roof caps, beacons, stars and a wet street.',
  size: { w: 64, h: 20 },
  minSize: { w: 24, h: 8 },
  loop: SL,
  setup(ctx) {
    const th = ctx.theme, b = ctx.buffer, W = ctx.width, H = ctx.height;
    const pal = ctx.palette('theme-heat');
    const refl = H >= 14 ? 2 : 0;
    const lblRow = H >= 12 && W >= 40 ? 1 : 0;
    const groundY = H - 1 - refl - lblRow;
    const rows = Math.max(2, groundY);
    const pitch = W >= 48 ? 5 : 4, tw = pitch - 1;
    const n = Math.max(3, Math.floor((W - 1) / pitch));
    const xoff = Math.max(0, Math.floor((W - (n * pitch - 1)) / 2));
    const maxH = Float32Array.from({ length: n }, (_, i) => Math.max(2, rows * (0.45 + 0.5 * hash2(i, 11))));
    const beacon = Array.from({ length: n }, (_, i) => hash2(i, 5) < 0.3);
    const bodyC = shade(th, 0.5), sideC = shade(th, 0.72);
    const street = shade(th, 0.62);
    const stars = Array.from({ length: Math.round(W * 0.5) }, (_, i) => [Math.floor(hash2(i, 21) * W), Math.floor(hash2(i, 22) * rows * 0.45), hash2(i, 23)]);
    const K = 22, STEP = 1 / 30;
    const cur = new Float32Array(n), tmp = new Float32Array(n), peak = new Float32Array(n);
    const FREQS = [[60, '60'], [250, '250'], [1000, '1k'], [4000, '4k'], [10000, '10k']];
    const lo = Math.log2(40), hi = Math.log2(12000);
    return (t) => {
      for (const [sx, sy, k] of stars) {
        if (Math.sin(TAU * (t / SL) * (2 + Math.floor(k * 4)) + k * 20) > -0.1) b.set(sx, sy, k > 0.8 ? '✦' : '·', lerpc(th.bg, th.ink, 0.35 + k * 0.3));
      }
      if (W >= 34) b.set(W - 5, 1, '☾', lerpc(th.bg, th.ink, 0.75));
      bands(t, n, cur);
      peak.set(cur);
      for (let k = 1; k < K; k++) {
        bands(t - k * STEP, n, tmp);
        const drop = Math.max(0, k * STEP - 0.22) ** 2 * 2.8;
        for (let i = 0; i < n; i++) { const v = tmp[i] - drop; if (v > peak[i]) peak[i] = v; }
      }
      for (let i = 0; i < n; i++) {
        const x0 = xoff + i * pitch;
        const hMax = maxH[i];
        const litF = cur[i] * hMax;
        for (let f = 0; f < hMax && f < rows; f++) {
          const y = groundY - 1 - f;
          if (y < 0) break;
          for (let dx = 0; dx < tw; dx++) {
            if (dx === tw - 1) { b.set(x0 + dx, y, '░', sideC); continue; }
            const win = dx % 2 === 0 && f % 2 === 0;
            if (win && f < litF) {
              const flick = hash2(i * 7 + dx, f, Math.floor(t * 10)) < 0.05;
              b.set(x0 + dx, y, '█', flick ? lerpc(th.bg, pal(0.3), 0.4) : pal(0.12 + 0.8 * (f / rows)));
            } else b.set(x0 + dx, y, '▒', bodyC);
          }
        }
        const pk = Math.min(hMax - 0.01, peak[i] * hMax);
        const py = groundY - 1 - Math.floor(pk);
        if (pk > litF + 0.6 && py >= 0) for (let dx = 0; dx < tw - 1; dx++) b.set(x0 + dx, py, '▔', light(th));
        if (beacon[i]) {
          const by = groundY - 1 - Math.floor(hMax);
          if (by >= 0 && (t * 1.5 + i * 0.37) % 1 < 0.45) b.set(x0 + ((tw - 1) >> 1), by, '◆', lerpc(th.neg, light(th), 0.25));
        }
      }
      b.fill(0, groundY, W, 1, ' ', th.ink, street);
      for (let x = 2; x < W; x += 9) b.set(x, groundY, '·', lerpc(street, th.warn, 0.7));
      if (lblRow) for (const [f, sN] of FREQS) {
        const x = Math.round(xoff + ((Math.log2(f) - lo) / (hi - lo)) * (n * pitch - 1) - sN.length / 2);
        if (x >= 0 && x + sN.length <= W) b.text(x, groundY + 1, sN, th.muted);
      }
      for (let r = 0; r < refl; r++) {
        const y = groundY + 1 + lblRow + r;
        if (y >= H) break;
        for (let i = 0; i < n; i++) {
          const litF = cur[i] * maxH[i];
          if (r + 0.5 >= litF) continue;
          const x0 = xoff + i * pitch;
          for (let dx = 0; dx < tw - 1; dx += 2) b.set(x0 + dx, y, '░', lerpc(th.bg, pal(0.5), 0.3 * (1 - r / refl)));
        }
      }
    };
  },
};

// ────────────────────────────────────────────────────────── channel scopes ──
const chanScopes = {
  id: 'retro-channel-scopes',
  since: '0.3.0',
  title: 'Channel Scopes',
  category: 'Chiptune Visuals',
  kind: 'scene',
  order: 250,
  tags: ['oscilloscope', 'channels', 'quad', 'famitracker', 'waveform', 'trigger', 'chiptune'],
  description: 'Four per-channel scopes in the famitracker style — drums, bass, lead and hats each hold a triggered wave and flash their frame on every hit.',
  size: { w: 64, h: 18 },
  minSize: { w: 24, h: 8 },
  loop: SL,
  canvas: 'line',
  setup(ctx) {
    const th = ctx.theme, b = ctx.buffer, W = ctx.width, H = ctx.height;
    const g = glyphs(ctx);
    const cv = ctx.canvas('line');
    const bw = W >> 1, bh = H >> 1;
    const boxes = [
      { x: 0, y: 0, w: bw, h: bh }, { x: bw, y: 0, w: W - bw, h: bh },
      { x: 0, y: bh, w: bw, h: H - bh }, { x: bw, y: bh, w: W - bw, h: H - bh },
    ];
    const CH = [
      { name: 'DRUMS', c: th.warn }, { name: 'BASS', c: th.accent },
      { name: 'LEAD', c: th.info }, { name: 'HATS', c: th.pos },
    ];
    const back = [0, 1, 2, 3].map((ch) => backTable(ch));
    const lineC = lerpc(th.bg, th.line, 1);
    return (t) => {
      const s = songAt(t);
      const lvls = [Math.max(s.kick, s.snare), s.bass, s.lead, s.hat];
      const labels = [s.kick >= s.snare ? 'BD' : 'SD', noteName(s.bassNote), noteName(s.leadNote), 'HH'];
      cv.clear();
      for (let i = 0; i < 4; i++) {
        const bx = boxes[i], ch = CH[i];
        const hot = ageAt(back[i], t) < 0.12;
        const title = `${i + 1}·${ch.name}`.slice(0, Math.max(0, bx.w - 6));
        const inner = frame(b, bx.x, bx.y, bx.w, bx.h, hot ? ch.c : lineC, g, title, hot ? ch.c : th.muted);
        if (bx.w >= 18) b.text(bx.x + bx.w - labels[i].length - 3, bx.y, ` ${labels[i]} `, th.muted);
        if (bx.w >= 12 && bx.h >= 3) {
          const nn = Math.round(Math.min(1, lvls[i]) * 5);
          for (let k = 0; k < 5; k++) b.set(bx.x + bx.w - 7 + k, bx.y + bx.h - 1, '▮', k < nn ? ch.c : lerpc(th.bg, ch.c, 0.2));
        }
        if (inner.w < 3 || inner.h < 1) continue;
        const X0 = inner.x * cv.sx + 1, X1 = (inner.x + inner.w) * cv.sx - 2;
        const midY = (inner.y + inner.h / 2) * cv.sy;
        const amp = Math.max(0, (inner.h * cv.sy) / 2 - 1.5);
        const env = lvls[i];
        const col = lerpc(th.bg, ch.c, 0.45 + 0.55 * Math.min(1, env * 1.2));
        let py = midY;
        for (let xp = X0; xp <= X1; xp++) {
          const u = (xp - X0) / Math.max(1, X1 - X0);
          let v;
          if (i === 0) v = s.kick * Math.sin(TAU * 52 * Math.max(0, s.kickAge - (1 - u) * 0.03)) + s.snare * 0.85 * (hash2(Math.floor(u * 48), Math.floor(t * 30), 3) * 2 - 1);
          else if (i === 1) v = (fract(u * 2) < 0.5 ? 1 : -1) * s.bass * 0.9;
          else if (i === 2) v = (fract(u * 2) < 0.25 ? 1 : -1) * s.lead * 0.9;
          else v = (hash2(Math.floor(u * 56), Math.floor(t * 34), 8) * 2 - 1) * s.hat;
          const y = midY - Math.max(-1, Math.min(1, v)) * amp;
          if (xp > X0) cv.line(xp - 1, py, xp, y, col);
          py = y;
        }
      }
      cv.paint(b);
    };
  },
};

export default [scrubber, eqTowers, chanScopes];

// Three chiptune performance surfaces on the shared tracker tune (_music.js):
// a C64 SID voice monitor with gate LEDs, ADSR readouts and triggered scopes;
// a falling piano roll raining the pattern onto a lit keyboard; and an x0x
// drum-machine step grid with a sweeping playhead and hit flashes. Everything
// is a pure function of t — songAt() hands out envelopes, notes and hits.
import { lerpc, fract, hash2 } from './_kit.js';
import { songAt, PATTERN, ROWS, ROW, LOOP as SL, noteName } from './_music.js';
import { onFill, light } from '../charts/_data.js';

const TAU = Math.PI * 2;
const wrap = (x) => ((x % SL) + SL) % SL;

// ─────────────────────────────────────────────────────── SID voice monitor ──
const sidVoices = {
  id: 'retro-sid-voices',
  since: '0.3.0',
  title: 'SID Voice Monitor',
  category: 'Chiptune Visuals',
  kind: 'scene',
  order: 200,
  tags: ['sid', 'c64', '6581', 'voice', 'adsr', 'gate', 'scope', 'chiptune'],
  description: 'A C64 SID chip monitor: three voices with gate LEDs, waveform badges, ADSR readouts, envelope ladders and live triggered scopes.',
  size: { w: 70, h: 20 },
  minSize: { w: 26, h: 9 },
  loop: SL,
  canvas: 'line',
  setup(ctx) {
    const th = ctx.theme, b = ctx.buffer, W = ctx.width, H = ctx.height;
    const cv = ctx.canvas('line');
    const chrome = H >= 12 && W >= 34;
    const top = chrome ? 1 : 0;
    const body = H - top - (chrome ? 1 : 0);
    const vh = Math.max(2, Math.floor(body / 3));
    const labW = W >= 58 ? 17 : W >= 40 ? 10 : 7;
    const envW = W >= 48 ? 6 : 0;
    const sx0 = labW + 1, sx1 = W - envW - 1;
    const vcol = [th.accent, th.info, th.warn];
    const meta = [
      { v: 'V1', adsr: '0A48', xtra: 'RING OFF' },
      { v: 'V2', adsr: '2986', xtra: '' },
      { v: 'V3', adsr: '0930', xtra: 'SYNC OFF' },
    ];
    const offLED = lerpc(th.bg, th.muted, 0.7);
    return (t) => {
      const s = songAt(t);
      const pw = 0.25 + 0.14 * Math.sin((TAU * 8 * t) / SL);
      const drumNoise = s.snare >= s.kick;
      const voices = [
        { env: s.bass, note: noteName(s.bassNote), f: s.bassFreq, wave: 'SQR',
          at: (u) => (fract(u * 2) < 0.5 ? 1 : -1) },
        { env: s.lead, note: noteName(s.leadNote), f: s.leadFreq, wave: 'PUL',
          at: (u) => (fract(u * 2) < pw ? 1 : -1) },
        { env: Math.max(s.kick, s.snare), note: drumNoise ? '···' : 'C-1', f: drumNoise ? 0 : 52,
          wave: drumNoise ? 'NOI' : 'TRI', raw: true,
          at: (u) => s.kick * Math.sin(TAU * 52 * Math.max(0, s.kickAge - (1 - u) * 0.03))
            + s.snare * 0.9 * (hash2(Math.floor(u * 64), Math.floor(t * 28), 9) * 2 - 1) },
      ];
      if (chrome) {
        b.fill(0, 0, W, 1, ' ', th.ink, th.panel);
        b.text(1, 0, 'SID 6581 ▸ $D400  prism_intro.sid', th.ink, th.panel);
        const r = `BAR ${s.bar + 1}/4  50Hz`;
        if (W >= 54) b.text(W - r.length - 1, 0, r, th.muted, th.panel);
      }
      cv.clear();
      for (let vi = 0; vi < 3; vi++) {
        const vc = vcol[vi], v = voices[vi], m = meta[vi];
        const y0 = top + vi * vh;
        const gate = v.env > 0.04;
        b.text(0, y0, m.v, vc);
        b.text(3, y0, v.wave, th.muted);
        b.set(labW - 1, y0, gate ? '●' : '○', gate ? th.pos : offLED);
        if (vh >= 2 && labW >= 10) {
          b.text(0, y0 + 1, v.note, th.ink);
          const f = v.f ? (v.f < 1000 ? `${v.f.toFixed(1)}Hz` : `${(v.f / 1000).toFixed(2)}kHz`) : 'NOISE';
          b.text(4, y0 + 1, f.slice(0, labW - 5), th.muted);
        }
        if (vh >= 4 && labW >= 17) {
          b.text(0, y0 + 2, `ADSR ${m.adsr}`, th.muted);
          if (vi === 1) {
            b.text(0, y0 + 3, 'PW', th.muted);
            const n = Math.round(pw * 14);
            for (let i = 0; i < 7; i++) b.set(3 + i, y0 + 3, i * 2 < n ? '▮' : '·', i * 2 < n ? vc : lerpc(th.bg, vc, 0.3));
          } else b.text(0, y0 + 3, m.xtra, lerpc(th.bg, th.muted, 0.8));
        }
        if (envW) {
          const lx = W - envW;
          for (let r = 0; r < vh; r++) {
            const f = 1 - r / Math.max(1, vh - 1);
            const col = f < 0.6 ? th.pos : f < 0.85 ? th.warn : th.neg;
            const on = v.env >= f - 0.02;
            for (let i = 0; i < 2; i++) b.set(lx + 1 + i, y0 + r, on ? '▮' : '·', on ? col : lerpc(th.bg, col, 0.22));
          }
        }
        if (sx1 - sx0 >= 4) {
          const X0 = sx0 * cv.sx, X1 = sx1 * cv.sx;
          const midY = (y0 + vh / 2) * cv.sy;
          const amp = Math.max(0, (vh * cv.sy) / 2 - 1);
          const col = lerpc(th.bg, vc, 0.4 + 0.6 * Math.min(1, v.env * 1.3));
          let py = midY;
          for (let xp = X0; xp <= X1; xp++) {
            const u = (xp - X0) / (X1 - X0);
            const val = v.raw ? v.at(u) : v.at(u) * v.env;
            const y = midY - Math.max(-1, Math.min(1, val)) * amp;
            if (xp > X0) cv.line(xp - 1, py, xp, y, col);
            py = y;
          }
        }
      }
      cv.paint(b);
      if (chrome) {
        const y = H - 1;
        const cut = 0.34 + 0.26 * Math.sin((TAU * 2 * t) / SL + 1.2);
        b.text(1, y, 'FILTER LP', th.muted);
        const bw = Math.max(6, Math.min(24, W - 32));
        const n = Math.round(cut * bw);
        for (let i = 0; i < bw; i++) b.set(11 + i, y, i < n ? '▮' : '·', i < n ? th.accent : lerpc(th.bg, th.accent, 0.25));
        b.text(12 + bw, y, 'RES 7  VOL F', th.muted);
      }
    };
  },
};

// ──────────────────────────────────────────────────────────────  piano roll ──
const pianoRoll = {
  id: 'retro-piano-roll',
  since: '0.3.0',
  title: 'Piano Roll',
  category: 'Chiptune Visuals',
  kind: 'scene',
  order: 210,
  tags: ['piano', 'roll', 'falling-notes', 'keyboard', 'midi', 'chiptune', 'synthesia'],
  description: 'Falling piano-roll notes rain the chiptune onto a lit keyboard — channel-colored trails, bar guides with chord names and key flashes.',
  size: { w: 64, h: 20 },
  minSize: { w: 24, h: 8 },
  loop: SL,
  setup(ctx) {
    const th = ctx.theme, b = ctx.buffer, W = ctx.width, H = ctx.height;
    const kb = H >= 11 ? 2 : 1;
    const fh = H - kb;
    const LO = 34, HI = 84;
    const X = (n) => Math.round(((n - LO) / (HI - LO)) * (W - 1));
    const LA = 2.6;
    const chC = [th.warn, th.accent, th.info, th.pos];
    const DUR = [0.26, ROW * 2, ROW * 1.6, ROW * 0.8];
    const nw = W >= 96 ? 2 : 1;
    const evs = [];
    for (let r = 0; r < ROWS; r++) for (let ch = 0; ch < 4; ch++) {
      const ev = PATTERN[r][ch];
      if (ev) evs.push({ tt: r * ROW, ch, x: X(ev.note) });
    }
    const BLACK = new Set([1, 3, 6, 8, 10]);
    const white = lerpc(th.panel, 0xffffff, 0.72);
    const black = lerpc(th.bg, 0x000000, 0.55);
    const guide = lerpc(th.bg, th.line, 0.7);
    const barC = lerpc(th.bg, th.muted, 0.55);
    const CHORDS = ['Am', 'F', 'C', 'G'];
    const lit = new Int32Array(W);
    return (t) => {
      lit.fill(-1);
      // Bar and beat guides fall with the notes; bars carry their chord name.
      for (let k = 0; k < 16; k++) {
        const dte = wrap(k * 4 * ROW - t);
        if (dte >= LA) continue;
        const y = Math.round((fh - 1) * (1 - dte / LA));
        const strong = k % 4 === 0;
        for (let x = strong ? 0 : 1; x < W; x += strong ? 2 : 4) b.set(x, y, '╌', strong ? barC : guide);
        if (strong && W >= 30 && y > 0) b.text(1, y, CHORDS[(k >> 2) % 4], barC);
      }
      // Falling notes: the head leads, the tail fades out above it.
      for (const ev of evs) {
        const age = wrap(t - ev.tt);
        if (age < 0.14) for (let dx = 0; dx < nw; dx++) if (ev.x + dx < W) lit[ev.x + dx] = chC[ev.ch];
        const dte = wrap(ev.tt - t);
        if (dte >= LA) continue;
        const yh = Math.round((fh - 1) * (1 - dte / LA));
        const len = Math.max(1, Math.round((DUR[ev.ch] / LA) * (fh - 1)));
        const c = chC[ev.ch];
        for (let i = 0; i < len; i++) {
          const y = yh - i;
          if (y < 0 || y >= fh) continue;
          const col = i === 0 ? lerpc(c, 0xffffff, 0.25) : lerpc(th.bg, c, 1 - (i / len) * 0.7);
          for (let dx = 0; dx < nw; dx++) if (ev.x + dx < W) b.set(ev.x + dx, y, i === 0 ? '█' : '▓', col);
        }
      }
      // Keyboard: black keys on the top row, hits light the whole key.
      for (let x = 0; x < W; x++) {
        const n = LO + Math.round((x / Math.max(1, W - 1)) * (HI - LO));
        const isB = BLACK.has(((n % 12) + 12) % 12);
        const seam = ((n % 12) + 12) % 12 === 0;
        const hit = lit[x];
        for (let r = 0; r < kb; r++) {
          let col = hit >= 0 ? hit : r === 0 && kb === 2 && isB ? black : white;
          let ch = hit >= 0 ? '█' : r === 0 && kb === 2 && isB ? '▓' : '█';
          if (hit < 0 && seam && !(r === 0 && kb === 2 && isB)) col = lerpc(col, black, 0.3);
          b.set(x, fh + r, ch, col);
        }
        if (hit >= 0 && fh >= 2) b.set(x, fh - 1, '✦', lerpc(hit, 0xffffff, 0.5));
      }
    };
  },
};

// ─────────────────────────────────────────────────────────  step sequencer ──
const stepSeq = {
  id: 'retro-step-sequencer',
  since: '0.3.0',
  title: 'Step Sequencer',
  category: 'Chiptune Visuals',
  kind: 'scene',
  order: 220,
  tags: ['drum-machine', 'sequencer', '808', 'x0x', 'pads', 'steps', 'rhythm', 'chiptune'],
  description: 'An x0x drum machine view of the chiptune: 16 color-grouped pads per track, a sweeping playhead, hit flashes and a bass note lane.',
  size: { w: 68, h: 18 },
  minSize: { w: 32, h: 8 },
  loop: SL,
  setup(ctx) {
    const th = ctx.theme, b = ctx.buffer, W = ctx.width, H = ctx.height;
    const is = (ev, inst) => (ev && ev.inst === inst ? ev : null);
    const TR = [
      { lab: 'BD', c: th.neg, at: (r) => is(PATTERN[r][0], 3) },
      { lab: 'SD', c: th.warn, at: (r) => is(PATTERN[r][0], 4) },
      { lab: 'CH', c: th.accent, at: (r) => is(PATTERN[r][3], 5) },
      { lab: 'OH', c: th.info, at: (r) => is(PATTERN[r][3], 6) },
      { lab: 'BA', c: th.pos, at: (r) => PATTERN[r][1], note: true },
    ];
    const header = H >= 10 ? 1 : 0;
    const footer = H >= 14 ? 1 : 0;
    const lab = W >= 44 ? 3 : 0;
    const cw = Math.max(2, Math.floor((W - lab) / 16));
    const x0 = lab + Math.max(0, Math.floor((W - lab - cw * 16 + 1) / 2));
    let avail = H - header - footer;
    const marker = avail >= 6 ? 1 : 0;
    avail -= marker;
    const trH = avail >= 12 ? 2 : 1;
    const nT = Math.min(TR.length, Math.max(1, Math.floor(avail / trH)));
    const gap = avail - nT * trH >= nT - 1 ? 1 : 0;
    const topY = header + marker;
    const group = [th.neg, th.warn, th.accent, th.pos];
    const hx2 = (n) => n.toString(16).toUpperCase().padStart(2, '0');
    return (t) => {
      const s = songAt(t);
      const step = s.row & 15, bar = s.bar;
      if (header) {
        b.fill(0, 0, W, 1, ' ', th.ink, th.panel);
        b.text(1, 0, 'TR-64 RHYTHM COMPOSER', th.ink, th.panel);
        const beatLit = (s.t / (ROW * 4)) % 1 < 0.5;
        const right = `PTN A${bar + 1}  STEP ${hx2(s.row)}  BPM 125 `;
        if (W >= 56) b.text(W - right.length - 2, 0, right, th.muted, th.panel);
        b.set(W - 2, 0, '●', beatLit ? th.pos : lerpc(th.panel, th.pos, 0.25), th.panel);
      }
      if (marker) {
        const mx = x0 + step * cw + ((cw - 2) >> 1);
        b.set(mx, header, '▼', light(th));
      }
      for (let ti = 0; ti < nT; ti++) {
        const tr = TR[ti];
        const y = topY + ti * (trH + gap);
        if (lab) b.text(0, y, tr.lab, tr.c);
        for (let st = 0; st < 16; st++) {
          const ev = tr.at(bar * 16 + st);
          const g = group[st >> 2];
          let col = ev ? tr.c : lerpc(th.bg, g, 0.22);
          let chG = ev ? '█' : '▒';
          if (st === step) {
            col = ev && s.frac < 0.4 ? lerpc(tr.c, light(th), 0.65) : lerpc(col, light(th), 0.28);
            if (!ev) chG = '█';
          }
          const px = x0 + st * cw;
          for (let r2 = 0; r2 < trH; r2++) for (let dx = 0; dx < cw - 1; dx++) b.set(px + dx, y + r2, chG, col);
          if (tr.note && ev && cw >= 4) b.text(px, y, noteName(ev.note).slice(0, cw - 1), onFill(th, col));
        }
      }
      if (footer) {
        const y = H - 1;
        for (let st = 0; st < 16; st++) {
          const mx = x0 + st * cw;
          b.text(mx, y, st % 4 === 0 ? String(st / 4 + 1) : '·', st % 4 === 0 ? th.muted : lerpc(th.bg, th.muted, 0.6));
        }
        const tail = 'SHUF 54%';
        if (x0 + 16 * cw + tail.length + 1 < W) b.text(W - tail.length - 1, y, tail, lerpc(th.bg, th.muted, 0.8));
      }
    };
  },
};

export default [sidVoices, pianoRoll, stepSeq];

// Amiga copper bars: glossy horizontal bars swing past each other in depth,
// each a vertical gradient with a white-hot center line — the copper chip's
// party trick, now in a terminal.
import { lerpc, shade, ground } from './_kit.js';

export default {
  title: 'Copper Bars',
  gallery: 'retro',
  category: 'Raster & Copper',
  kind: 'scene',
  tags: ['copper', 'raster bars', 'amiga', 'demoscene', 'gradient'],
  order: 10,
  description: 'Glossy raster bars swinging through each other in depth, each a gradient with a white-hot core.',
  size: { w: 80, h: 20 },
  minSize: { w: 20, h: 6 },
  loop: 10,
  canvas: 'field',
  palette: 'prism',
  params: {
    bars: { default: 7, min: 2, max: 14, label: 'Bars' },
    speed: { default: 1, min: 0.25, max: 4, label: 'Speed' },
  },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const n = Math.round(ctx.param('bars', 7));
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px } = cv;
    const r = Math.max(2, H / 14);
    const bars = Array.from({ length: n }, (_, i) => ({ phase: (i / n) * Math.PI * 2, color: pal(i / n) }));
    const bg = ctx.theme.bg, base = ground(ctx.theme);
    return (t) => {
      const tt = t * speed;
      for (let y = 0; y < H; y++) px.fill(shade(ctx.theme, 0.35 * Math.abs(y / H - 0.5) * 2), y * W, (y + 1) * W);
      const live = bars.map((b) => {
        const a = tt * 1.4 + b.phase;
        return { y: H / 2 + Math.sin(a) * (H / 2 - r - 1) * 0.92, z: Math.cos(a), color: b.color };
      }).sort((a, b) => a.z - b.z);
      for (const b of live) {
        const rr = r * (0.75 + 0.35 * (b.z + 1) / 2);
        const depth = 0.55 + 0.45 * (b.z + 1) / 2;
        for (let y = Math.max(0, Math.floor(b.y - rr)); y <= Math.min(H - 1, Math.ceil(b.y + rr)); y++) {
          const d = Math.abs(y + 0.5 - b.y) / rr;
          if (d > 1) continue;
          const k = 1 - d;
          let c = lerpc(base, b.color, Math.min(1, k * 1.6) * depth);
          if (k > 0.72) c = lerpc(c, 0xffffff, (k - 0.72) / 0.28 * 0.85 * depth);
          px.fill(c, y * W, (y + 1) * W);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

