// Dot tunnel: rings of dots flying at the camera along a snaking path, each
// ring twisted a little further than the last. Near dots are big and bright,
// far ones fade into the dark — braille makes the dots razor sharp.
import { lerpc } from './_kit.js';

export default {
  title: 'Dot Tunnel',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['tunnel', 'dots', 'demoscene', '3d', 'braille'],
  order: 50,
  description: 'Rings of dots racing at the camera along a snaking path, twisting ring by ring, fading with depth.',
  size: { w: 70, h: 24 },
  minSize: { w: 20, h: 8 },
  loop: 10,
  canvas: 'line',
  palette: 'prism',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, aspect } = cv;
    const VH = H * aspect;
    const RINGS = 30, DOTS = 28, DEPTH = 18;
    const f = Math.min(W, VH) * 0.62;
    const bg = ctx.theme.bg;
    const path = (z, t) => [Math.sin(z * 0.23 + t * 0.9) * 1.1, Math.cos(z * 0.17 + t * 0.7) * 0.8];
    return (t) => {
      const tt = t * speed;
      cv.clear();
      const travel = tt * 5;
      const [camX, camY] = path(travel, tt);
      for (let r = RINGS - 1; r >= 0; r--) {
        const zWorld = Math.floor(travel) + r + 1;
        const z = zWorld - travel;                 // distance from camera
        if (z <= 0.15) continue;
        const [ox, oy] = path(zWorld, tt);
        const fade = Math.pow(1 - Math.min(1, z / DEPTH), 0.55);
        const c = lerpc(bg, lerpc(pal((zWorld * 0.045) % 1), 0xffffff, 0.15 * fade), 0.2 + 0.8 * fade);
        const twist = zWorld * 0.35 + tt * 0.8;
        for (let d = 0; d < DOTS; d++) {
          const a = (d / DOTS) * Math.PI * 2 + twist;
          const x = W / 2 + ((ox - camX + Math.cos(a) * 1.6) * f) / z;
          const y = (VH / 2 + ((oy - camY + Math.sin(a) * 1.6) * f) / z) / aspect;
          cv.set(x, y, c);
          if (z < 2.2) { cv.set(x + 1, y, c); cv.set(x, y + 1, c); cv.set(x + 1, y + 1, c); }
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/dycp-scrolle:
// DYCP — "Different Y Character Position", the C64 scroller where every
// letter bobs on its own sine phase. This one bounces off a mirrored water line
// that ripples its reflection.
import { textMask, maskAt, fontPx, lerpc, dim, shade } from './_kit.js';

const MESSAGE = 'DIFFERENT Y CHARACTER POSITION   ';

export default {
  title: 'DYCP Scroller',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['dycp', 'scroller', 'c64', 'reflection', 'demoscene'],
  order: 20,
  description: 'C64-style DYCP scroller: every letter bobs on its own sine, mirrored in a rippling water line.',
  size: { w: 80, h: 20 },
  minSize: { w: 30, h: 8 },
  loop: 10,
  canvas: 'field',
  palette: 'candy',
  params: {
    text: { default: MESSAGE, label: 'Message' },
    speed: { default: 1, min: 0.25, max: 4, label: 'Speed' },
  },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const text = String(ctx.param('text', MESSAGE)).toUpperCase();
    const { width: W, height: H, px } = cv;
    const water = Math.round(H * 0.68);
    const S = fontPx(cv, Math.max(2, ctx.height * 0.22), 7);
    const chars = [...text].map((ch) => textMask(ch === ' ' ? ' ' : ch, { font: 'bold' }));
    const adv = chars.map((m) => (m.w + 1) * S.sx);
    const total = adv.reduce((a, b) => a + b, 0);
    const ch = 7 * S.sy;
    const amp = Math.max(1, (water - ch) * 0.42);
    const bg = ctx.theme.bg;
    const day = ctx.theme.mode === 'light';
    const sky0 = shade(ctx.theme, 0.25), sky1 = lerpc(bg, pal(0.3), 0.18);
    const sea = day ? lerpc(bg, pal(0.55), 0.3) : dim(pal(0.55), 0.22);
    return (t) => {
      const tt = t * speed;
      for (let y = 0; y < H; y++) {
        const c = y < water ? lerpc(sky0, sky1, y / water) : lerpc(sea, bg, (y - water) / (H - water));
        px.fill(c, y * W, (y + 1) * W);
      }
      let x0 = W - ((tt * 24 * S.sx) % (total + W));
      for (let i = 0; i < chars.length * 2; i++) {
        const k = i % chars.length;
        const m = chars[k];
        const gx = Math.round(x0);
        x0 += adv[k];
        if (gx > W || gx + adv[k] < 0 || text[k] === ' ') continue;
        const gy = Math.round(water - ch - 1 - Math.abs(Math.sin(tt * 2.6 + i * 0.55)) * amp);
        const color = pal((k / chars.length + tt * 0.1) % 1);
        for (let y = 0; y < ch; y++) for (let x = 0; x < m.w * S.sx; x++) {
          if (!maskAt(m, x, y, S.sx, S.sy)) continue;
          // The top row catches the light: white at Night; by Day it's the color itself over a deeper body.
          const c = day ? (y < S.sy ? color : lerpc(color, ctx.theme.ink, 0.2)) : y < S.sy ? lerpc(color, 0xffffff, 0.5) : color;
          cv.set(gx + x, gy + y, c);
          // Reflection below the water line, rippled and darker.
          const ry = water + (water - (gy + y)) - 1;
          if (ry < H) cv.set(gx + x + Math.round(Math.sin(ry * 0.9 + tt * 4) * 1.2), ry, lerpc(c, bg, 0.6));
        }
      }
      for (let x = 0; x < W; x++) px[water * W + x] = lerpc(pal(0.6), 0xffffff, 0.3 + 0.2 * Math.sin(x * 0.4 + tt * 3));
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/intro-effect:
// Four staples of the 1990 cracktro, canvas-rendered with loop-closed sine
// paths: shadebobs smearing additive trails, the infinite chessboard zoom,
// a waving sinus dot-flag, and a glass column refracting a copper backdrop.
import { lerpc, clamp01, fract, ground } from './_kit.js';

const TAU = Math.PI * 2;

export default [
  {
    id: 'retro-shadebobs',
    since: '0.3.0',
    title: 'Shadebobs',
    gallery: 'retro',
    category: 'Intros & Scrollers',
    kind: 'scene',
    tags: ['shadebobs', 'bobs', 'trails', 'lissajous', 'amiga', 'demoscene', 'cracktro', 'additive'],
    order: 200,
    description: 'Soft bobs on closed Lissajous paths smear additive heat trails that bloom and decay, Amiga shadebob style.',
    size: { w: 80, h: 22 },
    minSize: { w: 20, h: 6 },
    loop: 12,
    canvas: 'field',
    palette: 'magma',
    credits: 'after the Amiga shadebob intros',
    params: {
      bobs: { default: 3, min: 1, max: 6, label: 'Bobs' },
      speed: { default: 1, min: 0.25, max: 4, label: 'Speed' },
    },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const speed = ctx.param('speed', 1);
      const nBobs = Math.max(1, Math.round(ctx.param('bobs', 3)));
      const { width: W, height: H, px, aspect } = cv;
      const heat = new Float32Array(W * H);
      const base = ground(ctx.theme);
      // heat -> color, pre-blended toward the ground tone so decay fades cleanly
      const LUT = new Int32Array(160);
      for (let i = 0; i < 160; i++) {
        const v = i / 159;
        LUT[i] = lerpc(base, pal(0.08 + v * 0.88), Math.min(1, v * 1.7));
      }
      const r = Math.max(2.2, Math.min(W, H * aspect) / 7.5);
      const Rx = Math.ceil(r), Ry = Math.max(1, Math.ceil(r / aspect));
      // gaussian stamp kernel as flat buffer offsets (bob centers never reach the rim)
      const off = [], wgt = [];
      for (let dy = -Ry; dy <= Ry; dy++) for (let dx = -Rx; dx <= Rx; dx++) {
        const d = Math.hypot(dx, dy * aspect) / r;
        if (d > 1) continue;
        off.push(dy * W + dx);
        wgt.push(Math.exp(-d * d * 2.6) * 0.2);
      }
      const ax = Math.max(0, W / 2 - Rx - 1), ay = Math.max(0, H / 2 - Ry - 1);
      return (t, dt) => {
        const decay = Math.exp(-Math.min(0.25, dt) * 1.1);
        for (let i = 0; i < heat.length; i++) heat[i] *= decay;
        const step = Math.min(0.25, dt) / 3;
        for (let b = 0; b < nBobs; b++) {
          const ph = (b / nBobs) * TAU;
          const w1 = (TAU / 12) * (2 + (b % 3)), w2 = (TAU / 12) * (3 + (b % 2));
          for (let s = 0; s < 3; s++) {
            const ts = (t - s * step) * speed;
            const cx = Math.round(W / 2 + Math.sin(ts * w1 + ph) * ax);
            const cy = Math.round(H / 2 + Math.cos(ts * w2 + ph * 1.7) * ay);
            const c0 = cy * W + cx;
            for (let k = 0; k < off.length; k++) heat[c0 + off[k]] += wgt[k];
          }
        }
        for (let i = 0; i < heat.length; i++) {
          const h = heat[i];
          px[i] = LUT[h >= 1 ? 159 : (h * 159) | 0];
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'retro-chessboard-zoomer',
    since: '0.3.0',
    title: 'Chessboard Zoomer',
    gallery: 'retro',
    category: 'Intros & Scrollers',
    kind: 'scene',
    tags: ['checkerboard', 'zoom', 'tunnel', 'log-polar', 'spiral', 'cracktro', 'demoscene'],
    order: 210,
    description: 'An endless checkerboard rushes out of the screen center, breathing into a spiral as it zooms forever.',
    size: { w: 80, h: 22 },
    minSize: { w: 20, h: 6 },
    loop: 12,
    canvas: 'field',
    palette: 'prism',
    credits: 'after the infinite-zoom checkers of 90s cracktros',
    params: {
      segments: { default: 8, min: 4, max: 16, label: 'Segments' },
      speed: { default: 1, min: 0.25, max: 4, label: 'Speed' },
    },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const speed = ctx.param('speed', 1);
      const S = Math.max(4, Math.round(ctx.param('segments', 8) / 2) * 2); // even, so the seam wraps
      const { width: W, height: H, px, aspect } = cv;
      const n = W * H;
      const lr = new Float32Array(n), an = new Float32Array(n), fog = new Float32Array(n);
      const maxR = Math.hypot(W / 2, (H / 2) * aspect);
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        const dx = x - W / 2 + 0.5, dy = (y - H / 2 + 0.5) * aspect;
        const rr = Math.max(0.8, Math.hypot(dx, dy));
        const i = y * W + x;
        lr[i] = Math.log(rr) * 2.6;
        an[i] = (Math.atan2(dy, dx) / TAU + 0.5) * S;
        const d = clamp01(Math.log(rr) / Math.log(maxR + 1));
        fog[i] = d * d * (3 - 2 * d);
      }
      const base = ground(ctx.theme);
      return (t) => {
        const tt = t * speed;
        const zoom = tt * 2;                 // 24 rings per 12 s loop
        const rot = tt * (S / 12);           // one full segment turn per loop
        const twist = Math.sin(tt * (TAU / 12)) * 0.9;
        const hue = fract(tt / 12);
        const A = pal(fract(hue + 0.55));
        const B = lerpc(base, pal(hue), 0.35);
        const haze = lerpc(base, pal(fract(hue + 0.8)), 0.25);
        for (let i = 0; i < n; i++) {
          const u = lr[i] - zoom, v = an[i] + twist * lr[i] + rot;
          px[i] = lerpc(haze, (Math.floor(u) + Math.floor(v)) & 1 ? A : B, fog[i]);
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'retro-sine-dot-grid',
    since: '0.3.0',
    title: 'Sine Dot Grid',
    gallery: 'retro',
    category: 'Raster & Copper',
    kind: 'scene',
    tags: ['dots', 'sinus', 'dot flag', 'lattice', 'wave', 'perspective', 'amiga', 'demoscene'],
    order: 200,
    description: 'A perspective lattice of dots riding two crossed traveling sines — the sinus dot-flag every intro coder wrote.',
    size: { w: 80, h: 22 },
    minSize: { w: 20, h: 6 },
    loop: 8,
    canvas: 'line',
    palette: 'prism',
    credits: 'after the Amiga and Atari sinus dot flags',
    params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const speed = ctx.param('speed', 1);
      const { width: W, height: H } = cv;
      const base = ground(ctx.theme);
      const gx = Math.max(12, Math.min(56, Math.round(W / 3)));
      const gz = Math.max(7, Math.min(30, Math.round(H / 3.2)));
      const w1 = TAU * 2 / 8, w2 = TAU * 3 / 8, w3 = TAU / 8; // all close over the 8 s loop
      return (t) => {
        cv.clear();
        const tt = t * speed;
        for (let j = 0; j < gz; j++) {                   // far -> near, near dots win the cell
          const fz = gz === 1 ? 1 : j / (gz - 1);
          const z = 2.75 - fz * 2.1;
          const dim = 0.3 + 0.7 * fz;
          for (let i = 0; i < gx; i++) {
            const wx = (gx === 1 ? 0 : i / (gx - 1) - 0.5) * 3.0;
            const wave = Math.sin(wx * 2.2 + tt * w1 + fz * 5.2) * Math.cos(fz * 4.4 - tt * w2) * 0.52
              + Math.sin(wx * 0.9 - tt * w3) * 0.2;
            const sx = W / 2 + (wx / z) * W * 0.46;
            const sy = H * 0.16 + ((0.55 + wave * 0.8) / z) * H * 0.9;
            cv.set(sx, sy, lerpc(base, pal(clamp01(0.5 + wave * 0.95)), dim));
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'retro-glass-bar',
    since: '0.3.0',
    title: 'Glass Bar',
    gallery: 'retro',
    category: 'Raster & Copper',
    kind: 'scene',
    tags: ['glass', 'lens', 'refraction', 'column', 'raster', 'cracktro', 'amiga'],
    order: 210,
    description: 'A polished glass column glides over a dotted copper backdrop, magnifying and bending whatever it crosses.',
    size: { w: 80, h: 20 },
    minSize: { w: 20, h: 6 },
    loop: 10,
    canvas: 'field',
    palette: 'prism',
    credits: 'after the Amiga glass-column cracktros',
    params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px } = cv;
      const base = ground(ctx.theme);
      const back = new Int32Array(W * H);
      for (let y = 0; y < H; y++) {
        const v = y / Math.max(1, H - 1);
        for (let x = 0; x < W; x++) {
          const u = x / W;
          let c = lerpc(base, pal(fract(u * 0.5 + v * 0.22 + 0.04)), 0.3 + 0.25 * Math.sin(v * Math.PI));
          if (Math.abs(v - 0.26) < 0.05 || Math.abs(v - 0.72) < 0.05) c = lerpc(c, 0xffffff, 0.28);
          if (x % 10 === 4 && y % 8 === 3) c = lerpc(c, ctx.theme.ink, 0.6);
          back[y * W + x] = c;
        }
      }
      const hw = Math.max(3, Math.round(W * 0.1));
      const tint = pal(0.52);
      return (t) => {
        const tt = t * speed;
        px.set(back);
        const xB = W / 2 + Math.sin(tt * (TAU / 10)) * Math.max(0, W / 2 - hw - 1);
        const x0 = Math.max(0, Math.ceil(xB - hw)), x1 = Math.min(W - 1, Math.floor(xB + hw));
        for (let x = x0; x <= x1; x++) {
          const u = (x - xB) / hw;
          if (u < -1 || u > 1) continue;
          const sxp = Math.min(W - 1, Math.max(0, Math.round(xB + Math.sin(u * Math.PI / 2) * hw * 0.45)));
          const au = Math.abs(u);
          const edge = au > 0.78 ? (au - 0.78) / 0.22 : 0;
          const bend = (1 - au) * 1.8;
          for (let y = 0; y < H; y++) {
            const ys = Math.min(H - 1, Math.max(0, y + ((Math.sin(y * 0.18 + tt * (TAU * 3 / 10)) * bend) | 0)));
            let c = back[ys * W + sxp];
            c = lerpc(c, tint, 0.14);
            c = lerpc(c, 0xffffff, 0.1 + edge * 0.5);
            px[y * W + x] = c;
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

sources.prism-term/src/facets/retro/kefrens-bars:
// Kefrens bars (a.k.a. Alcatraz bars): one short shaded bar is redrawn on every
// scanline at a wandering x, and each line keeps what the line above drew —
// so the bars stack into a twisting staircase of cylinders. Pure 1990 magic.
import { lerpc } from './_kit.js';

export default {
  title: 'Kefrens Bars',
  gallery: 'retro',
  category: 'Raster & Copper',
  kind: 'scene',
  tags: ['kefrens', 'alcatraz', 'raster', 'amiga', 'demoscene'],
  order: 20,
  description: 'One shaded bar per scanline that never gets erased, stacking into a twisting staircase of cylinders.',
  size: { w: 80, h: 22 },
  minSize: { w: 24, h: 8 },
  loop: 12,
  canvas: 'field',
  palette: 'prism',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px } = cv;
    const bw = Math.max(3, Math.round(W / 14));
    const row = new Int32Array(W);
    const bg = ctx.theme.bg;
    return (t) => {
      const tt = t * speed;
      row.fill(bg);
      for (let y = 0; y < H; y++) {
        const x0 = Math.round(W / 2 - bw / 2
          + Math.sin(y * 0.11 + tt * 1.9) * W * 0.22
          + Math.sin(y * 0.047 - tt * 1.3) * W * 0.16);
        const c = pal((y / H) * 0.85 + tt * 0.07);
        for (let k = 0; k < bw; k++) {
          const x = x0 + k;
          if (x < 0 || x >= W) continue;
          const u = (k + 0.5) / bw * 2 - 1;          // -1..1 across the bar
          const shade = Math.sqrt(1 - u * u);       // cylinder
          let col = lerpc(0x000000, c, 0.25 + 0.75 * shade);
          if (shade > 0.9) col = lerpc(col, 0xffffff, (shade - 0.9) * 6);
          row[x] = col;
        }
        px.set(row, y * W);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/modem-connec:
// Dialing in, 1992: the modem init string, the dial, RINGING, CONNECT 2400,
// then the board's welcome screen painting itself cell by cell at line speed —
// cursor racing ahead of the paint — until NO CARRIER sends you back to start.
import { CellBuffer } from '../../buffer.js';
import { textMask, bbsPalette } from './_kit.js';
import { blockLogo, frame } from './_bbs.js';

const SCRIPT = [
  [0.0, 'ATZ'], [0.6, 'OK'], [1.0, 'ATDT 555-0142'], [2.4, 'RINGING'], [3.4, 'RINGING'], [4.2, 'CONNECT 2400/ARQ/V42BIS'],
];
const PAINT_AT = 5.0, PAINT = 3.4, HOLD = 2.6;

function welcome(W, H, P) {
  const s = new CellBuffer(W, H);
  s.clear(P[0]);
  const logo = textMask('PRISM', { font: 'bold' });
  const sx = logo.w * 2 + 2 <= W ? 2 : 1;
  let y = 1;
  if (H >= 14 && logo.w * sx <= W) {
    blockLogo(s, Math.floor((W - logo.w * sx) / 2), y, logo, { sx, ramp: (v) => (v < 0.25 ? P[15] : v < 0.5 ? P[14] : v < 0.8 ? P[6] : P[4]), shadow: P[8] });
    y += 5;
  }
  const lines = [['P R I S M   B B S', P[11]], ['300 · 1200 · 2400 bps · 24 hours · 2 nodes', P[7]], ['', 0], ['Home of the terminal art underground', P[6]]];
  for (const [text, c] of lines) { if (y < H - 4 && text) s.text(Math.max(0, Math.floor((W - text.length) / 2)), y, text, c); y++; }
  const fw = Math.min(W - 2, 44), fx = Math.floor((W - fw) / 2);
  if (y + 4 <= H) {
    frame(s, fx, y, fw, 4, P[2], 'NEWS', P[10]);
    s.text(fx + 2, y + 1, 'New door game: TradeWars 2002 on node 2'.slice(0, fw - 4), P[7]);
    s.text(fx + 2, y + 2, 'Upload ratio waived this weekend'.slice(0, fw - 4), P[7]);
  }
  return s;
}

export default {
  title: 'Modem Connect',
  gallery: 'retro',
  category: 'BBS & ANSI Art',
  kind: 'art',
  tags: ['modem', 'dial-up', 'bbs', 'ansi', 'connect', 'hayes', '2400 baud'],
  order: 50,
  description: 'Dialing a BBS: ATZ, ATDT, RINGING, CONNECT 2400 — then the welcome screen paints in at line speed.',
  size: { w: 80, h: 22 },
  minSize: { w: 40, h: 10 },
  loop: 12,
  color: '16',
  params: { colors: { default: 'vga', options: ['vga', 'theme'], label: 'Colors' } },
  setup(ctx) {
    const P = bbsPalette(ctx);
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const screen = welcome(W, H - 1, P);
    const total = W * (H - 1);
    const paintDur = PAINT, CPS = total / PAINT;
    const loop = PAINT_AT + PAINT + HOLD + 1;
    const statusBar = (lt, online) => {
      const secs = online ? Math.floor(lt - 4.2) : 0;
      const clock = `${String(Math.floor(secs / 60)).padStart(2, '0')}:${String(secs % 60).padStart(2, '0')}`;
      b.fill(0, H - 1, W, 1, ' ', P[0], P[3]);
      const parts = ['PRiSMTERM 3.51', 'Alt-Z Help', 'ANSI-BBS', '2400 N81', 'FDX', online ? `Online ${clock}` : 'Offline'];
      let x = 1;
      for (const [i, p] of parts.entries()) {
        if (x + p.length >= W) break;
        x = b.text(x, H - 1, p, i === parts.length - 1 && online ? P[15] : P[0], P[3]);
        if (i < parts.length - 1 && x + 3 < W) x = b.text(x, H - 1, ' │ ', P[1], P[3]);
      }
    };
    const dialBox = (lt) => {
      const bw = Math.min(W - 4, 36), bh = 6;
      if (H < bh + 4) return;
      const bx = Math.floor((W - bw) / 2), by = Math.max(SCRIPT.length + 1, Math.floor((H - bh) / 2));
      b.fill(bx, by, bw, bh, ' ', P[15], P[1]);
      frame(b, bx, by, bw, bh, P[11], 'Dialing', P[15]);
      const rows = [['System', 'PRISM BBS'], ['Number', '555-0142'], ['Elapsed', `${Math.floor((lt - 1) * 3)}s`], ['Status', lt < 2.4 ? 'Dialing' : lt < 4.2 ? 'Ringing' : 'CONNECT']];
      rows.forEach(([k, v], i) => {
        b.text(bx + 2, by + 1 + i, `${k}:`.padEnd(9), P[7], P[1]);
        b.text(bx + 11, by + 1 + i, v.slice(0, bw - 13), i === 3 && lt >= 4.2 ? P[10] : P[14], P[1]);
      });
    };
    return (t) => {
      const lt = t % loop;
      b.fill(0, 0, W, H, ' ', P[7], P[0]);
      const blink = Math.floor(t * 3) % 2 === 0;
      if (lt < PAINT_AT) {
        let y = 0;
        for (const [at, text] of SCRIPT) {
          if (lt < at || y >= H - 1) break;
          const isCmd = text.startsWith('AT');
          const shown = isCmd ? text.slice(0, Math.floor((lt - at) * 14)) : text;
          const end = b.text(0, y, shown, isCmd ? P[15] : text.startsWith('CONNECT') ? P[10] : P[7]);
          if (isCmd && shown.length < text.length && blink) b.set(end, y, '█', P[7]);
          y++;
        }
        if (lt >= 1 && lt < PAINT_AT - 0.3) dialBox(lt);
        statusBar(lt, lt >= 4.2);
        return;
      }
      // Paint the welcome screen in transmission order, cursor at the head.
      const n = Math.min(total, Math.floor((lt - PAINT_AT) * CPS));
      for (let i = 0; i < n; i++) {
        const x = i % W, y = (i / W) | 0;
        const c = screen.get(x, y);
        b.set(x, y, c.ch, c.fg, c.bg, c.attr);
      }
      if (n < total) b.set(n % W, (n / W) | 0, '█', P[7]);
      if (lt > PAINT_AT + paintDur + HOLD) {
        b.fill(0, H - 2, W, 1, ' ', P[7], P[0]);
        b.text(0, H - 2, 'NO CARRIER', P[12]);
      }
      statusBar(lt, lt <= PAINT_AT + paintDur + HOLD);
    };
  },
};

sources.prism-term/src/facets/retro/neon-skyline:
// A neon city at night drifting past in three parallax layers: hazy far
// towers, mid-rise blocks full of lit windows, near buildings trimmed in neon
// with flickering signs — searchlights sweeping the clouds, traffic streaming
// along the waterfront, and the whole thing mirrored in a rippling harbour.
import { lerpc, hash2 } from './_kit.js';

const LOOP = 40;
const add = (a, b, k) => {
  const r = Math.min(255, ((a >> 16) & 255) + ((b >> 16) & 255) * k);
  const g = Math.min(255, ((a >> 8) & 255) + ((b >> 8) & 255) * k);
  const bl = Math.min(255, (a & 255) + (b & 255) * k);
  return (r << 16) | (g << 8) | bl;
};

export default {
  title: 'Neon Skyline',
  gallery: 'retro',
  category: 'Outrun',
  kind: 'scene',
  tags: ['city', 'skyline', 'neon', 'night', 'parallax', 'reflection', 'synthwave', 'cyberpunk'],
  order: 20,
  description: 'A neon city drifting past in parallax: lit windows, neon trim, searchlights, waterfront traffic and a rippling harbour.',
  size: { w: 80, h: 22 },
  minSize: { w: 24, h: 8 },
  loop: LOOP,
  canvas: 'field',
  palette: 'synthwave',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { width: PW, height: PH, px, aspect } = cv;
    const waterY = Math.floor(PH * 0.72);
    const road = waterY - Math.max(2, Math.round(PH * 0.03));
    const pitch = Math.max(2, Math.round(PH / 24));                 // window grid in pixels
    const neon = [0xff3fd0, 0x3ff0ff, 0xffe45a, pal(0.62), 0x7a5cff];
    const scale = Math.max(1, PW / 80);
    // Each layer is a strip of buildings exactly one loop's travel long, so the drift repeats seamlessly.
    const LAYERS = [
      { speed: PW / 20, hMin: 0.22, hMax: 0.6, wMin: 4, wMax: 10, body: lerpc(pal(0.1), pal(0.24), 0.5), lit: 0.16, haze: 0.45 },
      { speed: PW / 10, hMin: 0.16, hMax: 0.48, wMin: 5, wMax: 12, body: lerpc(pal(0.07), pal(0.16), 0.5), lit: 0.42, haze: 0.18 },
      { speed: PW / 5, hMin: 0.08, hMax: 0.36, wMin: 8, wMax: 17, body: lerpc(pal(0.02), 0x000000, 0.5), lit: 0.3, haze: 0, near: true },
    ].map((L, li) => {
      const len = Math.round(L.speed * LOOP);
      const owner = new Int32Array(len), local = new Int32Array(len), bs = [];
      let x = 0, j = 0;
      while (x < len) {
        let w = Math.round((L.wMin + hash2(j, li, 1) * (L.wMax - L.wMin)) * scale);
        if (len - x - w < L.wMin * scale) w = len - x;
        const top = waterY - Math.round(PH * (L.hMin + Math.pow(hash2(j, li, 2), 1.3) * (L.hMax - L.hMin)));
        bs.push({ w, top, trim: L.near && hash2(j, li, 3) < 0.5, sign: L.near && hash2(j, li, 7) < 0.4, c: neon[Math.floor(hash2(j, li, 4) * neon.length)], mast: hash2(j, li, 5) < 0.3, tone: hash2(j, li, 6) });
        for (let i = 0; i < w && x + i < len; i++) { owner[x + i] = j; local[x + i] = i; }
        x += w; j++;
      }
      return { ...L, len, owner, local, bs };
    });
    const skyTop = pal(0.01), skyMid = pal(0.14), skyLow = pal(0.42);
    const stars = Array.from({ length: Math.round(PW * PH * 0.005) }, (_, i) => [Math.floor(hash2(i, 9) * PW), Math.floor(hash2(i, 8) * waterY * 0.45), hash2(i, 7)]);
    const above = new Int32Array(PW * waterY);
    const warm = 0xffd38a, cool = 0xa8ecff;
    const beams = [{ x: 0.28, ph: 0, sp: 0.31 }, { x: 0.71, ph: 2.1, sp: 0.23 }];

    return (t) => {
      const lt = t % LOOP;
      for (let y = 0; y < waterY; y++) {
        const v = y / waterY;
        above.fill(v < 0.5 ? lerpc(skyTop, skyMid, v / 0.5) : lerpc(skyMid, skyLow, Math.pow((v - 0.5) / 0.5, 1.3)), y * PW, (y + 1) * PW);
      }
      for (const [x, y, k] of stars) if (Math.sin((t * Math.PI * (1 + Math.floor(k * 3))) / 10 + k * 30) > -0.2) above[y * PW + x] = lerpc(skyMid, 0xffffff, 0.45 + k * 0.4);
      // Searchlights: soft additive cones swinging slowly across the sky.
      for (const bm of beams) {
        const ang = Math.sin((lt * Math.PI * 2 * 2) / LOOP + bm.ph) * 0.55;    // two sweeps per loop
        const ox = bm.x * PW, oy = waterY, dx = Math.sin(ang), dy = -Math.cos(ang);
        for (let y = 0; y < waterY; y++) for (let x = 0; x < PW; x++) {
          const vx = x + 0.5 - ox, vy = (y + 0.5 - oy) * aspect;
          const along = vx * dx + vy * dy;
          if (along <= 0) continue;
          const across = Math.abs(vx * dy - vy * dx), width = 0.6 + along * 0.09;
          if (across < width) above[y * PW + x] = add(above[y * PW + x], pal(0.7), 0.32 * (1 - across / width) * Math.max(0, 1 - along / (PW * 0.9)));
        }
      }
      for (const L of LAYERS) {
        const scroll = lt * L.speed;
        for (let x = 0; x < PW; x++) {
          const wx = Math.floor(x + scroll) % L.len, j = L.owner[wx], lx = L.local[wx], bd = L.bs[j];
          for (let y = Math.max(0, bd.top); y < waterY; y++) {
            let c = L.haze ? lerpc(L.body, skyLow, L.haze * (0.4 + 0.6 * ((y - bd.top) / (waterY - bd.top)))) : L.body;
            const wy = y - bd.top - 1, edge = lx === 0 || lx === bd.w - 1;
            if (!edge && wy > 0 && lx % pitch === 1 && wy % pitch === 1) {
              const cxI = (lx / pitch) | 0, cyI = (wy / pitch) | 0;
              const on = hash2(j * 31 + cxI, cyI, Math.floor(lt / 8 + hash2(j, cxI, cyI) * 5)) < L.lit;
              if (on) c = lerpc(bd.tone < 0.65 ? warm : cool, c, L.haze * 0.9);
            }
            if (bd.sign && lx >= 2 && lx < 2 + pitch && wy > pitch && wy < pitch * 7) {
              const flick = hash2(j, Math.floor(t * 12), 5) < 0.05 ? 0.2 : 1;
              c = lerpc(L.body, wy % (pitch * 2) < pitch ? bd.c : lerpc(bd.c, 0xffffff, 0.4), flick);
            }
            above[y * PW + x] = c;
          }
          // Neon trim along the roofline and down the edges of some near buildings.
          if (bd.trim && bd.top >= 0) {
            above[bd.top * PW + x] = bd.c;
            if (lx === 0 || lx === bd.w - 1) for (let y = bd.top; y < Math.min(road, bd.top + pitch * 4); y++) above[y * PW + x] = lerpc(bd.c, L.body, (y - bd.top) / (pitch * 4));
          }
          if (bd.mast && lx === bd.w >> 1) {
            const mh = Math.max(2, pitch * 2);
            for (let y = Math.max(0, bd.top - mh); y < bd.top; y++) above[y * PW + x] = L.body;
            if ((lt + j * 0.37) % 2 < 0.5 && bd.top - mh - 1 >= 0) above[(bd.top - mh - 1) * PW + x] = lerpc(L.body, 0xff3040, L.haze ? 0.55 : 1);
          }
        }
      }
      // Waterfront road: a dark deck with headlights streaming right and tail-lights left.
      for (let y = road; y < waterY; y++) above.fill(0x0a0612, y * PW, (y + 1) * PW);
      for (let i = 0; i < Math.ceil(PW / 14); i++) {
        const xr = Math.floor((hash2(i, 1) * PW + lt * PW * 0.25) % PW), xl = Math.floor((((hash2(i, 2) * PW - lt * PW * 0.2) % PW) + PW) % PW);
        above[road * PW + xr] = 0xfff4d0;
        if (road + 1 < waterY) above[(road + 1) * PW + xl] = 0xff3a3a;
      }
      for (let x = (PW >> 3) % 7; x < PW; x += 7) above[(road - 1) * PW + x] = lerpc(warm, above[(road - 1) * PW + x], 0.3);
      px.set(above);
      // Harbour: the city upside down, rippled sideways, lights stretching into streaks.
      const water = lerpc(skyTop, 0x000000, 0.3);
      for (let y = waterY; y < PH; y++) {
        const d = y - waterY, k = d / Math.max(1, PH - waterY);
        const my = waterY - 1 - Math.floor(d * 0.8);
        const off = Math.round(Math.sin(d * 1.3 + (t * Math.PI * 2 * 8) / LOOP) * (0.5 + k * 2) + Math.sin(d * 0.5 - (t * Math.PI * 2 * 5) / LOOP) * k * 1.4);
        for (let x = 0; x < PW; x++) {
          const sx = Math.min(PW - 1, Math.max(0, x + off));
          const src = my >= 0 ? above[my * PW + sx] : skyTop;
          px[y * PW + x] = lerpc(src, water, 0.38 + k * 0.3);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

// Outrun nights, three ways: the cabin view of a rainy drive with a working
// wiper; a per-pixel neon highway tunnel flying past; and a night dashboard
// with real gauge needles, gear shifts and blinking indicators.
import { lerpc, fract, hash2 } from './_kit.js';
import { light } from '../charts/_data.js';

const TAU = Math.PI * 2;
const addc = (a, b, k) => {
  if (k <= 0) return a;
  const r = Math.min(255, ((a >> 16) & 255) + ((b >> 16) & 255) * k);
  const g = Math.min(255, ((a >> 8) & 255) + ((b >> 8) & 255) * k);
  const bl = Math.min(255, (a & 255) + (b & 255) * k);
  return (r << 16) | (g << 8) | bl;
};

// ──────────────────────────────────────────────────────────────  rain drive ──
const rainDrive = {
  id: 'retro-rain-drive',
  since: '0.3.0',
  title: 'Rain Drive',
  category: 'Outrun',
  kind: 'scene',
  order: 210,
  tags: ['rain', 'night', 'drive', 'wiper', 'windshield', 'neon', 'tail-lights', 'outrun'],
  description: 'Behind the windshield on a rainy night drive: smeared tail-lights, passing lamps, rain streaks, drops that regrow after every wiper sweep.',
  size: { w: 80, h: 24 },
  minSize: { w: 24, h: 8 },
  loop: 12.8,
  canvas: 'field',
  palette: 'synthwave',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { width: PW, height: PH, px } = cv;
    const L = 12.8, Tw = 1.6;
    const hy = Math.max(1, Math.floor(PH * 0.52));
    const dashH = Math.max(1, Math.round(PH * 0.09));
    const cx = PW * 0.5;
    const rowC = new Int32Array(PH);
    const skyHz = lerpc(0x241238, pal(0.5), 0.3);
    for (let y = 0; y < PH; y++) {
      rowC[y] = y < hy
        ? lerpc(0x04030a, skyHz, Math.pow(y / hy, 1.35))
        : lerpc(0x0a0812, 0x171120, (y - hy) / Math.max(1, PH - hy));
    }
    const blob = (bx, by, r, c, k) => {
      const x0 = Math.max(0, Math.floor(bx - r)), x1 = Math.min(PW - 1, Math.ceil(bx + r));
      const y0 = Math.max(0, Math.floor(by - r)), y1 = Math.min(PH - 1, Math.ceil(by + r));
      for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
        const dx = x + 0.5 - bx, dy = y + 0.5 - by;
        const d2 = (dx * dx + dy * dy) / (r * r);
        if (d2 < 1) { const i = y * PW + x; px[i] = addc(px[i], c, k * (1 - d2) * (1 - d2)); }
      }
    };
    const smear = (bx, c, k, lt) => {
      const x = Math.round(bx), len = Math.max(2, Math.round((PH - hy) * 0.8));
      for (let d = 0; d < len; d++) {
        const y = hy + d;
        if (y >= PH) break;
        const xx = x + Math.round(Math.sin(d * 1.1 + (TAU * lt * 16) / L) * 0.8);
        const f = k * Math.exp(-d / (len * 0.5));
        for (let o = -1; o <= 1; o++) {
          const x2 = xx + o;
          if (x2 >= 0 && x2 < PW) px[y * PW + x2] = addc(px[y * PW + x2], c, f * (o ? 0.35 : 1));
        }
      }
    };
    const NR = Math.max(20, Math.round((PW * PH) / 80));
    const rain = Array.from({ length: NR }, (_, i) => ({
      x0: hash2(i, 1) * PW, y0: hash2(i, 2) * PH,
      kf: 12 + Math.floor(hash2(i, 3) * 9), kw: 1 + Math.floor(hash2(i, 4) * 2),
      br: 0.1 + hash2(i, 5) * 0.16,
    }));
    const pivot = { x: cx, y: PH * 1.32 };
    const Lw = PH * 1.22;
    const th0 = -0.62, th1 = 0.62;
    const ND = Math.max(14, Math.round((PW * PH) / 115));
    const drops = Array.from({ length: ND }, (_, i) => {
      const x = hash2(i, 6) * PW, y = hash2(i, 7) * PH * 0.94;
      const ang = Math.atan2(x - pivot.x, pivot.y - y);
      const rad = Math.hypot(x - pivot.x, pivot.y - y);
      const a01 = (ang - th0) / (th1 - th0);
      return { x: Math.floor(x), y: Math.floor(y), a01, wiped: rad < Lw && a01 > 0 && a01 < 1, k: hash2(i, 8) };
    });
    const b = ctx.buffer;
    return (t) => {
      const lt = t % L;
      for (let y = 0; y < PH; y++) px.fill(rowC[y], y * PW, (y + 1) * PW);
      // the car ahead: twin tail-lights, bobbing, braking once a loop
      const bob = Math.sin((TAU * lt) / 3.2) * PH * 0.012;
      const brake = lt > 7.9 && lt < 9.3;
      for (const s of [-1, 1]) {
        const bx = cx + s * PW * 0.078, by = hy - PH * 0.04 + bob;
        blob(bx, by, PW * 0.05, 0xff2432, 0.22);
        blob(bx, by, Math.max(1, PW * (brake ? 0.03 : 0.021)), brake ? 0xff3846 : 0xd81e30, brake ? 1 : 0.8);
        smear(bx, 0xd81e30, brake ? 0.5 : 0.3, lt);
      }
      // oncoming headlights, one car every 3.2 s
      const ph = fract(lt / 3.2);
      const ox = cx - (0.06 + ph * ph * 0.46) * PW, oy2 = hy - PH * 0.02 + ph * PH * 0.15;
      const orr = 0.6 + ph * ph * PW * 0.03;
      for (const s of [-1, 1]) blob(ox + s * orr * 1.3, oy2, orr, 0xfff2d8, 0.9);
      blob(ox, oy2, orr * 3.2, 0xffe9c0, 0.16 + ph * 0.1);
      smear(ox, 0xffe9c0, 0.28 + ph * 0.25, lt);
      // sodium lamps sail overhead, alternating sides
      const phL = fract(lt / 1.6), side = Math.floor(lt / 1.6) % 2 ? -1 : 1;
      const lx = cx + side * (0.04 + Math.pow(phL, 1.7) * 0.58) * PW, ly = hy - PH * (0.06 + phL * 0.3);
      blob(lx, ly, 0.6 + phL * 2.4, 0xffbe5a, 0.8);
      blob(lx, ly, (0.6 + phL * 2.4) * 2.6, 0xffbe5a, 0.1);
      smear(lx, 0xffbe5a, 0.18, lt);
      // rain, slanted with the car's speed
      for (const p of rain) {
        const yy = (p.y0 + (lt / L) * p.kf * PH) % PH;
        const xx = (p.x0 + (lt / L) * p.kw * PW) % PW;
        for (let d = 0; d < 3; d++) {
          const y = Math.floor(yy) - d, x = Math.floor(xx) + (d >> 1);
          if (x >= 0 && x < PW && y >= 0 && y < PH) px[y * PW + x] = addc(px[y * PW + x], 0xaac8e8, d ? p.br * 0.5 : p.br);
        }
      }
      // drops on the glass grow back after each wiper pass
      const u = fract(lt / Tw);
      for (const d of drops) {
        let vis = 0.55 + 0.45 * Math.sin(TAU * d.k + (TAU * lt) / L);
        if (d.wiped) {
          const u1 = d.a01 / 2, u2 = 1 - d.a01 / 2;
          const since = Math.min(fract(u - u1), fract(u - u2)) * Tw;
          vis = Math.min(1, since / 1.3);
        }
        if (vis < 0.12) continue;
        const i = d.y * PW + d.x;
        px[i] = addc(px[i], 0xcfe4ff, 0.12 + 0.3 * vis);
        if (vis > 0.82 && d.y + 1 < PH) px[i + PW] = addc(px[i + PW], 0xcfe4ff, 0.1);
      }
      // the wiper arm, always on top
      const sw = u < 0.5 ? u * 2 : 2 - u * 2;
      const ang = th0 + (th1 - th0) * sw;
      const dirx = Math.sin(ang), diry = -Math.cos(ang);
      for (let i = 0; i < Lw; i++) {
        const X = Math.floor(pivot.x + dirx * i), Y = Math.floor(pivot.y + diry * i);
        if (Y < 0 || Y >= PH) continue;
        const arm = i > Lw * 0.45;
        for (let o = 0; o < 2; o++) if (X + o >= 0 && X + o < PW) px[Y * PW + X + o] = arm ? 0x05060c : 0x0a0b12;
      }
      // dashboard silhouette
      for (let y = PH - dashH; y < PH; y++) px.fill(0x070609, y * PW, (y + 1) * PW);
      const gy = PH - Math.max(1, dashH >> 1) - 0;
      blob(PW * 0.18, gy, 1.4, 0x3ae0ff, 0.5);
      if (fract(lt) < 0.5) blob(PW * 0.82, gy, 1.1, 0xffbe5a, 0.5);
      cv.paint(b);
    };
  },
};

// ──────────────────────────────────────────────────────────────  neon tunnel ──
const neonTunnel = {
  id: 'retro-neon-tunnel',
  since: '0.3.0',
  title: 'Neon Tunnel',
  category: 'Outrun',
  kind: 'scene',
  order: 220,
  tags: ['tunnel', 'neon', 'highway', 'ribs', 'perspective', 'drive', 'outrun', 'synthwave'],
  description: 'Flying down a neon highway tunnel: magenta and cyan light ribs sweep past over a dashed roadway, swaying through a long S-curve.',
  size: { w: 80, h: 24 },
  minSize: { w: 24, h: 8 },
  loop: 8,
  canvas: 'field',
  palette: 'synthwave',
  params: { speed: { default: 1, min: 0.25, max: 3, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: PW, height: PH, px, aspect } = cv;
    const F = PW * 0.52, cx = PW / 2;
    const cyv = PH * 0.52 * aspect;
    const A = 1.05, Bt = 0.8, Bf = 0.85, oyc = 0.22;
    const RS = 2, S = 6 * speed, D = 48 * speed;
    const bloomC = pal(0.82);
    const b = ctx.buffer;
    return (t) => {
      const camZ = t * S;
      const ox = Math.sin((TAU * camZ) / D) * 0.34;
      const lean = Math.cos((TAU * camZ) / D) * 0.03;
      for (let y = 0, i = 0; y < PH; y++) {
        const dy = ((y + 0.5) * aspect - cyv) / F;
        for (let x = 0; x < PW; x++, i++) {
          const dx = (x + 0.5 - cx) / F + lean;
          const zx = dx > 1e-6 ? (A - ox) / dx : dx < -1e-6 ? (-A - ox) / dx : 1e9;
          const zy = dy > 1e-6 ? (Bf - oyc) / dy : dy < -1e-6 ? (-Bt - oyc) / dy : 1e9;
          const wall = zx < zy;
          const z = wall ? zx : zy;
          const w = camZ + z;
          const fog = Math.exp(-z / 24);
          let c;
          if (!wall && dy > 0) {
            const xw = ox + dx * z;
            c = Math.abs(xw) < 0.82 ? 0x0d0c13 : 0x120a1c;
            if (Math.abs(xw) < 0.03 && fract(w / 2.4) < 0.45) c = lerpc(c, 0xffd27a, fog);
            if (Math.abs(Math.abs(xw) - 0.68) < 0.03) c = lerpc(c, 0x9a4fd8, fog * 0.8);
          } else if (!wall) {
            const xw = ox + dx * z;
            c = 0x070510;
            if (Math.abs(xw) < 0.12 && fract(w / 4) < 0.2) c = lerpc(c, 0xcfe9ff, fog);
          } else c = 0x0b0714;
          const fr = fract(w / RS);
          const dRib = Math.min(fr, 1 - fr) * RS;
          const edge = Math.max(0, 1 - dRib / 0.09);
          const halo = Math.exp(-dRib * 2.6) * 0.3;
          c = addc(c, Math.floor(w / RS) & 1 ? 0xff2f9e : 0x25d8f0, (edge * edge + halo) * fog);
          if (z > 30) c = lerpc(c, bloomC, Math.min(1, (z - 30) / 26) * 0.9);
          px[i] = c;
        }
      }
      cv.paint(b);
    };
  },
};

// ───────────────────────────────────────────────────────────  night dashboard ──
const nightDash = {
  id: 'retro-night-dash',
  since: '0.3.0',
  title: 'Night Dashboard',
  category: 'Outrun',
  kind: 'scene',
  order: 230,
  tags: ['dashboard', 'speedometer', 'tachometer', 'gauges', 'cockpit', 'drive', 'night', 'outrun'],
  description: 'A night cockpit: speedo and tach needles ride a cruise with real gear shifts, indicators blink, and oncoming lights drift past the glass.',
  size: { w: 76, h: 20 },
  minSize: { w: 26, h: 9 },
  loop: 12,
  canvas: 'line',
  setup(ctx) {
    const th = ctx.theme, b = ctx.buffer, W = ctx.width, H = ctx.height;
    const cv = ctx.canvas('line');
    const L = 12;
    const ws = H >= 14 ? Math.floor(H * 0.26) : 0;
    const gh = H - ws - 1;
    const lcdY = H - 1;
    const gcy = ws + gh * 0.74;
    const R = Math.max(2.6, Math.min(W * 0.2, (gh - 1.6) * 1.75));
    const SPAN = 2.05;
    const g1x = W * 0.25, g2x = W * 0.75;
    const at = (gx, p, r) => {
      const aa = -SPAN + p * 2 * SPAN;
      return [(gx + r * Math.sin(aa)) * cv.sx, (gcy - (r * Math.cos(aa)) / 2) * cv.sy];
    };
    const panel = lerpc(th.bg, th.panel, 0.85);
    const tickD = lerpc(panel, th.ink, 0.5), tickM = lerpc(panel, th.ink, 0.85);
    const needleC = th.warn;
    const glass = 0x060910;
    const TH = [0, 48, 82, 122, 168, 240];
    const spd = (tt) => 126 + 58 * Math.sin((TAU * tt) / L) + 16 * Math.sin((2 * TAU * tt) / L + 1.1);
    const city = Array.from({ length: 12 }, (_, k) => [Math.floor(hash2(k, 31) * W), Math.max(0, Math.floor(hash2(k, 32) * Math.max(1, ws - 1))), hash2(k, 33)]);
    const lcd = lerpc(th.bg, 0x05080a, th.mode === 'light' ? 0.75 : 0.5);
    const labels = W >= 44;
    const gauge = (gx, max, val, redFrom, step, major) => {
      for (let v2 = 0; v2 <= max; v2 += step) {
        const p = v2 / max, isMaj = v2 % major === 0;
        const col = v2 >= redFrom ? th.neg : isMaj ? tickM : tickD;
        const [x0, y0] = at(gx, p, R * (isMaj ? 0.76 : 0.84));
        const [x1, y1] = at(gx, p, R * 0.95);
        cv.line(x0, y0, x1, y1, col);
      }
      const p = Math.max(0, Math.min(1, val / max));
      const [nx0, ny0] = at(gx, p, R * 0.08), [nx1, ny1] = at(gx, p, R * 0.97);
      cv.line(nx0, ny0, nx1, ny1, needleC);
      cv.line(nx0 + 1, ny0, nx1 + 1, ny1, needleC);
      cv.ellipse(gx * cv.sx, gcy * cv.sy, R * 0.1 * cv.sx, (R * 0.05 * cv.sy) / 2, tickM, true);
    };
    return (t) => {
      const lt = t % L;
      const v = spd(t);
      let g = 1;
      while (g < 5 && v >= TH[g]) g++;
      const rpm = 1.1 + ((v - TH[g - 1]) / (TH[g] - TH[g - 1])) * 5.4;
      if (ws) {
        b.fill(0, 0, W, ws, ' ', th.ink, glass);
        for (const [sx2, sy2, kk] of city) if (Math.sin(TAU * (lt / L) * (1 + Math.floor(kk * 3)) + kk * 25) > -0.2) b.set(sx2, sy2, '·', lerpc(glass, 0xd8e8ff, 0.4 + kk * 0.35));
        for (let k = 0; k < 3; k++) {
          const ph = fract(lt / 4 + k / 3);
          const x = Math.round(W * (0.52 - 0.48 * Math.pow(ph, 1.4)));
          const y = Math.min(ws - 1, Math.round((ws - 1) * (0.3 + ph * 0.7)));
          b.set(x, y, '●', lerpc(glass, 0xffe9b8, 0.25 + ph * 0.75));
          if (ph > 0.3 && x + 1 < W) b.set(x + 1, y, '─', lerpc(glass, 0xffe9b8, ph * 0.4));
        }
      }
      b.fill(0, ws, W, Math.max(1, H - ws - 1), ' ', th.ink, panel);
      cv.clear();
      gauge(g1x, 280, v, 999, 20, 40);
      gauge(g2x, 8, rpm, 6.5, 0.5, 1);
      cv.paint(b);
      if (labels) {
        for (const vl of [0, 80, 160, 240]) {
          const [x, y] = at(g1x, vl / 280, R * 0.58);
          const sVal = String(vl);
          b.text(Math.round(x / cv.sx - sVal.length / 2), Math.floor(y / cv.sy), sVal, lerpc(panel, th.ink, 0.75), panel);
        }
        for (let vl = 0; vl <= 8; vl += 2) {
          const [x, y] = at(g2x, vl / 8, R * 0.58);
          b.text(Math.round(x / cv.sx), Math.floor(y / cv.sy), String(vl), vl >= 7 ? th.neg : lerpc(panel, th.ink, 0.75), panel);
        }
      }
      const mx = Math.round(W / 2);
      const dy0 = ws + Math.max(1, Math.floor(gh * 0.3));
      const sv = String(Math.round(v)).padStart(3);
      b.text(mx - 3, dy0, sv, light(th), panel);
      b.text(mx + 1, dy0, 'km/h'.slice(0, Math.max(0, W - mx - 2)), lerpc(panel, th.muted, 1), panel);
      b.text(mx - 2, dy0 + 1, `G${g}`, th.accent, panel);
      if (W >= 34 && dy0 + 2 < lcdY) b.text(mx - 2, dy0 + 2, `${rpm.toFixed(1)}k`, lerpc(panel, th.muted, 1), panel);
      const lOn = lt >= 2 && lt < 4.5 && fract(lt * 1.5) < 0.5;
      const rOn = lt >= 7.5 && lt < 10 && fract(lt * 1.5) < 0.5;
      b.text(1, ws, '◀', lOn ? th.pos : lerpc(panel, th.pos, 0.3), panel);
      b.text(W - 2, ws, '▶', rOn ? th.pos : lerpc(panel, th.pos, 0.3), panel);
      b.fill(0, lcdY, W, 1, ' ', th.warn, lcd);
      const trip = `TRIP 412.${Math.floor(fract(t / L) * 10)}km`;
      const info = W >= 54 ? `${trip}  FUEL ▮▮▮▮░  OUT 9°C  22:41` : trip;
      b.text(1, lcdY, info.slice(0, W - 2), th.warn, lcd);
      const hb = 'HI-BEAM';
      if (W >= 70) b.text(W - hb.length - 1, lcdY, hb, lerpc(lcd, th.info, 0.8), lcd);
    };
  },
};

export default [rainDrive, neonTunnel, nightDash];

sources.prism-term/src/facets/retro/oscilloscope:
// A phosphor oscilloscope on the chiptune: graticule, a trace triggered on the
// bass so it stands still, and persistence — the last few sweeps fading out
// behind the beam. `--set mode=xy` plots bass against lead as Lissajous figures.
import { lerpc } from './_kit.js';
import { songAt } from './_music.js';

const PHOSPHOR = { green: 0x40ff80, amber: 0xffb020, blue: 0x60c8ff };

export default {
  title: 'Oscilloscope',
  gallery: 'retro',
  category: 'Chiptune Visuals',
  kind: 'scene',
  tags: ['oscilloscope', 'scope', 'waveform', 'phosphor', 'lissajous', 'audio', 'chiptune'],
  order: 30,
  description: 'A phosphor oscilloscope on the chiptune: graticule, a bass-triggered trace with persistence, and an XY Lissajous mode.',
  size: { w: 64, h: 18 },
  minSize: { w: 20, h: 6 },
  loop: 7.68,
  canvas: 'line',
  params: {
    mode: { default: 'yt', options: ['yt', 'xy'], label: 'Mode' },
    phosphor: { default: 'green', options: ['green', 'amber', 'blue', 'theme'], label: 'Phosphor' },
  },
  setup(ctx) {
    const { theme } = ctx;
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const cv = ctx.canvas('line');
    const PW = cv.width, PHt = cv.height;
    const xy = ctx.param('mode', 'yt') === 'xy';
    const ph = ctx.param('phosphor', 'green');
    const beam = ph === 'theme' ? theme.accent : PHOSPHOR[ph] ?? PHOSPHOR.green;
    // Phosphor glows on dark CRT glass, even in daylight; the 'theme' phosphor draws
    // in the theme's own ink on the page instead (with a firmer persistence by Day).
    const day = theme.mode === 'light';
    const glass = day && ph !== 'theme' ? 0x060b08 : theme.bg;
    const K = (k) => (day && ph === 'theme' ? 1 - (1 - k) * (1 - k) : k);
    const grid = lerpc(glass, beam, K(0.2)), axis = lerpc(glass, beam, K(0.32));
    const trails = [1, 0.5, 0.26, 0.12].map((k) => lerpc(glass, beam, K(k)));
    const readout = H >= 10 && W >= 36;
    const cx = PW / 2, cy = PHt / 2;
    const amp = PHt * 0.42;
    function graticule() {
      const dx = PW / 10, dy = PHt / 8;
      for (let i = 0; i <= 10; i++) {
        const x = Math.min(PW - 1, Math.round(i * dx));
        for (let y = 0; y < PHt; y += 3) cv.set(x, y, i === 5 ? axis : grid);
      }
      for (let j = 0; j <= 8; j++) {
        const y = Math.min(PHt - 1, Math.round(j * dy));
        for (let x = 0; x < PW; x += 3) cv.set(x, y, j === 4 ? axis : grid);
      }
      // Minor ticks along the center axes.
      for (let i = 0; i <= 50; i++) { const x = Math.round((i * PW) / 50); cv.set(x, Math.round(cy) - 1, axis); cv.set(x, Math.round(cy) + 1, axis); }
      for (let j = 0; j <= 40; j++) { const y = Math.round((j * PHt) / 40); cv.set(Math.round(cx) - 1, y, axis); cv.set(Math.round(cx) + 1, y, axis); }
    }
    // The scope looks at the tonal voices through a gentle low-pass: rounded
    // squares and pulses plus the kick's thump; the noise channels stay out.
    const soft = (ph, duty) => Math.tanh(4 * (Math.sin(2 * Math.PI * ph) + (duty - 0.5) * 2)) * 0.95;
    function sweepYT(t, color) {
      // Trigger on the bass so the picture holds still: two bass periods per screen.
      const s = songAt(t), fb = s.bassFreq;
      const start = Math.floor(t * fb) / fb, span = 2 / fb;
      let px = 0, py = cy;
      for (let x = 0; x < PW; x++) {
        const tau = start + (x / PW) * span, a = s.kickAge + (tau - start);
        const v = 0.42 * s.bass * soft(tau * fb, 0.5) + 0.28 * s.lead * soft(tau * s.leadFreq, 0.3) + 0.45 * s.kick * Math.sin(2 * Math.PI * 52 * a);
        const y = cy - v * amp;
        if (x) cv.line(px, py, x, y, color);
        px = x; py = y;
      }
    }
    // XY: the bass/lead interval picks a small-integer frequency ratio, so the
    // figure changes shape with the harmony and closes on itself.
    const RATIO = [[1, 1], [9, 8], [9, 8], [6, 5], [5, 4], [4, 3], [7, 5], [3, 2], [8, 5], [5, 3], [7, 4], [2, 1]];
    function sweepXY(t, color) {
      const s = songAt(t);
      const [p, q] = RATIO[(((s.leadNote - s.bassNote) % 12) + 12) % 12];
      const ax = (0.55 + 0.35 * s.bass) * (1 + s.kick * 0.18), ay = (0.5 + 0.4 * s.lead) * (1 + s.kick * 0.18);
      const phase = t * 0.9, N = Math.max(200, PW * 4);
      let px = 0, py = 0;
      for (let i = 0; i <= N; i++) {
        const u = (i / N) * 2 * Math.PI;
        const x = cx + Math.sin(q * u + phase) * ax * cx * 0.92;
        const y = cy - Math.sin(p * u) * ay * amp * 1.05;
        if (i) cv.line(px, py, x, y, color);
        px = x; py = y;
      }
    }
    return (t) => {
      b.fill(0, 0, W, H, ' ', theme.ink, glass);
      cv.clear();
      graticule();
      // Persistence: older sweeps first, dimmer, so the newest sits on top.
      for (let k = trails.length - 1; k >= 0; k--) (xy ? sweepXY : sweepYT)(t - k / 30, trails[k]);
      cv.paint(b);
      if (readout) {
        const s = songAt(t);
        const dim = lerpc(glass, beam, K(0.6));
        b.text(1, 0, xy ? 'X: BASS  Y: LEAD' : 'CH1 0.5V/div', dim);
        b.text(W - 12, 0, xy ? '    XY MODE' : 'TRIG ↑ BASS', dim);
        b.text(1, H - 1, xy ? `${RATIO[(((s.leadNote - s.bassNote) % 12) + 12) % 12].join(':')}  ${s.bassFreq.toFixed(1)} Hz` : `${s.bassFreq.toFixed(1)} Hz`, dim);
        if (!xy) b.text(W - 11, H - 1, `${((2 / s.bassFreq) * 100).toFixed(2)}ms/div`.padStart(10), dim);
      }
    };
  },
};

// Arcade-racer pseudo-3D: a road built row by row from the horizon down, with
// curvature integrated per scanline so it sweeps left and right, alternating
// rumble strips and lane dashes, palm silhouettes scaling past, the sunset
// sliding against the curves, a red convertible leaning in — and the HUD.
import { lerpc, hash2 } from './_kit.js';

const CAR = [
  '......rrrrrrrrrrrrrrrr......',
  '.....rkkkkkkkkkkkkkkkkr.....',
  '....rkkhkkkkkkkkkkkkkkkr....',
  '..rrrrrrrrrrrrrrrrrrrrrrrr..',
  '.RRRRRRRRRRRRRRRRRRRRRRRRRR.',
  'RRLLLLRRRRRRRRRRRRRRRRLLLLRR',
  'RRLLLLRRggggggggggggRRLLLLRR',
  'RRRRRRRRggggggggggggRRRRRRRR',
  'ddssssddddddddddddddddssssdd',
  'kkkkkk................kkkkkk',
];
const SEG = 7, LOOP = 12, SPEED = 60;            // world units; one loop covers 720 units
const TAU = Math.PI * 2, LEN = SPEED * LOOP;
const curve = (z) => Math.sin((TAU * z) / LEN) * 0.9 + Math.sin((TAU * 3 * z) / LEN + 1) * 0.45;
const curveInt = (z) => (-Math.cos((TAU * z) / LEN) * 0.9 * LEN) / TAU - (Math.cos((TAU * 3 * z) / LEN + 1) * 0.45 * LEN) / (3 * TAU);

export default {
  title: 'Outrun Road',
  gallery: 'retro',
  category: 'Outrun',
  kind: 'scene',
  tags: ['outrun', 'racer', 'pseudo-3d', 'road', 'palms', 'sunset', 'arcade', '1986'],
  order: 10,
  description: 'Arcade pseudo-3D racing: a curving road with rumble strips, palm silhouettes, a sunset and a red convertible.',
  size: { w: 80, h: 24 },
  minSize: { w: 24, h: 8 },
  loop: LOOP,
  canvas: 'field',
  palette: 'sunset',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { theme } = ctx;
    const b = ctx.buffer;
    const { width: PW, height: PH, px, aspect } = cv;
    const hy = Math.floor(PH * 0.46);
    const rows = PH - hy;
    const zNear = 3, zFar = 260;
    const halfW = (p) => p * PW * 0.4;
    const fogC = pal(0.62);
    const roadA = 0x5c5866, roadB = 0x56525f, grassA = 0x1f7a3c, grassB = 0x1a6a34;
    const sil = lerpc(pal(0.05), 0x000000, 0.3);
    const sunR = Math.min(PW * 0.16, hy * aspect * 0.8);
    // Mountains: a ridge wider than the screen so it can slide with the curves.
    const MW = PW * 3, ridge = new Float32Array(MW);
    for (let x = 0; x < MW; x++) {
      const u = x / MW;
      ridge[x] = hy - PH * (0.04 + 0.09 * Math.pow(Math.abs(Math.sin(u * TAU * 3 + 1.3)), 0.7) * (0.6 + 0.4 * Math.sin(u * TAU * 7)));
    }
    const wx = new Float32Array(rows);            // road centre per row, in road half-widths
    const hud = PW >= 40 && ctx.height >= 12;
    const carW0 = CAR[0].length, carH0 = CAR.length;
    const carScale = Math.max(PW * 0.3, 8) / carW0;
    const carColors = { r: 0xd81e2c, R: 0xf0283a, k: 0x1a1020, h: 0x6a6aa8, L: 0xffb040, g: 0x2a1418, d: 0x301018, s: 0x8a8a96 };

    return (t) => {
      const lt = t % LOOP, camZ = lt * SPEED;
      const shift = (curveInt(camZ) * 0.04 * PW) / 10;
      // Sky and sun.
      for (let y = 0; y < hy; y++) {
        const c = pal(0.04 + (y / hy) * 0.62);
        px.fill(c, y * PW, (y + 1) * PW);
      }
      const sunX = PW / 2 - shift * 0.6, sunY = hy - sunR * 0.35 / aspect;
      for (let y = Math.max(0, Math.floor(sunY - sunR / aspect)); y < hy; y++) for (let x = Math.max(0, Math.floor(sunX - sunR)); x < Math.min(PW, sunX + sunR); x++) {
        const dx = x + 0.5 - sunX, dy = (y + 0.5 - sunY) * aspect;
        if (dx * dx + dy * dy < sunR * sunR) px[y * PW + x] = lerpc(pal(0.98), pal(0.78), (y - (sunY - sunR / aspect)) / (2 * sunR / aspect));
      }
      for (let x = 0; x < PW; x++) {
        const rx = Math.floor((((x + shift) % MW) + MW) % MW);
        for (let y = Math.max(0, Math.floor(ridge[rx])); y < hy; y++) px[y * PW + x] = lerpc(sil, fogC, 0.35);
      }
      // Road: walk from the bottom (near) up to the horizon, integrating curvature.
      let x = 0, dx = 0, zPrev = zNear;
      for (let r = rows - 1; r >= 0; r--) {
        const p = (r + 1) / rows, z = zNear / p;
        if (z > zFar) { wx[r] = x; continue; }
        const dz = z - zPrev; zPrev = z;
        dx += curve(camZ + z) * 0.0011 * dz;
        x += dx * dz;
        wx[r] = x;
      }
      for (let r = 0; r < rows; r++) {
        const y = hy + r, p = (r + 1) / rows, z = zNear / p;
        const hw = halfW(p), cx = PW / 2 + wx[r] * hw;
        const seg = Math.floor((camZ + z) / SEG) & 1;
        const fog = Math.min(1, Math.pow(z / zFar, 0.7));
        const grass = lerpc(seg ? grassA : grassB, fogC, fog), road = lerpc(seg ? roadA : roadB, fogC, fog);
        const rumble = lerpc(seg ? 0xf0f0f0 : 0xd02030, fogC, fog), lane = lerpc(0xf0f0f0, road, fog);
        const rw = hw * 0.12, lw = hw * 0.035;
        for (let xx = 0; xx < PW; xx++) {
          const d = Math.abs(xx + 0.5 - cx);
          let c = grass;
          if (d < hw) c = road;
          else if (d < hw + rw) c = rumble;
          if (seg && d < hw && Math.abs(d - hw / 3) < lw) c = lane;
          px[y * PW + xx] = c;
        }
      }
      // Palms, far to near: trunk and drooping fronds, silhouetted against the sunset.
      const GAP = 10, first = Math.ceil((camZ + zNear + 1) / GAP), last = Math.floor((camZ + zFar) / GAP);
      for (let k = last; k >= first; k--) {
        const z = k * GAP - camZ, p = zNear / z;
        const r = Math.min(rows - 1, Math.max(0, Math.round(p * rows) - 1));
        const side = k & 1 ? 1 : -1, hw = halfW(p);
        const bx = PW / 2 + (wx[r] + side * (1.4 + hash2(k, 3) * 0.35)) * hw, by = hy + r;
        const fog = Math.min(1, Math.pow(z / zFar, 0.7)), c = lerpc(sil, fogC, fog * 0.9);
        const hgt = (hw * 2.1) / aspect, lean = side * hw * 0.22;
        const th = Math.max(1, hw * 0.06);
        for (let i = 0; i <= 40; i++) {
          const f = i / 40, tx = bx + lean * f * f, ty = by - hgt * f;
          for (let w = 0; w < th; w++) cv.set(tx + w - th / 2, ty, c);
        }
        const topX = bx + lean, topY = by - hgt;
        for (let a = 0; a < 8; a++) {
          // Fronds arc up and out, then droop; each a little different.
          const ang = -Math.PI + (a / 7) * Math.PI, len = hw * (0.7 + 0.2 * hash2(k, a));
          for (let i = 0; i <= 30; i++) {
            const f = i / 30, fx = topX + Math.cos(ang) * len * f, fy = topY + (Math.sin(ang) * len * f * 0.55 + len * f * f * 0.7) / aspect;
            cv.set(fx, fy, c);
            if (f < 0.7) cv.set(fx, fy + 1, c);
          }
        }
      }
      // The car: bobbing slightly, leaning into the curve.
      const lean = curve(camZ + 20) * PW * 0.03;
      const cw = carW0 * carScale, ch = (carH0 * carScale) / aspect;
      const cx0 = PW / 2 - cw / 2 + lean, cy0 = PH - ch - Math.max(1, PH * 0.03) - (Math.floor(lt * 8) % 2 ? 0 : 0.6);
      for (let y = 0; y < ch; y++) for (let xx = 0; xx < cw; xx++) {
        const k = CAR[Math.min(carH0 - 1, Math.floor((y / ch) * carH0))][Math.min(carW0 - 1, Math.floor((xx / cw) * carW0))];
        if (k !== '.') cv.set(cx0 + xx, cy0 + y, k === 'L' && Math.floor(lt * 2) % 4 === 0 ? 0xff5a3a : carColors[k]);
      }
      cv.paint(b);
      if (hud) {
        const time = 60 - Math.floor(lt * 2.5);
        const score = String(1250000 + Math.floor(camZ * 37) * 10).padStart(8, '0');
        const kmh = 286 + Math.round(Math.sin(lt * 1.3) * 6);
        b.text(1, 0, 'TIME', theme.warn);
        b.text(6, 0, String(time), 0xffffff);
        b.text(Math.floor(ctx.width / 2) - 7, 0, `SCORE ${score}`, 0x7cf0ff);
        const sp = `${kmh} km/h`;
        b.text(ctx.width - sp.length - 1, ctx.height - 1, sp, 0xffe14a);
      }
    };
  },
};

sources.prism-term/src/facets/retro/raster-color:
// Scanline color machines: four effects the Amiga copper chip would recognize.
// A plasma rewritten into a copper list, translucent curtains blending
// additively, venetian slats rippling open, and interference rings multiplying
// into moire blooms. All loops close on whole sine periods.
import { lerpc, clamp01, fract, ground } from './_kit.js';

const TAU = Math.PI * 2;

export default [
  {
    id: 'retro-copper-plasma',
    since: '0.3.0',
    title: 'Copper Plasma',
    gallery: 'retro',
    category: 'Raster & Copper',
    kind: 'scene',
    tags: ['copper', 'plasma', 'raster', 'scanline', 'bands', 'gradient', 'amiga'],
    order: 220,
    description: 'A copper list rewritten every frame: scanline-only plasma posterized into crawling bands with white-hot seams.',
    size: { w: 80, h: 22 },
    minSize: { w: 20, h: 6 },
    loop: 12,
    canvas: 'field',
    palette: 'prism-sheen',
    params: {
      bands: { default: 14, min: 4, max: 32, label: 'Bands' },
      speed: { default: 1, min: 0.25, max: 4, label: 'Speed' },
    },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const speed = ctx.param('speed', 1);
      const NB = Math.max(2, Math.round(ctx.param('bands', 14)));
      const { width: W, height: H, px } = cv;
      const w = TAU / 12;
      return (t) => {
        const tt = t * speed;
        let prevB = -1;
        for (let y = 0; y < H; y++) {
          const yy = (y / H) * 9;
          const p = Math.sin(yy * 1.9 + tt * w * 3) + Math.sin(yy * 3.3 - tt * w * 5)
            + Math.sin((yy + Math.sin(tt * w * 2) * 1.5) * 1.1 + tt * w);
          const v = fract(p / 6 + 0.5 + tt / 12);
          const bq = Math.floor(v * NB);
          let c = pal((bq + 0.5) / NB);
          if (bq !== prevB && prevB >= 0) c = lerpc(c, 0xffffff, 0.42); // the copper "split" seam
          prevB = bq;
          px.fill(c, y * W, (y + 1) * W);
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'retro-raster-curtains',
    since: '0.3.0',
    title: 'Raster Curtains',
    gallery: 'retro',
    category: 'Raster & Copper',
    kind: 'scene',
    tags: ['curtains', 'raster', 'additive', 'translucent', 'interference', 'copper', 'blend'],
    order: 230,
    description: 'Three translucent raster curtains drift across each other, blending additively and flaring white in the overlaps.',
    size: { w: 80, h: 22 },
    minSize: { w: 20, h: 6 },
    loop: 12,
    canvas: 'field',
    palette: 'prism',
    params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px } = cv;
      const base = ground(ctx.theme);
      const bR = (base >> 16) & 255, bG = (base >> 8) & 255, bB = base & 255;
      const CU = [0.0, 0.33, 0.66].map((h, i) => {
        const rr = new Float32Array(H), gg = new Float32Array(H), bb = new Float32Array(H);
        for (let y = 0; y < H; y++) {
          const c = pal(fract(h + 0.07 + (y / H) * 0.14));
          rr[y] = (c >> 16) & 255; gg[y] = (c >> 8) & 255; bb[y] = c & 255;
        }
        return { rr, gg, bb, k: i + 1, ph: i * 2.2, hw: Math.max(3, W * (0.3 - i * 0.055)) };
      });
      const ws = [new Float32Array(W), new Float32Array(W), new Float32Array(W)];
      return (t) => {
        const tt = t * speed * (TAU / 12);
        for (let ci = 0; ci < 3; ci++) {
          const cu = CU[ci], wv = ws[ci];
          const cx = W * 0.5 + Math.sin(tt * cu.k + cu.ph) * Math.max(0, W * 0.5 - cu.hw * 0.5);
          for (let x = 0; x < W; x++) {
            const d = Math.abs(x - cx) / cu.hw;
            wv[x] = d >= 1 ? 0 : (1 - d) ** 1.6;
          }
        }
        const [w0, w1, w2] = ws;
        for (let y = 0; y < H; y++) {
          const r0 = CU[0].rr[y], g0 = CU[0].gg[y], b0 = CU[0].bb[y];
          const r1 = CU[1].rr[y], g1 = CU[1].gg[y], b1 = CU[1].bb[y];
          const r2 = CU[2].rr[y], g2 = CU[2].gg[y], b2 = CU[2].bb[y];
          const row = y * W;
          for (let x = 0; x < W; x++) {
            const a = w0[x], c = w1[x], e = w2[x];
            const sw = a + c + e;
            if (sw < 0.004) { px[row + x] = base; continue; }
            const cov = sw > 1 ? 1 : sw;
            const ov = sw > 1 ? Math.min(0.85, (sw - 1) * 0.55) : 0;
            const inv = 1 / sw;
            let R = (a * r0 + c * r1 + e * r2) * inv;
            let G = (a * g0 + c * g1 + e * g2) * inv;
            let B = (a * b0 + c * b1 + e * b2) * inv;
            if (ov) { R += (255 - R) * ov; G += (255 - G) * ov; B += (255 - B) * ov; }
            R = bR + (R - bR) * cov; G = bG + (G - bG) * cov; B = bB + (B - bB) * cov;
            px[row + x] = (R << 16) | (G << 8) | B;
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'retro-venetian-rasters',
    since: '0.3.0',
    title: 'Venetian Rasters',
    gallery: 'retro',
    category: 'Raster & Copper',
    kind: 'scene',
    tags: ['venetian', 'blinds', 'slats', 'raster', 'reveal', 'scanline', 'wave'],
    order: 240,
    description: 'Venetian slats ripple open in a traveling wave, letting a scrolling spectrum blaze through the gaps between them.',
    size: { w: 80, h: 22 },
    minSize: { w: 20, h: 6 },
    loop: 10,
    canvas: 'field',
    palette: 'prism-sheen',
    params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px } = cv;
      const base = ground(ctx.theme);
      const slatC = lerpc(ctx.theme.bg, ctx.theme.ink, 0.42);
      const nSlats = Math.max(3, Math.min(14, Math.round(H / 7)));
      const sh = H / nSlats;
      const lip = Math.min(0.45, 0.9 / sh);
      return (t) => {
        const tt = t * speed * (TAU / 10);
        for (let y = 0; y < H; y++) {
          const i = Math.min(nSlats - 1, Math.floor(y / sh));
          const local = (y - i * sh) / sh;
          const o = clamp01(0.5 + 0.58 * Math.sin(tt * 2 - i * 0.8));
          const d = Math.abs(local - 0.5);
          let c;
          if (d < o * 0.5) {
            c = pal(fract((y / H) * 0.5 + tt / TAU));           // the spectrum behind the blinds
          } else {
            const toward = local < 0.5 ? 1 - local * 2 : local * 2 - 1;
            c = lerpc(base, slatC, 0.3 + 0.6 * toward);
            if (d - o * 0.5 < lip) c = lerpc(c, 0xffffff, 0.45); // lit lip at the opening
          }
          px.fill(c, y * W, (y + 1) * W);
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'retro-moire-rings',
    since: '0.3.0',
    title: 'Moire Rings',
    gallery: 'retro',
    category: 'Raster & Copper',
    kind: 'scene',
    tags: ['moire', 'interference', 'rings', 'circles', 'amiga', 'raster', 'pattern'],
    order: 250,
    description: 'Two drifting sets of concentric rings multiply into blooming moire interference — the Amiga circle trick.',
    size: { w: 80, h: 22 },
    minSize: { w: 20, h: 6 },
    loop: 12,
    canvas: 'field',
    palette: 'prism',
    credits: 'after the Amiga interference-circle effect',
    params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
    setup(ctx) {
      const cv = ctx.canvas();
      const pal = ctx.palette();
      const speed = ctx.param('speed', 1);
      const { width: W, height: H, px, aspect } = cv;
      const base = ground(ctx.theme);
      const LUT = new Int32Array(256);
      for (let i = 0; i < 256; i++) {
        const u = i / 255;
        LUT[i] = lerpc(base, pal(0.06 + u * 0.72), 0.1 + 0.9 * u * u);
      }
      const k = 0.62 * (96 / Math.max(24, Math.min(W, H * aspect)));
      return (t) => {
        const tt = t * speed * (TAU / 12);
        const x1 = W / 2 + Math.cos(tt) * W * 0.24, y1 = H / 2 + Math.sin(tt * 2) * H * 0.24;
        const x2 = W / 2 + Math.cos(tt * 3 + Math.PI) * W * 0.2, y2 = H / 2 + Math.sin(tt + Math.PI) * H * 0.2;
        const ph = tt * 4;
        for (let y = 0; y < H; y++) {
          const dy1 = (y - y1) * aspect, dy2 = (y - y2) * aspect;
          const q1 = dy1 * dy1, q2 = dy2 * dy2;
          const row = y * W;
          for (let x = 0; x < W; x++) {
            const ax = x - x1, bx = x - x2;
            const v = Math.sin(Math.sqrt(ax * ax + q1) * k - ph) * Math.sin(Math.sqrt(bx * bx + q2) * k + ph);
            px[row + x] = LUT[(127.5 + v * 127.5) | 0];
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

