// Rotozoomer: one small tile — a checker with a prism emblem — rotated and
// zoomed across the whole screen every frame. The texture-mapping trick that
// showed what a 7 MHz CPU could do.
import { lerpc, shade } from './_kit.js';

const T = 32;
function makeTile(pal, theme) {
  const tile = new Int32Array(T * T);
  for (let y = 0; y < T; y++) for (let x = 0; x < T; x++) {
    const check = ((x >> 3) + (y >> 3)) & 1;
    let c = check ? lerpc(theme.bg, theme.accent, 0.42) : shade(theme, 0.25);
    // Prism emblem: a triangle with a bright edge, centered in the tile.
    const u = (x - T / 2 + 0.5) / (T / 2), v = (y - T / 2 + 0.5) / (T / 2);
    const inTri = v > -0.62 && v < 0.55 && Math.abs(u) < (v + 0.62) * 0.62;
    const edge = inTri && (v > 0.43 || Math.abs(u) > (v + 0.62) * 0.62 - 0.16);
    if (inTri) c = edge ? 0xffffff : pal(((u + 1) * 0.5 + 0.1) % 1);
    tile[y * T + x] = c;
  }
  return tile;
}

export default {
  title: 'Rotozoomer',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['rotozoom', 'texture mapping', 'demoscene', 'rotation', 'zoom'],
  order: 60,
  description: 'One small emblem tile rotated and zoomed across the whole screen every frame — classic texture mapping.',
  size: { w: 70, h: 22 },
  minSize: { w: 16, h: 6 },
  loop: 12,
  canvas: 'field',
  palette: 'prism',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const { width: W, height: H, px, aspect } = cv;
    const tile = makeTile(pal, ctx.theme);
    return (t) => {
      const tt = t * speed;
      const a = tt * 0.6, zoom = 1.1 + Math.sin(tt * 0.45) * 0.75;
      const ca = Math.cos(a) * zoom * (T / Math.min(W, H * aspect)) * 1.6, sa = Math.sin(a) * zoom * (T / Math.min(W, H * aspect)) * 1.6;
      const ox = tt * 9, oy = tt * 5;
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y - H / 2) * aspect;
        for (let x = 0; x < W; x++, i++) {
          const vx = x - W / 2;
          const u = Math.floor(vx * ca - vy * sa + ox), v = Math.floor(vx * sa + vy * ca + oy);
          px[i] = tile[(v & (T - 1)) * T + (u & (T - 1))];
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/sine-scrolle:
// The classic sine scroller: a big bitmap-font message rides a sine wave from
// right to left, each scanline tinted by a cycling copper gradient, over a
// parallax starfield. Drop shadow included, as the law requires.
import { textMask, maskAt, fontPx, makeStars, dim, lerpc } from './_kit.js';

const MESSAGE = 'PRISM TERMINAL FACETS   *   SINE SCROLLERS NEVER DIE   *   GREETINGS TO EVERY SYSOP STILL RUNNING A NODE   *   ';

export default {
  title: 'Sine Scroller',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['scroller', 'sine', 'cracktro', 'demoscene', 'bitmap font'],
  order: 10,
  description: 'Big bitmap-font message riding a sine wave, copper-tinted per scanline, over a parallax starfield.',
  size: { w: 80, h: 20 },
  minSize: { w: 30, h: 8 },
  loop: 12,
  canvas: 'field',
  palette: 'prism',
  params: {
    speed: { default: 1, min: 0.25, max: 4, label: 'Speed' },
    text: { default: MESSAGE, label: 'Message' },
  },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const m = textMask(String(ctx.param('text', MESSAGE)).toUpperCase(), { font: 'bold' });
    const { width: W, height: H, px } = cv;
    const { sx, sy } = fontPx(cv, Math.max(3, ctx.height * 0.34), 7);
    const tw = m.w * sx, th = m.h * sy;
    const amp = Math.max(0, (H - th) / 2 - 1);
    const stars = makeStars(ctx.rng, W, H, Math.round(W * H * 0.012));
    const bg0 = ctx.theme.bg, bg1 = lerpc(ctx.theme.bg, pal(0.65), 0.12);
    const shadow = dim(ctx.theme.bg, 0.4);
    return (t) => {
      const tt = t * speed;
      for (let y = 0; y < H; y++) px.fill(lerpc(bg0, bg1, y / H), y * W, (y + 1) * W);
      for (const s of stars) {
        const v = 0.25 + s[2] * 0.75;
        const x = ((s[0] - tt * (6 + 40 * s[2] * s[2])) % W + W) % W;
        cv.set(x, s[1], lerpc(bg0, ctx.theme.ink, v));
      }
      const scroll = tt * 26 * sx;
      const period = tw + W;
      for (let x = 0; x < W; x++) {
        const u = ((x - W + scroll) % period + period) % period; // text-space column
        if (u >= tw) continue;
        const yOff = Math.round(H / 2 - th / 2 + Math.sin(u * 0.045 / sx * 2 + tt * 2.1) * amp);
        for (let k = 0; k < th; k++) {
          if (!maskAt(m, u, k, sx, sy)) continue;
          const y = yOff + k;
          const c = pal(((y / H) * 0.9 + tt * 0.12) % 1);
          cv.set(x + 1, y + 1, shadow);
          cv.set(x, y, k < sy ? lerpc(c, 0xffffff, 0.45) : c);
        }
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/spectrum-ana:
// A 1998 media-player spectrum analyser: log-spaced bars in eighth-block
// resolution, green-to-red by height, falling bars and peak caps that drop
// with gravity — dancing to the shared chiptune. A dim floor reflection when tall.
import { lerpc } from './_kit.js';
import { bands } from './_music.js';

const EIGHTHS = ' ▁▂▃▄▅▆▇█';
const K = 26, STEP = 1 / 30;

export default {
  title: 'Spectrum Analyzer',
  gallery: 'retro',
  category: 'Chiptune Visuals',
  kind: 'scene',
  tags: ['spectrum', 'analyzer', 'fft', 'eq', 'audio', 'bars', 'chiptune', 'winamp'],
  order: 20,
  description: 'A media-player spectrum analyser: log-spaced bars in eighth-blocks, falling peak caps and a floor reflection.',
  size: { w: 64, h: 16 },
  minSize: { w: 20, h: 6 },
  loop: 7.68,
  params: { style: { default: 'classic', options: ['classic', 'palette'], label: 'Colors' } },
  setup(ctx) {
    const { theme } = ctx;
    const b = ctx.buffer;
    const W = ctx.width, H = ctx.height;
    const pal = ctx.palette('prism');
    const classic = ctx.param('style', 'classic') !== 'palette';
    const barW = W >= 48 ? 2 : 1, pitch = barW + 1;
    const n = Math.max(4, Math.floor((W - 1) / pitch));
    const x0 = Math.floor((W - (n * pitch - 1)) / 2);
    const labels = H >= 10;
    const reflect = H >= 12 ? Math.max(2, Math.round(H * 0.18)) : 0;
    const rows = H - (labels ? 1 : 0) - reflect;
    const hist = Array.from({ length: K }, () => new Float32Array(n));
    const color = (f) => (!classic ? pal(f) : f < 0.55 ? theme.pos : f < 0.8 ? lerpc(theme.pos, theme.warn, (f - 0.55) / 0.25) : lerpc(theme.warn, theme.neg, (f - 0.8) / 0.2));
    const rowColor = Array.from({ length: rows }, (_, r) => color((r + 0.5) / rows));
    const freqs = [[60, '60'], [250, '250'], [1000, '1k'], [4000, '4k'], [10000, '10k']];
    return (t) => {
      b.fill(0, 0, W, H, ' ', theme.ink, theme.bg);
      for (let k = 0; k < K; k++) bands(t - k * STEP, n, hist[k]);
      for (let i = 0; i < n; i++) {
        // Bars fall at a fixed rate; caps hold briefly then fall with gravity.
        let bar = 0, peak = 0;
        for (let k = 0; k < K; k++) {
          const v = hist[k][i], age = k * STEP;
          bar = Math.max(bar, v - age * 2.2);
          peak = Math.max(peak, v - Math.max(0, age - 0.2) ** 2 * 3.2);
        }
        const h = Math.max(0, bar) * rows, ph = Math.max(h / rows, peak) * rows;
        const x = x0 + i * pitch;
        for (let r = 0; r < rows; r++) {
          const y = rows - 1 - r, fill = Math.min(1, Math.max(0, h - r));
          if (fill <= 0) break;
          const ch = EIGHTHS[Math.max(1, Math.round(fill * 8))];
          for (let dx = 0; dx < barW; dx++) b.set(x + dx, y, ch, rowColor[r]);
        }
        // The cap sits on the cell above the bar's top when there's room.
        const pr = Math.min(rows - 1, Math.floor(ph));
        if (ph > 0.05 && pr >= Math.ceil(h)) for (let dx = 0; dx < barW; dx++) b.set(x + dx, rows - 1 - pr, '▔', lerpc(rowColor[pr], theme.ink, 0.5));
        // Floor reflection: dim, upside down, fading away.
        for (let r = 0; r < reflect; r++) {
          const fill = Math.min(1, Math.max(0, h - r));
          if (fill <= 0) break;
          const fade = 0.28 * (1 - r / reflect);
          for (let dx = 0; dx < barW; dx++) b.set(x + dx, rows + r, fill > 0.5 ? '█' : '▀', lerpc(theme.bg, rowColor[r], fade));
        }
      }
      if (labels) {
        const y = H - 1;
        const lo = Math.log2(40), hi = Math.log2(12000);
        for (const [f, s] of freqs) {
          const x = Math.round(x0 + ((Math.log2(f) - lo) / (hi - lo)) * (n * pitch - 1) - s.length / 2);
          if (x >= 0 && x + s.length <= W) b.text(x, y, s, theme.muted);
        }
      }
    };
  },
};

sources.prism-term/src/facets/retro/starfield.js:
// Warp-speed starfield: stars fly at the camera in 3D, drawn as braille
// streaks whose length tracks the current speed. Every ten seconds the ship
// surges to warp; color temperature runs from ember (far) to blue-white (near).
export default {
  title: 'Starfield',
  gallery: 'retro',
  category: 'Intros & Scrollers',
  kind: 'scene',
  tags: ['starfield', 'warp', 'space', 'demoscene'],
  order: 10,
  description: 'Warp-speed 3D starfield — braille motion streaks, periodic warp surges, depth-based color temperature.',
  canvas: 'line',
  setup(ctx) {
    const cv = ctx.canvas();
    const { width: W, height: H, aspect } = cv;
    const rand = ctx.rng;
    const temp = ctx.palette(['#ff5a2e', '#ffab5e', '#fff0d8', '#d6e4ff', '#8db4ff']);
    // Deep space stays dark by Day: starlight is light, not ink.
    const sky = ctx.theme.mode === 'light' ? 0x06070b : -1;
    const speedK = ctx.param('speed', 1);
    const Hv = H * aspect;
    const k = 0.5 * Math.max(W, Hv);
    const ax = (W / 2 / k) * 1.2, ay = (Hv / 2 / k) * 1.2;
    const N = Math.max(60, Math.min(1800, Math.round(ctx.width * ctx.height * 0.16)));
    const X = new Float32Array(N), Y = new Float32Array(N), Z = new Float32Array(N), T = new Float32Array(N);
    const spawn = (i, z) => {
      X[i] = (rand() * 2 - 1) * ax;
      Y[i] = (rand() * 2 - 1) * ay;
      Z[i] = z;
      T[i] = rand();
    };
    for (let i = 0; i < N; i++) spawn(i, 0.04 + rand() * 0.96);
    const cx = W / 2, cy = H / 2;

    // Brightness-ramped line: dim at the tail, full at the head.
    const streak = (x0, y0, x1, y1, c) => {
      const n = Math.min(240, Math.max(1, Math.ceil(Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0)))));
      const r = (c >> 16) & 255, g = (c >> 8) & 255, b = c & 255;
      for (let s = 0; s <= n; s++) {
        const u = s / n, k2 = 0.18 + 0.82 * u * u;
        cv.set(x0 + (x1 - x0) * u, y0 + (y1 - y0) * u, ((r * k2) << 16) | ((g * k2) << 8) | ((b * k2) | 0));
      }
    };

    return (t, dt) => {
      // Surge envelope: cruise, then a 5 s warp bump every 10 s.
      const u = (t % 10) / 10;
      const bump = u < 0.5 ? Math.pow(Math.sin(Math.PI * u * 2), 2) : 0;
      const speed = (0.22 + 1.9 * bump) * speedK;
      const tail = 0.06 + 0.1 * bump;
      const roll = 0.35 * Math.sin(t * 0.11) + 0.25 * bump * Math.sin(t * 0.7);
      const cr = Math.cos(roll), sr = Math.sin(roll);
      cv.clear();
      for (let i = 0; i < N; i++) {
        Z[i] -= speed * dt;
        if (Z[i] <= 0.03) { spawn(i, 1); continue; }
        const x = X[i] * cr - Y[i] * sr, y = X[i] * sr + Y[i] * cr;
        const z = Z[i], zt = Math.min(1.05, z + speed * tail + 0.004);
        const hx = cx + (x / z) * k, hy = cy + ((y / z) * k) / aspect;
        if (hx < -2 || hy < -2 || hx > W + 2 || hy > H + 2) { spawn(i, 1); continue; }
        const tx = cx + (x / zt) * k, ty = cy + ((y / zt) * k) / aspect;
        const near = 1 - z;
        const c = temp(Math.min(1, near * 0.85 + T[i] * 0.3));
        const bright = Math.min(1, 0.42 + 0.8 * near * near + 0.25 * bump);
        const r = ((c >> 16) & 255) * bright, g = ((c >> 8) & 255) * bright, b = (c & 255) * bright;
        const col = (r << 16) | (g << 8) | (b | 0);
        streak(tx, ty, hx, hy, col);
        // Close stars get a fat 2×2 head so they read as bodies, not just lines.
        if (z < 0.3) { cv.set(hx + 1, hy, col); cv.set(hx, hy + 1, col); cv.set(hx + 1, hy + 1, col); }
      }
      if (sky >= 0) ctx.buffer.fill(0, 0, ctx.width, ctx.height, ' ', ctx.theme.ink, sky);
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/retro/sunset-strip:
// Four postcards from the sunset strip: a side-scrolling coastal drive past
// palms and glitter water; a braille wireframe flyover with hidden-line
// mountains; 80s chrome lettering floating over a scanline horizon; and a
// striped sun that pulses on the chiptune's kick.
import { lerpc, fract, hash2, textMask, fontPx } from './_kit.js';
import { songAt, LOOP as SL } from './_music.js';

const TAU = Math.PI * 2;
const addc = (a, b, k) => {
  if (k <= 0) return a;
  const r = Math.min(255, ((a >> 16) & 255) + ((b >> 16) & 255) * k);
  const g = Math.min(255, ((a >> 8) & 255) + ((b >> 8) & 255) * k);
  const bl = Math.min(255, (a & 255) + (b & 255) * k);
  return (r << 16) | (g << 8) | bl;
};

// ───────────────────────────────────────────────────────────── sunset drive ──
const SPR = [
  '...........bbbbbbbbb........',
  '.........bbwwwwwwwwbb.......',
  '......bbbbwwwwwwwwwwbb......',
  '..bbbbbbbbbbbbbbbbbbbbbbL...',
  'Tbbbbbbbbbbbbbbbbbbbbbbbb...',
  '...tttt...........tttt......',
  '...tHHt...........tHHt......',
];
const sunsetDrive = {
  id: 'retro-sunset-drive',
  since: '0.3.0',
  title: 'Sunset Drive',
  category: 'Outrun',
  kind: 'scene',
  order: 200,
  tags: ['sunset', 'drive', 'coast', 'palms', 'side-scroller', 'parallax', 'ocean', 'outrun'],
  description: 'A side-view coastal cruise at dusk: striped sun over glitter water, parallax palms, a guardrail, and a convertible with spinning wheels.',
  size: { w: 80, h: 22 },
  minSize: { w: 24, h: 8 },
  loop: 16,
  canvas: 'field',
  palette: 'sunset',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { width: PW, height: PH, px } = cv;
    const b = ctx.buffer;
    const L = 16;
    const hy = Math.max(1, Math.floor(PH * 0.5));
    const royTop = Math.max(hy + 1, Math.floor(PH * 0.72));
    const roadTop = Math.min(PH - 1, royTop + Math.max(1, Math.round(PH * 0.05)));
    const sunX = PW * 0.66, sunR = Math.max(2, Math.min(PW * 0.17, hy * 0.85));
    const sunY = hy - sunR * 0.25;
    const P = (x, y, c) => { x |= 0; y |= 0; if (x >= 0 && x < PW && y >= 0 && y < PH) px[y * PW + x] = c; };
    // pattern speeds quantized so every scroll closes exactly at the loop
    const VR = (126 * Math.max(1, Math.round((PW * 3) / 126))) / L;
    const spanF = Math.round(PW * 2), spanN = Math.round(PW * 2);
    const vF = spanF / L, vN = (spanN * 2) / L;
    const palmsF = Array.from({ length: 5 }, (_, i) => hash2(i, 41) * spanF);
    const palmsN = Array.from({ length: 4 }, (_, i) => hash2(i, 42) * spanN);
    const spanC = Math.round(PW * 1.6), vC = spanC / L;
    const clouds = Array.from({ length: 3 }, (_, i) => [hash2(i, 43) * spanC, Math.round(hy * (0.2 + 0.2 * i)), Math.round(PW * (0.2 + hash2(i, 44) * 0.2))]);
    const sil = lerpc(0x1c0530, 0x000000, 0.25);
    const palm = (bx, by, hgt, c) => {
      const lean = hgt * 0.16;
      for (let i = 0; i <= 24; i++) {
        const f = i / 24, x = bx + lean * f * f, y = by - hgt * f;
        const w = Math.max(1, hgt * 0.07 * (1 - f * 0.45));
        for (let o = 0; o < w; o++) P(x + o - w / 2, y, c);
      }
      const tx = bx + lean, ty = by - hgt;
      for (let a = 0; a < 7; a++) {
        const ang = -Math.PI + (a / 6) * Math.PI;
        const len = hgt * 0.48 * (0.75 + 0.25 * hash2(a, 3));
        for (let i = 0; i <= 14; i++) {
          const f = i / 14;
          P(tx + Math.cos(ang) * len * f, ty + Math.sin(ang) * len * f * 0.45 + len * f * f * 0.5, c);
        }
      }
    };
    const cs = Math.max(1, Math.floor(PW / 52));
    const carH = 7 * cs;
    const carX = Math.round(PW * 0.14);
    const SPRC = { b: lerpc(0x33123a, pal(0.25), 0.35), w: lerpc(pal(0.8), 0x33184a, 0.55), t: 0x0a0712, L: 0xffe9a0, T: 0xff4050 };
    return (t) => {
      const lt = t % L;
      // sky and sun
      for (let y = 0; y < hy; y++) px.fill(pal(0.04 + (y / hy) * 0.52), y * PW, (y + 1) * PW);
      for (let y = Math.max(0, Math.floor(sunY - sunR)); y < hy; y++) {
        for (let x = Math.max(0, Math.floor(sunX - sunR)); x < Math.min(PW, sunX + sunR + 1); x++) {
          const dx = x + 0.5 - sunX, dy = y + 0.5 - sunY;
          const d = Math.sqrt(dx * dx + dy * dy);
          if (d < sunR) {
            const v = (dy / sunR + 1) / 2;
            const band = fract(v * 6 - (lt * 3) / L);
            if (band > (v - 0.5) * 1.3) px[y * PW + x] = pal(0.96 - v * 0.36);
          } else if (d < sunR * 1.45) {
            const i = y * PW + x;
            px[i] = lerpc(px[i], pal(0.78), Math.pow(1 - (d - sunR) / (sunR * 0.45), 2) * 0.4);
          }
        }
      }
      for (const [c0, cy2, len] of clouds) {
        const xs = Math.floor((((c0 - lt * vC) % spanC) + spanC) % spanC) - Math.floor(PW * 0.3);
        for (let d2 = 0; d2 < len; d2++) {
          const x = xs + d2;
          P(x, cy2, lerpc(sil, pal(0.8), 0.35));
          if (d2 > 2 && d2 < len - 3) P(x, cy2 + 1, sil);
        }
      }
      // ocean with a glitter path
      for (let y = hy; y < royTop; y++) {
        const k = (y - hy) / Math.max(1, royTop - hy);
        const base = y === hy ? lerpc(0x1c0c34, pal(0.9), 0.55) : lerpc(0x241040, 0x120920, k);
        for (let x = 0; x < PW; x++) {
          let c = base;
          const dxs = Math.abs(x + 0.5 - sunX);
          const pw2 = sunR * (0.25 + k * 1.3);
          if (y > hy && dxs < pw2 && hash2(x, y, Math.floor(t * 6) % 97) < 0.45 * (1 - dxs / pw2) + 0.06) {
            c = lerpc(base, pal(0.88), 0.4 + 0.4 * hash2(x, y, 9));
          }
          px[y * PW + x] = c;
        }
      }
      // far palms on the headland across the water
      for (let j = 0; j < palmsF.length; j++) {
        const sx = Math.floor((((palmsF[j] - lt * vF) % spanF) + spanF) % spanF) - Math.floor(PW * 0.4);
        palm(sx, royTop - 1, PH * (0.2 + hash2(j, 45) * 0.1), lerpc(sil, pal(0.6), 0.25));
      }
      // shoulder, guardrail, road
      const sand = lerpc(0x4a2c44, pal(0.62), 0.22);
      for (let y = royTop; y < roadTop; y++) px.fill(sand, y * PW, (y + 1) * PW);
      for (let x = 0; x < PW; x++) {
        P(x, royTop, 0x1a0e24);
        if (fract((x + lt * VR) / 18) < 0.08) for (let y = royTop; y < roadTop; y++) P(x, y, 0x140a1c);
      }
      for (let y = roadTop; y < PH; y++) {
        const k = (y - roadTop) / Math.max(1, PH - roadTop);
        px.fill(lerpc(0x191326, 0x0f0b18, k), y * PW, (y + 1) * PW);
      }
      const midR = Math.min(PH - 1, Math.round((roadTop + PH - 1) / 2));
      for (let x = 0; x < PW; x++) if (fract((x + lt * VR) / 14) < 0.45) P(x, midR, lerpc(0x191326, 0xffd79a, 0.75));
      // the car
      const spin = Math.floor(lt * 10) % 2;
      const bobY = Math.floor(lt * 6) % 2 ? cs : 0;
      const carTop = PH - 1 - Math.round((PH - roadTop) * 0.12) - carH + 1 - bobY;
      for (let sy = 0; sy < 7; sy++) for (let sx = 0; sx < 28; sx++) {
        const ch = SPR[sy][sx];
        if (ch === '.') continue;
        let c = SPRC[ch];
        if (ch === 'H') c = spin ? 0xd8c8e0 : 0x403048;
        for (let oy = 0; oy < cs; oy++) for (let ox2 = 0; ox2 < cs; ox2++) P(carX + sx * cs + ox2, carTop + sy * cs + oy, c);
      }
      for (let d2 = 1; d2 <= 6 * cs; d2++) {
        const x = carX + 25 * cs + d2, y = carTop + 3 * cs;
        if (x >= 0 && x < PW && y >= 0 && y < PH) px[y * PW + x] = addc(px[y * PW + x], 0xffe9a0, 0.3 * (1 - d2 / (6 * cs)));
      }
      // near palms sweep past in the foreground
      for (let j = 0; j < palmsN.length; j++) {
        const sx = Math.floor((((palmsN[j] - lt * vN) % spanN) + spanN) % spanN) - Math.floor(PW * 0.4);
        palm(sx, PH - 1, PH * (0.5 + hash2(j, 46) * 0.16), lerpc(sil, 0x000000, 0.2));
      }
      cv.paint(b);
    };
  },
};

// ────────────────────────────────────────────────────────  wireframe flyover ──
const wireframe = {
  id: 'retro-wireframe-flyover',
  since: '0.3.0',
  title: 'Wireframe Flyover',
  category: 'Outrun',
  kind: 'scene',
  order: 240,
  tags: ['wireframe', 'terrain', 'mountains', 'flyover', 'hidden-line', 'braille', 'vector', 'outrun'],
  description: 'A vector flyover through wireframe mountains: hidden-line ridges sweep under the camera while a striped sun and stars hold the horizon.',
  size: { w: 80, h: 24 },
  minSize: { w: 24, h: 8 },
  loop: 10,
  glyphs: 'braille',
  canvas: 'line',
  palette: 'synthwave',
  params: { speed: { default: 1, min: 0.25, max: 3, label: 'Speed' } },
  setup(ctx) {
    const th = ctx.theme, b = ctx.buffer;
    const cv = ctx.canvas('line');
    const pal = ctx.palette();
    const n3 = ctx.noise.noise3;
    const { width: PW, height: PH } = cv;
    const ar = cv.aspect;
    const L = 10, spdW = 4.2 * ctx.param('speed', 1);
    const D = spdW * L;
    const F = PW * 0.5, hz = Math.max(1, Math.floor(PH * 0.42)), camH = 2.1;
    const znear = Math.max(1.2, ((camH * F) / ar) / Math.max(1, PH - hz - 1));
    const zfar = znear * 15;
    const ND = Math.max(5, Math.min(26, Math.round((PH - hz) / 5)));
    const zs = Float32Array.from({ length: ND }, (_, k) => 1 / (1 / znear + (k / (ND - 1)) * (1 / zfar - 1 / znear)));
    const minY = new Float32Array(PW);
    const ease = (k) => (th.mode === 'light' ? 1 - (1 - k) * (1 - k) : k);
    const cols = Array.from({ length: ND }, (_, k) => {
      const kf = k / (ND - 1);
      return lerpc(th.bg, pal(0.44 + 0.3 * (1 - kf) + (k % 3 === 0 ? 0.08 : 0)), ease(0.14 + 0.86 * Math.pow(1 - kf, 1.15)));
    });
    const Rs = Math.max(2, Math.min(PW * 0.2, hz * ar * 0.85));
    const cxs = PW * 0.5, cys = hz - (Rs / ar) * 0.1;
    const stars = Array.from({ length: 46 }, (_, i) => [Math.floor(hash2(i, 51) * PW), Math.floor(hash2(i, 52) * hz * 0.8), hash2(i, 53)]);
    return (t) => {
      const lt = t % L;
      const camZ = lt * spdW;
      const camX = Math.sin((TAU * lt) / L) * 2.4;
      cv.clear();
      minY.fill(PH * 4);
      for (let k = 0; k < ND; k++) {
        const z = zs[k], col = cols[k];
        const aa = (TAU * (camZ + z)) / D;
        const ca = Math.cos(aa) * 1.9, sa = Math.sin(aa) * 1.9;
        for (let x = 0; x < PW; x++) {
          const wx = ((x + 0.5 - PW / 2) * z) / F + camX;
          const nn = n3(wx * 0.14, ca, sa);
          let h = Math.max(0, 1 - Math.abs(nn) * 1.75);
          h = h * h * 3.6 * Math.min(1, Math.abs(wx) * 0.16 + 0.08);
          const y = hz + (((camH - h) * F) / z) / ar;
          if (y < minY[x] - 0.4 && y >= 0) cv.set(x, y, col);
          if (y < minY[x]) minY[x] = y;
        }
      }
      // striped sun and stars show only above the final silhouette
      const rTop = Math.max(0, Math.floor(cys - Rs / ar)), rBot = Math.floor(cys + Rs / ar);
      for (let yy = rTop; yy <= rBot; yy++) {
        const dyv = (yy - cys) * ar;
        if (Math.abs(dyv) > Rs || (yy & 1) === 1) continue;
        if (dyv > Rs * 0.05 && Math.floor((dyv / Rs) * 7) % 2 === 1) continue;
        const hw = Math.sqrt(Rs * Rs - dyv * dyv);
        const sc = pal(0.92 - ((dyv / Rs + 1) / 2) * 0.3);
        for (let xx = Math.max(0, Math.ceil(cxs - hw)); xx <= Math.min(PW - 1, cxs + hw); xx++) {
          if (yy < minY[xx] - 0.5) cv.set(xx, yy, sc);
        }
      }
      for (const [sx, sy, kk] of stars) {
        if (sy < minY[sx] - 1 && Math.sin(TAU * (lt / L) * (1 + Math.floor(kk * 3)) + kk * 20) > 0.2) {
          cv.set(sx, sy, lerpc(th.bg, pal(0.96), ease(0.4 + kk * 0.5)));
        }
      }
      cv.paint(b);
    };
  },
};

// ──────────────────────────────────────────────────────────  chrome horizon ──
const chromeHorizon = {
  id: 'retro-chrome-horizon',
  since: '0.3.0',
  title: 'Chrome Horizon',
  category: 'Outrun',
  kind: 'scene',
  order: 250,
  tags: ['chrome', 'logo', 'text', '80s', 'horizon', 'scanlines', 'glint', 'outrun'],
  description: 'An 80s chrome logo floats over a scanline dusk: sky-to-steel letter shading, a sweeping specular glint, star sparkles and a rippled mirror.',
  size: { w: 72, h: 20 },
  minSize: { w: 24, h: 8 },
  loop: 10,
  canvas: 'field',
  palette: 'synthwave',
  params: { text: { default: 'PRISM', label: 'Text' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { width: PW, height: PH, px } = cv;
    const b = ctx.buffer;
    const L = 10;
    const txt = String(ctx.param('text', 'PRISM')).slice(0, 12) || 'PRISM';
    const hz = Math.max(2, Math.floor(PH * 0.64));
    let m = textMask(txt, { font: 'bold' });
    let { sx: spx, sy: spy } = fontPx(cv, Math.max(3, Math.min(9, Math.round(ctx.height * 0.4))));
    const ratio = Math.max(0.25, spy / Math.max(1, spx));
    while (m.w * spx > PW * 0.94 && spx > 1) { spx--; spy = Math.max(1, Math.round(spx * ratio)); }
    if (m.w * spx > PW * 0.98) { m = textMask(txt, { font: 'tiny' }); spx = 1; spy = Math.max(1, Math.round(ratio)); }
    const tiny = m.w * spx > PW;
    const tW = m.w * spx, tH = Math.max(1, m.h * spy);
    const tx0 = Math.max(0, Math.floor((PW - tW) / 2));
    const ty0 = Math.max(0, hz - tH - Math.max(1, Math.round(PH * 0.05)));
    const bit = (mx, my) => (mx < 0 || my < 0 || mx >= m.w || my >= m.h ? 0 : m.bits[my * m.w + mx]);
    const corners = [];
    for (let my = 0; my < m.h; my++) for (let mx = 0; mx < m.w; mx++) {
      if (m.bits[my * m.w + mx] && !bit(mx - 1, my) && !bit(mx, my - 1)) corners.push([mx, my, ctx.rng()]);
    }
    const sparkles = corners.filter((_, i) => i % Math.max(1, Math.floor(corners.length / 7)) === 0).slice(0, 7);
    const rim = 0x0d0618;
    const chrome = (v) => {
      if (v < 0.44) return lerpc(0x1b3f8f, 0xdef2ff, Math.pow(v / 0.44, 1.3));
      if (v < 0.52) return 0xffffff;
      const s = (v - 0.52) / 0.48;
      return Math.floor(s * 5) % 2 === 0 ? lerpc(0xffb24a, 0x6b2f0c, s) : lerpc(0xffd98a, 0x8a4a16, s);
    };
    const rowChrome = Int32Array.from({ length: tH }, (_, my) => chrome(my / Math.max(1, tH - 1)));
    const stars = Array.from({ length: Math.round(PW * 0.4) }, (_, i) => [Math.floor(hash2(i, 61) * PW), Math.floor(hash2(i, 62) * hz * 0.9), hash2(i, 63)]);
    return (t) => {
      const lt = t % L;
      const shift = Math.floor((lt / L) * 36);
      for (let y = 0; y < PH; y++) {
        let c;
        if (y < hz) {
          c = lerpc(pal(0.05), pal(0.4), Math.pow(y / hz, 1.3));
          if ((y + shift) % 3 === 0) c = lerpc(c, 0x000000, 0.22);
        } else if (y === hz) c = pal(0.85);
        else {
          const k = (y - hz) / Math.max(1, PH - hz);
          c = lerpc(0x0c0618, 0x1e0f30, k);
          if ((y - hz) % 4 === 0) c = lerpc(c, pal(0.6), 0.12);
        }
        px.fill(c, y * PW, (y + 1) * PW);
      }
      for (const [sx, sy, kk] of stars) {
        if (Math.sin(TAU * (lt / L) * (1 + Math.floor(kk * 3)) + kk * 30) > 0) px[sy * PW + sx] = lerpc(px[sy * PW + sx], 0xffffff, 0.35 + kk * 0.4);
      }
      if (!tiny) {
        const g = fract(lt / (L / 2));
        for (let myp = 0; myp < tH; myp++) {
          const my = Math.floor(myp / spy);
          const y = ty0 + myp;
          if (y >= PH) break;
          for (let mxp = 0; mxp < tW; mxp++) {
            const mx = Math.floor(mxp / spx);
            if (!m.bits[my * m.w + mx]) continue;
            const edge = !bit(mx - 1, my) || !bit(mx + 1, my) || !bit(mx, my - 1) || !bit(mx, my + 1);
            let c = edge ? rim : rowChrome[myp];
            const d = mxp / tW + (myp / tH) * 0.35 - g * 1.6 + 0.3;
            if (!edge && Math.abs(d) < 0.045) c = lerpc(c, 0xffffff, 0.9);
            px[y * PW + tx0 + mxp] = c;
          }
        }
        const maxRy = Math.min(tH, PH - hz - 1);
        for (let ry = 0; ry < maxRy; ry++) {
          const myp = tH - 1 - ry;
          const y = hz + 1 + ry;
          const off = Math.round(Math.sin(ry * 0.9 + (TAU * lt * 2) / L) * 1.2);
          for (let mxp = 0; mxp < tW; mxp++) {
            const mx = Math.floor(mxp / spx), my = Math.floor(myp / spy);
            if (!m.bits[my * m.w + mx]) continue;
            const x = tx0 + mxp + off;
            if (x < 0 || x >= PW) continue;
            const i = y * PW + x;
            px[i] = lerpc(px[i], rowChrome[myp], 0.32 * (1 - ry / maxRy));
          }
        }
        for (const [mx, my, ph] of sparkles) {
          const tw = Math.max(0, Math.sin(TAU * ((lt / L) * 3 + ph)));
          if (tw < 0.55) continue;
          const sx = tx0 + mx * spx, sy = ty0 + my * spy;
          const len = 1 + Math.round(tw * 2);
          for (let d2 = -len; d2 <= len; d2++) {
            const k2 = 1 - Math.abs(d2) / (len + 1);
            if (sx + d2 >= 0 && sx + d2 < PW && sy >= 0 && sy < PH) px[sy * PW + sx + d2] = addc(px[sy * PW + sx + d2], 0xffffff, tw * k2 * 0.9);
            if (sy + d2 >= 0 && sy + d2 < PH && sx >= 0 && sx < PW) px[(sy + d2) * PW + sx] = addc(px[(sy + d2) * PW + sx], 0xffffff, tw * k2 * 0.7);
          }
        }
      }
      cv.paint(b);
      if (tiny) b.text(Math.max(0, Math.floor((ctx.width - txt.length) / 2)), Math.max(0, Math.floor(ctx.height * 0.4)), txt, pal(0.9));
    };
  },
};

// ───────────────────────────────────────────────────────────────  sun pulse ──
const sunPulse = {
  id: 'retro-sun-pulse',
  since: '0.3.0',
  title: 'Sun Pulse',
  category: 'Outrun',
  kind: 'scene',
  order: 260,
  tags: ['sun', 'pulse', 'retrowave', 'scanlines', 'beat', 'water', 'kick', 'outrun'],
  description: 'A giant striped retrowave sun breathes on the chiptune kick — shockwave rings roll off every beat across a scanline sky and shimmering sea.',
  size: { w: 64, h: 20 },
  minSize: { w: 20, h: 7 },
  loop: SL,
  canvas: 'field',
  palette: 'sunset',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const { width: PW, height: PH, px } = cv;
    const b = ctx.buffer;
    const hz = Math.max(1, Math.floor(PH * 0.62));
    const cxs = PW * 0.5;
    const R0 = Math.max(2, Math.min(PW * 0.34, hz * 0.88));
    const cys = hz - R0 * 0.16;
    const seaT = lerpc(0x180a28, 0x241233, 0.5);
    const corona = pal(0.8);
    const birds = PH >= 14;
    return (t) => {
      const s = songAt(t);
      const pulse = s.kick;
      const R = R0 * (1 + 0.07 * pulse);
      const rr = R * 1.08 + s.kickAge * PW * 0.42;
      const rw = 1.6 + pulse;
      const ringA = Math.exp(-s.kickAge * 2.1);
      const shift = Math.floor((t / SL) * 24);
      for (let y = 0; y < PH; y++) {
        const sky = y < hz;
        const yv = sky ? y + 0.5 : hz - 1 - (y - hz) * 0.92 + 0.5;
        const k = sky ? 0 : (y - hz) / Math.max(1, PH - hz);
        const rowBase = sky
          ? lerpc(pal(0.08), pal(0.46), Math.pow(y / hz, 1.25))
          : lerpc(lerpc(pal(0.08), pal(0.46), Math.pow(Math.min(1, Math.max(0, yv) / hz), 1.25)), seaT, 0.4);
        const scan = sky && (y + shift) % 2 === 0;
        const xoff = sky ? 0 : Math.sin((y - hz) * 1.6 + (TAU * t * 4) / SL) * (0.6 + k * 1.8);
        const dy = yv - cys;
        for (let x = 0; x < PW; x++) {
          const dx = x + xoff + 0.5 - cxs;
          const d = Math.sqrt(dx * dx + dy * dy);
          let c = rowBase;
          if (d < R) {
            const v = (dy / R + 1) / 2;
            const band = fract(v * 7 - (t / SL) * 3);
            if (band > (v - 0.44) * 1.35) c = lerpc(pal(0.97 - v * 0.42), 0xfff3c0, pulse * 0.3);
          } else if (d < R * 1.55) {
            c = addc(c, corona, Math.pow(1 - (d - R) / (R * 0.55), 2) * (0.18 + 0.3 * pulse));
          }
          if (Math.abs(d - rr) < rw) c = lerpc(c, 0xffe9b0, ringA * 0.6 * (1 - Math.abs(d - rr) / rw));
          if (scan) c = lerpc(c, 0x000000, 0.18);
          if (!sky) {
            c = lerpc(c, seaT, 0.3 + k * 0.3);
            if (hash2(x, y, Math.floor(t * 8) % 89) < 0.03 + 0.1 * pulse * (1 - k)) c = lerpc(c, pal(0.9), 0.4);
          } else if (hash2(x, y, Math.floor(t * 12) % 83) < 0.012) c = addc(c, 0xffffff, 0.06);
          px[y * PW + x] = c;
        }
      }
      if (birds) for (let k2 = 0; k2 < 2; k2++) {
        const u = fract(t / SL + k2 * 0.5);
        const bx = Math.floor(u * (PW + 10) - 5);
        const by = Math.floor(PH * (0.12 + 0.07 * k2) + Math.sin(TAU * u * 3) * 1.5);
        const wing = fract((t / SL) * 20) < 0.5 ? -1 : 0;
        for (const [ox, oy] of [[-2, wing], [-1, 0], [0, 1], [1, 0], [2, wing]]) {
          const x = bx + ox, y = by + oy;
          if (x >= 0 && x < PW && y >= 0 && y < Math.max(1, hz - 1)) px[y * PW + x] = 0x1a0a20;
        }
      }
      cv.paint(b);
    };
  },
};

export default [sunsetDrive, wireframe, chromeHorizon, sunPulse];

sources.prism-term/src/facets/retro/synthwave.js:
// Outrun flyover: a striped, gradient sun sinking behind a neon-rimmed
// mountain ridge, starry dusk sky, and a perspective grid racing toward the
// camera. Grid lines are anti-aliased analytically (world-space distance
// converted to pixels per row), so they stay crisp without moiré at the horizon.
export default {
  title: 'Synthwave',
  gallery: 'retro',
  category: 'Outrun',
  kind: 'scene',
  tags: ['synthwave', 'outrun', 'retrowave', 'grid', 'sun'],
  order: 40,
  description: 'Outrun flyover — striped gradient sun, neon-rimmed mountains and an anti-aliased perspective grid.',
  canvas: 'field',
  palette: 'synthwave',
  setup(ctx) {
    const cv = ctx.canvas();
    const pal = ctx.palette();
    const speed = ctx.param('speed', 1);
    const rand = ctx.rng;
    const { fbm } = ctx.noise;
    const { width: W, height: H, px, aspect } = cv;
    const hz = Math.floor(H * 0.6);           // horizon row
    const S = Math.min(W, H * aspect);
    const sunR = S * 0.3, sunX = W / 2, sunY = hz * aspect - sunR * 0.62; // sun center in visual units
    const camH = 1, focal = W * 0.55;
    const gridC = pal(0.62), gridC2 = pal(0.5), rimC = pal(0.7);
    const sky = new Int32Array(W * hz);
    const skyTop = pal(0.02), skyLow = pal(0.45);
    for (let y = 0; y < hz; y++) {
      const k = Math.pow(y / hz, 1.6);
      sky.fill(lerpc(skyTop, skyLow, k * 0.85), y * W, (y + 1) * W);
    }
    const stars = Array.from({ length: Math.floor(W * hz * 0.01) }, () => [Math.floor(rand() * W), Math.floor(rand() * hz * 0.7), rand()]);
    const ridge = new Float32Array(W), ridge2 = new Float32Array(W);
    // Ridged noise for sharp peaks; the near range is low in the middle so the sun shows.
    for (let x = 0; x < W; x++) {
      const u = x / W, side = 0.25 + 0.75 * Math.min(1, Math.abs(u - 0.5) * 2.4);
      const p = Math.max(0, 1 - Math.abs(fbm(u * 3.4, 1.7, 0, 3)) * 1.7);
      const q = Math.max(0, 1 - Math.abs(fbm(u * 7.5, 8.2, 0, 3)) * 1.7);
      ridge[x] = hz - H * (0.012 + 0.2 * side * p * p);
      ridge2[x] = hz - H * (0.02 + 0.13 * q * q * (0.35 + 0.65 * side));
    }

    return (t) => {
      const zoff = t * 2.2 * speed;
      const xoff = Math.sin(t * 0.25) * 1.2;
      for (let y = 0, i = 0; y < H; y++) {
        const vy = (y + 0.5) * aspect;
        for (let x = 0; x < W; x++, i++) {
          if (y < hz) {
            let c = sky[i];
            // Sun: vertical gradient, with horizontal gaps that widen toward its base and scroll down.
            const dx = x + 0.5 - sunX, dy = vy - sunY;
            const d = Math.sqrt(dx * dx + dy * dy);
            if (d < sunR) {
              const v = (dy / sunR + 1) / 2;       // 0 top → 1 bottom
              const band = v > 0.42 ? ((v * 6.5 - t * 0.35) % 1 + 1) % 1 : 1;
              const gap = (v - 0.42) * 1.35;
              if (band > gap) c = pal(0.98 - v * 0.42);
            } else if (d < sunR * 1.5) {
              c = lerpc(c, pal(0.75), Math.pow(1 - (d - sunR) / (sunR * 0.5), 2) * 0.35);
            }
            if (y >= ridge2[x]) c = lerpc(0x1a0630, rimC, y - ridge2[x] < 1 ? 0.55 : 0.04);
            if (y >= ridge[x]) c = lerpc(0x0c0218, rimC, y - ridge[x] < 1 ? 0.95 : 0.02);
            px[i] = c;
          } else {
            const dyp = y - hz + 0.5;
            const z = (camH * focal) / dyp;           // world depth of this row
            const wx = ((x + 0.5 - W / 2) * z) / focal + xoff;
            const fx = wx - Math.round(wx), fz = (z + zoff) - Math.round(z + zoff);
            const pxPerX = focal / z, pxPerZ = (camH * focal) / (z * z);
            // Coverage of a ~0.9px line, faded out as lines converge below ~3px spacing (no moiré).
            const lx = Math.max(0, 1 - Math.abs(fx) * pxPerX / 0.9) * Math.min(1, Math.max(0, (pxPerX - 2.5) / 6));
            const lz = Math.max(0, 1 - Math.abs(fz) * pxPerZ / 0.9) * Math.min(1, Math.max(0, (pxPerZ - 1.5) / 4));
            const fog = Math.exp(-z / 18);
            const near = Math.min(1, dyp / (H - hz));
            const base = lerpc(0x0a0016, 0x1d0638, near);
            let c = lerpc(base, gridC2, Math.min(1, lz * fog * 1.15));
            c = lerpc(c, gridC, Math.min(1, lx * fog * 1.2));
            // Horizon haze glow.
            const sx = (x + 0.5 - sunX) / (sunR * 1.3);
            c = lerpc(c, pal(0.74), Math.pow(Math.max(0, 1 - dyp / (H * 0.12)), 1.5) * (0.3 + 0.45 * Math.exp(-sx * sx)));
            px[i] = c;
          }
        }
      }
      for (const [sx, sy, p] of stars) {
        const tw = 0.4 + 0.6 * Math.abs(Math.sin(t * (0.8 + p * 2) + p * 10));
        const dx = sx + 0.5 - sunX, dy = (sy + 0.5) * aspect - sunY;
        if (sy < ridge2[sx] && dx * dx + dy * dy > sunR * sunR * 1.6) px[sy * W + sx] = lerpc(px[sy * W + sx], 0xffffff, tw * 0.8);
      }
      cv.paint(ctx.buffer);
    };
  },
};

function lerpc(a, b, t) {
  const r = ((a >> 16) & 255) + ((((b >> 16) & 255) - ((a >> 16) & 255)) * t);
  const g = ((a >> 8) & 255) + ((((b >> 8) & 255) - ((a >> 8) & 255)) * t);
  const bl = (a & 255) + (((b & 255) - (a & 255)) * t);
  return (r << 16) | (g << 8) | (bl | 0);
}

