    function relaxPair(i, j, rest) {
      const dx = x[j] - x[i], dy = y[j] - y[i];
      const d = Math.hypot(dx, dy) || 1e-4;
      const k = ((d - rest) / d) * 0.5;
      x[i] += dx * k; y[i] += dy * k;
      x[j] -= dx * k; y[j] -= dy * k;
