// Storm cells — the violent end of the weather gallery: a gusting thunderstorm
// over open fields, a hurricane's spiral banding from orbit, a roping tornado
// funnel, and hail hammering and bouncing off a frozen paddock.
import { mix } from '../../color.js';

const TAU = Math.PI * 2;
const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);

export default [
  {
    id: 'sim-thunderstorm',
    since: '0.3.0',
    title: 'Thunderstorm Cell',
    gallery: 'sim',
    category: 'Weather',
    kind: 'scene',
    tags: ['thunderstorm', 'lightning', 'rain', 'wind', 'gusts', 'storm'],
    order: 200,
    description: 'A churning cloud deck drives gusts of slanted rain across open fields; forked lightning floods the scene and bends the lone tree.',
    size: { w: 80, h: 24 },
    minSize: { w: 24, h: 8 },
    loop: 20,
    canvas: 'field',
    params: { intensity: { default: 1, min: 0.3, max: 2.5, label: 'Rain intensity' } },
    setup(ctx) {
      const cv = ctx.canvas();
      const W = cv.width, H = cv.height, px = cv.px;
      const th = ctx.theme, rand = ctx.rng, noise = ctx.noise;
      const gy = Math.max(3, Math.round(H * 0.84)), cloudH = Math.max(2, Math.round(H * 0.42));
      const skyHi = mix(th.bg, 0x11161f, 0.6), skyLo = mix(th.bg, 0x2a3440, 0.55);
      const cloudDark = mix(th.bg, 0x0a0e14, 0.75), cloudLit = mix(th.bg, 0x3d4a52, 0.5);
      const stormGreen = 0x25332c;
      const fieldC = mix(th.bg, 0x14240f, 0.6), fieldD = mix(th.bg, 0x0b1608, 0.65);
      const rainC = mix(th.info, 0xc8d6ff, 0.5);
      const flashC = 0xe8eeff;
      const N = clamp(Math.round((ctx.width * ctx.height) / 10) * ctx.param('intensity', 1), 40, 420) | 0;
      const RX = new Float32Array(N), RY = new Float32Array(N), RS = new Float32Array(N);
      for (let i = 0; i < N; i++) { RX[i] = rand() * W; RY[i] = rand() * H; RS[i] = 0.75 + rand() * 0.5; }
      // One wind-bent tree, grown once; redrawn each frame with the gust lean.
      const tx = W * 0.24, trunkH = Math.max(3, (gy - cloudH) * 0.55);
      const limbs = [];
      const mkLimbs = (x, y, ang, len, depth) => {
        limbs.push([x, y, ang, len]);
        if (depth <= 0 || len < 1.3) return;
        mkLimbs(x + Math.cos(ang) * len, y - Math.sin(ang) * len, ang + 0.4 + rand() * 0.25, len * 0.62, depth - 1);
        mkLimbs(x + Math.cos(ang) * len, y - Math.sin(ang) * len, ang - 0.4 - rand() * 0.25, len * 0.62, depth - 1);
      };
      mkLimbs(0, 0, Math.PI / 2, trunkH * 0.55, 3);
      const plot = (x0, y0, x1, y1, c) => {
        const n = Math.max(1, Math.ceil(Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0))));
        for (let k = 0; k <= n; k++) {
          const x = Math.round(x0 + (x1 - x0) * (k / n)), y = Math.round(y0 + (y1 - y0) * (k / n));
          if (x >= 0 && x < W && y >= 0 && y < H) px[y * W + x] = c;
        }
      };
      let nextBolt = 1.5 + rand() * 2, boltAt = -10, bolt = [];
      const mkBolt = () => {
        const segs = [];
        const descend = (x, y, depth) => {
          while (y < gy - 1) {
            const ny = y + 1.5 + rand() * 3, nx = x + (rand() - 0.5) * 5;
            segs.push([x, y, nx, ny]);
            if (depth < 2 && rand() < 0.14) descend(nx, ny, depth + 1);
            if (depth > 0 && rand() < 0.1) return;
            x = nx; y = ny;
          }
        };
        descend(W * (0.2 + rand() * 0.6), cloudH * (0.5 + rand() * 0.4), 0);
        return segs;
      };

      return (t, dt) => {
        dt = clamp(dt, 0, 0.1);
        const wind = 0.35 + 0.35 * noise.noise2(t * 0.33, 2.2) + 0.45 * Math.max(0, noise.noise2(t * 1.1, 9.1));
        if (t >= nextBolt) { boltAt = t; bolt = mkBolt(); nextBolt = t + 3.5 + rand() * 4; }
        const u = t - boltAt;
        const f = u < 0 || u > 1 ? 0 : Math.min(1, Math.exp(-u * 9) + (u > 0.14 ? 0.65 * Math.exp(-(u - 0.14) * 8) : 0));
        for (let y = 0; y < H; y++) {
          const row = y * W;
          if (y < cloudH) {
            const ky = y / cloudH;
            for (let x = 0; x < W; x++) {
              const d = noise.fbm(x * 0.045 - t * (0.35 + wind * 0.5), y * 0.12, t * 0.05, 2) + (1 - ky) * 0.45;
              let c = d > 0.08 ? mix(mix(skyLo, cloudDark, clamp(d * 1.5, 0, 1)), cloudLit, clamp(d - 0.45, 0, 0.4)) : mix(skyHi, skyLo, ky);
              if (d > 0.2 && ky > 0.6) c = mix(c, stormGreen, 0.3);
              if (f > 0.02) c = mix(c, flashC, f * clamp(0.25 + d * 0.6, 0, 0.9));
              px[row + x] = c;
            }
          } else if (y < gy) {
            const ky = (y - cloudH) / Math.max(1, gy - cloudH);
            let c = mix(skyLo, mix(skyHi, 0x3a4450, 0.4), ky);
            if (f > 0.02) c = mix(c, flashC, f * 0.5);
            for (let x = 0; x < W; x++) px[row + x] = c;
          } else {
            for (let x = 0; x < W; x++) {
              let c = (x * 13 + y * 29) % 9 < 2 ? fieldD : fieldC;
              if (f > 0.02) c = mix(c, flashC, f * 0.3);
              px[row + x] = c;
            }
          }
        }
        // Tree, leaning with the gust.
        const lean = (wind - 0.35) * 2.2;
        const treeC = mix(0x05070a, th.bg, 0.12);
        for (const [lx, ly, ang, len] of limbs) {
          const bend = lean * (ly / Math.max(1, trunkH));
          const x0 = tx + lx + lean * (ly / trunkH) * 3, y0 = gy - ly;
          const a = ang - bend * 0.5;
          plot(x0, y0, x0 + Math.cos(a) * len, y0 - Math.sin(a) * len, f > 0.3 ? mix(treeC, 0x000000, 0.5) : treeC);
        }
        plot(tx, gy, tx + lean * 3, gy - trunkH * 0.55, treeC);
        // Rain: slant follows the gust; drops splash at the ground line.
        const vy = H * 1.6, lit = Math.min(1, 0.55 + f);
        for (let i = 0; i < N; i++) {
          RY[i] += vy * RS[i] * dt;
          RX[i] += vy * RS[i] * wind * 0.55 * dt;
          if (RX[i] >= W) RX[i] -= W; else if (RX[i] < 0) RX[i] += W;
          if (RY[i] >= gy) {
            const xi = RX[i] | 0;
            if (xi >= 0 && xi < W) px[(gy - 1) * W + xi] = mix(px[(gy - 1) * W + xi], rainC, 0.8);
            RY[i] = -rand() * H * 0.2; RX[i] = rand() * W;
            continue;
          }
          const c = mix(px[clamp(RY[i] | 0, 0, H - 1) * W + clamp(RX[i] | 0, 0, W - 1)], rainC, 0.6 * lit);
          for (let k = 0; k < 3; k++) {
            const x = (RX[i] - wind * 0.55 * k) | 0, y = (RY[i] - k) | 0;
            if (x >= 0 && x < W && y >= 0 && y < H && y < gy) px[y * W + x] = k ? mix(px[y * W + x], c, 0.55) : c;
          }
        }
        if (f > 0.18) {
          const bc = mix(rainC, 0xf4f7ff, Math.min(1, f * 1.3));
          for (const [x0, y0, x1, y1] of bolt) plot(x0, y0, x1, y1, bc);
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'sim-hurricane',
    since: '0.3.0',
    title: 'Hurricane Eye',
    gallery: 'sim',
    category: 'Weather',
    kind: 'scene',
    tags: ['hurricane', 'cyclone', 'satellite', 'spiral', 'eye', 'storm'],
    order: 210,
    description: 'Satellite view of a cyclone: rainbands spiral into a bright eyewall around a calm eye, crawling toward a dark coastline.',
    size: { w: 64, h: 24 },
    minSize: { w: 20, h: 8 },
    loop: 24,
    canvas: 'field',
    palette: 'ocean',
    setup(ctx) {
      const cv = ctx.canvas();
      const W = cv.width, H = cv.height, px = cv.px, asp = cv.aspect;
      const th = ctx.theme, noise = ctx.noise;
      const cx = W * 0.52, cy = (H * 0.46) * asp;
      const R = Math.max(6, Math.min(W, H * asp) * 0.52);
      const re = R * 0.14;
      const seaC = mix(th.bg, 0x062a44, 0.62), seaD = mix(th.bg, 0x04121f, 0.7);
      const landC = mix(th.bg, 0x1c2b1a, 0.6), shoreC = mix(th.bg, 0x44573e, 0.5);
      const cloudLo = 0x8fa3b8, cloudHi = 0xffffff;
      const land = new Uint8Array(W * H);
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        // A ragged landmass hugging the lower-left corner.
        const d = Math.hypot(x / W, (H - y) / H);
        const edge = 0.52 + 0.2 * noise.fbm(x * 0.05 + 31, y * 0.08 + 17, 0, 2);
        if (d < edge * 0.75) land[y * W + x] = d > edge * 0.62 ? 2 : 1;
      }
      const w1 = TAU * 2 / 24; // two full rotations per loop — closes exactly

      return (t) => {
        const ca = Math.cos(w1 * t), sa = Math.sin(w1 * t);
        const drift = Math.sin(t * w1 * 0.5) * R * 0.04;
        for (let y = 0; y < H; y++) {
          const row = y * W, dyv = y * asp - cy - drift * 0.4;
          for (let x = 0; x < W; x++) {
            const dx = x - cx - drift;
            const r = Math.hypot(dx, dyv);
            let base = land[row + x] ? (land[row + x] === 2 ? shoreC : landC) : ((x * 7 + y * 13) % 17 < 1 ? mix(seaC, 0x2f6a8f, 0.4) : mix(seaC, seaD, r / (R * 2)));
            if (r < R * 1.9) {
              const th0 = Math.atan2(dyv, dx);
              const xr = dx * ca + dyv * sa, yr = dyv * ca - dx * sa;
              const tex = noise.fbm(xr * 0.045 + 3.1, yr * 0.045 + 7.7, 0, 2);
              const band = Math.sin(4.6 * Math.log(r + 4) - 3 * th0 + 3 * w1 * t);
              const radial = Math.exp(-r / (R * 0.75));
              const eyeK = clamp((r - re * 0.55) / (re * 0.8), 0, 1);
              const wall = Math.exp(-Math.pow((r - re * 1.15) / (re * 0.5), 2)) * 0.55;
              let dens = clamp(((tex + 0.42) * (0.52 + 0.48 * band)) * radial * 1.6 * eyeK + wall, 0, 1);
              if (dens > 0.04) {
                const lit = clamp(0.55 + 0.45 * ((dx - dyv) / (r + 4)) * 0.5 + dens * 0.5, 0, 1);
                base = mix(base, mix(cloudLo, cloudHi, lit), Math.min(1, dens * 1.5));
              }
            }
            px[row + x] = base;
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'sim-tornado',
    since: '0.3.0',
    title: 'Tornado Funnel',
    gallery: 'sim',
    category: 'Weather',
    kind: 'scene',
    tags: ['tornado', 'funnel', 'debris', 'vortex', 'storm', 'dust'],
    order: 220,
    description: 'A roping funnel sways under its wall cloud, striations spinning down the column while debris orbits up out of the dust skirt.',
    size: { w: 64, h: 24 },
    minSize: { w: 20, h: 8 },
    loop: 25,
    canvas: 'field',
    setup(ctx) {
      const cv = ctx.canvas();
      const W = cv.width, H = cv.height, px = cv.px;
      const th = ctx.theme, rand = ctx.rng, noise = ctx.noise;
      const ch = Math.max(2, Math.round(H * 0.2)), gyv = Math.max(ch + 2, Math.round(H * 0.84));
      const skyC = mix(th.bg, 0x232b2c, 0.6), skyD = mix(th.bg, 0x11171a, 0.7);
      const cloudC = mix(th.bg, 0x090d10, 0.75);
      const groundC = mix(th.bg, 0x332817, 0.55), groundD = mix(th.bg, 0x201808, 0.6);
      const funnelC = mix(th.bg, 0x4a5258, 0.45), funnelD = mix(th.bg, 0x1a2024, 0.7);
      const dustC = mix(th.bg, 0x6b573a, 0.5);
      const M = clamp(Math.round((W * H) / 180), 16, 48);
      const deb = Array.from({ length: M }, () => ({ y: gyv - rand() * (gyv - ch) * 0.6, a: rand() * TAU, r: 0.6 + rand() * 0.7, v: 5 + rand() * 4 }));
      const cxAt = (y, t) => {
        const ky = clamp((y - ch) / Math.max(1, gyv - ch), 0, 1);
        return W * 0.5 + W * 0.1 * Math.sin(t * 0.1)
          + noise.noise2(t * 0.33, 1.1) * W * 0.07 * ky
          + noise.noise2(t * 0.9, 5.5) * W * 0.045 * ky * ky;
      };
      const wAt = (y, t) => {
        const ky = clamp((y - ch) / Math.max(1, gyv - ch), 0, 1);
        return Math.max(1.2, (W * 0.15 * Math.pow(1 - ky, 0.85) + W * 0.02) * (1 + 0.1 * Math.sin(t * 0.7)));
      };

      return (t, dt) => {
        dt = clamp(dt, 0, 0.1);
        for (let y = 0; y < H; y++) {
          const row = y * W;
          if (y < ch) {
            for (let x = 0; x < W; x++) {
              const d = noise.fbm(x * 0.05 - t * 0.25, y * 0.3, t * 0.04, 2) + 0.3;
              px[row + x] = mix(skyD, cloudC, clamp(d * 1.6, 0, 1));
            }
          } else if (y < gyv) {
            const ky = (y - ch) / Math.max(1, gyv - ch);
            const c = mix(skyD, skyC, ky);
            for (let x = 0; x < W; x++) px[row + x] = c;
          } else {
            for (let x = 0; x < W; x++) px[row + x] = (x * 11 + y * 23) % 7 < 2 ? groundD : groundC;
          }
        }
        // The funnel: a translucent column with striations spiralling down.
        for (let y = ch; y <= gyv; y++) {
          const cx = cxAt(y, t), w = wAt(y, t), row = y * W;
          const x0 = Math.max(0, Math.floor(cx - w - 1)), x1 = Math.min(W - 1, Math.ceil(cx + w + 1));
          for (let x = x0; x <= x1; x++) {
            const u = (x - cx) / w;
            if (u < -1 || u > 1) continue;
            const dens = Math.sqrt(1 - u * u);
            const stri = 0.5 + 0.5 * Math.sin(u * 2.6 + y * 0.42 - t * 9);
            const nd = noise.noise2(u * 1.8 + t * 1.6, y * 0.18) * 0.25;
            const k = clamp(dens * (0.55 + 0.3 * stri + nd), 0, 1);
            px[row + x] = mix(px[row + x], Math.abs(u) > 0.78 ? funnelD : mix(funnelD, funnelC, stri), k);
          }
        }
        // Dust skirt boiling at the contact point.
        const cg = cxAt(gyv, t), skirtW = Math.max(3, W * 0.12);
        for (let y = gyv - 2; y < Math.min(H, gyv + 3); y++) {
          const row = y * W;
          const x0 = Math.max(0, Math.floor(cg - skirtW)), x1 = Math.min(W - 1, Math.ceil(cg + skirtW));
          for (let x = x0; x <= x1; x++) {
            const k = Math.max(0, 1 - Math.abs(x - cg) / skirtW);
            const d = Math.max(0, noise.noise2(x * 0.3 - t * 2.4, y * 0.5 + t * 0.8)) * k;
            if (d > 0.04) px[row + x] = mix(px[row + x], dustC, Math.min(0.85, d * 1.8));
          }
        }
        // Debris rides the vortex upward, then recycles into the skirt.
        for (const d of deb) {
          d.a += d.v * dt;
          d.y -= (1.6 + d.v * 0.25) * dt * (H / 24);
          if (d.y < ch + 1) { d.y = gyv - rand() * 2; d.a = rand() * TAU; d.v = 5 + rand() * 4; }
          const w = wAt(d.y, t);
          const x = cxAt(d.y, t) + Math.cos(d.a) * w * (0.9 + d.r * 0.4);
          const xi = x | 0, yi = d.y | 0;
          if (xi >= 0 && xi < W && yi >= 0 && yi < H) {
            const front = Math.sin(d.a) > 0;
            px[yi * W + xi] = mix(px[yi * W + xi], front ? 0x8a7a5a : 0x2a241a, front ? 0.9 : 0.6);
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'sim-hailstorm',
    since: '0.3.0',
    title: 'Hailstorm',
    gallery: 'sim',
    category: 'Weather',
    kind: 'scene',
    tags: ['hail', 'bounce', 'ice', 'storm', 'weather', 'physics'],
    order: 230,
    description: 'Hailstones streak down, bounce two or three times with real restitution, and pile into a rattling white crust over the paddock.',
    size: { w: 72, h: 22 },
    minSize: { w: 24, h: 8 },
    loop: 22,
    canvas: 'field',
    palette: 'ice',
    setup(ctx) {
      const cv = ctx.canvas();
      const W = cv.width, H = cv.height, px = cv.px;
      const th = ctx.theme, rand = ctx.rng, noise = ctx.noise;
      const base = Math.round(H * 0.8);
      const gy = new Float32Array(W);
      for (let x = 0; x < W; x++) {
        let g = base + Math.sin(x * 0.1) * 0.8;
        // Two low bushes the crust will bury.
        for (const [bx, bw, bh] of [[W * 0.22, W * 0.07, H * 0.1], [W * 0.68, W * 0.09, H * 0.13]]) {
          const d = Math.abs(x - bx) / bw;
          if (d < 1) g -= bh * Math.sqrt(1 - d * d);
        }
        gy[x] = g;
      }
      const accum = new Float32Array(W);
      const skyHi = mix(th.bg, 0x27332f, 0.6), skyLo = mix(th.bg, 0x47545a, 0.5);
      const fieldC = mix(th.bg, 0x1d2a14, 0.6);
      const bushC = mix(th.bg, 0x0f1a0a, 0.7);
      const iceA = 0xeef5ff, iceB = mix(th.bg, 0x9fb8cc, 0.4);
      const stoneC = 0xe8f2ff, streakC = mix(th.info, 0xdce9ff, 0.6);
      const N = clamp(Math.round((ctx.width * ctx.height) / 34), 22, 110);
      const SX = new Float32Array(N), SY = new Float32Array(N), VX = new Float32Array(N), VY = new Float32Array(N);
      const SR = new Float32Array(N), SB = new Uint8Array(N);
      const reset = (i, top) => {
        SX[i] = rand() * W; SY[i] = top ? -rand() * H * 0.4 : rand() * H * 0.5;
        SR[i] = rand() < 0.08 ? 2 : 1; SB[i] = 0;
        VY[i] = H * (0.9 + rand() * 0.5); VX[i] = H * (0.08 + rand() * 0.12);
      };
      for (let i = 0; i < N; i++) reset(i, false);
      const hits = [];
      const G = H * 2;

      return (t, dt) => {
        dt = clamp(dt, 0, 0.1);
        const wind = 0.5 + 0.5 * noise.noise2(t * 0.4, 3.3);
        // Sky with fast scud.
        for (let y = 0; y < H; y++) {
          const row = y * W, ky = y / Math.max(1, H - 1);
          if (y < H * 0.3) {
            for (let x = 0; x < W; x++) {
              const d = noise.fbm(x * 0.05 - t * (0.8 + wind), y * 0.25, 0, 2) + 0.2;
              px[row + x] = mix(mix(skyHi, skyLo, ky * 2), mix(th.bg, 0x121a18, 0.7), clamp(d * 1.3, 0, 1));
            }
          } else {
            const c = mix(skyHi, skyLo, ky);
            for (let x = 0; x < W; x++) px[row + x] = c;
          }
        }
        // Ground, bushes and the hail crust.
        for (let x = 0; x < W; x++) {
          const g = gy[x], surf = g - accum[x];
          for (let y = Math.max(0, surf | 0); y < H; y++) {
            const i = y * W + x;
            if (y < g) px[i] = (x * 31 + y * 17) % 7 < 2 ? iceB : iceA;
            else px[i] = g < base - 1 ? bushC : (x * 13 + y * 11) % 9 < 2 ? mix(fieldC, 0x0c1408, 0.5) : fieldC;
          }
        }
        // Light slump keeps the crust natural.
        for (let x = 1; x < W - 1; x++) {
          const h0 = gy[x] - accum[x], h1 = gy[x + 1] - accum[x + 1];
          if (h1 - h0 > 1.7 && accum[x] > 0.3) { accum[x] -= 0.1; accum[x + 1] += 0.1; }
          else if (h0 - h1 > 1.7 && accum[x + 1] > 0.3) { accum[x + 1] -= 0.1; accum[x] += 0.1; }
        }
        // Stones: gravity, restitution, then they join the crust.
        for (let i = 0; i < N; i++) {
          VY[i] += G * dt;
          SX[i] += (VX[i] * wind) * dt; SY[i] += VY[i] * dt;
          if (SX[i] < 0) SX[i] += W; else if (SX[i] >= W) SX[i] -= W;
          const xi = clamp(SX[i] | 0, 0, W - 1);
          const surf = gy[xi] - accum[xi];
          if (SY[i] >= surf) {
            const maxB = SR[i] > 1 ? 3 : 2;
            if (SB[i] < maxB && VY[i] > H * 0.3) {
              VY[i] = -VY[i] * (0.42 + rand() * 0.12);
              VX[i] += (rand() - 0.5) * H * 0.3;
              SY[i] = surf - 0.01; SB[i]++;
              if (hits.length < 40) hits.push({ x: SX[i], y: surf - 1, life: 0.14 });
            } else {
              accum[xi] = Math.min(accum[xi] + SR[i] * 0.55, H * 0.25);
              reset(i, true);
            }
            continue;
          }
          if (SY[i] > H + 2) { reset(i, true); continue; }
          // Streak, then the stone itself.
          const sx = SX[i], sy = SY[i];
          for (let k = 1; k <= 2; k++) {
            const x = (sx - VX[i] * wind * dt * k * 2) | 0, y = (sy - VY[i] * dt * k * 2) | 0;
            if (x >= 0 && x < W && y >= 0 && y < H) px[y * W + x] = mix(px[y * W + x], streakC, 0.45);
          }
          const r = SR[i] | 0;
          for (let dy2 = 0; dy2 < r; dy2++) for (let dx2 = 0; dx2 < r; dx2++) {
            const x = (sx | 0) + dx2, y = (sy | 0) + dy2;
            if (x >= 0 && x < W && y >= 0 && y < H) px[y * W + x] = stoneC;
          }
        }
        for (let i = hits.length - 1; i >= 0; i--) {
          const s = hits[i];
          s.life -= dt;
          if (s.life <= 0) { hits.splice(i, 1); continue; }
          const xi = s.x | 0, yi = s.y | 0;
          for (const [ox, oy] of [[0, 0], [1, -1], [-1, -1]]) {
            const x = xi + ox, y = yi + oy;
            if (x >= 0 && x < W && y >= 0 && y < H) px[y * W + x] = mix(px[y * W + x], 0xffffff, s.life * 5);
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

sources.prism-term/src/facets/sim/string-waves.j:
// A six-string harp played in an arpeggio. Each string is a real 1-D wave
// equation (finite differences, fixed ends, light damping and a touch of
// stiffness) plucked into a triangle and left to ring, so you see the kink
// split into two traveling waves, reflect off the bridges and settle into
// the fundamental. Lower strings swing slower and wider; ringing strings glow,
// and a dotted envelope traces each string's recent swing — the blur your eye
// sees on a real vibrating string, which single frames would otherwise miss.
import { mix } from '../../color.js';
import { fadeMark } from '../../palettes.js';

const STRINGS = 6, N = 72, HZ = 900;
const PLUCK = 0.5; // seconds between plucks
const PATTERN = [0, 2, 4, 5, 3, 1, 2, 4, 3, 5, 1, 0];

export default {
  title: 'Plucked Strings',
  gallery: 'sim',
  category: 'Physics',
  kind: 'scene',
  tags: ['wave equation', 'strings', 'harp', 'standing waves', 'pluck', 'braille'],
  order: 40,
  description: 'A six-string harp plucked in an arpeggio: real wave-equation strings that split, reflect and ring down.',
  size: { w: 60, h: 20 },
  minSize: { w: 20, h: 7 },
  loop: PATTERN.length * PLUCK,
  canvas: 'line',
  palette: 'prism',
  params: {},
  setup(ctx) {
    const cv = ctx.canvas('line');
    const W = cv.width, H = cv.height, th = ctx.theme;
    const pal = ctx.palette();
    // Wave speed per string (Courant number ≤ 1), lowest string first.
    const c = Array.from({ length: STRINGS }, (_, k) => 0.42 + k * 0.11);
    const y = Array.from({ length: STRINGS }, () => new Float32Array(N));
    const yp = Array.from({ length: STRINGS }, () => new Float32Array(N));
    const yn = new Float32Array(N);
    const energy = new Float32Array(STRINGS);
    const env = Array.from({ length: STRINGS }, () => new Float32Array(N));
    const cols = Array.from({ length: STRINGS }, (_, k) => pal(k / STRINGS));
    const x0 = Math.max(2, W * 0.06), x1 = W - 1 - Math.max(2, W * 0.06);
    const gap = H / STRINGS;
    let acc = 0, plucked = -1;
    const pluck = (k, at, amp) => {
      const p = Math.round(N * at);
      for (let i = 0; i < N; i++) y[k][i] = yp[k][i] = i <= p ? (amp * i) / p : (amp * (N - 1 - i)) / (N - 1 - p);
    };
    const step = () => {
      for (let k = 0; k < STRINGS; k++) {
        const Y = y[k], P = yp[k], c2 = c[k] * c[k];
        let e = 0;
        for (let i = 1; i < N - 1; i++) {
          const lap = Y[i - 1] - 2 * Y[i] + Y[i + 1];
          const stiff = i > 1 && i < N - 2 ? Y[i - 2] - 4 * Y[i - 1] + 6 * Y[i] - 4 * Y[i + 1] + Y[i + 2] : 0;
          yn[i] = (2 * Y[i] - P[i] * 0.9993 + c2 * lap - 0.004 * stiff) / 1.0007;
          e += Math.abs(yn[i]);
        }
        yn[0] = yn[N - 1] = 0;
        P.set(Y); Y.set(yn);
        const E = env[k];
        for (let i = 0; i < N; i++) { const a = yn[i] < 0 ? -yn[i] : yn[i]; E[i] = a > E[i] ? a : E[i] * 0.9988; }
        energy[k] = e / N;
      }
    };

    return (t, dt) => {
      const n = Math.floor(t / PLUCK);
      if (n !== plucked) {
        plucked = n;
        const k = PATTERN[((n % PATTERN.length) + PATTERN.length) % PATTERN.length];
        pluck(k, 0.18 + (n % 3) * 0.07, 1 - k * 0.05);
      }
      acc += Math.min(0.25, Math.max(0, dt)) * HZ;
      for (let s = 0; acc >= 1 && s < 240; s++, acc--) step();
      if (acc > 240) acc = 0;
      cv.clear();
      for (let k = 0; k < STRINGS; k++) {
        const base = gap * (k + 0.5), amp = gap * 0.9;
        const glow = Math.min(1, energy[k] * 4);
        const col = mix(mix(th.bg, th.muted, 0.85), cols[k], glow);
        const haze = fadeMark(th, cols[k], 0.25 + 0.45 * glow);
        const Y = y[k], E = env[k];
        let px = x0, py = base;
        for (let s = 1; s <= Math.ceil(x1 - x0); s++) {
          const f = s / (x1 - x0), u = f * (N - 1), i = Math.min(N - 2, Math.floor(u)), fr = u - i;
          const v = Y[i] * (1 - fr) + Y[i + 1] * fr;
          const nx = x0 + s, ny = base + v * amp;
          // Envelope edges, every other pixel so they read as a blur, not a second string.
          const e = (E[i] * (1 - fr) + E[i + 1] * fr) * amp;
          if (e > 1.2 && (s & 1) === 0) { cv.set(nx, base - e, haze); cv.set(nx, base + e, haze); }
          cv.line(px, py, nx, ny, col);
          px = nx; py = ny;
        }
        // Pegs and bridge pins.
        cv.set(x0 - 1, base, th.ink); cv.set(x0 - 2, base, th.ink);
        cv.set(x1 + 1, base, th.ink);
      }
      cv.paint(ctx.buffer);
    };
  },
};

sources.prism-term/src/facets/sim/swarm-minds.js:
// Swarm minds — collective behaviour where simple local rules add up to one
// moving shape: a fish school wrapping around a hunting shark, a starling
// murmuration smeared into a living density cloud, fireflies pulse-coupling
// into synchrony, and an ant colony condensing pheromone highways.
import { NONE, mix } from '../../color.js';

const TAU = Math.PI * 2;
const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);

export default [
  {
    id: 'sim-fish-school',
    since: '0.3.0',
    title: 'Fish School',
    gallery: 'sim',
    category: 'Life & Flocking',
    kind: 'scene',
    tags: ['fish', 'school', 'shark', 'predator', 'flocking', 'ocean', 'boids'],
    order: 200,
    description: 'A silver school schooling tight through god rays, scattering in a flash-expansion each time the patrolling shark lunges.',
    size: { w: 80, h: 24 },
    minSize: { w: 24, h: 8 },
    loop: 24,
    canvas: 'line',
    palette: 'ocean',
    credits: 'after Reynolds (1987)',
    params: { speed: { default: 1, min: 0.3, max: 2.5, label: 'Speed' } },
    setup(ctx) {
      const water = ctx.canvas('field');
      const view = ctx.canvas('line');
      const W = view.width, H = view.height;
      const FW = water.width, FH = water.height, fpx = water.px;
      const th = ctx.theme, rand = ctx.rng, noise = ctx.noise, pal = ctx.palette();
      const speedK = ctx.param('speed', 1);
      const S = Math.max(8, Math.min(W, H));
      const N = clamp(Math.round((ctx.width * ctx.height) / 16), 24, 190);
      const X = new Float32Array(N), Y = new Float32Array(N), VX = new Float32Array(N), VY = new Float32Array(N), FEAR = new Float32Array(N);
      const a0 = rand() * TAU;
      for (let i = 0; i < N; i++) {
        X[i] = W * (0.25 + rand() * 0.3); Y[i] = H * (0.3 + rand() * 0.4);
        const a = a0 + (rand() - 0.5) * 0.9;
        VX[i] = Math.cos(a); VY[i] = Math.sin(a);
      }
      const cruise = S * 0.17 * speedK, burst = cruise * 2.7;
      const rN = S * 0.1, rS = rN * 0.42, rP = S * 0.34, margin = S * 0.09;
      // Spatial hash: neighbour queries stay O(N) even at full tile size.
      const cs = Math.max(2, rN), gw = Math.max(1, Math.ceil(W / cs)), gh = Math.max(1, Math.ceil(H / cs));
      const head = new Int32Array(gw * gh), next = new Int32Array(N);
      const shark = { x: -S * 0.2, y: H * 0.5, vx: cruise * 0.7, vy: 0, mode: 0 };
      let lungeAt = 4 + rand() * 3, lungeEnd = 0;
      const bubbles = Array.from({ length: Math.max(5, Math.round(FW / 16)) }, () => ({ x: rand() * FW, y: rand() * FH, s: 0.5 + rand() * 0.9, ph: rand() * TAU }));
      const colShaft = new Float32Array(Math.max(1, FW));
      const deepTop = mix(th.bg, 0x08365e, 0.55), deepBot = mix(th.bg, 0x02101f, 0.72);
      const shaftC = mix(th.info, 0xbfe9ff, 0.55);
      const sharkC = mix(th.ink, th.bg, 0.45);
      const size = view.mode === 'braille' ? 2.6 : 1.4;

      return (t, dt) => {
        dt = clamp(dt, 0, 0.1);
        // Water: depth gradient, slanted light shafts, rising bubbles.
        for (let x = 0; x < FW; x++) {
          const a = noise.noise2(x * 0.05 + t * 0.3, 1.7), b = noise.noise2(x * 0.012 + t * 0.05, 8.2);
          colShaft[x] = Math.max(0, a) * Math.max(0, b) * 1.6;
        }
        for (let y = 0; y < FH; y++) {
          const ky = y / Math.max(1, FH - 1), base = mix(deepTop, deepBot, ky);
          const row = y * FW, slant = Math.round(y * 0.45), fade = (1 - ky) * (1 - ky);
          for (let x = 0; x < FW; x++) {
            const s = colShaft[(x + slant) % FW] * fade;
            fpx[row + x] = s > 0.03 ? mix(base, shaftC, Math.min(0.42, s)) : base;
          }
        }
        for (const b of bubbles) {
          b.y -= (2.5 + b.s * 3) * dt * (FH / 24);
          b.x += Math.sin(t * 1.7 + b.ph) * dt * 2;
          if (b.y < 0) { b.y = FH - 1; b.x = rand() * FW; }
          const xi = b.x | 0, yi = b.y | 0;
          if (xi >= 0 && xi < FW && yi >= 0 && yi < FH) fpx[yi * FW + xi] = mix(fpx[yi * FW + xi], 0xcfe9ff, 0.45);
        }
        water.paint(ctx.buffer);

        // Shark: patrol an easy loop, then lunge at the school's centroid.
        let mx = 0, my = 0;
        for (let i = 0; i < N; i++) { mx += X[i]; my += Y[i]; }
        mx /= N; my /= N;
        if (shark.mode === 0 && t >= lungeAt) { shark.mode = 1; lungeEnd = t + 1.5; }
        if (shark.mode === 1 && t > lungeEnd) { shark.mode = 0; lungeAt = t + 4 + rand() * 4; }
        const tx = shark.mode ? mx : W * 0.5 + Math.cos(t * 0.21) * W * 0.4;
        const ty = shark.mode ? my : H * 0.5 + Math.sin(t * 0.13) * H * 0.32;
        const acc = shark.mode ? S * 1.5 : S * 0.3;
        const dd = Math.hypot(tx - shark.x, ty - shark.y) || 1;
        shark.vx += ((tx - shark.x) / dd) * acc * dt; shark.vy += ((ty - shark.y) / dd) * acc * dt;
        const sv = Math.hypot(shark.vx, shark.vy) || 1, smax = shark.mode ? cruise * 2.3 : cruise * 0.75;
        if (sv > smax) { shark.vx *= smax / sv; shark.vy *= smax / sv; }
        shark.x += shark.vx * dt; shark.y += shark.vy * dt;
        shark.x = clamp(shark.x, -S * 0.2, W + S * 0.2); shark.y = clamp(shark.y, 1, H - 2);

        // School: hashed neighbourhood, flash-expansion fear response.
        head.fill(-1);
        for (let i = 0; i < N; i++) {
          const gi = clamp((Y[i] / cs) | 0, 0, gh - 1) * gw + clamp((X[i] / cs) | 0, 0, gw - 1);
          next[i] = head[gi]; head[gi] = i;
        }
        for (let i = 0; i < N; i++) {
          const xi = X[i], yi = Y[i];
          let ax = 0, ay = 0, cx = 0, cy = 0, sx = 0, sy = 0, n = 0;
          const gx = clamp((xi / cs) | 0, 0, gw - 1), gy = clamp((yi / cs) | 0, 0, gh - 1);
          for (let oy = -1; oy <= 1; oy++) for (let ox = -1; ox <= 1; ox++) {
            const cxg = gx + ox, cyg = gy + oy;
            if (cxg < 0 || cyg < 0 || cxg >= gw || cyg >= gh) continue;
            for (let j = head[cyg * gw + cxg]; j !== -1; j = next[j]) {
              if (j === i) continue;
              const dx = X[j] - xi, dy = Y[j] - yi, d2 = dx * dx + dy * dy;
              if (d2 > rN * rN) continue;
              n++; ax += VX[j]; ay += VY[j]; cx += X[j]; cy += Y[j];
              if (d2 < rS * rS) { const d = Math.sqrt(d2) || 0.01; sx -= dx / d * (rS - d); sy -= dy / d * (rS - d); }
            }
          }
          let vx = VX[i], vy = VY[i];
          if (n) {
            vx += (ax / n - vx) * 1.6 * dt; vy += (ay / n - vy) * 1.6 * dt;
            vx += (cx / n - xi) * 1.1 * dt; vy += (cy / n - yi) * 1.1 * dt;
          }
          vx += sx * 7 * dt; vy += sy * 7 * dt;
          const pdx = xi - shark.x, pdy = yi - shark.y, pd = Math.hypot(pdx, pdy);
          if (pd < rP) {
            const k = 1 - pd / rP;
            FEAR[i] = Math.max(FEAR[i], k);
            vx += (pdx / (pd || 1)) * burst * 4.5 * k * dt; vy += (pdy / (pd || 1)) * burst * 4.5 * k * dt;
          }
          FEAR[i] *= Math.exp(-dt * 1.3);
          if (xi < margin) vx += cruise * 3 * dt; else if (xi > W - margin) vx -= cruise * 3 * dt;
          if (yi < margin) vy += cruise * 3 * dt; else if (yi > H - margin) vy -= cruise * 3 * dt;
          const want = cruise * (1 + 1.8 * FEAR[i]);
          const v = Math.hypot(vx, vy) || 1;
          const cl = v > want ? want / v : v < cruise * 0.55 ? (cruise * 0.55) / v : 1;
          VX[i] = vx * cl; VY[i] = vy * cl;
        }

        view.clear();
        for (let i = 0; i < N; i++) {
          X[i] = clamp(X[i] + VX[i] * dt, 0, W - 0.5); Y[i] = clamp(Y[i] + VY[i] * dt, 0, H - 0.5);
          const v = Math.hypot(VX[i], VY[i]) || 1, dx = VX[i] / v, dy = VY[i] / v;
          const len = size * (1 + 0.5 * FEAR[i]);
          const depth = clamp(Y[i] / Math.max(1, H), 0, 1);
          const c = mix(pal(0.45 + 0.3 * (1 - depth)), th.ink, clamp(FEAR[i] * 0.9, 0, 0.8));
          view.line(X[i] - dx * len, Y[i] - dy * len, X[i], Y[i], c);
        }
        // Shark: a long-nosed body polygon with a tail fin.
        const sv2 = Math.hypot(shark.vx, shark.vy) || 1, sdx = shark.vx / sv2, sdy = shark.vy / sv2;
        const sl = size * 3.4, px0 = shark.x, py0 = shark.y;
        const c = mix(sharkC, th.neg, shark.mode ? 0.35 : 0.08);
        view.polygon([
          [px0 + sdx * sl, py0 + sdy * sl],
          [px0 - sdx * sl * 0.5 - sdy * sl * 0.45, py0 - sdy * sl * 0.5 + sdx * sl * 0.45],
          [px0 - sdx * sl * 0.9, py0 - sdy * sl * 0.9],
          [px0 - sdx * sl * 0.5 + sdy * sl * 0.45, py0 - sdy * sl * 0.5 - sdx * sl * 0.45],
        ], c);
        view.line(px0 - sdx * sl * 0.9 - sdy * sl * 0.5, py0 - sdy * sl * 0.9 + sdx * sl * 0.5, px0 - sdx * sl * 0.9 + sdy * sl * 0.5, py0 - sdy * sl * 0.9 - sdx * sl * 0.5, c);
        view.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'sim-murmuration',
    since: '0.3.0',
    title: 'Murmuration',
    gallery: 'sim',
    category: 'Life & Flocking',
    kind: 'scene',
    tags: ['starlings', 'murmuration', 'flock', 'density', 'dusk', 'birds'],
    order: 210,
    description: 'Hundreds of starlings render as a breathing density cloud that folds and ribbons over a dusk horizon with bare trees.',
    size: { w: 80, h: 24 },
    minSize: { w: 24, h: 8 },
    loop: 24,
    canvas: 'field',
    palette: 'sunset',
    credits: 'after Reynolds (1987)',
    setup(ctx) {
      const cv = ctx.canvas();
      const W = cv.width, H = cv.height, px = cv.px;
      const th = ctx.theme, rand = ctx.rng, noise = ctx.noise, pal = ctx.palette();
      const N = clamp(Math.round((ctx.width * ctx.height) / 8), 80, 420);
      const X = new Float32Array(N), Y = new Float32Array(N), VX = new Float32Array(N), VY = new Float32Array(N);
      const S = Math.max(8, Math.min(W, H));
      for (let i = 0; i < N; i++) {
        X[i] = W * (0.4 + rand() * 0.2); Y[i] = H * (0.3 + rand() * 0.25);
        const a = rand() * TAU; VX[i] = Math.cos(a) * S * 0.3; VY[i] = Math.sin(a) * S * 0.3;
      }
      let D = new Float32Array(W * H), tmp = new Float32Array(W * H);
      // Ground silhouette with two bare trees plotted into a static mask.
      const gy = new Float32Array(W);
      for (let x = 0; x < W; x++) gy[x] = H * (0.85 + 0.04 * noise.noise2(x * 0.03, 4.4));
      const mask = new Uint8Array(W * H);
      const plot = (x0, y0, x1, y1) => {
        const n = Math.max(1, Math.ceil(Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0))));
        for (let k = 0; k <= n; k++) {
          const x = Math.round(x0 + (x1 - x0) * (k / n)), y = Math.round(y0 + (y1 - y0) * (k / n));
          if (x >= 0 && x < W && y >= 0 && y < H) mask[y * W + x] = 1;
        }
      };
      const tree = (bx, scale) => {
        const base = gy[clamp(bx | 0, 0, W - 1)];
        const grow = (x, y, ang, len, depth) => {
          const nx = x + Math.cos(ang) * len, ny = y - Math.sin(ang) * len;
          plot(x, y, nx, ny);
          if (depth <= 0 || len < 1.2) return;
          grow(nx, ny, ang + 0.35 + rand() * 0.3, len * 0.66, depth - 1);
          grow(nx, ny, ang - 0.35 - rand() * 0.3, len * 0.66, depth - 1);
        };
        grow(bx, base, Math.PI / 2, H * 0.16 * scale, 4);
      };
      tree(W * 0.78, 1); tree(W * 0.15, 0.6);
      const birdC = mix(th.ink, 0x05070d, 0.78);
      const silC = mix(birdC, 0x000000, 0.25);
      const vmin = S * 0.22, vmax = S * 0.52;

      return (t, dt) => {
        dt = clamp(dt, 0, 0.1);
        // The roost target loops the sky; attraction breathes so the cloud
        // contracts to a knot and shakes back out into ribbons.
        const Tx = W * (0.5 + 0.3 * Math.sin(t * 0.37) + 0.1 * noise.noise2(t * 0.11, 3.3));
        const Ty = H * (0.38 + 0.2 * Math.sin(t * 0.53 + 1.3) + 0.1 * noise.noise2(t * 0.13, 7.7));
        const breath = 0.5 + 0.45 * Math.sin(t * 0.52 + noise.noise2(t * 0.07, 5.5) * 2);
        for (let i = 0; i < D.length; i++) D[i] *= 0.8;
        for (let i = 0; i < N; i++) {
          const ang = noise.noise3(X[i] * 0.016, Y[i] * 0.03, t * 0.12) * 2.8;
          VX[i] += Math.cos(ang) * S * 0.9 * dt + (Tx - X[i]) * (0.35 + breath) * dt;
          VY[i] += Math.sin(ang) * S * 0.9 * dt + (Ty - Y[i]) * (0.35 + breath) * dt;
          // Tangential slip makes the cloud orbit instead of collapsing.
          VX[i] += (Ty - Y[i]) * 0.5 * dt; VY[i] -= (Tx - X[i]) * 0.5 * dt;
          const v = Math.hypot(VX[i], VY[i]) || 1;
          const cl = v > vmax ? vmax / v : v < vmin ? vmin / v : 1;
          VX[i] *= cl; VY[i] *= cl;
          X[i] += VX[i] * dt; Y[i] += VY[i] * dt;
          if (X[i] < 1) { X[i] = 1; VX[i] = Math.abs(VX[i]); } else if (X[i] > W - 2) { X[i] = W - 2; VX[i] = -Math.abs(VX[i]); }
          const floor = gy[clamp(X[i] | 0, 0, W - 1)] - 2;
          if (Y[i] < 1) { Y[i] = 1; VY[i] = Math.abs(VY[i]); } else if (Y[i] > floor) { Y[i] = floor; VY[i] = -Math.abs(VY[i]); }
          D[(Y[i] | 0) * W + (X[i] | 0)] += 1;
        }
        // One separable 1-2-1 blur softens dots into a murmuration smear.
        for (let y = 0; y < H; y++) {
          const r = y * W;
          for (let x = 0; x < W; x++) {
            const a = D[r + Math.max(0, x - 1)], b = D[r + x], cc = D[r + Math.min(W - 1, x + 1)];
            tmp[r + x] = a * 0.25 + b * 0.5 + cc * 0.25;
          }
        }
        for (let y = 0; y < H; y++) {
          const up = Math.max(0, y - 1) * W, dn = Math.min(H - 1, y + 1) * W, r = y * W;
          for (let x = 0; x < W; x++) D[r + x] = tmp[up + x] * 0.25 + tmp[r + x] * 0.5 + tmp[dn + x] * 0.25;
        }
        const sunX = W * 0.3, sunY = H * 0.68, sunR = Math.max(2, S * 0.14);
        for (let y = 0; y < H; y++) {
          const ky = y / Math.max(1, H - 1);
          const row = mix(pal(0.08 + 0.05 * Math.sin(t * 0.04)), pal(0.8), Math.pow(ky, 1.4));
          for (let x = 0; x < W; x++) {
            const i = y * W + x;
            let c = row;
            const sd = Math.hypot(x - sunX, (y - sunY) * 1.6) / sunR;
            if (sd < 2.2) c = mix(c, 0xffd9a0, Math.max(0, 1 - sd * 0.45));
            const d = D[i];
            if (d > 0.04) c = mix(c, birdC, Math.min(0.94, d * 0.5));
            if (y > gy[x] || mask[i]) c = silC;
            px[i] = c;
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'sim-fireflies',
    since: '0.3.0',
    title: 'Fireflies in Sync',
    gallery: 'sim',
    category: 'Life & Flocking',
    kind: 'scene',
    tags: ['fireflies', 'synchronization', 'kuramoto', 'meadow', 'night', 'emergence'],
    order: 220,
    description: 'Pulse-coupled fireflies drift over a night meadow, nudging neighbours each flash until the whole field blinks as one.',
    size: { w: 72, h: 22 },
    minSize: { w: 24, h: 8 },
    loop: 30,
    canvas: 'field',
    palette: 'toxic',
    credits: 'after Mirollo & Strogatz (1990)',
    params: { coupling: { default: 1, min: 0, max: 3, label: 'Coupling' } },
    setup(ctx) {
      const cv = ctx.canvas();
      const W = cv.width, H = cv.height, px = cv.px;
      const th = ctx.theme, rand = ctx.rng, noise = ctx.noise;
      const eps = 0.04 * ctx.param('coupling', 1);
      const S = Math.max(8, Math.min(W, H));
      const N = clamp(Math.round((ctx.width * ctx.height) / 24), 26, 130);
      const X = new Float32Array(N), Y = new Float32Array(N), PH = new Float32Array(N), FR = new Float32Array(N), GL = new Float32Array(N), SD = new Float32Array(N);
      const grass = new Float32Array(W), blade = new Float32Array(W);
      for (let x = 0; x < W; x++) {
        grass[x] = H * (0.72 + 0.05 * noise.noise2(x * 0.06, 2.2));
        blade[x] = rand() < 0.5 ? rand() * H * 0.1 : 0;
      }
      for (let i = 0; i < N; i++) {
        X[i] = 2 + rand() * (W - 4);
        Y[i] = H * 0.2 + rand() * (grass[clamp(X[i] | 0, 0, W - 1)] - H * 0.2 - 2);
        PH[i] = rand(); FR[i] = 0.42 + rand() * 0.12; SD[i] = rand() * 100;
      }
      const R2 = Math.pow(S * 0.38, 2);
      const stars = Array.from({ length: Math.max(4, W >> 3) }, () => ({ x: (rand() * W) | 0, y: (rand() * H * 0.4) | 0, ph: rand() * TAU }));
      const skyTop = mix(th.bg, 0x060b22, 0.6), skyHor = mix(th.bg, 0x14253a, 0.55);
      const grassC = mix(0x07130a, th.bg, 0.2), bladeC = mix(0x0d2412, th.bg, 0.15);
      const glowC = mix(th.warn, 0xd9ff7a, 0.55), coreC = 0xfaffd8;
      const flashed = new Int32Array(N);

      return (t, dt) => {
        dt = clamp(dt, 0, 0.1);
        let nf = 0;
        for (let i = 0; i < N; i++) {
          PH[i] += FR[i] * dt;
          if (PH[i] >= 1) { PH[i] -= 1; GL[i] = 1; flashed[nf++] = i; }
          GL[i] *= Math.exp(-3.6 * dt);
          // A lazy wander: drift along a personal noise path above the grass.
          X[i] += noise.noise2(t * 0.3, SD[i]) * S * 0.25 * dt;
          Y[i] += noise.noise2(t * 0.27, SD[i] + 40) * S * 0.18 * dt;
          X[i] = clamp(X[i], 1, W - 2);
          Y[i] = clamp(Y[i], H * 0.12, grass[clamp(X[i] | 0, 0, W - 1)] + Math.min(4, H * 0.08));
        }
        // Each flash nudges every neighbour's clock forward (Mirollo-Strogatz).
        for (let k = 0; k < nf; k++) {
          const f = flashed[k];
          for (let j = 0; j < N; j++) {
            if (j === f || GL[j] > 0.6) continue;
            const dx = X[j] - X[f], dy = Y[j] - Y[f];
            if (dx * dx + dy * dy < R2) PH[j] = Math.min(1, PH[j] + eps * (0.4 + PH[j]));
          }
        }
        // Night meadow backdrop.
        for (let y = 0; y < H; y++) {
          const row = y * W, sky = mix(skyTop, skyHor, Math.pow(y / Math.max(1, H - 1), 1.6));
          for (let x = 0; x < W; x++) {
            const g = grass[x];
            px[row + x] = y > g ? grassC : y > g - blade[x] && ((x * 7 + y * 3) % 5 < 2) ? bladeC : sky;
          }
        }
        for (const s of stars) {
          const k = 0.25 + 0.3 * Math.max(0, Math.sin(t * 0.9 + s.ph));
          if (s.y < H && s.x < W) px[s.y * W + s.x] = mix(px[s.y * W + s.x], 0xcfd8ff, k);
        }
        for (let i = 0; i < N; i++) {
          const xi = X[i] | 0, yi = Y[i] | 0, g = GL[i];
          if (g > 0.04) {
            for (let dy = -1; dy <= 1; dy++) for (let dx = -2; dx <= 2; dx++) {
              const x = xi + dx, y = yi + dy;
              if (x < 0 || y < 0 || x >= W || y >= H) continue;
              const k = g * Math.max(0, 1 - (dx * dx + dy * dy * 4) / 6);
              if (k > 0.02) px[y * W + x] = mix(px[y * W + x], glowC, Math.min(0.95, k));
            }
            px[yi * W + xi] = mix(glowC, coreC, g * 0.7);
          } else if (xi >= 0 && xi < W && yi >= 0 && yi < H) {
            px[yi * W + xi] = mix(px[yi * W + xi], th.muted, 0.22);
          }
        }
        cv.paint(ctx.buffer);
      };
    },
  },

  {
    id: 'sim-ant-trails',
    since: '0.3.0',
    title: 'Ant Trails',
    gallery: 'sim',
    category: 'Life & Flocking',
    kind: 'scene',
    tags: ['ants', 'pheromone', 'stigmergy', 'colony', 'trails', 'emergence', 'foraging'],
    order: 230,
    description: 'Foragers wander from the nest, and carriers lay pheromone home — trails condense to golden highways and dissolve as piles empty.',
    size: { w: 64, h: 22 },
    minSize: { w: 22, h: 8 },
    loop: 30,
    canvas: 'field',
    palette: 'gold',
    credits: 'after Deneubourg’s double-bridge experiments',
    setup(ctx) {
      const cv = ctx.canvas();
      const W = cv.width, H = cv.height, px = cv.px;
      const th = ctx.theme, rand = ctx.rng, noise = ctx.noise;
      const nest = { x: Math.max(2, W * 0.16), y: H * 0.6 };
      const foods = Array.from({ length: 3 }, (_, k) => ({
        x: W * (0.5 + 0.44 * rand()), y: 3 + rand() * (H - 6), amt: 1, hue: k,
      }));
      let pher = new Float32Array(W * H), tmp = new Float32Array(W * H);
      const N = clamp(Math.round((W * H) / 48), 44, 300);
      const AX = new Float32Array(N), AY = new Float32Array(N), AA = new Float32Array(N), AS = new Uint8Array(N);
      for (let i = 0; i < N; i++) { AX[i] = nest.x; AY[i] = nest.y; AA[i] = rand() * TAU; }
      const soil = new Int32Array(W * H);
      const soilBase = mix(th.bg, 0x241509, 0.45);
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++)
        soil[y * W + x] = mix(soilBase, 0x3a2a16, 0.25 + 0.3 * noise.noise2(x * 0.2, y * 0.33));
      const trailC = mix(th.warn, 0xffd75e, 0.5);
      const antC = mix(th.ink, soilBase, 0.3), carryC = mix(th.pos, 0xbfff9a, 0.4);
      const foodC = mix(th.pos, 0x3f8f2a, 0.35);
      const speed = Math.max(4, Math.min(W, H)) * 0.42;
      const senseAt = (x, y) => {
        if (x < 0 || y < 0 || x >= W || y >= H) return -2;
        let v = pher[(y | 0) * W + (x | 0)];
        for (const f of foods) {
          const d = Math.hypot(x - f.x, y - f.y);
          const r = 1.5 + f.amt * 2.5;
          if (d < r + 5) v += (1 - d / (r + 5)) * 9 * f.amt;
        }
        return v;
      };

      return (t, dt) => {
        dt = clamp(dt, 0, 0.1);
        const step = speed * dt;
        for (let i = 0; i < N; i++) {
          let a = AA[i];
          const x = AX[i], y = AY[i];
          if (AS[i] === 0) {
            // Searcher: three pheromone sensors plus jitter.
            const d = 3.5;
            const c = senseAt(x + Math.cos(a) * d, y + Math.sin(a) * d);
            const l = senseAt(x + Math.cos(a - 0.65) * d, y + Math.sin(a - 0.65) * d);
            const r = senseAt(x + Math.cos(a + 0.65) * d, y + Math.sin(a + 0.65) * d);
            if (l > c && l >= r) a -= 0.3; else if (r > c && r > l) a += 0.3;
            a += (rand() - 0.5) * 0.4;
            for (const f of foods) {
              if (f.amt > 0.02 && Math.hypot(x - f.x, y - f.y) < 1.6 + f.amt * 2.5) {
                AS[i] = 1; f.amt = Math.max(0, f.amt - 0.012); a += Math.PI; break;
              }
            }
          } else {
            // Carrier: head home, drop scent as it goes.
            const want = Math.atan2(nest.y - y, nest.x - x);
            let diff = want - a;
            while (diff > Math.PI) diff -= TAU; while (diff < -Math.PI) diff += TAU;
            a += clamp(diff, -0.35, 0.35) + (rand() - 0.5) * 0.12;
            const pi = (y | 0) * W + (x | 0);
            if (pi >= 0 && pi < pher.length) pher[pi] = Math.min(30, pher[pi] + 3);
            if (Math.hypot(x - nest.x, y - nest.y) < 2.5) { AS[i] = 0; a += Math.PI; }
          }
          let nx = x + Math.cos(a) * step, ny = y + Math.sin(a) * step;
          if (nx < 1 || nx > W - 2) { a = Math.PI - a; nx = clamp(nx, 1, W - 2); }
          if (ny < 1 || ny > H - 2) { a = -a; ny = clamp(ny, 1, H - 2); }
          AX[i] = nx; AY[i] = ny; AA[i] = a;
        }
        for (const f of foods) if (f.amt <= 0.02) { f.x = W * (0.45 + 0.5 * rand()); f.y = 3 + rand() * (H - 6); f.amt = 1; }
        // Evaporate + separable diffuse keeps trails crisp but mortal.
        for (let y = 0; y < H; y++) {
          const r = y * W;
          for (let x = 0; x < W; x++) {
            const a = pher[r + Math.max(0, x - 1)], b = pher[r + x], c = pher[r + Math.min(W - 1, x + 1)];
            tmp[r + x] = a * 0.2 + b * 0.6 + c * 0.2;
          }
        }
        for (let y = 0; y < H; y++) {
          const up = Math.max(0, y - 1) * W, dn = Math.min(H - 1, y + 1) * W, r = y * W;
          for (let x = 0; x < W; x++) pher[r + x] = (tmp[up + x] * 0.2 + tmp[r + x] * 0.6 + tmp[dn + x] * 0.2) * 0.985;
        }
        // Soil, trails, nest, food, ants.
        px.set(soil);
        for (let i = 0; i < pher.length; i++) {
          const p = pher[i];
          if (p > 0.08) px[i] = mix(px[i], trailC, Math.min(0.8, p * 0.08));
        }
        for (let dy = -2; dy <= 2; dy++) for (let dx = -3; dx <= 3; dx++) {
          const x = (nest.x | 0) + dx, y = (nest.y | 0) + dy;
          if (x < 0 || y < 0 || x >= W || y >= H) continue;
          const d = Math.hypot(dx, dy * 1.6);
          if (d < 3) px[y * W + x] = d < 1.2 ? 0x120a04 : mix(px[y * W + x], 0x4a3820, 0.5);
        }
        for (const f of foods) {
          const r = 1 + f.amt * 2.5;
          for (let dy = -3; dy <= 3; dy++) for (let dx = -3; dx <= 3; dx++) {
            const x = (f.x | 0) + dx, y = (f.y | 0) + dy;
            if (x < 0 || y < 0 || x >= W || y >= H) continue;
            const d = Math.hypot(dx, dy * 1.4);
            if (d < r) px[y * W + x] = mix(foodC, 0xd8ffb0, Math.max(0, 1 - d / (r + 0.01)) * 0.5);
          }
        }
        for (let i = 0; i < N; i++) {
          const xi = AX[i] | 0, yi = AY[i] | 0;
          if (xi < 0 || yi < 0 || xi >= W || yi >= H) continue;
          px[yi * W + xi] = AS[i] ? carryC : antC;
          const bx = (AX[i] - Math.cos(AA[i])) | 0, by = (AY[i] - Math.sin(AA[i])) | 0;
          if (bx >= 0 && by >= 0 && bx < W && by < H) px[by * W + bx] = mix(px[by * W + bx], AS[i] ? carryC : antC, 0.6);
        }
        cv.paint(ctx.buffer);
      };
    },
  },
];

sources.prism-term/src/facets/sim/wireworld.js:
// Wireworld on a generated circuit board. Clock loops (cut-corner rings, each
// carrying one electron, period = ring length) fire pulses down tapped traces
// that a router lays out PCB-style — straight runs, diagonal corners, fan-out
// branches — keeping every trace clear of every other. Rules: head → tail,
// tail → copper, copper → head when one or two neighbors are heads.
import { NONE, mix } from '../../color.js';

const EMPTY = 0, WIRE = 1, HEAD = 2, TAIL = 3;
const D4 = [[1, 0], [0, 1], [-1, 0], [0, -1]];

export default {
  title: 'Wireworld',
  gallery: 'sim',
  category: 'Cellular Automata',
  kind: 'scene',
  tags: ['wireworld', 'cellular automata', 'circuit', 'electrons', 'pcb', 'clock'],
  order: 30,
  description: 'Wireworld on a generated circuit board: clock loops fire electrons down routed traces that fan out across it.',
  size: { w: 60, h: 22 },
  minSize: { w: 20, h: 7 },
  loop: 12,
  canvas: 'field',
  palette: 'theme',
  params: { speed: { default: 1, min: 0.25, max: 4, label: 'Speed' } },
  setup(ctx) {
    const cv = ctx.canvas();
    const W = cv.width, H = cv.height, px = cv.px, th = ctx.theme, rand = ctx.rng;
    const gps = 14 * ctx.param('speed', 1);
    let cur = new Uint8Array(W * H), nxt = new Uint8Array(W * H);
    const taken = new Uint8Array(W * H); // occupied or reserved by a clock
    const inside = (x, y) => x >= 1 && y >= 1 && x < W - 1 && y < H - 1;
    const at = (x, y) => y * W + x;
    // A cell may be laid if all its neighbors are empty except the `allow` cells.
    const clear = (x, y, allow) => {
      if (!inside(x, y) || taken[at(x, y)]) return false;
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dy) continue;
        const X = x + dx, Y = y + dy;
        if (X < 0 || Y < 0 || X >= W || Y >= H) continue;
        if (taken[at(X, Y)] && !allow.includes(at(X, Y))) return false;
      }
      return true;
    };
    const lay = (x, y) => { cur[at(x, y)] = WIRE; taken[at(x, y)] = 1; };
    const ends = []; // trace ends, drawn as vias

    // Route a trace from (x, y) heading d; returns cells laid.
    const route = (x, y, d, prev, budget, depth) => {
      const trail = [...prev];
      let run = 2 + Math.floor(rand() * 4), extra = [];
      for (let n = 0; n < budget; n++) {
        let moved = false;
        // Keep going straight for the rest of the run, turning only when forced;
        // after a run, prefer a turn. (A trunk just past a branch must go straight.)
        const side = rand() < 0.5 ? 1 : 3, other = 4 - side;
        const options = run > 0 ? (extra.length ? [0] : [0, side, other]) : [side, 0, other];
        for (const turn of options) {
          let nx, ny, nd = (d + turn) & 3;
          if (turn) { nx = x + D4[d][0] + D4[nd][0]; ny = y + D4[d][1] + D4[nd][1]; } // diagonal corner
          else { nx = x + D4[d][0]; ny = y + D4[d][1]; }
          if (!clear(nx, ny, [...trail.slice(-2), ...extra])) continue;
          lay(nx, ny); trail.push(at(nx, ny)); x = nx; y = ny; d = nd; moved = true; extra = [];
          run = turn ? 2 + Math.floor(rand() * 5) : run - 1;
          break;
        }
        if (!moved) break;
        // Occasionally fan out a branch at right angles.
        if (depth < 3 && n > 2 && rand() < 0.1) {
          const bd = (d + (rand() < 0.5 ? 1 : 3)) & 3, bx = x + D4[bd][0], by = y + D4[bd][1];
          const allow = trail.slice(-3);
          // The branch's first cell sits diagonal to the trunk's next cell, so let the trunk pass it.
          if (clear(bx, by, allow)) { lay(bx, by); extra = [at(bx, by)]; run = Math.max(run, 1); route(bx, by, bd, [...allow, at(bx, by)], Math.floor(budget * 0.5), depth + 1); }
        }
      }
      if (trail.length) ends.push([x, y]);
      return trail;
    };

    // Clocks: cut-corner rings with one electron and a tap from a side.
    const clocks = Math.max(1, Math.min(7, Math.round((W * H) / 700)));
    for (let c = 0; c < clocks; c++) {
      for (let tries = 0; tries < 30; tries++) {
        // Small boards get small clocks and a one-cell margin.
        const m = W < 30 || H < 14 ? 1 : 2;
        const w = (m === 1 ? 4 : 5) + Math.floor(rand() * 5), h = (m === 1 ? 2 : 3) + Math.floor(rand() * 3);
        const x0 = m + Math.floor(rand() * Math.max(1, W - w - 2 * m)), y0 = m + Math.floor(rand() * Math.max(1, H - h - 2 * m));
        let ok = x0 + w < W - m && y0 + h < H - m;
        for (let y = y0 - 1; ok && y <= y0 + h + 1; y++) for (let x = x0 - 1; x <= x0 + w + 1; x++) if (taken[at(x, y)]) { ok = false; break; }
        if (!ok) continue;
        const ring = [];
        for (let x = x0 + 1; x < x0 + w; x++) ring.push([x, y0]);
        for (let y = y0 + 1; y < y0 + h; y++) ring.push([x0 + w, y]);
        for (let x = x0 + w - 1; x > x0; x--) ring.push([x, y0 + h]);
        for (let y = y0 + h - 1; y > y0; y--) ring.push([x0, y]);
        for (const [x, y] of ring) lay(x, y);
        for (let y = y0; y <= y0 + h; y++) for (let x = x0; x <= x0 + w; x++) taken[at(x, y)] = 1; // keep the interior clear
        cur[at(...ring[1])] = HEAD; cur[at(...ring[0])] = TAIL;
        // Tap out of the middle of the right or left side.
        const right = x0 + w < W * 0.6, ym = y0 + (h >> 1);
        const tx = right ? x0 + w + 1 : x0 - 1, d = right ? 0 : 2;
        const allow = [at(right ? x0 + w : x0, ym - 1), at(right ? x0 + w : x0, ym), at(right ? x0 + w : x0, ym + 1)];
        if (clear(tx, ym, allow)) { lay(tx, ym); route(tx, ym, d, [...allow, at(tx, ym)], W + H, 0); }
        break;
      }
    }

    const copper = mix(th.bg, 0xc8873e, 0.45), via = mix(th.bg, 0xe8c27a, 0.8), headC = mix(0x9fe8ff, th.ink, 0.2), tailC = 0xff7a3c;
    let acc = 0;
    const step = () => {
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        const i = y * W + x, s = cur[i];
        if (s === EMPTY) { nxt[i] = EMPTY; continue; }
        if (s === HEAD) { nxt[i] = TAIL; continue; }
        if (s === TAIL) { nxt[i] = WIRE; continue; }
        let n = 0;
        for (let dy = -1; dy <= 1; dy++) {
          const Y = y + dy;
          if (Y < 0 || Y >= H) continue;
          for (let dx = -1; dx <= 1; dx++) {
            const X = x + dx;
            if (X >= 0 && X < W && cur[Y * W + X] === HEAD) n++;
          }
        }
        nxt[i] = n === 1 || n === 2 ? HEAD : WIRE;
      }
      [cur, nxt] = [nxt, cur];
    };

    return (t, dt) => {
      acc += Math.min(0.25, Math.max(0, dt)) * gps;
      for (let k = 0; acc >= 1 && k < 8; k++, acc--) step();
      if (acc > 8) acc = 0;
      for (let i = 0; i < W * H; i++) {
        const s = cur[i];
        px[i] = s === EMPTY ? NONE : s === WIRE ? copper : s === HEAD ? headC : tailC;
      }
      // Vias where traces end (drawing only — not part of the automaton).
      for (const [x, y] of ends) if (cur[at(x, y)] === WIRE) px[at(x, y)] = via;
      cv.paint(ctx.buffer);
    };
  },
};

